-- =============================================================================
-- 428 — LE CATALOGUE DES CONTRÔLES BLANCS : 5e
--
-- 408 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 428 --niveau 5e
--
--   allemand.c01                  9 sujets · 3 fiches
--   anglais.c02                  60 sujets · 20 fiches
--   anglais.c03                  57 sujets · 19 fiches
--   francais.c08                 39 sujets · 13 fiches
--   histoire-geo.c24             33 sujets · 11 fiches
--   histoire-geo.c25             30 sujets · 10 fiches
--   latin.c28                     9 sujets · 3 fiches
--   maths.c31                    39 sujets · 13 fiches
--   maths.c32                    39 sujets · 13 fiches
--   physique-chimie.c35          48 sujets · 16 fiches
--   physique-chimie.c36          45 sujets · 15 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('f9ccd6ca-42ef-5703-8abd-90b26c93cf77'::uuid, 1, 'traduction', $exo${"titre":"Saluer et se présenter","consigne":"Réponds en allemand. Écris des phrases complètes.","enonce":"**A. Salue.** Écris en allemand la formule qui convient.\n\n1. Tu salues ta voisine le matin.\n2. Tu salues un ami, à n'importe quelle heure (formule familière).\n3. Tu quittes ton professeur (formule polie).\n\n**B. Présente-toi.** Traduis en allemand.\n\n4. Je m'appelle Léa.\n5. J'ai 13 ans.\n6. Je viens de France.\n7. J'habite à Lyon.","bareme":[{"critere":"Trois formules de salutation justes (Guten Morgen, Hallo, Auf Wiedersehen)","points":6},{"critere":"Phrases 4 et 5 justes (Ich heiße / Ich bin Léa ; Ich bin 13 Jahre alt, sans « habe »)","points":7},{"critere":"Phrases 6 et 7 justes (aus Frankreich ; in Lyon)","points":7}],"dureeMin":6,"corrige":"**A.**\n1. *Guten Morgen* (le matin, neutre).\n2. *Hallo* (à toute heure, familier).\n3. *Auf Wiedersehen* (en partant, poli).\n\n**B.**\n4. *Ich heiße Léa.* (ou *Ich bin Léa.*)\n5. *Ich bin 13 Jahre alt.* En allemand on **est** âgé de 13 ans : *Ich habe 13 Jahre* est faux.\n6. *Ich komme aus Frankreich.* On dit d'où l'on vient avec *aus*.\n7. *Ich wohne in Lyon.* On dit où l'on habite avec *in*."}$exo$::jsonb),
  ('f9ccd6ca-42ef-5703-8abd-90b26c93cf77'::uuid, 2, 'traduction', $exo${"titre":"Tutoyer ou vouvoyer ?","consigne":"Réponds en allemand pour les phrases demandées, en français pour les explications.","enonce":"**Situation.** Lina arrive dans un collège allemand. Elle rencontre d'abord Max, un élève de son âge, puis Frau Braun, la professeure principale.\n\n1. Écris en allemand la question que Lina pose à Max pour connaître son nom.\n2. Écris en allemand la question que Lina pose à Frau Braun pour connaître son nom.\n3. Frau Braun demande : *Wie heißen Sie ?* Écris la réponse de Lina : elle dit son nom et qu'elle vient de France.\n4. Explique en français pourquoi Lina ne dit pas la même chose à Max et à Frau Braun. Que remarques-tu sur l'écriture de *Sie* ?\n5. Écris en chiffres : *einundzwanzig* et *vierundsechzig*.","bareme":[{"critere":"Questions 1 et 2 justes : Wie heißt du ? / Wie heißen Sie ?","points":6},{"critere":"Réponse 3 : phrase correcte avec heiße (ou bin) et komme aus Frankreich","points":5},{"critere":"Explication du tutoiement et du vouvoiement, majuscule de Sie","points":5},{"critere":"Nombres justes : 21 et 64","points":4}],"dureeMin":9,"corrige":"1. *Wie heißt du ?* (tutoiement, avec un camarade.)\n2. *Wie heißen Sie ?* (vouvoiement, avec une adulte.)\n3. *Ich heiße Lina. Ich komme aus Frankreich.* (ou *Ich bin Lina.*)\n4. Max est un élève de son âge : on le tutoie (*du*). Frau Braun est une adulte inconnue : on la vouvoie (*Sie*). Le tutoiement se propose, il ne se prend pas. *Sie* de politesse s'écrit **toujours avec une majuscule**, même au milieu d'une phrase, et le verbe prend -en (*heißen*).\n5. *einundzwanzig* = 21 (un-et-vingt) ; *vierundsechzig* = 64 (quatre-et-soixante). L'allemand dit l'unité avant la dizaine."}$exo$::jsonb),
  ('f9ccd6ca-42ef-5703-8abd-90b26c93cf77'::uuid, 3, 'traduction', $exo${"titre":"Ma fiche de présentation","consigne":"Écris en allemand simple. Justifie tes corrections en français.","enonce":"**A. Production.** Tom est un élève de Lyon. Il a 14 ans. Il vient de France. Écris en allemand une présentation de Tom, à la première personne (*Ich…*), de 4 phrases : il salue, donne son prénom, son âge, d'où il vient et où il habite.\n\n**B. Corrige.** Chaque phrase contient une faute. Récris-la correctement et explique la faute en français.\n\n1. *Ich habe 13 Jahre.*\n2. *Ich wohne Frankreich.* (Je viens de France)\n3. Tu parles à ton professeur : *Wie heißt du ?*\n4. Tu parles à un adulte : *Wie heißen sie ?*","bareme":[{"critere":"Présentation de 4 phrases : salutation, prénom, âge avec « bin … alt », origine avec aus, ville avec in","points":8},{"critere":"Phrases 1 et 2 corrigées (Ich bin 13 Jahre alt ; Ich komme aus Frankreich)","points":6},{"critere":"Phrases 3 et 4 corrigées (Wie heißen Sie ? avec majuscule)","points":4},{"critere":"Explications justes des quatre fautes","points":2}],"dureeMin":14,"corrige":"**A.** Exemple : *Hallo ! Ich heiße Tom. Ich bin 14 Jahre alt. Ich komme aus Frankreich und ich wohne in Lyon.* Éléments attendus : une salutation, *heiße* ou *bin* avec le prénom, *bin … Jahre alt* (jamais *habe*), *komme aus Frankreich*, *wohne in Lyon*.\n\n**B.**\n1. *Ich bin 13 Jahre alt.* En allemand on est âgé, on n'a pas d'âge.\n2. *Ich komme aus Frankreich.* *Wohnen* signifie habiter (avec *in*) ; pour dire d'où l'on vient, on emploie *kommen aus*.\n3. *Wie heißen Sie ?* On vouvoie un professeur : *Sie* et non *du*.\n4. *Wie heißen Sie ?* Le *Sie* de politesse prend toujours une majuscule."}$exo$::jsonb),
  ('ec3f56f3-71ee-50ec-afa9-c7c87ace6ca7'::uuid, 1, 'traduction', $exo${"titre":"Der, die ou das ?","consigne":"Réponds en allemand. Pour les noms, l'énoncé donne le genre en français.","enonce":"**A. Articles.** Écris l'article défini (der, die ou das) puis l'article indéfini (ein ou eine) de chaque nom.\n\n1. Tisch (masculin)\n2. Lampe (féminin)\n3. Buch (neutre)\n\n**B. Majuscules.** Récris correctement ces groupes de mots.\n\n4. das haus\n5. die schule\n6. der freund","bareme":[{"critere":"Trois articles définis justes : der Tisch, die Lampe, das Buch","points":6},{"critere":"Trois articles indéfinis justes : ein Tisch, eine Lampe, ein Buch","points":6},{"critere":"Trois majuscules ajoutées aux noms (Haus, Schule, Freund)","points":6},{"critere":"Explication de la règle : tous les noms communs prennent une majuscule","points":2}],"dureeMin":6,"corrige":"**A.**\n1. *der Tisch* — *ein Tisch*.\n2. *die Lampe* — *eine Lampe*.\n3. *das Buch* — *ein Buch*. Le masculin et le neutre partagent l'article indéfini *ein*.\n\n**B.**\n4. *das Haus*\n5. *die Schule*\n6. *der Freund*\nRègle : en allemand, tous les noms communs prennent une majuscule, quelle que soit leur place dans la phrase, sans exception."}$exo$::jsonb),
  ('ec3f56f3-71ee-50ec-afa9-c7c87ace6ca7'::uuid, 2, 'traduction', $exo${"titre":"Sujet ou complément ?","consigne":"Réponds en allemand pour les phrases, en français pour les explications.","enonce":"**A. Complète à l'accusatif** avec l'article qui convient.\n\n1. Ich sehe ___ Hund. (masculin, défini)\n2. Ich habe ___ Lampe. (féminin, indéfini)\n3. Ich sehe ___ Buch. (neutre, défini)\n4. Ich habe ___ Tisch. (masculin, indéfini)\n\n**B. Traduis en allemand.**\n\n5. Le chien voit l'homme. (der Hund, der Mann)\n\n**C. Explique** en une phrase : à l'accusatif, quel genre change d'article ?","bareme":[{"critere":"Quatre articles à l'accusatif justes : den, eine, das, einen","points":8},{"critere":"Traduction 5 : Der Hund sieht den Mann (sujet au nominatif, COD à l'accusatif)","points":6},{"critere":"Explication : seul le masculin change (der → den, ein → einen)","points":6}],"dureeMin":9,"corrige":"**A.**\n1. *Ich sehe **den** Hund.* (masculin accusatif).\n2. *Ich habe **eine** Lampe.* (le féminin ne change pas).\n3. *Ich sehe **das** Buch.* (le neutre ne change pas).\n4. *Ich habe **einen** Tisch.* (masculin accusatif).\n\n**B.** 5. *Der Hund sieht den Mann.* *Der Hund* est le sujet (nominatif), *den Mann* le COD (accusatif).\n\n**C.** À l'accusatif, seul le **masculin** change : *der* devient *den* et *ein* devient *einen*. Le féminin, le neutre et le pluriel restent identiques au nominatif."}$exo$::jsonb),
  ('ec3f56f3-71ee-50ec-afa9-c7c87ace6ca7'::uuid, 3, 'traduction', $exo${"titre":"Qui voit qui ?","consigne":"Réponds en français pour les explications et en allemand pour les phrases à écrire.","enonce":"**A. Deux phrases.**\n\n> a. *Der Hund sieht den Mann.*\n> b. *Den Hund sieht der Mann.*\n\n1. Traduis chaque phrase en français.\n2. Dans chacune, quel mot est le sujet et quel mot est le COD ? Quel indice le montre ?\n3. Pourquoi peut-on changer l'ordre des mots sans changer les rôles ici ?\n\n**B. Corrige** ces phrases et explique la faute.\n\n4. *Ich sehe der Tisch.*\n5. *Ich habe ein Lampe.*\n6. *Die schule ist neu.*","bareme":[{"critere":"Traductions justes : le chien voit l'homme / c'est l'homme qui voit le chien","points":4},{"critere":"Sujet et COD identifiés dans chaque phrase, avec l'indice (der ou den sur le masculin)","points":6},{"critere":"Explication : la forme de l'article, non la place, indique la fonction","points":3},{"critere":"Phrases 4, 5 et 6 corrigées (den Tisch ; eine Lampe ; Schule) avec explications","points":7}],"dureeMin":14,"corrige":"**A.**\n1. a. *Le chien voit l'homme.* b. *C'est l'homme qui voit le chien* (le chien est mis en avant).\n2. En a, *der Hund* est le sujet (nominatif) et *den Mann* le COD (accusatif). En b, *den Hund* est le COD et *der Mann* le sujet. L'indice est l'article masculin : *der* = sujet, *den* = COD.\n3. Les mots sont masculins, et le masculin change de forme à l'accusatif : la forme de l'article indique la fonction, donc le sens ne dépend pas de la place.\n\n**B.**\n4. *Ich sehe **den** Tisch.* Le COD masculin se met à l'accusatif : *der* devient *den*.\n5. *Ich habe **eine** Lampe.* *Lampe* est féminin : *eine*, non *ein*.\n6. *Die **Schule** ist neu.* Un nom commun prend toujours une majuscule."}$exo$::jsonb),
  ('7e448107-365b-5ddb-acd8-5abfa8712cf3'::uuid, 1, 'traduction', $exo${"titre":"Conjuguer au présent","consigne":"Réponds en allemand.","enonce":"**A. Conjugue** le verbe *spielen* (jouer) au présent : ich, du, er, wir, ihr.\n\n**B. Complète** avec le verbe *sein* ou *haben* qui convient.\n\n1. Ich ___ Anna. (sein)\n2. Du ___ einen Hund. (haben)\n3. Er ___ Lehrer. (sein)\n4. Wir ___ ein Buch. (haben)","bareme":[{"critere":"Cinq formes de spielen justes : spiele, spielst, spielt, spielen, spielt","points":10},{"critere":"Quatre formes de sein et haben justes : bin, hast, ist, haben","points":8},{"critere":"Explication de la méthode : radical + terminaison (-e, -st, -t, -en, -t)","points":2}],"dureeMin":7,"corrige":"**A.** On retire *-en* de l'infinitif (radical *spiel-*) et on ajoute la terminaison : *ich spiele*, *du spielst*, *er spielt*, *wir spielen*, *ihr spielt*.\n\n**B.**\n1. *Ich **bin** Anna.*\n2. *Du **hast** einen Hund.*\n3. *Er **ist** Lehrer.*\n4. *Wir **haben** ein Buch.*\n*Sein* et *haben* sont irréguliers : il faut les apprendre par cœur."}$exo$::jsonb),
  ('7e448107-365b-5ddb-acd8-5abfa8712cf3'::uuid, 2, 'traduction', $exo${"titre":"Ordre des mots et questions","consigne":"Réponds en allemand. Les phrases doivent être complètes.","enonce":"**A. Remets les mots dans l'ordre** pour former une phrase correcte.\n\n1. gehe / ins Kino / ich / heute (commence par *Ich*)\n2. gehe / ins Kino / ich / heute (commence par *Heute*)\n\n**B. Pose la question.**\n\n3. Transforme en question fermée (oui / non) : *Du spielst Fußball.*\n4. Traduis en allemand : *Quand viens-tu ?* (wann, kommen)\n\n**C. Explique** en une phrase la règle de la place du verbe dans une phrase déclarative.","bareme":[{"critere":"Deux phrases justes : Ich gehe heute ins Kino ; Heute gehe ich ins Kino","points":6},{"critere":"Question fermée juste : Spielst du Fußball ? (verbe en première position)","points":5},{"critere":"Question ouverte juste : Wann kommst du ? (verbe après le mot interrogatif, bonne terminaison)","points":5},{"critere":"Règle : verbe conjugué toujours en deuxième position, sujet derrière si un complément est en tête","points":4}],"dureeMin":10,"corrige":"**A.**\n1. *Ich gehe heute ins Kino.*\n2. *Heute gehe ich ins Kino.* Le verbe reste en deuxième position ; le sujet passe après lui (inversion).\n\n**B.**\n3. *Spielst du Fußball ?* Dans une question fermée, le verbe est en **première** position.\n4. *Wann kommst du ?* Le verbe suit le mot interrogatif, avec la terminaison *-st* de *du*.\n\n**C.** Dans une phrase déclarative, le verbe conjugué occupe toujours la **deuxième** place, quel que soit l'élément placé en tête. Quand un complément est en première position, le sujet se place derrière le verbe."}$exo$::jsonb),
  ('7e448107-365b-5ddb-acd8-5abfa8712cf3'::uuid, 3, 'traduction', $exo${"titre":"La lettre d'Emma","consigne":"Écris en allemand simple. Explique les corrections en français.","enonce":"Emma écrit un petit message à son correspondant. *(Texte écrit pour l'exercice, avec des fautes.)*\n\n> Hallo ! Ich bin Emma. Heute ich spiele Fußball. Du spielt auch gern ? Wir haben einen Hund. Er haben einen Ball. Wo du wohnst ?\n\n**A.** Relève quatre fautes de conjugaison ou de place du verbe et corrige-les. Explique chaque faute en français.\n\n**B.** Écris à ton tour trois phrases en allemand pour répondre à Emma : une qui commence par *Heute*, une question fermée, une question ouverte avec *Wo*.","bareme":[{"critere":"Quatre fautes repérées et corrigées (Heute spiele ich ; Spielst du ; Er hat ; Wo wohnst du)","points":8},{"critere":"Explications justes : verbe en deuxième position, terminaison -st, conjugaison de haben","points":4},{"critere":"Trois phrases correctes : inversion après Heute, question fermée, question avec Wo","points":6},{"critere":"Terminaisons justes dans les trois phrases","points":2}],"dureeMin":15,"corrige":"**A.**\n1. *Heute **spiele ich** Fußball.* Après *Heute*, le verbe reste en deuxième position et le sujet passe derrière.\n2. *Spielst du auch gern ?* À *du*, la terminaison est *-st* ; question fermée : verbe en tête.\n3. *Er **hat** einen Ball.* *Haben* est irrégulier : *er hat*.\n4. *Wo wohnst du ?* Dans une question ouverte, le verbe se place juste après le mot interrogatif.\n\n**B.** Exemples : *Heute gehe ich ins Kino.* — *Spielst du Fußball ?* — *Wo wohnst du ?* Éléments attendus : verbe en deuxième position avec inversion après *Heute*, verbe en première position dans la question fermée, verbe juste après *Wo* avec la terminaison *-st*."}$exo$::jsonb),
  ('c35d5f08-6d70-5be4-bf01-ccaa86897c0b'::uuid, 1, 'traduction', $exo${"titre":"Remets les mots dans l'ordre","consigne":"Réponds en anglais, phrase par phrase, puis justifie brièvement en français.","enonce":"**A. Remets les mots dans l'ordre pour former une phrase correcte.**\n\n1. at home / played / Tom / yesterday / the guitar *(commence par Tom)*\n2. late / am / never / I\n3. goes / the cinema / often / she / to *(commence par She)*\n\n**B. Corrige l'erreur, puis explique-la en une phrase.**\n\n4. I didn't see nobody at the party.\n5. I speak well English.","bareme":[{"critere":"Trois phrases remises dans le bon ordre (sujet, verbe, objet, adverbe de fréquence bien placé)","points":12},{"critere":"Deux erreurs corrigées et expliquées (double négation ; adverbe entre verbe et objet)","points":8}],"dureeMin":6,"corrige":"**A.**\n1. *Tom played the guitar at home yesterday.* Ordre : sujet – verbe – objet, puis lieu, puis temps.\n2. *I am never late.* L'adverbe de fréquence se place **après be**.\n3. *She often goes to the cinema.* L'adverbe de fréquence se place **avant le verbe lexical**.\n\n**B.**\n4. *I didn't see **anybody** at the party.* Il ne faut qu'une seule négation : *didn't* suffit, on remplace *nobody* par *anybody*.\n5. *I speak **English well**.* L'adverbe ne s'intercale jamais entre le verbe et son complément d'objet : il se place après l'objet."}$exo$::jsonb),
  ('c35d5f08-6d70-5be4-bf01-ccaa86897c0b'::uuid, 2, 'traduction', $exo${"titre":"Relier et choisir la conjonction","consigne":"Réponds en anglais ; les traductions doivent être des phrases complètes.","enonce":"**A. Complète avec but, so, because ou or.**\n\n1. I was tired, … I went to bed early.\n2. She stayed at home … it was raining.\n3. Do you want tea … coffee?\n4. I like pizza, … my brother doesn't.\n\n**B. Traduis en anglais.**\n\n5. Je t'appellerai quand j'arriverai.\n6. S'il pleut demain, nous resterons à la maison.\n\n**C. Corrige la faute.**\n\n7. When she will arrive, we will eat.","bareme":[{"critere":"Quatre conjonctions de coordination justes","points":8},{"critere":"Traductions 5 et 6 : présent après when et if, will dans la principale","points":8},{"critere":"Correction de la phrase 7 avec la règle du présent après when","points":4}],"dureeMin":9,"corrige":"**A.** 1. *so* (conséquence) — 2. *because* (cause) — 3. *or* (choix) — 4. *but* (opposition).\n\n**B.**\n5. *I'll call you when I arrive.* Après *when*, on emploie le **présent** même pour parler de l'avenir.\n6. *If it rains tomorrow, we will stay at home.* Après *if*, présent aussi ; *will* seulement dans la proposition principale.\n\n**C.** 7. *When she **arrives**, we will eat.* Après une conjonction de temps, on n'emploie pas *will* : *when she will arrive* est faux."}$exo$::jsonb),
  ('c35d5f08-6d70-5be4-bf01-ccaa86897c0b'::uuid, 3, 'traduction', $exo${"titre":"Corriger puis écrire","consigne":"Corrige d'abord le texte en justifiant chaque correction, puis rédige tes propres phrases.","enonce":"**A. Ce message d'un correspondant contient quatre erreurs. Repère-les, corrige-les et donne la règle.**\n\n> Every Saturday, I go often to the park with my dog. Yesterday I didn't meet nobody there. My sister speaks fluently English. When she will arrive tonight, we will watch a film.\n\n**B. Écris quatre phrases sur ton week-end :**\n\n- une phrase avec une **coordination** (and, but ou so) ;\n- une phrase avec une subordonnée de **temps** (when, before ou after) ;\n- une phrase avec une subordonnée de **condition** (if ou unless) ;\n- une phrase avec un verbe, un complément d'objet, puis un complément de **lieu** et un complément de **temps**.","bareme":[{"critere":"Quatre erreurs repérées, corrigées et expliquées","points":8},{"critere":"Phrase avec coordination et phrase avec subordonnée de temps correctes","points":6},{"critere":"Phrase avec condition correcte (présent après if)","points":3},{"critere":"Phrase avec ordre objet – lieu – temps respecté","points":3}],"dureeMin":14,"corrige":"**A.**\n1. *I **often go** to the park.* Adverbe de fréquence **avant** le verbe lexical.\n2. *I didn't meet **anybody**.* Pas de double négation.\n3. *My sister speaks **English fluently**.* Pas d'adverbe entre le verbe et son objet.\n4. *When she **arrives** tonight, we will watch a film.* Présent après *when*.\n\n**B.** Exemples attendus :\n- *I wanted to go out, but it was raining.*\n- *I will call Ben when I get home.* (présent après *when*)\n- *If the weather is nice, we will go to the beach.* (jamais *if it will be*)\n- *We played football in the garden on Sunday.* (objet, lieu, temps)\nToute phrase correcte et conforme à la consigne est acceptée."}$exo$::jsonb),
  ('b5de6f27-974a-50e9-b102-160316cc7b1f'::uuid, 1, 'traduction', $exo${"titre":"Sujet ou complément ?","consigne":"Complète chaque phrase avec le pronom qui convient, puis réponds aux deux questions en français.","enonce":"**Complète avec un pronom personnel (sujet ou complément).**\n\n1. My sister is ten. … loves dancing.\n2. I like Tom. I often play with … .\n3. Look at the girls: … are happy.\n4. Mum, can you help … ?\n5. Sam and I are friends. … live in Leeds.\n6. This book is not yours, it is … .\n\n**7.** Pourquoi dit-on *with him* et non « with he » ?\n\n**8.** Dans *It is cold*, que désigne *it* ?","bareme":[{"critere":"Six pronoms justes (she, him, they, me, we, mine)","points":12},{"critere":"Explication : après une préposition, on emploie le pronom complément","points":4},{"critere":"Explication : it est un sujet vide, il ne remplace rien","points":4}],"dureeMin":6,"corrige":"1. *She* — sujet. 2. *him* — complément après la préposition *with*. 3. *they* — sujet pluriel. 4. *me* — complément du verbe *help*. 5. *We* — sujet (Sam et moi). 6. *mine* — pronom possessif de *I* (il remplace « my book »).\n\n7. Après une **préposition** (with, for, to…), on emploie le pronom **complément** : *him*, jamais *he*.\n\n8. *It* est un **sujet vide** : il ne désigne aucun objet, mais le sujet est obligatoire en anglais (*It is cold*, *It's five o'clock*)."}$exo$::jsonb),
  ('b5de6f27-974a-50e9-b102-160316cc7b1f'::uuid, 2, 'traduction', $exo${"titre":"Réfléchis, one et they","consigne":"Réponds en anglais ; justifie brièvement les choix 1 à 4 en français.","enonce":"**A. Complète avec un pronom réfléchi, ou écris ∅ s'il n'en faut pas.**\n\n1. Tom made this cake … .\n2. My grandmother lives by … .\n3. I did my homework … .\n4. She hurt … yesterday.\n\n**B. Traduis en anglais.**\n\n5. Je me lève à six heures. Je me sens fatigué.\n\n**C. Évite la répétition avec one ou ones.**\n\n6. I prefer the red bag to the blue bag.\n\n**D.** 7. *Someone called. … left a message.* Complète avec le pronom qui convient.","bareme":[{"critere":"Quatre réfléchis justes (himself, herself, myself, herself)","points":6},{"critere":"Traduction sans réfléchi : I get up… I feel…","points":6},{"critere":"Phrase 6 avec one (the blue one)","points":4},{"critere":"Pronom they avec sens neutre singulier","points":4}],"dureeMin":9,"corrige":"**A.** 1. *himself* (insistance) — 2. *herself* (*by herself* = toute seule) — 3. *myself* (insistance) — 4. *herself* (l'action revient sur le sujet).\n\n**B.** 5. *I get up at six. I feel tired.* Ces verbes pronominaux en français ne prennent **pas** de réfléchi en anglais.\n\n**C.** 6. *I prefer the red bag to the blue **one**.*\n\n**D.** 7. ***They** left a message.* *They* peut être un pronom singulier neutre quand on ne connaît pas la personne ou son genre."}$exo$::jsonb),
  ('b5de6f27-974a-50e9-b102-160316cc7b1f'::uuid, 3, 'traduction', $exo${"titre":"Chasse aux fautes de pronoms","consigne":"Corrige chaque phrase, donne la règle en français, puis traduis les quatre dernières phrases.","enonce":"**A. Chaque phrase contient une erreur de pronom. Corrige-la et explique.**\n\n1. Tom and me play football every day.\n2. I gave the keys to she.\n3. The dog hurt hisself.\n4. She lives by her.\n5. Every morning I get myself up at seven.\n6. This isn't my pen, it's your.\n\n**B. Traduis en anglais.**\n\n7. Quelqu'un a téléphoné : ils ont laissé un message.\n8. Je préfère les rouges.\n9. Il faut une heure.\n10. Il est cinq heures.","bareme":[{"critere":"Six phrases corrigées (I, her, itself, herself, get up, yours)","points":6},{"critere":"Règle donnée pour chaque correction (sujet, complément après préposition, réfléchi, pronom possessif…)","points":6},{"critere":"Traductions 7 et 8 (they ; the red ones)","points":4},{"critere":"Traductions 9 et 10 avec it sujet vide","points":4}],"dureeMin":14,"corrige":"**A.**\n1. *Tom and **I** play…* — sujet, donc pronom sujet.\n2. *…to **her**.* — après une préposition, pronom complément.\n3. *…hurt **itself**.* — le réfléchi de *it* est *itself*.\n4. *…by **herself**.* — *by* + réfléchi = toute seule.\n5. *…I **get up** at seven.* — pas de réfléchi en anglais.\n6. *…it's **yours**.* — après *it's*, on emploie le **pronom** possessif, sans nom (*your* est un adjectif).\n\n**B.**\n7. *Someone called — **they** left a message.*\n8. *I prefer the red **ones**.* (*one/ones* évite de répéter le nom)\n9. ***It** takes an hour.*\n10. ***It's** five o'clock.*"}$exo$::jsonb),
  ('4467697b-756b-5552-83d8-a6b71c220718'::uuid, 1, 'traduction', $exo${"titre":"Choisir le bon relatif","consigne":"Complète chaque phrase, puis réponds aux deux questions en français.","enonce":"**Complète avec who, which, whose, where ou when.**\n\n1. The boy … lives next door is Sam.\n2. I have a cat … is very lazy.\n3. That is the girl … bag was stolen.\n4. London is the city … I was born.\n5. I remember the day … we moved house.\n\n**6.** Dans quelles phrases (1 à 5) peut-on remplacer le relatif par *that* ?\n\n**7.** Dans *The film I saw was good*, le relatif est absent. Pourquoi est-ce possible ?","bareme":[{"critere":"Cinq relatifs justes (who, which, whose, where, when)","points":10},{"critere":"Phrases 1 et 2 identifiées, sans les autres","points":5},{"critere":"Omission possible : relatif complément dans une relative déterminative","points":5}],"dureeMin":7,"corrige":"1. *who* (personne). 2. *which* (animal) — 3. *whose* (possession) — 4. *where* (lieu) — 5. *when* (temps).\n\n6. *That* est possible dans les phrases **1 et 2** (*who / which* → *that*, relatives déterminatives). Il est impossible pour *whose*, *where* et *when*.\n\n7. Dans *The film (that) I saw*, le relatif est **complément** (le sujet de la relative est *I*) : il peut donc disparaître. Un relatif **sujet** est obligatoire."}$exo$::jsonb),
  ('4467697b-756b-5552-83d8-a6b71c220718'::uuid, 2, 'traduction', $exo${"titre":"Deux sortes de relatives","consigne":"Réponds en anglais, puis justifie la question 4 en français.","enonce":"**A. Relie les deux phrases avec un pronom relatif.**\n\n1. My aunt lives in Rome. She is a doctor. *(relative explicative : l'information est ajoutée)*\n2. The man is my uncle. He is talking to Mum. *(relative déterminative)*\n\n**B. Traduis en anglais.**\n\n3. Le livre que tu m'as prêté est génial.\n\n**C.** 4. Pourquoi ne peut-on pas écrire *My aunt, that lives in Rome, is a doctor* ?","bareme":[{"critere":"Phrase 1 : relative explicative entre virgules avec who","points":5},{"critere":"Phrase 2 : who + verbe, sans virgule (ou that)","points":4},{"critere":"Traduction 3 avec relatif complément (that, which ou omis)","points":5},{"critere":"Explication : that est impossible dans une explicative","points":6}],"dureeMin":9,"corrige":"1. *My aunt, **who** lives in Rome, is a doctor.* Explicative : entre **virgules**, avec *who*.\n\n2. *The man **who / that** is talking to Mum is my uncle.* Déterminative : pas de virgule.\n\n3. *The book **(that / which)** you lent me is great.* Le relatif est **complément** (sujet de la relative : *you*) : on peut l'omettre. « que » ne se traduit pas mot à mot.\n\n4. Dans une relative **explicative**, *that* est **impossible** et le relatif n'est jamais omis : il faut *who* (personne) ou *which* (chose), entre virgules."}$exo$::jsonb),
  ('4467697b-756b-5552-83d8-a6b71c220718'::uuid, 3, 'traduction', $exo${"titre":"Sujet, complément, omission","consigne":"Analyse, corrige puis reformule ; justifie tes réponses en français.","enonce":"**A. Pour chaque phrase, dis si le relatif est sujet ou complément de la relative, et s'il peut être omis.**\n\n1. The girl who I spoke to is French.\n2. The teacher who teaches us maths is kind.\n3. The film which we watched was long.\n\n**B.** Reformule la phrase 1 en registre soutenu (la préposition ne reste pas à la fin).\n\n**C. Corrige et explique.**\n\n4. My mother, that is a nurse, works at night.\n5. The boy which lives next door is called Sam.","bareme":[{"critere":"Analyse des trois phrases (fonction du relatif, omission)","points":9},{"critere":"Reformulation soutenue : the girl to whom I spoke","points":4},{"critere":"Deux phrases corrigées (who, virgules) et expliquées","points":7}],"dureeMin":14,"corrige":"**A.**\n1. *who* est **complément** (sujet de la relative : *I*) : omission possible → *The girl I spoke to is French.*\n2. *who* est **sujet** (*who teaches*) : omission impossible.\n3. *which* est **complément** (sujet : *we*) : omission possible → *The film we watched was long.*\n\n**B.** *The girl **to whom** I spoke is French.* La préposition remonte devant le relatif.\n\n**C.**\n4. *My mother, **who** is a nurse, works at night.* Relative explicative : *that* impossible.\n5. *The boy **who** lives next door…* *Which* est réservé aux choses et aux animaux ; pour une personne, on emploie *who* (ou *that*)."}$exo$::jsonb),
  ('c60debd8-5bd9-564b-b978-8580d0a9c82e'::uuid, 1, 'traduction', $exo${"titre":"Poser la question","consigne":"Transforme et complète en anglais, puis réponds à la dernière question en français.","enonce":"**A. Transforme en question fermée (réponse oui / non).**\n\n1. You are ready.\n2. She can swim.\n3. They like pizza.\n4. He finished his work.\n\n**B. Pose la question sur la partie en gras.**\n\n5. Tom lives **in Paris**.\n6. The film starts **at eight**. *(pose la question avec when)*\n\n**C.** 7. Pourquoi ne peut-on pas dire *Do you are ready?*","bareme":[{"critere":"Quatre questions fermées justes (Are you…, Can she…, Do they…, Did he…)","points":8},{"critere":"Questions ouvertes 5 et 6 (Where does Tom live ? When does the film start ?)","points":8},{"critere":"Explication : be est déjà auxiliaire, do n'est pas nécessaire","points":4}],"dureeMin":7,"corrige":"**A.** 1. *Are you ready?* — 2. *Can she swim?* — 3. *Do they like pizza?* — 4. *Did he finish his work?* (après *did*, base verbale).\n\n**B.** 5. *Where does Tom live?* — 6. *When does the film start?* (mot interrogatif + auxiliaire + sujet + verbe).\n\n**C.** 7. *Be* joue lui-même le rôle d'auxiliaire : on l'inverse avec le sujet (*Are you ready?*). On n'ajoute *do* que pour un verbe à un temps simple sans auxiliaire."}$exo$::jsonb),
  ('c60debd8-5bd9-564b-b978-8580d0a9c82e'::uuid, 2, 'traduction', $exo${"titre":"Mots interrogatifs et sujet","consigne":"Réponds en anglais ; justifie la dernière question en français.","enonce":"**A. Complète avec who, where, why, whose, how many ou how long.**\n\n1. … is this bag? — It's Kate's.\n2. … brothers have you got? — Two.\n3. … did you go to bed late? — Because I was watching TV.\n4. … have you lived here? — For five years.\n\n**B. Écris la question qui correspond à chaque réponse.**\n\n5. — I met Sam.\n6. — Sam broke the window.\n\n**C.** 7. Compare la construction des questions 5 et 6.","bareme":[{"critere":"Quatre mots interrogatifs justes (whose, how many, why, how long)","points":8},{"critere":"Deux questions justes : Who did you meet ? Who broke the window ?","points":6},{"critere":"Explication : who complément avec did ; who sujet, sans do","points":6}],"dureeMin":9,"corrige":"**A.** 1. *Whose* — 2. *How many* — 3. *Why* — 4. *How long*.\n\n**B.** 5. *Who did you meet?* — 6. *Who broke the window?*\n\n**C.** En 5, *who* est **complément** : on garde l'ordre mot interrogatif + auxiliaire (*did*) + sujet + verbe. En 6, *who* est **sujet** : il n'y a ni inversion ni *do*, l'ordre reste celui de l'affirmative."}$exo$::jsonb),
  ('c60debd8-5bd9-564b-b978-8580d0a9c82e'::uuid, 3, 'traduction', $exo${"titre":"Questions indirectes","consigne":"Écris des phrases anglaises complètes ; justifie tes corrections en français.","enonce":"**A. Transforme en question indirecte, avec l'introduction demandée.**\n\n1. *Do you know…* : Where does Tom live?\n2. *Could you tell me…* : What time does the bus leave?\n3. *Do you know…* : Why did she leave?\n4. *Do you know…* : Who called me?\n\n**B. Corrige et explique.**\n\n5. I wonder where does he work.\n6. Who did break the window?\n\n**C.** Un touriste te demande son chemin. Écris quatre lignes de dialogue : deux questions ouvertes, une question fermée et une question indirecte.","bareme":[{"critere":"Quatre questions indirectes à l'ordre de l'affirmative, sans do","points":8},{"critere":"Deux corrections expliquées (where he works ; who broke)","points":4},{"critere":"Dialogue : quatre questions de nature demandée, correctes","points":8}],"dureeMin":15,"corrige":"**A.**\n1. *Do you know where Tom lives?*\n2. *Could you tell me what time the bus leaves?*\n3. *Do you know why she left?*\n4. *Do you know who called me?* — *who* est sujet : il n'y a jamais de *do*.\nDans une question indirecte, on reprend l'ordre de l'**affirmative**, sans *do/does/did*.\n\n**B.** 5. *I wonder where **he works**.* — 6. *Who **broke** the window?* (*who* est sujet : pas de *did*).\n\n**C.** Exemple : *Excuse me, where is the station? — Could you tell me how far it is? — Is there a bank near here? — How long does it take?* Toute série correcte et conforme (2 ouvertes, 1 fermée, 1 indirecte) est acceptée."}$exo$::jsonb),
  ('061ffe93-f193-57de-a631-c208fc865ae8'::uuid, 1, 'traduction', $exo${"titre":"Complète le tag","consigne":"Complète chaque phrase avec le question tag qui convient, puis réponds à la dernière question en français.","enonce":"**Complète avec le question tag.**\n\n1. She is a teacher, … ?\n2. You can swim, … ?\n3. They didn't come, … ?\n4. He has finished, … ?\n5. You like coffee, … ?\n6. Tom isn't here, … ?\n\n**7.** Quelle intonation faut-il pour poser une vraie question, quand on doute ?","bareme":[{"critere":"Six tags justes (isn't she, can't you, did they, hasn't he, don't you, is he)","points":18},{"critere":"Intonation montante quand on doute","points":2}],"dureeMin":5,"corrige":"1. *isn't she?* — 2. *can't you?* — 3. *did they?* — 4. *hasn't he?* — 5. *don't you?* (temps simple : *do*) — 6. *is he?* (phrase négative : tag affirmatif).\n\nRègle : auxiliaire de la phrase (ou *do/does/did*), polarité inversée, sujet repris par un pronom.\n\n7. L'intonation **montante** marque un vrai doute : c'est une vraie question. L'intonation descendante cherche seulement l'accord."}$exo$::jsonb),
  ('061ffe93-f193-57de-a631-c208fc865ae8'::uuid, 2, 'traduction', $exo${"titre":"Les cas particuliers","consigne":"Complète les tags, traduis, puis explique en français.","enonce":"**A. Complète avec le question tag.**\n\n1. I am late, … ?\n2. Let's go, … ?\n3. Close the door, … ?\n4. Somebody called, … ?\n5. There is a problem, … ?\n\n**B. Traduis en anglais avec un question tag.**\n\n6. Il fait beau, n'est-ce pas ?\n\n**C.** 7. Explique la différence de sens entre un tag à intonation descendante et un tag à intonation montante.","bareme":[{"critere":"Cinq tags des cas particuliers justes (aren't I, shall we, will you, didn't they, isn't there)","points":10},{"critere":"Traduction 6 : It's sunny/nice, isn't it ?","points":4},{"critere":"Explication des deux intonations","points":6}],"dureeMin":8,"corrige":"**A.** 1. *aren't I?* (forme consacrée) — 2. *shall we?* — 3. *will you?* (impératif) — 4. *didn't they?* (sujet indéfini repris par *they*) — 5. *isn't there?* (on reprend *there*).\n\n**B.** 6. *It's a nice day, isn't it?* (ou *It's sunny, isn't it?*)\n\n**C.** L'intonation **descendante** : on est presque sûr, on cherche l'accord de l'autre. L'intonation **montante** : on doute vraiment, c'est une véritable question."}$exo$::jsonb),
  ('061ffe93-f193-57de-a631-c208fc865ae8'::uuid, 3, 'traduction', $exo${"titre":"Le dialogue rempli d'erreurs","consigne":"Corrige les erreurs, puis écris un court dialogue avec des question tags.","enonce":"**A. Chaque réplique contient une erreur de question tag. Corrige-la.**\n\n1. — You don't like fish, don't you?\n2. — Everyone is ready, isn't he?\n3. — Tom and Mary have left, haven't he?\n4. — I'm right, amn't I?\n5. — Let's start, will we?\n\n**B. Écris un mini-dialogue de trois répliques avec un tag après une phrase affirmative, un tag après une phrase négative et un tag après un impératif.**\n\n**C.** Résume en une phrase les trois étapes mécaniques pour former un question tag.","bareme":[{"critere":"Cinq tags corrigés avec la bonne règle","points":10},{"critere":"Dialogue avec trois tags justes (affirmatif, négatif, impératif)","points":6},{"critere":"Trois étapes : auxiliaire, polarité inversée, pronom sujet","points":4}],"dureeMin":13,"corrige":"**A.**\n1. *You don't like fish, **do you**?* — phrase négative : tag affirmatif.\n2. *Everyone is ready, **aren't they**?* — sujet indéfini : on le reprend par *they*.\n3. *Tom and Mary have left, **haven't they**?* — sujet pluriel repris par *they*.\n4. *I'm right, **aren't I**?* — forme consacrée pour *I am*.\n5. *Let's start, **shall we**?*\n\n**B.** Exemple : *You're tired, aren't you? — You don't like tea, do you? — Open the window, will you?* Toute production correcte est acceptée.\n\n**C.** On reprend l'**auxiliaire** de la phrase (ou *do/does/did*), on **inverse la polarité** (affirmatif ↔ négatif), et on reprend le sujet sous forme de **pronom**."}$exo$::jsonb),
  ('c93c33d5-5821-52be-8a6f-7306d97cc9a7'::uuid, 1, 'traduction', $exo${"titre":"What ou how ?","consigne":"Complète, traduis et corrige.","enonce":"**A. Complète avec What ou How.**\n\n1. … a beautiful day!\n2. … fast he runs!\n3. … terrible weather!\n4. … strange!\n5. … an interesting book!\n6. … kind she is!\n\n**B. Traduis en anglais.** 7. Quel dommage !\n\n**C. Corrige.** 8. How beautiful is this place!","bareme":[{"critere":"Six mots exclamatifs justes (What, How, What, How, What, How)","points":12},{"critere":"Traduction 7 : What a pity ! (ou What a shame !)","points":4},{"critere":"Correction 8 : How beautiful this place is ! (sans inversion)","points":4}],"dureeMin":6,"corrige":"**A.** 1. *What* (a + nom) — 2. *How* (adverbe) — 3. *What* (nom indénombrable, sans article) — 4. *How* (adjectif) — 5. *What* (an + nom) — 6. *How* (adjectif).\n\n**B.** 7. *What a pity!* ou *What a shame!*\n\n**C.** 8. *How beautiful this place is!* L'anglais ne fait **pas d'inversion** dans l'exclamation : le sujet reste devant le verbe."}$exo$::jsonb),
  ('c93c33d5-5821-52be-8a6f-7306d97cc9a7'::uuid, 2, 'traduction', $exo${"titre":"So, such et transformations","consigne":"Réponds en anglais ; justifie brièvement le choix de so ou such.","enonce":"**A. Complète avec so, such ou such a.**\n\n1. It was … good film!\n2. She is … kind!\n3. They are … nice people!\n4. He runs … fast!\n\n**B. Transforme en exclamation avec what ou how.**\n\n5. This is a very big house.\n6. The children are very noisy.\n7. This is very bad weather.\n\n**C. Traduis en anglais.** 8. Comme c'est beau !","bareme":[{"critere":"Quatre so / such / such a justes","points":8},{"critere":"Trois exclamations transformées (What a big house ! How noisy the children are ! What bad weather !)","points":9},{"critere":"Traduction 8 : How beautiful ! (ou How beautiful it is !)","points":3}],"dureeMin":9,"corrige":"**A.** 1. *such a* (adjectif + nom singulier) — 2. *so* (adjectif seul) — 3. *such* (nom pluriel) — 4. *so* (adverbe).\n\n**B.** 5. *What a big house!* — 6. *How noisy the children are!* — 7. *What bad weather!* (indénombrable, sans article).\n\n**C.** 8. *How beautiful!* ou *How beautiful it is!* — jamais *How is it beautiful!*"}$exo$::jsonb),
  ('c93c33d5-5821-52be-8a6f-7306d97cc9a7'::uuid, 3, 'traduction', $exo${"titre":"Une carte postale enthousiaste","consigne":"Corrige puis rédige une carte postale ; justifie tes corrections en français.","enonce":"**A. Corrige et donne la règle.**\n\n1. What beautiful day!\n2. How is she tall!\n3. She is so a good singer.\n\n**B. Tu es en vacances à Londres. Écris une carte postale de quatre ou cinq lignes à un ami en utilisant obligatoirement :**\n\n- une exclamation avec *What a / What an* + nom ;\n- une exclamation avec *What* + nom pluriel ou indénombrable, sans article ;\n- une exclamation avec *How* + adjectif ou adverbe ;\n- une phrase avec *so* ou *such*.","bareme":[{"critere":"Trois phrases corrigées avec la règle (What a…, pas d'inversion, such a)","points":9},{"critere":"Quatre exclamations demandées correctes","points":8},{"critere":"Carte postale cohérente, sans inversion dans l'exclamation","points":3}],"dureeMin":14,"corrige":"**A.**\n1. *What **a** beautiful day!* — singulier dénombrable : *what a*.\n2. *How tall she **is**!* — pas d'inversion.\n3. *She is **such a** good singer.* — *so* ne s'emploie pas devant *a + nom* ; *such a* + adjectif + nom singulier.\n\n**B.** Exemple : *Dear Sam, London is amazing! What a big city! What lovely weather! How friendly the people are! It's such a great trip!* Toute production correcte respectant les quatre contraintes est acceptée."}$exo$::jsonb),
  ('49a7648e-c39b-5aa0-92a2-1c524fb71aae'::uuid, 1, 'traduction', $exo${"titre":"Passer à la voix passive","consigne":"Transforme chaque phrase à la voix passive, puis réponds à la dernière question en français.","enonce":"**Transforme à la voix passive.**\n\n1. They build houses.\n2. Shakespeare wrote *Hamlet*.\n3. They will open the shop tomorrow.\n4. Someone stole my bike.\n\n**5.** Pourquoi n'écrit-on pas *by someone* dans la phrase 4 ?","bareme":[{"critere":"Quatre phrases passives justes (are built, was written by, will be opened, was stolen)","points":16},{"critere":"Explication : l'auteur est inconnu, il est omis","points":4}],"dureeMin":7,"corrige":"1. *Houses **are built**.* — 2. *Hamlet **was written by** Shakespeare.* — 3. *The shop **will be opened** tomorrow.* — 4. *My bike **was stolen**.*\n\nRègle : *be* au temps de l'actif + participe passé ; l'objet devient sujet.\n\n5. L'auteur de l'action est **inconnu** (et sans intérêt) : le complément d'agent est omis, comme dans la grande majorité des phrases passives."}$exo$::jsonb),
  ('49a7648e-c39b-5aa0-92a2-1c524fb71aae'::uuid, 2, 'traduction', $exo${"titre":"Present perfect, modaux et erreurs","consigne":"Transforme et corrige en anglais ; justifie en français.","enonce":"**A. Transforme à la voix passive.**\n\n1. They have repaired the car.\n2. You can see the stars.\n3. The chef cooked the meal.\n\n**B. Corrige.**\n\n4. The window broken yesterday.\n5. The letter is sent yesterday.\n\n**C.** 6. Dans quels cas emploie-t-on la voix passive ? Donne deux raisons.","bareme":[{"critere":"Trois phrases passives justes (has been repaired, can be seen, was cooked by the chef)","points":9},{"critere":"Deux corrections (was broken ; was sent)","points":6},{"critere":"Deux raisons d'employer le passif (auteur inconnu, évident, ou on insiste sur l'action)","points":5}],"dureeMin":9,"corrige":"**A.** 1. *The car **has been repaired**.* — 2. *The stars **can be seen**.* — 3. *The meal **was cooked by the chef**.*\n\n**B.** 4. *The window **was** broken yesterday.* — *be* ne peut pas être oublié. 5. *The letter **was** sent yesterday.* — le temps de *be* suit le prétérit (*yesterday*).\n\n**C.** On emploie le passif quand l'auteur est **inconnu** (*My bike was stolen*), **évident** ou sans intérêt (*The shop is closed at six*), ou pour mettre en avant **ce qui a été fait** (textes scientifiques, journaux)."}$exo$::jsonb),
  ('49a7648e-c39b-5aa0-92a2-1c524fb71aae'::uuid, 3, 'traduction', $exo${"titre":"Double passif et texte scientifique","consigne":"Réponds en anglais ; justifie la dernière question en français.","enonce":"**A. Un verbe à deux compléments.** Écris les deux passifs possibles de *They gave me a prize.*, puis un passif de *They sent Lucy an invitation.*\n\n**B. Rédige le protocole d'une expérience.** Passe ces trois phrases à la voix passive, au même temps :\n\n1. Scientists heat the water to 100 °C.\n2. They add salt.\n3. They will measure the temperature.\n\n**C.** Pourquoi le passif est-il fréquent dans un texte scientifique ? Pourquoi *by scientists* est-il omis ?","bareme":[{"critere":"Double passif : I was given a prize / A prize was given to me ; Lucy was sent an invitation","points":7},{"critere":"Trois phrases passives justes (is heated, is added, will be measured)","points":9},{"critere":"Explication : on met en avant l'action, l'auteur est évident","points":4}],"dureeMin":13,"corrige":"**A.** *They gave me a prize.* → *I **was given** a prize.* (le plus courant) ou *A prize **was given** to me.* — *They sent Lucy an invitation.* → *Lucy **was sent** an invitation.* (ou *An invitation was sent to Lucy.*)\n\n**B.** 1. *The water **is heated** to 100 °C.* — 2. *Salt **is added**.* — 3. *The temperature **will be measured**.* (présent, présent, futur : *be* garde le temps de l'actif).\n\n**C.** Dans un texte scientifique, ce qui compte est **ce qui est fait**, pas qui le fait : on met l'action en avant. Le complément d'agent *by scientists* est évident, donc omis."}$exo$::jsonb),
  ('52817878-95bd-5024-ab4e-fb4e5ef65e70'::uuid, 1, 'traduction', $exo${"titre":"Comparer deux personnes","consigne":"Complète avec le comparatif de l'adjectif entre parenthèses, puis réponds à la dernière question en français.","enonce":"**Complète avec la forme correcte.**\n\n1. Tom is (tall) … than Ben.\n2. This bag is (expensive) … than that one.\n3. My sister is (happy) … than me.\n4. Today's weather is (bad) … than yesterday's.\n5. She is … tall … her brother. *(égalité)*\n\n**6.** Pourquoi *more taller* est-il faux ?","bareme":[{"critere":"Cinq comparatifs justes (taller, more expensive, happier, worse, as tall as)","points":15},{"critere":"Explication : on ne cumule pas -er et more","points":5}],"dureeMin":6,"corrige":"1. *taller* (adjectif court : -er). 2. *more expensive* (adjectif long). 3. *happier* (-y devient -ier). 4. *worse* (irrégulier de *bad*). 5. *as tall as* (égalité).\n\n6. Un adjectif prend **soit** -er (court), **soit** *more* (long), **jamais les deux** : *taller* ou *more intelligent*, mais pas *more taller*."}$exo$::jsonb),
  ('52817878-95bd-5024-ab4e-fb4e5ef65e70'::uuid, 2, 'traduction', $exo${"titre":"Less, fewer et structures utiles","consigne":"Réponds en anglais ; justifie brièvement en français quand c'est demandé.","enonce":"**A. Complète avec less ou fewer.**\n\n1. There are … cars than before.\n2. I have … money than you.\n\n**B. Traduis en anglais.**\n\n3. Il est de plus en plus grand.\n4. Plus tu t'entraînes, meilleur tu deviens.\n\n**C. Deux vélos.** Le vélo A coûte 200 £ et le vélo B 300 £. Écris trois phrases pour les comparer avec *cheaper*, *less expensive* et *not as expensive as*.","bareme":[{"critere":"Less / fewer : fewer cars, less money","points":4},{"critere":"Traduction 3 : He is bigger and bigger","points":4},{"critere":"Traduction 4 : The more you practise, the better you get","points":4},{"critere":"Trois phrases justes comparant les vélos","points":8}],"dureeMin":9,"corrige":"**A.** 1. *fewer* (dénombrable : *cars*) — 2. *less* (indénombrable : *money*).\n\n**B.** 3. *He is **bigger and bigger**.* — 4. ***The more** you practise, **the better** you get.*\n\n**C.** *Bike A is **cheaper than** bike B.* — *Bike A is **less expensive than** bike B.* — *Bike A is **not as expensive as** bike B.* (ou *Bike B is more expensive than bike A.*)"}$exo$::jsonb),
  ('52817878-95bd-5024-ab4e-fb4e5ef65e70'::uuid, 3, 'traduction', $exo${"titre":"Deux villes","consigne":"Rédige des phrases complètes en anglais ; justifie les corrections en français.","enonce":"**A. Voici deux villes imaginaires.**\n\n| | Northtown | Bigcity |\n|---|---|---|\n| Habitants | 20 000 | 500 000 |\n| Ambiance | calme | bruyante |\n| Prix | pas cher | cher |\n| Cinémas | 3 | 40 |\n\nÉcris **six phrases** comparant les villes, avec : un comparatif de supériorité en -er, un avec *more … than*, un d'infériorité avec *less*, un d'égalité (*as … as* ou *not as … as*), un avec *fewer* ou *less* + nom, et un avec l'irrégulier *better* ou *worse*.\n\n**B. Corrige et explique.**\n\n1. Bigcity is more bigger than Northtown.\n2. Northtown is not as noisy than Bigcity.","bareme":[{"critere":"Six phrases justes avec les six structures demandées","points":12},{"critere":"Phrases cohérentes avec les données du tableau","points":4},{"critere":"Deux corrections expliquées (bigger than ; as … as)","points":4}],"dureeMin":15,"corrige":"**A.** Exemples : *Bigcity is **bigger than** Northtown.* — *Bigcity is **more expensive than** Northtown.* — *Northtown is **less noisy than** Bigcity.* — *Northtown is **not as big as** Bigcity.* — *Northtown has **fewer** cinemas than Bigcity.* — *For a quiet life, Northtown is **better than** Bigcity.* Toute phrase juste et cohérente est acceptée.\n\n**B.**\n1. *Bigcity is **bigger than** Northtown.* — on ne cumule pas *more* et -er.\n2. *Northtown is not **as** noisy **as** Bigcity.* — l'égalité se construit avec **as … as**, jamais *as … than*."}$exo$::jsonb),
  ('a1312160-4dfc-578c-b5b2-2da7c5657ed5'::uuid, 1, 'traduction', $exo${"titre":"Le meilleur, le plus grand","consigne":"Complète avec le superlatif de l'adjectif entre parenthèses, puis réponds à la dernière question en français.","enonce":"**Complète avec la forme correcte.**\n\n1. Tom is (tall) … boy in the class.\n2. This is (expensive) … hotel in town.\n3. She is (happy) … girl I know.\n4. This is (good) … day of my life.\n5. It was (bad) … film of the year.\n\n**6.** Qu'est-ce qui manque dans *He is tallest boy in the class* ?","bareme":[{"critere":"Cinq superlatifs justes (the tallest, the most expensive, the happiest, the best, the worst)","points":15},{"critere":"Explication : l'article the est obligatoire","points":5}],"dureeMin":6,"corrige":"1. *the tallest* — 2. *the most expensive* — 3. *the happiest* — 4. *the best* — 5. *the worst*.\n\n6. Il manque l'article **the** : *He is **the** tallest boy in the class.* L'article est obligatoire devant un superlatif."}$exo$::jsonb),
  ('a1312160-4dfc-578c-b5b2-2da7c5657ed5'::uuid, 2, 'traduction', $exo${"titre":"In, of et expérience","consigne":"Réponds en anglais ; justifie la dernière question en français.","enonce":"**A. Complète avec in ou of.**\n\n1. It's the coldest day … the year.\n2. Emma is the tallest girl … the class.\n3. Ben is the tallest … the three.\n\n**B. Traduis en anglais.** 4. C'est le meilleur film que j'aie jamais vu.\n\n**C. Complète.**\n\n5. He is (tall) … of the two.\n6. He is (tall) … of the three.","bareme":[{"critere":"Trois prépositions justes (of, in, of)","points":6},{"critere":"Traduction 4 : the best film I have ever seen","points":6},{"critere":"Comparatif avec deux, superlatif avec trois (the taller, the tallest)","points":8}],"dureeMin":8,"corrige":"**A.** 1. *of* (période) — 2. *in* (groupe, lieu) — 3. *of* (ensemble de trois).\n\n**B.** 4. *It's **the best** film I **have ever seen**.* (superlatif + relative au present perfect pour l'expérience)\n\n**C.** 5. *the taller* (deux éléments : comparatif) — 6. *the tallest* (trois éléments : superlatif)."}$exo$::jsonb),
  ('a1312160-4dfc-578c-b5b2-2da7c5657ed5'::uuid, 3, 'traduction', $exo${"titre":"Le classement de la classe","consigne":"Rédige en anglais ; justifie tes corrections en français.","enonce":"**A. Voici quatre élèves.**\n\n| | Taille | Âge | Argent de poche |\n|---|---|---|---|\n| Amy | 1,55 m | 13 ans | 5 £ |\n| Ben | 1,62 m | 12 ans | 7 £ |\n| Cara | 1,48 m | 13 ans | 3 £ |\n| Dan | 1,70 m | 14 ans | 9 £ |\n\nÉcris **quatre phrases** au superlatif : une avec *the tallest*, une avec *the youngest*, une avec *the most* + nom, une avec *the least* + nom. Emploie *in* ou *of* dans au moins une phrase.\n\n**B.** Écris une phrase pour comparer Amy et Ben (*the … of the two*).\n\n**C. Corrige et explique.**\n\n1. Dan is the most tallest boy.\n2. Cara is taller girl in the class.","bareme":[{"critere":"Quatre superlatifs justes et cohérents avec le tableau","points":12},{"critere":"Phrase du comparatif : Ben is the taller of the two","points":2},{"critere":"Deux corrections expliquées (the tallest ; the taller… / the … in)","points":6}],"dureeMin":12,"corrige":"**A.** *Dan is **the tallest** boy in the class.* — *Ben is **the youngest** of the four.* — *Dan has **the most** pocket money.* — *Cara has **the least** money.* (Toute phrase juste et cohérente est acceptée.)\n\n**B.** *Ben is **the taller of the two**.* (deux éléments : comparatif)\n\n**C.**\n1. *Dan is **the tallest** boy.* — on ne cumule pas *most* et -est.\n2. *Cara is **the shortest** girl in the class.* — **the** est obligatoire, et *in* introduit un groupe (*Cara is taller girl* est fautif : ni comparatif ni superlatif)."}$exo$::jsonb),
  ('20deed1b-d518-5549-9c9f-3c0098217864'::uuid, 1, 'traduction', $exo${"titre":"Toujours, parfois, autrefois","consigne":"Écris des phrases correctes en anglais ; la dernière question est en français.","enonce":"**A. Place l'adverbe.**\n\n1. I go to school by bus. *(always)*\n2. He is late. *(never)*\n\n**B. Traduis en anglais.**\n\n3. Quand j'étais petit, je jouais au football (mais plus maintenant).\n\n**C. Complète.** 4. *Did you … to live here ?*","bareme":[{"critere":"Phrase 1 : I always go…","points":4},{"critere":"Phrase 2 : He is never late","points":4},{"critere":"Traduction avec used to + base verbale","points":6},{"critere":"Did you use to (sans -d après did)","points":6}],"dureeMin":6,"corrige":"1. *I **always** go to school by bus.* — l'adverbe se place **avant** le verbe lexical.\n2. *He is **never** late.* — l'adverbe se place **après** *be*.\n3. *I **used to play** football.* — habitude passée **révolue**, suivie de la base verbale.\n4. *Did you **use** to live here?* — après *did*, on écrit *use* sans -d."}$exo$::jsonb),
  ('20deed1b-d518-5549-9c9f-3c0098217864'::uuid, 2, 'traduction', $exo${"titre":"Used to, be used to, get used to","consigne":"Complète avec la forme correcte du verbe entre parenthèses ; justifie la dernière question en français.","enonce":"**A. Complète.**\n\n1. I used to (play) … football when I was ten.\n2. She is used to (get up) … early.\n3. I'm getting used to (live) … in London.\n4. He didn't use to (like) … fish.\n5. Every summer, we would (go) … to the beach.\n\n**B.** 6. Pourquoi *I would be shy* est-il faux pour parler d'un état passé ?","bareme":[{"critere":"Cinq formes justes (play, getting up, living, like, go)","points":15},{"critere":"Explication : would ne s'emploie pas pour un état, used to oui","points":5}],"dureeMin":8,"corrige":"1. *play* (*used to* + base verbale) — 2. *getting up* (*be used to* + -ING) — 3. *living* (*get used to* + -ING) — 4. *like* (après *didn't use to*, base verbale) — 5. *go* (*would* + base verbale, action répétée).\n\n6. *Would* exprime une habitude passée pour des **actions répétées**, jamais pour un **état** : on écrit *I **used to** be shy*."}$exo$::jsonb),
  ('20deed1b-d518-5549-9c9f-3c0098217864'::uuid, 3, 'traduction', $exo${"titre":"Lina change de vie","consigne":"Rédige des phrases complètes en anglais ; explique en français quand c'est demandé.","enonce":"**Situation.** Le mois dernier, Lina a quitté son village pour une grande ville.\n\n**A.** Écris **deux phrases** avec *used to* sur sa vie d'avant.\n**B.** Écris **une phrase** avec *would* pour une action répétée de son enfance (chaque été…).\n**C.** Écris **deux phrases** sur ses habitudes actuelles avec un adverbe de fréquence.\n**D.** Écris **une phrase** avec *be used to* ou *get used to* + -ING pour sa nouvelle vie.\n**E.** Explique la différence entre *I used to swim* et *I am used to swimming*.","bareme":[{"critere":"Deux phrases justes avec used to + base verbale","points":4},{"critere":"Phrase avec would : action répétée, pas un état","points":3},{"critere":"Deux habitudes présentes avec adverbe bien placé","points":4},{"critere":"Phrase avec be/get used to + -ING","points":4},{"critere":"Explication de la différence de sens et de construction","points":5}],"dureeMin":12,"corrige":"**A.** *She **used to live** in a small village. She **used to walk** to school.*\n**B.** *Every summer, she **would go** to her grandmother's farm.* (jamais *would* pour un état)\n**C.** *She **usually takes** the bus. She is **often** tired in the evening.* (adverbe avant le verbe lexical, après *be*)\n**D.** *She **is getting used to living** in a big city.* (ou *She is used to taking the metro.*)\n**E.** *I used to swim* : habitude passée **révolue** (avant, plus maintenant), suivie de la **base verbale**. *I am used to swimming* : je suis **habitué** à nager, aujourd'hui, suivi de **-ING**."}$exo$::jsonb),
  ('29cafe3f-cc1c-54b3-8d40-11e6aff359e9'::uuid, 1, 'traduction', $exo${"titre":"Pourquoi fais-tu cela ?","consigne":"Complète avec to, for ou so as, puis corrige et explique en français.","enonce":"**A. Complète avec to, for ou so as.**\n\n1. I went to the shop … buy bread.\n2. I went to the shop … bread.\n3. This knife is … cutting bread.\n4. I wrote it down … not to forget.\n\n**B. Corrige et explique.** 5. I went to the shop for buying bread.","bareme":[{"critere":"Quatre mots justes (to, for, for, so as)","points":12},{"critere":"Correction de la phrase 5 (to buy bread)","points":4},{"critere":"Explication : pour le but d'une action, to + base verbale","points":4}],"dureeMin":6,"corrige":"**A.** 1. *to* (but, même sujet). 2. *for* (+ nom : aller chercher). 3. *for* (+ -ING : à quoi sert l'objet). 4. *so as* (but négatif : *so as not to*).\n\n**B.** 5. *I went to the shop **to buy** bread.* — Pour dire le but d'une action, on emploie **to + base verbale**, jamais *for + verbe*."}$exo$::jsonb),
  ('29cafe3f-cc1c-54b3-8d40-11e6aff359e9'::uuid, 2, 'traduction', $exo${"titre":"So that ou to ?","consigne":"Relie ou traduis en anglais.","enonce":"**A. Relie les deux phrases avec l'expression demandée.**\n\n1. She saved money. Her son could study abroad. *(so that)*\n2. I'll speak slowly. You can understand. *(so that)*\n3. He left early. He wanted to catch the train. *(in order to)*\n\n**B. Traduis en anglais.** 4. Il l'a écrit pour ne pas oublier.\n\n**C. Réponds à la question avec une réponse courte commençant par To.** 5. Why did you call? *(tu voulais lui poser une question)*","bareme":[{"critere":"Phrase 1 : so that + proposition avec could","points":4},{"critere":"Phrase 2 : so that + can","points":4},{"critere":"Phrase 3 : in order to + base verbale","points":4},{"critere":"Traduction 4 : so as not to / in order not to forget","points":4},{"critere":"Réponse 5 : To ask you something","points":4}],"dureeMin":8,"corrige":"1. *She saved money **so that** her son **could** study abroad.* — le but concerne **un autre sujet** : proposition complète, souvent avec un modal.\n2. *I'll speak slowly **so that** you **can** understand.*\n3. *He left early **in order to catch** the train.* — même sujet : *in order to* + base verbale.\n4. *He wrote it down **so as not to forget**.* (ou *in order not to forget*) — le but négatif se dit avec *so as not to*.\n5. *To ask you something.*"}$exo$::jsonb),
  ('29cafe3f-cc1c-54b3-8d40-11e6aff359e9'::uuid, 3, 'traduction', $exo${"titre":"Choisir la bonne construction","consigne":"Réponds en anglais ; justifie chaque choix de la partie A en une phrase française.","enonce":"**A. Complète avec la construction qui convient et justifie.**\n\n1. I study hard … my parents are proud of me.\n2. She took a coat … catch a cold.\n3. I use this app … learning English.\n\n**B. Écris quatre phrases exprimant un but :**\n\n- une avec *to* + base verbale ;\n- une avec *in order to* ;\n- une avec *so that* + modal ;\n- une avec *so as not to*.\n\n**C. Corrige et explique.** 4. I called him for asking a question.","bareme":[{"critere":"Trois constructions justes et justifiées (so that … will/can, so as not to, for)","points":6},{"critere":"Quatre phrases de but correctes, une par construction","points":8},{"critere":"Correction 4 (to ask) et règle","points":6}],"dureeMin":13,"corrige":"**A.**\n1. *so that* my parents **will** be proud (ou *can be*) — le but concerne un autre sujet.\n2. *so as not to* catch a cold — but **négatif**, même sujet.\n3. *for* — *for* + -ING dit à quoi sert un objet : *I use this app **for learning** English.*\n\n**B.** Exemples : *I went to town to buy shoes.* — *He left early in order to catch the train.* — *I'll speak slowly so that you can understand.* — *I wrote it down so as not to forget.*\n\n**C.** 4. *I called him **to ask** a question.* — le but d'une action se dit avec **to + base verbale**, jamais *for + -ING*."}$exo$::jsonb),
  ('2e15b697-2e2a-56a6-8320-eabcbfab245f'::uuid, 1, 'traduction', $exo${"titre":"For ou since ?","consigne":"Complète avec for, since ou ago, puis réponds à la dernière question en français.","enonce":"**Complète.**\n\n1. I have lived here … five years.\n2. She has worked here … 2020.\n3. I met him three years … .\n4. We have waited … Monday.\n5. He has been ill … two days.\n\n**6.** Quel test permet de choisir entre *for* et *since* ?","bareme":[{"critere":"Cinq mots justes (for, since, ago, since, for)","points":15},{"critere":"Test : combien de temps ? → for ; depuis quand ? → since","points":5}],"dureeMin":6,"corrige":"1. *for* (durée) — 2. *since* (point de départ) — 3. *ago* (après la durée, avec le prétérit) — 4. *since* (point de départ) — 5. *for* (durée).\n\n6. On se demande : **combien de temps ?** → *for* ; **depuis quand ?** → *since*."}$exo$::jsonb),
  ('2e15b697-2e2a-56a6-8320-eabcbfab245f'::uuid, 2, 'traduction', $exo${"titre":"Trois mots pour « depuis »","consigne":"Complète et traduis en anglais ; justifie brièvement le point 5 en français.","enonce":"**A. Complète avec for, since, ago ou during.**\n\n1. It's been two years … I saw him.\n2. We swam every day … the holidays.\n3. I stayed there … two hours.\n\n**B. Traduis en anglais.**\n\n4. J'habite ici depuis cinq ans.\n5. Je l'ai rencontré il y a trois ans.\n6. Depuis combien de temps es-tu ici ?\n\n**C.** 7. Pourquoi ne peut-on pas dire *I have met him three years ago* ?","bareme":[{"critere":"Trois mots justes (since, during, for)","points":6},{"critere":"Traductions 4, 5 et 6 correctes (temps et mot de durée)","points":12},{"critere":"Explication : ago se construit avec le prétérit","points":2}],"dureeMin":8,"corrige":"**A.** 1. *since* (*It's been … since*) — 2. *during* (+ nom : *the holidays*) — 3. *for* (durée : *two hours*, jamais *during two hours*).\n\n**B.** 4. *I have lived here **for** five years.* — 5. *I met him three years **ago**.* — 6. ***How long** have you been here?*\n\n**C.** 7. *Ago* désigne un moment précis du passé, terminé : il s'emploie **toujours avec le prétérit** (*I met him three years ago*)."}$exo$::jsonb),
  ('2e15b697-2e2a-56a6-8320-eabcbfab245f'::uuid, 3, 'traduction', $exo${"titre":"Un message à corriger","consigne":"Corrige, rédige, puis explique en français.","enonce":"**A. Ce message d'un correspondant contient quatre erreurs. Corrige-les et donne la règle.**\n\n> I live here since 2019. I have moved to this town five years ago. Last year I stayed in London during three weeks. When have you arrived here ?\n\n**B. Écris trois phrases sur toi : une avec *for*, une avec *since*, une avec *ago*.**\n\n**C.** Explique la différence entre *How long have you been here?* et *When did you arrive?*","bareme":[{"critere":"Quatre erreurs corrigées avec la règle","points":12},{"critere":"Trois phrases justes avec for, since et ago","points":6},{"critere":"Différence entre how long (durée) et when (moment précis)","points":2}],"dureeMin":12,"corrige":"**A.**\n1. *I **have lived** here since 2019.* — *since* se construit avec le present perfect.\n2. *I **moved** to this town five years ago.* — *ago* se construit avec le prétérit.\n3. *…I stayed in London **for** three weeks.* — *during* + nom (*during the holidays*) ; devant une durée, on emploie *for*.\n4. *When **did** you arrive here?* — moment précis : prétérit.\n\n**B.** Exemple : *I have studied English for four years. — I have lived here since 2020. — I started school ten years ago.*\n\n**C.** *How long…* interroge la **durée** d'une situation en cours ; *When did…* demande le **moment précis** d'un fait passé."}$exo$::jsonb),
  ('69d931a0-9043-5259-843c-6ea1cf12af86'::uuid, 1, 'traduction', $exo${"titre":"Rapporter ce qu'on a dit","consigne":"Transforme au discours indirect (verbe introducteur au passé) ; complète la dernière phrase.","enonce":"**Transforme au discours indirect.**\n\n1. « I am tired, » he said.\n2. « I like pizza, » she said.\n3. « I can swim, » Tom said.\n4. « I saw her, » Mia said.\n5. « I will help you, » Sam said to me.\n\n**6.** Complète avec *said* ou *told* : *He … me that he was tired.*","bareme":[{"critere":"Cinq phrases justes (was tired, liked, could, had seen, would help me)","points":15},{"critere":"said ou told : told (complément de personne)","points":5}],"dureeMin":7,"corrige":"1. *He said he **was** tired.* — 2. *She said she **liked** pizza.* — 3. *Tom said he **could** swim.* — 4. *Mia said she **had seen** her.* — 5. *Sam said he **would** help me.*\n\n6. *He **told** me…* : *tell* exige un complément de personne, *say* n'en prend pas."}$exo$::jsonb),
  ('69d931a0-9043-5259-843c-6ea1cf12af86'::uuid, 2, 'traduction', $exo${"titre":"Questions, ordres et repères","consigne":"Transforme au discours indirect, verbe introducteur au passé.","enonce":"1. « Where do you live? » he asked me.\n2. « Are you ready? » he asked me.\n3. « Close the door, » she told me.\n4. « Don't be late, » she told me.\n5. « I lost my keys yesterday, » she said.","bareme":[{"critere":"Question ouverte : where I lived (ordre affirmatif)","points":4},{"critere":"Question fermée avec if ou whether","points":4},{"critere":"Ordre : to close the door","points":4},{"critere":"Ordre négatif : not to be late","points":4},{"critere":"Recul des temps et repères : had lost … the day before","points":4}],"dureeMin":9,"corrige":"1. *He asked me **where I lived**.* — ordre de l'affirmative, pas de *do*.\n2. *He asked me **if / whether I was** ready.* — question fermée : *if* ou *whether*.\n3. *She told me **to close** the door.* — ordre : *tell* + complément + *to* + base verbale.\n4. *She told me **not to be** late.* — négation : *not to*.\n5. *She said she **had lost** her keys **the day before**.* — prétérit → past perfect ; *yesterday* → *the day before*, *my* → *her*."}$exo$::jsonb),
  ('69d931a0-9043-5259-843c-6ea1cf12af86'::uuid, 3, 'traduction', $exo${"titre":"Une conversation rapportée","consigne":"Rapporte chaque réplique au discours indirect, avec un verbe introducteur au passé, puis explique en français.","enonce":"**Dialogue écrit pour l'exercice.**\n\n> **Mia :** « I'm making a cake for my brother today. »\n> **Sam :** « Have you bought the eggs? »\n> **Mia :** « No, I haven't. Can you come with me to the shop now? »\n> **Sam :** « Wait here. Don't go without me. »\n\n**A. Rapporte :**\n\n1. la première réplique de Mia ;\n2. la question de Sam ;\n3. la réponse « No, I haven't » ;\n4. la question de Mia (« Can you come… now ? ») ;\n5. les deux ordres de Sam.\n\n**B.** Explique pourquoi le recul des temps ne s'applique pas dans *He says he is tired*.","bareme":[{"critere":"Répliques 1 et 3 : was making … that day, her brother ; she hadn't","points":7},{"critere":"Question de Sam : if/whether she had bought the eggs","points":4},{"critere":"Question 4 : if he could come … to the shop then","points":4},{"critere":"Ordres 5 : to wait there ; not to go without him","points":3},{"critere":"Explication : verbe introducteur au présent","points":2}],"dureeMin":14,"corrige":"1. *Mia said she **was making** a cake for her brother **that day**.* (*today* → *that day*, *my* → *her*)\n2. *Sam asked her **if / whether she had bought** the eggs.* (present perfect → past perfect ; ordre affirmatif)\n3. *She said she **hadn't**.* (ou *She said that she hadn't bought them.*)\n4. *She asked him **if he could** come with her to the shop **then**.* (*can* → *could* ; *now* → *then*)\n5. *He told her **to wait there** and **not to go** without him.* (ordres : *tell* + complément + *to* + base verbale ; *here* → *there*)\n\n**B.** Le recul des temps n'a lieu que si le verbe introducteur est au **passé**. Avec *says* (présent), on garde le temps du discours direct."}$exo$::jsonb),
  ('95f5a069-6fbd-5984-a10f-853c99fba68a'::uuid, 1, 'traduction', $exo${"titre":"Pluriels et indénombrables","consigne":"Écris le pluriel, puis réponds aux questions.","enonce":"**A. Écris le pluriel.**\n\n1. box   2. city   3. leaf   4. child   5. sheep   6. boy\n\n**B.** 7. Parmi *water*, *book*, *advice*, *table*, *news*, lesquels sont indénombrables ?\n\n**C.** 8. Complète : *The news … good.* (is / are)","bareme":[{"critere":"Six pluriels justes (boxes, cities, leaves, children, sheep, boys)","points":12},{"critere":"Trois indénombrables : water, advice, news","points":4},{"critere":"is, car news est indénombrable donc singulier","points":4}],"dureeMin":6,"corrige":"**A.** 1. *boxes* — 2. *cities* (consonne + y) — 3. *leaves* — 4. *children* — 5. *sheep* (inchangé) — 6. *boys* (voyelle + y : simple -s).\n\n**B.** 7. *water*, *advice*, *news* : pas de pluriel, pas de *a/an*.\n\n**C.** 8. *The news **is** good.* — un indénombrable prend toujours le verbe au singulier."}$exo$::jsonb),
  ('95f5a069-6fbd-5984-a10f-853c99fba68a'::uuid, 2, 'traduction', $exo${"titre":"Faux amis et partitifs","consigne":"Corrige et traduis ; justifie brièvement les corrections.","enonce":"**A. Corrige chaque phrase et explique.**\n\n1. I need an advice.\n2. The news are bad.\n3. She gave me many informations.\n4. We bought two furnitures.\n\n**B. Traduis en anglais.**\n\n5. un conseil ; un verre d'eau.\n6. les livres des élèves ; le téléphone de ma sœur.","bareme":[{"critere":"Quatre phrases corrigées avec la règle des indénombrables","points":12},{"critere":"Partitifs : a piece of advice ; a glass of water","points":4},{"critere":"Génitifs : the students' books ; my sister's phone","points":4}],"dureeMin":9,"corrige":"**A.**\n1. *I need **some advice** / **a piece of advice**.* — *advice* est indénombrable : pas de *a*.\n2. *The news **is** bad.* — verbe au singulier.\n3. *…**a lot of information** / **much information**.* — *information* est indénombrable, sans -s ni *many*.\n4. *…**two pieces of furniture**.* — *furniture* est indénombrable ; pour le compter, il faut un partitif.\n\n**B.** 5. *a **piece of** advice* ; *a **glass of** water*. — 6. *the **students'** books* (pluriel en -s : apostrophe seule) ; *my **sister's** phone*."}$exo$::jsonb),
  ('95f5a069-6fbd-5984-a10f-853c99fba68a'::uuid, 3, 'traduction', $exo${"titre":"Un message pour Kate qui déménage","consigne":"Rédige un message en anglais d'environ six lignes.","enonce":"**Situation.** Ton amie Kate déménage dans une nouvelle maison. Écris-lui un message de six lignes environ. Tu dois utiliser :\n\n- au moins **trois noms indénombrables** parmi *advice, news, information, furniture, homework, water, money* ;\n- **deux pluriels irréguliers** (*children, men, women, feet, teeth, people, mice…*) ;\n- **un partitif** (*a piece of, a glass of…*) avec le verbe au singulier quand il le faut ;\n- **un génitif** (*Kate's room*, *the children's toys*…).","bareme":[{"critere":"Trois indénombrables employés correctement (sans article a, sans -s, verbe au singulier)","points":6},{"critere":"Deux pluriels irréguliers corrects","points":4},{"critere":"Un partitif correct","points":4},{"critere":"Un génitif correct (’s ou s’)","points":3},{"critere":"Message cohérent et compréhensible","points":3}],"dureeMin":13,"corrige":"Exemple de production attendue :\n\n*Hi Kate! I have some great **news**: my parents can lend you our old **furniture**. Here is a **piece of advice**: pack the **children's** toys first. Ask the **people** next door for some **information** about the neighbourhood. **Kate's** new room looks big! See you soon.*\n\nPoints de vigilance : *news* et *furniture* prennent le verbe au **singulier** ; *advice* et *information* n'ont ni *a* ni pluriel ; on compte avec un partitif (*a piece of advice*) ; *children's*, pluriel irrégulier, prend *'s*. Toute production correcte respectant les consignes est acceptée."}$exo$::jsonb),
  ('eb8cfd70-8778-534a-9f8c-f96bc31d179e'::uuid, 1, 'traduction', $exo${"titre":"A, an, the ou rien","consigne":"Complète avec a, an, the ou ∅ (pas d'article), puis explique en français.","enonce":"**Complète.**\n\n1. … apple\n2. … university\n3. … hour\n4. I bought … car. … car is red.\n5. I play … piano.\n6. I play … football.\n\n**7.** Pourquoi dit-on *an hour* et *a university* ?","bareme":[{"critere":"Trois articles justes (an, a, an)","points":6},{"critere":"Phrase 4 : a car, The car","points":4},{"critere":"Piano avec the, football sans article","points":4},{"critere":"Explication : c'est le son (voyelle ou consonne) qui décide, pas la lettre","points":6}],"dureeMin":6,"corrige":"1. *an apple* — 2. *a university* — 3. *an hour*.\n4. *I bought **a** car. **The** car is red.* — première mention : *a* ; deuxième mention : *the*.\n5. *I play **the** piano.* — un instrument prend *the*. 6. *I play football.* — un sport ne prend pas d'article.\n\n7. C'est le **son** initial qui décide : *hour* commence par un son de voyelle (le h ne se prononce pas) → *an* ; *university* commence par le son consonne [j] → *a*."}$exo$::jsonb),
  ('eb8cfd70-8778-534a-9f8c-f96bc31d179e'::uuid, 2, 'traduction', $exo${"titre":"Article défini, indéfini ou zéro","consigne":"Complète avec a, an, the ou ∅, puis traduis.","enonce":"**A. Complète.**\n\n1. She is … dentist.\n2. Twice … week.\n3. … sun is hot.\n4. I like … dogs.\n5. We have … breakfast at eight.\n6. She lives near … Thames.\n7. They live in … Netherlands.\n8. … water is essential.\n\n**B. Traduis en anglais.**\n\n9. Elle va à l'école *(elle est élève)*.\n10. Elle va à l'école *(le bâtiment précis, pour voir le directeur)*.","bareme":[{"critere":"Huit articles justes (a, a, The, ∅, ∅, the, the, ∅)","points":16},{"critere":"Traductions 9 et 10 : goes to school / goes to the school","points":4}],"dureeMin":8,"corrige":"1. *a* (métier) — 2. *a* (fréquence) — 3. *The* (objet unique) — 4. ∅ (pluriel au sens général) — 5. ∅ (repas) — 6. *the* (fleuve) — 7. *the* (pays au pluriel) — 8. ∅ (indénombrable au sens général).\n\n**B.** 9. *She goes to school.* (pour étudier) — 10. *She goes to **the** school.* (le bâtiment précis)"}$exo$::jsonb),
  ('eb8cfd70-8778-534a-9f8c-f96bc31d179e'::uuid, 3, 'traduction', $exo${"titre":"Un texte à compléter","consigne":"Complète le texte avec a, an, the ou ∅, puis justifie deux de tes choix en français.","enonce":"> Yesterday I met **(1)** … new student at **(2)** … school. **(3)** … boy is from **(4)** … France. He plays **(5)** … guitar and **(6)** … tennis. He has **(7)** … older sister, who is a nurse. We had **(8)** … lunch together.\n\n**B.** Justifie tes choix pour **(2)** et **(5)/(6)**.","bareme":[{"critere":"Huit articles justes (a, ∅, The, ∅, the, ∅, an, ∅)","points":16},{"critere":"Justification de (2) : at school = pour étudier","points":2},{"critere":"Justification de (5)/(6) : instrument avec the, sport sans article","points":2}],"dureeMin":8,"corrige":"(1) *a* — première mention d'un élève. (2) ∅ — *at school* : en tant qu'élève. (3) *The* — le garçon dont on vient de parler. (4) ∅ — nom de pays. (5) *the* — un instrument prend *the*. (6) ∅ — un sport ne prend pas d'article. (7) *an* — son de voyelle (*older*). (8) ∅ — un repas.\n\n**B.** *At school* sans article parce qu'on parle de l'élève qui étudie ; *the guitar* car un instrument prend *the*, mais *tennis* est un sport : pas d'article."}$exo$::jsonb),
  ('4b7c35f2-4a0a-56d3-98d2-af6a7a425f9a'::uuid, 1, 'traduction', $exo${"titre":"This, that, these, those","consigne":"Complète avec this, that, these ou those ; corrige et explique la dernière question en français.","enonce":"**Complète.**\n\n1. … book in my hand is interesting. *(près, singulier)*\n2. … house over there is old. *(loin, singulier)*\n3. … shoes are new. *(près, pluriel)*\n4. … were the days. *(loin, pluriel)*\n5. Hello, … is Paul speaking. *(au téléphone)*\n\n**6.** Pourquoi n'écrit-on jamais *thoses* ?","bareme":[{"critere":"Cinq démonstratifs justes (This, That, These, Those, this)","points":15},{"critere":"Explication : those est déjà le pluriel de that","points":5}],"dureeMin":5,"corrige":"1. *This* — 2. *That* — 3. *These* — 4. *Those* — 5. *this* (au téléphone, l'anglais dit *this is* pour « c'est »).\n\n6. *Those* est **déjà** le pluriel de *that* : les démonstratifs ne prennent pas de -s supplémentaire."}$exo$::jsonb),
  ('4b7c35f2-4a0a-56d3-98d2-af6a7a425f9a'::uuid, 2, 'traduction', $exo${"titre":"Accord en nombre","consigne":"Complète, transforme et traduis en anglais.","enonce":"1. Complète : … children are noisy. *(proches de toi)*\n2. Mets au pluriel : *This book is interesting.*\n3. Mets au pluriel : *That house is old.*\n4. Traduis : Voici ma sœur Kate. *(tu la présentes)*\n5. Dans *This is my car* et dans *I prefer these*, dis si le démonstratif est adjectif ou pronom.","bareme":[{"critere":"These children : accord en nombre et proximité","points":4},{"critere":"These books are interesting","points":4},{"critere":"Those houses are old (verbe au pluriel)","points":4},{"critere":"This is my sister, Kate","points":4},{"critere":"Adjectif ou pronom : This est pronom ; these est pronom","points":4}],"dureeMin":7,"corrige":"1. *These* children are noisy. — 2. *These books are interesting.* — 3. *Those houses are old.* — 4. *This is my sister, Kate.* (l'anglais présente avec *this*.)\n\n5. Dans *This is my car*, *this* est **pronom** (il n'est pas suivi d'un nom). Dans *I prefer these*, *these* est aussi **pronom** (employé seul). Un adjectif serait suivi d'un nom : *this car*."}$exo$::jsonb),
  ('4b7c35f2-4a0a-56d3-98d2-af6a7a425f9a'::uuid, 3, 'traduction', $exo${"titre":"Une photo à présenter","consigne":"Rédige en anglais ; justifie les corrections en français.","enonce":"**A.** Tu montres une photo de vacances à un ami. Écris **cinq phrases** :\n\n- une avec **this**, une avec **that**, une avec **these**, une avec **those** ;\n- une phrase de **présentation** d'une personne (*This is…*) ;\n- une expression de temps avec un démonstratif (*this morning*, *that summer*…).\n\n(La phrase de présentation ou de temps peut aussi contenir l'un des quatre démonstratifs demandés.)\n\n**B. Corrige et explique.**\n\n1. This shoes are new.\n2. Thoses were the days.","bareme":[{"critere":"Quatre démonstratifs justes, avec la bonne distance et le bon nombre","points":8},{"critere":"Phrase de présentation avec this is","points":3},{"critere":"Expression de temps correcte avec un démonstratif","points":3},{"critere":"Deux corrections expliquées (These ; Those)","points":4},{"critere":"Phrases cohérentes","points":2}],"dureeMin":10,"corrige":"**A.** Exemples : *This photo is my favourite.* — *That castle over there is huge.* — *These flowers are beautiful.* — *Those people are my cousins.* — *This is my friend Leo.* — *We visited that castle **that summer**.* — *This morning, we went to the beach.* Toute production correcte est acceptée.\n\n**B.**\n1. *These shoes are new.* — le démonstratif s'accorde en nombre avec le nom : pluriel → *these*.\n2. *Those were the days.* — *those* est déjà un pluriel : jamais de -s ajouté."}$exo$::jsonb),
  ('b6622973-3f5e-5526-929b-44578e7e4244'::uuid, 1, 'traduction', $exo${"titre":"À qui est-ce ?","consigne":"Réécris avec le génitif ou complète avec le possessif qui convient.","enonce":"**A. Réécris avec 's, s' ou of.**\n\n1. The bike of my brother\n2. The room of the girls\n3. The toys of the children\n4. The roof of the house\n\n**B. Complète avec le possessif qui convient.**\n\n5. This book is (I) … .\n6. (She) … bag is red.\n7. Kate and … brother are here. *(le frère de Kate)*\n8. The dog wagged … tail.","bareme":[{"critere":"Quatre groupes justes (my brother's bike, the girls' room, the children's toys, the roof of the house)","points":12},{"critere":"Trois possessifs justes (mine, Her, her)","points":6},{"critere":"its sans apostrophe","points":2}],"dureeMin":7,"corrige":"**A.** 1. *my brother**'s** bike* — 2. *the girls**'** room* (pluriel en -s : apostrophe seule) — 3. *the children**'s** toys* (pluriel irrégulier : ’s) — 4. *the roof **of** the house* (objet : structure avec *of*).\n\n**B.** 5. *mine* (pronom) — 6. *Her* — 7. *her* (possesseur : Kate) — 8. *its* (sans apostrophe : *it's* = *it is*)."}$exo$::jsonb),
  ('b6622973-3f5e-5526-929b-44578e7e4244'::uuid, 2, 'traduction', $exo${"titre":"Corriger et traduire","consigne":"Corrige chaque phrase et explique ; puis traduis et réponds.","enonce":"**A. Corrige et explique.**\n\n1. This is mine book.\n2. The dog is chasing it's tail.\n3. Kate and his brother are here. *(le frère de Kate)*\n4. The roof's house is red.\n\n**B.** 5. — *Whose bag is this?* (elle appartient à Kate) Écris la réponse.\n\n**C. Traduis en anglais.** 6. La voiture de mon père.","bareme":[{"critere":"Quatre phrases corrigées avec la règle (my book, its, her, of)","points":12},{"critere":"Réponse 5 : It's Kate's","points":4},{"critere":"Traduction 6 : my father's car","points":4}],"dureeMin":8,"corrige":"**A.**\n1. *This is **my** book* ou *This book is **mine**.* — un pronom possessif n'est jamais suivi d'un nom.\n2. *…chasing **its** tail.* — *it's* = *it is* ; le possessif est *its*.\n3. *Kate and **her** brother…* — le possessif s'accorde avec le possesseur (Kate : *her*).\n4. *The roof **of** the house…* — pour un objet, on emploie *of*, pas le génitif.\n\n**B.** 5. *It's **Kate's**.*\n\n**C.** 6. *My **father's** car.* — le possesseur d'abord, l'ordre est inversé par rapport au français."}$exo$::jsonb),
  ('b6622973-3f5e-5526-929b-44578e7e4244'::uuid, 3, 'traduction', $exo${"titre":"Les objets trouvés","consigne":"Rédige en anglais ; explique en français quand c'est demandé.","enonce":"**Situation.** Après une fête, on range des objets oubliés.\n\n**A. Écris cinq phrases :**\n\n1. un génitif singulier (*Ben's…*) ;\n2. un génitif avec un pluriel en -s ;\n3. une structure avec *of* pour un objet ;\n4. un pronom possessif (*mine, yours, hers…*) ;\n5. un emploi de *its* (possessif).\n\n**B.** Écris un mini-dialogue de deux répliques avec *Whose … is this ?*\n\n**C.** Pourquoi dit-on *the leg of the table* et *my brother's leg* ?\n\n**D.** Traduis : *le journal d'aujourd'hui*.","bareme":[{"critere":"Cinq phrases justes (génitif, s', of, pronom possessif, its)","points":10},{"critere":"Dialogue avec Whose et réponse en 's ou pronom","points":4},{"critere":"Explication : génitif pour les êtres animés, of pour les objets","points":3},{"critere":"Traduction : today's newspaper","points":3}],"dureeMin":12,"corrige":"**A.** Exemples : *This is Ben**'s** jacket.* — *These are the boys**'** boots.* — *Where is the door **of** the room?* — *This scarf is **mine**.* — *The cat licked **its** paw.*\n\n**B.** *Whose phone is this? — It's Sara's.* (ou *It's hers.*)\n\n**C.** Le génitif ’s s'emploie surtout avec des **êtres animés** (personnes, animaux) ; pour un **objet**, on emploie la structure avec *of*.\n\n**D.** *today**'s** newspaper* — le génitif s'emploie aussi avec des expressions de temps."}$exo$::jsonb),
  ('e51207eb-106e-5801-b2c8-47305f9420ae'::uuid, 1, 'traduction', $exo${"titre":"Some, any, much, many","consigne":"Complète avec some, any, much ou many, puis réponds à la dernière question en français.","enonce":"**Complète.**\n\n1. I have … money.\n2. I don't have … money.\n3. Would you like … tea?\n4. Is there … milk in the fridge?\n5. How … water do you drink?\n6. How … books have you got?\n\n**7.** Que signifie *any* dans *Take any book you like* ?","bareme":[{"critere":"Six quantifieurs justes (some, any, some, any, much, many)","points":18},{"critere":"Any en affirmative : n'importe quel","points":2}],"dureeMin":6,"corrige":"1. *some* (affirmative) — 2. *any* (négative) — 3. *some* (offre polie) — 4. *any* (interrogative) — 5. *much* (*water* est indénombrable) — 6. *many* (*books* : dénombrable pluriel).\n\n7. En affirmative, *any* veut dire « **n'importe quel** »."}$exo$::jsonb),
  ('e51207eb-106e-5801-b2c8-47305f9420ae'::uuid, 2, 'traduction', $exo${"titre":"Peu ou un peu ?","consigne":"Complète, puis explique et traduis.","enonce":"**A. Complète avec a few, few, a little, little, enough ou too many.**\n\n1. There is … milk left: we can make pancakes.\n2. There is … milk left: we can't make pancakes.\n3. I have … friends here: I feel lonely.\n4. I have … friends here: I'm happy.\n5. I don't have … money to buy a bike.\n6. There are … people in the bus: I can't sit down.\n\n**B.** 7. Explique la différence entre *a few* et *few*.\n\n**C. Traduis en anglais.** 8. Chaque élève a un livre.","bareme":[{"critere":"Six quantifieurs justes (a little, little, few, a few, enough, too many)","points":12},{"critere":"Explication : a few rassure, few inquiète (trop peu)","points":4},{"critere":"Traduction : Every student has a book (verbe au singulier)","points":4}],"dureeMin":9,"corrige":"**A.** 1. *a little* — 2. *little* — 3. *few* — 4. *a few* — 5. *enough* — 6. *too many*.\n\n**B.** *A few* = quelques, assez (ton positif). *Few* = peu, trop peu (ton négatif). Même chose pour *a little* / *little*.\n\n**C.** 8. *Every student has a book.* (*every* + nom **singulier**)"}$exo$::jsonb),
  ('e51207eb-106e-5801-b2c8-47305f9420ae'::uuid, 3, 'traduction', $exo${"titre":"Préparer la fête","consigne":"Rédige en anglais ; justifie brièvement les corrections.","enonce":"**A.** Tu prépares une fête. Écris **six phrases** avec :\n\n1. *How much* ou *How many* (une question) ;\n2. *some* dans une offre polie ;\n3. *any* dans une négative ;\n4. *few* ou *little* (sens négatif) ;\n5. *a few* ou *a little* (sens positif) ;\n6. *enough*, *too much* ou *too many*.\n\n**B. Corrige et explique.**\n\n7. How much people are coming?\n8. I have few money.\n9. There isn't some milk.","bareme":[{"critere":"Six phrases justes, une par quantifieur demandé","points":12},{"critere":"Phrases cohérentes avec la situation de la fête","points":2},{"critere":"Trois corrections expliquées (many ; little ; any)","points":6}],"dureeMin":13,"corrige":"**A.** Exemples : *How many friends are coming?* — *Would you like some juice?* — *There isn't any cake.* — *There is little space in the kitchen.* — *We have a few chairs.* — *There are too many people.* Toute phrase correcte respectant la consigne est acceptée.\n\n**B.**\n7. *How **many** people are coming?* — *people* est dénombrable.\n8. *I have **little** money.* — *money* est indénombrable : *little* et non *few*.\n9. *There isn't **any** milk.* — négation : *any*."}$exo$::jsonb),
  ('5f00280a-ce05-524a-94b3-8eb4ed4305a2'::uuid, 1, 'traduction', $exo${"titre":"Ennuyé ou ennuyeux ?","consigne":"Choisis la bonne forme, puis traduis en anglais.","enonce":"**A. Choisis.**\n\n1. The film is (bored / boring).\n2. I am (interested / interesting) in music.\n3. She looks (tired / tiring).\n\n**B. Traduis en anglais.**\n\n4. un garçon de cinq ans\n5. une grande voiture rouge *(taille avant couleur)*\n6. les riches","bareme":[{"critere":"Trois formes justes (boring, interested, tired)","points":9},{"critere":"Traduction 4 : a five-year-old boy","points":4},{"critere":"Traduction 5 : a big red car","points":4},{"critere":"Traduction 6 : the rich (pluriel)","points":3}],"dureeMin":6,"corrige":"1. *boring* (ce qui provoque le sentiment) — 2. *interested* (ce que ressent la personne) — 3. *tired* (après *look*, verbe d'état).\n\n4. *a five-**year**-old boy* — trait d'union, nom au **singulier**. 5. *a big red car* — taille puis couleur ; l'adjectif est invariable. 6. *the rich* — adjectif substantivé, verbe au pluriel."}$exo$::jsonb),
  ('5f00280a-ce05-524a-94b3-8eb4ed4305a2'::uuid, 2, 'traduction', $exo${"titre":"L'ordre des adjectifs","consigne":"Range, puis corrige et explique.","enonce":"**A. Range les mots pour former un groupe nominal correct.**\n\n1. wooden / a / old / table / lovely\n2. French / a / small / car / black\n\n**B. Corrige et explique.**\n\n3. two reds cars\n4. a house beautiful\n5. I am boring. *(l'élève veut dire « je m'ennuie »)*\n6. a five-years-old boy","bareme":[{"critere":"Deux groupes ordonnés (a lovely old wooden table ; a small black French car)","points":8},{"critere":"Quatre corrections expliquées","points":12}],"dureeMin":9,"corrige":"**A.** 1. *a lovely old wooden table* (opinion, âge, matière). — 2. *a small black French car* (taille, couleur, origine).\n\n**B.**\n3. *two red cars* — l'adjectif est invariable : pas de -s.\n4. *a beautiful house* — l'adjectif se place **avant** le nom.\n5. *I am **bored**.* — -ed : ce que ressent la personne ; *I am boring* = « je suis ennuyeux ».\n6. *a five-**year**-old boy* — dans un adjectif composé, le nom reste au singulier."}$exo$::jsonb),
  ('5f00280a-ce05-524a-94b3-8eb4ed4305a2'::uuid, 3, 'traduction', $exo${"titre":"Décrire avec précision","consigne":"Rédige une courte description en anglais ; explique la dernière question en français.","enonce":"**A.** Décris ton meilleur ami, ou une pièce de ta maison, en six ou sept phrases. Le texte doit contenir :\n\n- un groupe nominal avec **trois adjectifs** dans le bon ordre ;\n- une phrase avec un **verbe d'état** (*be, look, feel, seem…*) suivi d'un adjectif ;\n- un couple **-ed / -ing** bien employé (*bored/boring*, *tired/tiring*…) ;\n- un **adjectif composé** avec trait d'union (*a two-hour film*…) ;\n- un **adjectif substantivé** (*the young*, *the rich*…).\n\n**B.** Pourquoi *I am boring* ne veut-il pas dire « je m'ennuie » ?","bareme":[{"critere":"Groupe nominal à trois adjectifs dans le bon ordre","points":4},{"critere":"Verbe d'état + adjectif","points":3},{"critere":"Couple -ed / -ing correct","points":4},{"critere":"Adjectif composé (nom au singulier) et adjectif substantivé (the + verbe au pluriel)","points":6},{"critere":"Explication de I am boring","points":3}],"dureeMin":13,"corrige":"**A.** Exemple : *My best friend Leo has a lovely little old brown dog. He looks tired today because the film was tiring: it was a two-hour film. He is never bored when the young play together...* Toute production correcte respectant les cinq contraintes est acceptée.\n- ordre : opinion, taille, âge, couleur… (*a lovely little old brown dog*) ;\n- verbe d'état : *looks tired* ;\n- -ed/-ing : *bored / boring* ;\n- composé : *a two-hour film* (jamais *hours*) ;\n- substantivé : *the young are* (pluriel).\n\n**B.** *I am bored* = je ressens de l'ennui ; *I am boring* = **je suis ennuyeux** : -ing décrit ce qui provoque le sentiment."}$exo$::jsonb),
  ('8c4e15fc-abcd-5587-9bfe-829e9d2f3b87'::uuid, 1, 'traduction', $exo${"titre":"Questions, négations, reprises","consigne":"Réponds en anglais ; les trois dernières questions sont en français ou en anglais courts.","enonce":"**A. Mets à la forme interrogative.**\n\n1. You are ready.\n2. She has finished.\n3. They like pizza.\n\n**B. Mets à la forme négative.** 4. I know.\n\n**C. Reprise courte.**\n\n5. *Do you like tea?* — Yes, … .\n6. *Are you French?* — No, … .\n\n**7.** Cite les quatre familles d'auxiliaires.","bareme":[{"critere":"Trois questions justes (Are you ready ? Has she finished ? Do they like pizza ?)","points":9},{"critere":"Négation : I don't know","points":3},{"critere":"Deux reprises courtes (I do ; I'm not)","points":4},{"critere":"Quatre familles : be, have, do, modaux","points":4}],"dureeMin":6,"corrige":"1. *Are you ready?* — 2. *Has she finished?* — 3. *Do they like pizza?* (temps simple : *do*).\n4. *I **don't** know.*\n5. *Yes, I **do**.* — 6. *No, I'm **not**.* (*No, I'm not*, ou *No, I am not*.)\n\n7. **be**, **have**, **do**, et les **modaux** (can, must, should, may, will)."}$exo$::jsonb),
  ('8c4e15fc-abcd-5587-9bfe-829e9d2f3b87'::uuid, 2, 'traduction', $exo${"titre":"Repérer l'auxiliaire","consigne":"Réponds en français ou en anglais, avec précision.","enonce":"**A. Pour chaque phrase, relève l'auxiliaire et dis ce qu'il forme.**\n\n1. She is working.\n2. It was built in 1990.\n3. I have finished.\n4. You can go.\n\n**B. Traduis en anglais.** 5. As-tu une voiture ?\n\n**C. Complète la reprise courte.**\n\n6. *Can she swim?* — Yes, … .\n7. *Does he play tennis?* — No, … .","bareme":[{"critere":"Quatre auxiliaires relevés et leur rôle (be : -ING ; be : passif ; have : temps composé ; modal)","points":12},{"critere":"Traduction : Do you have a car ?","points":4},{"critere":"Deux reprises courtes (she can ; he doesn't)","points":4}],"dureeMin":9,"corrige":"**A.** 1. *is* (*be*) forme le temps en **-ING**. — 2. *was* (*be*) forme le **passif**. — 3. *have* forme un temps **composé** (present perfect). — 4. *can* est un **modal**.\n\n**B.** 5. *Do you have a car?* — ici *have* est **lexical** : il faut *do*.\n\n**C.** 6. *Yes, she **can**.* — 7. *No, he **doesn't**.*"}$exo$::jsonb),
  ('8c4e15fc-abcd-5587-9bfe-829e9d2f3b87'::uuid, 3, 'traduction', $exo${"titre":"Trois pouvoirs, trois corrections","consigne":"Réponds et écris en anglais ; justifie en français quand c'est demandé.","enonce":"**A. Pour chaque phrase, relève l'auxiliaire et dis quel pouvoir il exerce (question, négation, reprise courte).**\n\n1. She doesn't like coffee.\n2. Has he arrived?\n3. I can't come.\n4. Are you working? — Yes, I am.\n\n**B. Corrige et explique.**\n\n5. Do you be ready?\n6. She no likes tea.\n7. Does he can swim?\n\n**C. Écris un mini-dialogue de quatre répliques avec au moins deux reprises courtes.**","bareme":[{"critere":"Quatre auxiliaires repérés avec leur pouvoir","points":8},{"critere":"Trois corrections expliquées (Are you ready ? ; doesn't like ; Can he swim ?)","points":6},{"critere":"Dialogue correct avec deux reprises courtes","points":6}],"dureeMin":14,"corrige":"**A.**\n1. *doesn't* (*do* + *not*) : **négation**. — 2. *Has* : **question** (l'auxiliaire passe devant le sujet). — 3. *can't* (modal + *not*) : **négation**. — 4. *Are* : **question**, puis *I am* : **reprise courte**.\n\n**B.**\n5. *Are you ready?* — *be* est déjà un auxiliaire : pas de *do*.\n6. *She **doesn't like** tea.* — la négation se forme avec l'auxiliaire *do* + *not*.\n7. *Can he swim?* — un modal passe lui-même devant le sujet, sans *do*.\n\n**C.** Exemple : *Do you like pizza? — Yes, I do. — Can your brother cook? — No, he can't.* Toute production correcte est acceptée."}$exo$::jsonb),
  ('e1a5cb5f-1474-5c26-946f-122bbe083379'::uuid, 1, 'traduction', $exo${"titre":"Be ou have ?","consigne":"Réponds en anglais, phrase par phrase.","enonce":"**Complète chaque phrase avec la bonne forme de be ou have (présent).**\n\n1. My brother … 12 years old.\n2. We … a dog and two cats.\n3. I … hungry: let's eat!\n4. She … a bike, but he … a scooter.\n5. They … very tired today.","bareme":[{"critere":"Les cinq formes de be/have justes (am, is, are, have, has)","points":15},{"critere":"Emploi de be pour l'âge et la faim, jamais have","points":5}],"dureeMin":6,"corrige":"1. *is* (l'âge se dit avec be : *He is 12*).\n2. *have* (posséder ; sujet *we*).\n3. *am* (la faim se dit avec be : *I am hungry*).\n4. *has* (3e personne) … *has*.\n5. *are* (sujet *they*).\n\nRappel : *I am 15*, jamais *I have 15*.\n\n**Points attendus.** Les cinq formes de be/have justes (am, is, are, have, has) (15 pts) ; Emploi de be pour l'âge et la faim, jamais have (5 pts)."}$exo$::jsonb),
  ('e1a5cb5f-1474-5c26-946f-122bbe083379'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Nora","consigne":"Réponds en anglais ; justifie brièvement en français quand c'est demandé.","enonce":"**Situation.** Nora écrit à une amie.\n\n> Yesterday we ___ (be) at my grandma's house. She ___ (have) a big garden. We ___ (have) lunch outside. I ___ (be) cold, so I ___ (have) a sweater.\n\n**A.** Complète avec le prétérit de be ou have.\n\n**B.** Traduis en anglais : « Elle a soif. » et « Il a fait une douche. » (have d'action).\n\n**C.** Que peut vouloir dire *she's* dans *She's finished* ? Justifie en français.","bareme":[{"critere":"Quatre ou cinq prétérits justes (were, had, had, was, had)","points":10},{"critere":"Traductions : She is thirsty ; He had a shower","points":6},{"critere":"Contraction expliquée (she has, car suivi d'un participe passé)","points":4}],"dureeMin":10,"corrige":"**A.** *were* — *had* — *had* — *was* — *had*. Be : *was/were* ; have : *had* pour toutes les personnes.\n\n**B.** *She is thirsty.* (la soif se dit avec be) — *He had a shower.* (expression d'action).\n\n**C.** *She's finished* = *she **has** finished* : c'est ce qui suit qui tranche. Suivie d'un participe passé (*finished*), la contraction vaut *has* ; dans *she's tired*, elle vaudrait *is*."}$exo$::jsonb),
  ('e1a5cb5f-1474-5c26-946f-122bbe083379'::uuid, 3, 'traduction', $exo${"titre":"Questions, négations et pièges","consigne":"Réponds en anglais, puis justifie les corrections en français.","enonce":"**A.** Mets à la forme demandée.\n\n1. She has a car. → question avec *have* (sans do)\n2. They have breakfast at seven. → question (have d'action)\n3. He is tired. → négation\n4. I have got a brother. → négation\n\n**B.** Corrige et explique.\n\n5. I have 14 years.\n6. Yesterday she haved a cold.\n\n**C.** *We'd finished* : que peut valoir *'d* ? Donne les deux sens avec un exemple pour chacun.","bareme":[{"critere":"Quatre transformations justes (Has she a car ? / Do they have breakfast… ? / He isn't tired / I haven't got a brother)","points":8},{"critere":"Deux corrections expliquées (am 14 ; had)","points":6},{"critere":"'d = had ou would, avec deux exemples","points":6}],"dureeMin":15,"corrige":"**A.**\n1. *Has she got a car?* / *Does she have a car?* (avec *got*, pas de do ; avec *have* lexical, do).\n2. *Do they have breakfast at seven?* (have d'action : do).\n3. *He isn't tired.*\n4. *I haven't got a brother.*\n\n**B.**\n5. *I am 14.* L'âge se dit avec be.\n6. *Yesterday she had a cold.* Le prétérit de have est *had* à toutes les personnes.\n\n**C.** *'d* = *had* (*We'd finished* = we had finished, suivi d'un participe passé) ou *would* (*We'd like a coffee* = we would like, suivi de la base verbale)."}$exo$::jsonb),
  ('8a8605d5-ea6f-5b68-92e4-da445fea8267'::uuid, 1, 'traduction', $exo${"titre":"Négations avec do","consigne":"Réponds en anglais, phrase par phrase.","enonce":"**Mets ces phrases à la forme négative.**\n\n1. I like coffee.\n2. She works here.\n3. They played football.\n4. He went to school by bus.","bareme":[{"critere":"Quatre négations justes avec don't / doesn't / didn't","points":16},{"critere":"Verbe revenu à la base verbale (pas de -s ni de -ed)","points":4}],"dureeMin":5,"corrige":"1. *I don't like coffee.*\n2. *She doesn't work here.*\n3. *They didn't play football.*\n4. *He didn't go to school by bus.*\n\nRègle : dès que do apparaît, il porte la marque du temps et de la personne ; le verbe lexical revient à la base verbale."}$exo$::jsonb),
  ('8a8605d5-ea6f-5b68-92e4-da445fea8267'::uuid, 2, 'traduction', $exo${"titre":"Questions à Lina","consigne":"Réponds en anglais ; les questions doivent être des phrases complètes.","enonce":"**Situation.** Tu interroges Lina, une élève anglaise.\n\n**A.** Écris la question qui correspond à chaque réponse.\n\n1. — ? — Yes, I play tennis every week.\n2. — ? — No, she doesn't live in London.\n3. — ? — Yes, we went to the cinema yesterday.\n\n**B.** Traduis en anglais : « Qui a cassé la fenêtre ? » et « Qu'est-ce que tu fais dans la vie ? »","bareme":[{"critere":"Trois questions avec Do / Does / Did et la base verbale","points":9},{"critere":"Who broke the window ? (sans do)","points":4},{"critere":"What do you do ? (deux do)","points":4},{"critere":"Aucune marque de temps doublée","points":3}],"dureeMin":9,"corrige":"**A.**\n1. *Do you play tennis every week?*\n2. *Does she live in London?*\n3. *Did you go to the cinema yesterday?*\n\n**B.** *Who broke the window?* : *who* est le sujet, donc pas de do. *What do you do?* : le premier do est l'auxiliaire, le second le verbe lexical."}$exo$::jsonb),
  ('8a8605d5-ea6f-5b68-92e4-da445fea8267'::uuid, 3, 'traduction', $exo${"titre":"Do : trouver l'erreur","consigne":"Réponds en anglais, puis explique chaque correction en français.","enonce":"**A.** Corrige les erreurs et explique-les.\n\n1. She doesn't works here.\n2. Did you went to school?\n3. Do you can swim?\n4. Does she is a teacher?\n\n**B.** Que veut dire *I do like it!* ? Traduis, puis dis en quoi c'est différent de *I like it*.\n\n**C.** Écris la question et la réponse négative : *He did his homework.* → question ; puis *No, …*","bareme":[{"critere":"Quatre erreurs corrigées","points":8},{"critere":"Explications : une seule marque de temps ; pas de do avec modal ni be","points":6},{"critere":"Insistance expliquée (j'aime vraiment ça)","points":3},{"critere":"Question et réponse négative justes (Did he do… ? No, he didn't.)","points":3}],"dureeMin":14,"corrige":"**A.**\n1. *She doesn't work here.* Doesn't porte déjà le -s.\n2. *Did you go to school?* Did porte le passé, le verbe revient à la base.\n3. *Can you swim?* Avec un modal, on n'emploie pas do.\n4. *Is she a teacher?* Avec be, pas de do.\n\n**B.** *J'aime vraiment ça !* Le do accentué marque l'insistance ; *I like it* est neutre.\n\n**C.** *Did he do his homework?* — *No, he didn't.* (le premier *did* est l'auxiliaire, *do* le verbe lexical)."}$exo$::jsonb),
  ('2669f2b1-5e6e-5c5e-b739-e3ea65d8ccf7'::uuid, 1, 'traduction', $exo${"titre":"Must, mustn't ou don't have to ?","consigne":"Réponds en anglais, phrase par phrase.","enonce":"**Choisis la bonne forme et traduis la phrase en français.**\n\n1. You (must / mustn't) be quiet in the library: it's forbidden to talk.\n2. Tomorrow is Sunday: we (mustn't / don't have to) get up early.\n3. She (must / mustn't) to go now. → cette phrase est fausse : corrige-la.","bareme":[{"critere":"Choix justes : mustn't, don't have to","points":8},{"critere":"Traductions en français correctes","points":6},{"critere":"Correction de la phrase 3 (She must go now)","points":6}],"dureeMin":6,"corrige":"1. *mustn't* : « tu ne dois pas », c'est une interdiction.\n2. *don't have to* : « nous ne sommes pas obligés » ; ce n'est pas obligatoire.\n3. *She must go now.* Must est invariable et n'est jamais suivi de *to*.\n\n**Points attendus.** Choix justes : mustn't, don't have to (8 pts) ; Traductions en français correctes (6 pts) ; Correction de la phrase 3 (She must go now) (6 pts)."}$exo$::jsonb),
  ('2669f2b1-5e6e-5c5e-b739-e3ea65d8ccf7'::uuid, 2, 'traduction', $exo${"titre":"Le règlement du club","consigne":"Réponds en anglais.","enonce":"**Situation.** Voici le règlement d'un club de sport.\n\n- Tout le monde porte un maillot (règle du club).\n- Il est interdit de courir près de la piscine.\n- Venir avant 9 h n'est pas obligatoire.\n\n**A.** Écris ces trois règles en anglais avec *have to*, *mustn't* et *don't have to*.\n\n**B.** Hier, Tom a dû porter un maillot. Écris la phrase au passé.\n\n**C.** Demain, tu devras apporter ta carte. Écris la phrase au futur.","bareme":[{"critere":"Trois règles justes (have to, mustn't, don't have to)","points":9},{"critere":"Had to au passé","points":5},{"critere":"Will have to au futur","points":6}],"dureeMin":10,"corrige":"**A.** *Everyone has to wear a shirt.* — *You mustn't run near the pool.* — *You don't have to come before nine.*\n\n**B.** *Tom had to wear a shirt yesterday.* Must n'a pas de passé : on prend *had to*.\n\n**C.** *You will have to bring your card tomorrow.* Must n'a pas de futur : *will have to*."}$exo$::jsonb),
  ('2669f2b1-5e6e-5c5e-b739-e3ea65d8ccf7'::uuid, 3, 'traduction', $exo${"titre":"Conseils, ordres et interdits","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Explique la différence de sens en français.\n\n1. *You mustn't come.* / 2. *You don't have to come.*\n\n**B.** Traduis en anglais.\n\n3. « Est-ce que tu dois partir maintenant ? » (have to)\n4. « Il n'avait pas le droit d'entrer hier. »\n5. « Je dois arrêter de fumer : je l'ai décidé. » (must) puis la même idée si le médecin l'exige (have to).\n\n**C.** *You should see a doctor* : c'est une obligation ? Réponds en une phrase.","bareme":[{"critere":"Différence mustn't / don't have to (interdiction / pas obligatoire)","points":5},{"critere":"Traductions 3 et 4 justes (Do you have to go ? ; wasn't allowed to / couldn't)","points":6},{"critere":"Traduction 5 : must (source = moi) et have to (source = extérieure)","points":5},{"critere":"Should = conseil, pas obligation","points":4}],"dureeMin":14,"corrige":"**A.** 1 : interdiction (« tu ne dois pas venir »). 2 : absence d'obligation (« tu n'es pas obligé de venir »).\n\n**B.**\n3. *Do you have to go now?* (have to se nie et s'interroge avec do)\n4. *He wasn't allowed to enter yesterday.* ou *He couldn't enter.*\n5. *I must stop smoking.* (conviction personnelle) ; *I have to stop smoking.* (obligation venue de l'extérieur).\n\n**C.** Non : *should* exprime un **conseil**, une obligation faible."}$exo$::jsonb),
  ('8d68818e-c062-5f37-a317-cf9c65dfae73'::uuid, 1, 'traduction', $exo${"titre":"Can, could ou be able to ?","consigne":"Réponds en anglais, phrase par phrase.","enonce":"**Complète avec can, can't, could ou will be able to.**\n\n1. I … swim: I learned last summer.\n2. When I was five, I … ride a bike. (capacité passée)\n3. Next year, I … drive. (futur)\n4. … you help me, please? (demande polie)","bareme":[{"critere":"Can (ou can't) au présent","points":5},{"critere":"Could pour la capacité passée","points":5},{"critere":"Will be able to au futur","points":5},{"critere":"Could pour la politesse","points":5}],"dureeMin":6,"corrige":"1. *can* (capacité présente).\n2. *could* (capacité passée générale).\n3. *will be able to* : can n'a pas de futur, on prend be able to.\n4. *Could* (ou *Can*) *you help me, please?* : could est plus poli.\n\n**Points attendus.** Can (ou can't) au présent (5 pts) ; Could pour la capacité passée (5 pts) ; Will be able to au futur (5 pts) ; Could pour la politesse (5 pts)."}$exo$::jsonb),
  ('8d68818e-c062-5f37-a317-cf9c65dfae73'::uuid, 2, 'traduction', $exo${"titre":"Un exploit d'Anna","consigne":"Réponds en anglais.","enonce":"**Situation.** Anna raconte sa journée.\n\n> I ___ (can) play the piano when I was six. Yesterday the door was locked, but I ___ (be able to) open it with a pin. Now I ___ (can) see the mountain from my window.\n\n**A.** Complète avec la bonne forme.\n\n**B.** Pourquoi ne dit-on pas *could* pour « Yesterday I opened the door » (réussite précise) ? Réponds en français.\n\n**C.** Traduis : « Je vois la mer d'ici. »","bareme":[{"critere":"Could ; was able to ; can","points":9},{"critere":"Explication : réussite ponctuelle passée → was/were able to","points":6},{"critere":"I can see the sea from here","points":5}],"dureeMin":9,"corrige":"**A.** *could play* — *was able to open* — *can see*.\n\n**B.** *Could* exprime une capacité passée **générale** (« je savais jouer »). Pour une **réussite ponctuelle** (cette fois-là, j'y suis parvenu), on emploie *was/were able to* (ou *managed to*).\n\n**C.** *I can see the sea from here.* Avec les verbes de perception, on emploie *can*, alors que le français ne dit pas « pouvoir »."}$exo$::jsonb),
  ('8d68818e-c062-5f37-a317-cf9c65dfae73'::uuid, 3, 'traduction', $exo${"titre":"Capacité à tous les temps","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Traduis en anglais.\n\n1. « Elle sait parler trois langues. »\n2. « Il n'a pas pu finir hier. » (réussite précise)\n3. « J'ai réussi à finir. » (present perfect)\n4. « Vous pourriez peut-être venir. » (après might)\n\n**B.** Corrige et explique : *I will can swim next year.* et *She cans speak French.*\n\n**C.** Dans quel cas can ne peut pas être utilisé ? Donne la règle et deux exemples.","bareme":[{"critere":"Traductions 1 à 4 justes","points":8},{"critere":"Deux corrections expliquées (will be able to ; can invariable)","points":6},{"critere":"Règle : pas de can après un autre modal ni au futur/present perfect, avec deux exemples","points":6}],"dureeMin":14,"corrige":"**A.**\n1. *She can speak three languages.*\n2. *He wasn't able to finish yesterday.* (ou *couldn't*, mais on attend *wasn't able to*)\n3. *I have been able to finish.*\n4. *You might be able to come.*\n\n**B.** *I will be able to swim next year.* : can n'a pas de futur. *She can speak French.* : can est invariable, jamais de -s.\n\n**C.** Can n'a que le présent (et could au passé) : pour le futur, le present perfect ou après un modal, on emploie be able to (*will be able to*, *have been able to*, *might be able to*)."}$exo$::jsonb),
  ('be1d4915-6dbd-5fe9-8eb2-ee28dd76aaa4'::uuid, 1, 'traduction', $exo${"titre":"Demander et accorder","consigne":"Réponds en anglais.","enonce":"**Complète avec can, may, could ou can't.**\n\n1. (Entre amis) … I use your phone?\n2. (Avec le directeur) … I come in, please?\n3. (Refus entre amis) Sorry, you … use my phone.\n4. (Demande polie) … I borrow your pen?","bareme":[{"critere":"Can pour le familier, may pour le formel","points":8},{"critere":"Can't pour le refus","points":4},{"critere":"Could pour la demande polie","points":4},{"critere":"Registre justifié par un mot en français","points":4}],"dureeMin":6,"corrige":"1. *Can* (familier).\n2. *May* (formel, adulte).\n3. *can't* (refus).\n4. *Could* (demande polie).\n\nOn croise le registre : familier = can, poli = could, formel = may.\n\n**Points attendus.** Can pour le familier, may pour le formel (8 pts) ; Can't pour le refus (4 pts) ; Could pour la demande polie (4 pts) ; Registre justifié par un mot en français (4 pts)."}$exo$::jsonb),
  ('be1d4915-6dbd-5fe9-8eb2-ee28dd76aaa4'::uuid, 2, 'traduction', $exo${"titre":"Au collège en Angleterre","consigne":"Réponds en anglais.","enonce":"**Situation.** Tu écris un email à une correspondante.\n\n**A.** Traduis en anglais.\n\n1. « Nous n'avions pas le droit d'utiliser nos téléphones. »\n2. « Tu auras le droit de sortir à 16 ans. »\n3. « Les élèves n'ont pas le droit de courir. » (style règlement)\n\n**B.** Explique en français pourquoi on ne dit pas *could* pour la permission accordée une fois.","bareme":[{"critere":"Wasn't/weren't allowed to","points":5},{"critere":"Will be allowed to","points":5},{"critere":"May not (règlement)","points":5},{"critere":"Explication de could (suggestion)","points":5}],"dureeMin":10,"corrige":"**A.**\n1. *We weren't allowed to use our phones.*\n2. *You will be allowed to go out at 16.*\n3. *Students may not run.* (may not est formel, pour un règlement)\n\n**B.** Pour une permission accordée, on n'emploie pas *could* : *You could go* veut dire « tu pourrais y aller », donc une suggestion. On dit *You can go* ou, au passé, *I was allowed to go*."}$exo$::jsonb),
  ('be1d4915-6dbd-5fe9-8eb2-ee28dd76aaa4'::uuid, 3, 'traduction', $exo${"titre":"Registres et règles","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Range ces trois demandes de la plus familière à la plus formelle et explique (en français) quand on les emploie : *May I come in? / Can I come in? / Could I come in?*\n\n**B.** Traduis.\n\n1. « Il est interdit de toucher ça. » (interdiction forte)\n2. « J'ai le droit de veiller tard. » (règle extérieure, présent)\n\n**C.** Corrige : *I could to go out yesterday (permission).* et *You may to enter.*","bareme":[{"critere":"Ordre can → could → may avec contextes","points":6},{"critere":"Traductions 1 et 2 (mustn't ; am allowed to)","points":6},{"critere":"Deux corrections (was allowed to ; may enter sans to)","points":5},{"critere":"Rigueur du registre","points":3}],"dureeMin":14,"corrige":"**A.** *Can I…?* : familier, entre proches. *Could I…?* : poli. *May I…?* : formel, avec un adulte ou à l'écrit.\n\n**B.** 1. *You mustn't touch it.* 2. *I am allowed to stay up late.*\n\n**C.** *I was allowed to go out yesterday.* : could ne dit pas la permission accordée une fois ; *You may enter.* : may est un modal, sans *to*."}$exo$::jsonb),
  ('02d9bc22-41f8-5ac3-9908-5754e0eafb59'::uuid, 1, 'traduction', $exo${"titre":"Should ou must ?","consigne":"Réponds en anglais.","enonce":"**Complète avec should, shouldn't ou must.**\n\n1. You have a bad cough: you … see a doctor. (conseil)\n2. You … eat so much sugar. (conseil négatif)\n3. Stop! It is red: you … stop. (obligation)\n4. … I call her? (question)","bareme":[{"critere":"Should pour le conseil","points":6},{"critere":"Shouldn't pour le conseil négatif","points":5},{"critere":"Must pour l'obligation","points":5},{"critere":"Should en question","points":4}],"dureeMin":6,"corrige":"1. *should* (conseil).\n2. *shouldn't* (conseil négatif).\n3. *must* (obligation).\n4. *Should* I call her? : should s'interroge sans do.\n\nShould est invariable : pas de -s, pas de *to*.\n\n**Points attendus.** Should pour le conseil (6 pts) ; Shouldn't pour le conseil négatif (5 pts) ; Must pour l'obligation (5 pts) ; Should en question (4 pts)."}$exo$::jsonb),
  ('02d9bc22-41f8-5ac3-9908-5754e0eafb59'::uuid, 2, 'traduction', $exo${"titre":"Lettre à Inès","consigne":"Réponds en anglais.","enonce":"**Situation.** Inès a raté son contrôle. Elle t'écrit : « I didn't revise and I failed the test. I'm sad! »\n\n**A.** Écris trois conseils avec *should*, *ought to* et *why don't you*.\n\n**B.** Écris un conseil pressant avec *had better*.\n\n**C.** Écris ce qu'Inès aurait dû faire (should have + participe passé).","bareme":[{"critere":"Trois conseils construits (should + BV ; ought to + to ; Why don't you + BV)","points":9},{"critere":"Had better + base verbale (sans to)","points":5},{"critere":"Should have revised","points":6}],"dureeMin":10,"corrige":"**A.** *You should ask your teacher for help.* — *You ought to revise every day.* — *Why don't you make flashcards?*\n\n**B.** *You'd better start now!* (had better + base verbale, sans *to*).\n\n**C.** *You should have revised.* : regret ou reproche sur le passé."}$exo$::jsonb),
  ('02d9bc22-41f8-5ac3-9908-5754e0eafb59'::uuid, 3, 'traduction', $exo${"titre":"Nuances du conseil","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Range *You should rest / You'd better rest / You must rest* du plus faible au plus fort et explique.\n\n**B.** Corrige et explique.\n\n1. You had better to hurry.\n2. You hadn't better be late.\n3. She should to call him.\n\n**C.** Traduis : « Si j'étais toi, je m'excuserais. » et « Il ne devrait pas manger si tard. »","bareme":[{"critere":"Ordre should → had better → must expliqué","points":5},{"critere":"Trois corrections expliquées","points":9},{"critere":"Traductions justes (If I were you, I'd apologise ; He shouldn't eat so late)","points":6}],"dureeMin":14,"corrige":"**A.** *should* = conseil ordinaire ; *had better* = conseil pressant, avec menace implicite ; *must* = obligation.\n\n**B.** 1. *You'd better hurry.* : had better + base verbale, sans *to*. 2. *You'd better not be late.* : la négation se place après *better*. 3. *She should call him.* : should est suivi de la base verbale.\n\n**C.** *If I were you, I'd apologise.* — *He shouldn't eat so late.*"}$exo$::jsonb),
  ('04dc7b15-d693-563d-8d97-a0bd1acfcc6a'::uuid, 1, 'traduction', $exo${"titre":"Let's, how about, why don't we","consigne":"Réponds en anglais.","enonce":"**Complète avec la bonne forme du verbe entre parenthèses.**\n\n1. Let's (go) to the park.\n2. How about (play) tennis?\n3. Why don't we (watch) a film?\n4. Shall we (start)?\n5. What about a picnic? (nom) → recopie la phrase en la finissant avec le verbe *have*.","bareme":[{"critere":"Base verbale après Let's, Why don't we, Shall we","points":10},{"critere":"-ING après How about / What about","points":10}],"dureeMin":6,"corrige":"1. *go* (Let's + base verbale).\n2. *playing* (How about + -ING).\n3. *watch* (Why don't we + base verbale).\n4. *start* (Shall we + base verbale).\n5. *What about having a picnic?* (What about + -ING).\n\n**Points attendus.** Base verbale après Let's, Why don't we, Shall we (10 pts) ; -ING après How about / What about (10 pts)."}$exo$::jsonb),
  ('04dc7b15-d693-563d-8d97-a0bd1acfcc6a'::uuid, 2, 'traduction', $exo${"titre":"Le samedi de Léo et Maya","consigne":"Réponds en anglais.","enonce":"**Situation.** Léo et Maya choisissent une activité.\n\n**A.** Écris quatre suggestions différentes (Let's / Shall we / How about / Why don't we).\n\n**B.** Maya répond : accepte la première suggestion, refuse poliment la deuxième.\n\n**C.** Léo préfère rester à la maison : écris sa phrase avec *would rather*.","bareme":[{"critere":"Quatre suggestions construites juste","points":8},{"critere":"Acceptation et refus polis","points":6},{"critere":"I'd rather stay home","points":6}],"dureeMin":10,"corrige":"**A.** *Let's go swimming? → Let's go to the cinema.* — *Shall we play chess?* — *How about going to the park?* — *Why don't we cook together?*\n\n**B.** *Good idea!* (ou *That sounds great*) — *I'd rather not.* (ou *Sorry, I'm busy*).\n\n**C.** *I'd rather stay home.* (would rather + base verbale)."}$exo$::jsonb),
  ('04dc7b15-d693-563d-8d97-a0bd1acfcc6a'::uuid, 3, 'traduction', $exo${"titre":"Suggestions et préférences","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Corrige et explique.\n\n1. How about go out tonight?\n2. Why don't we meeting at six?\n3. Let's don't waste time.\n4. I'd rather to stay home.\n\n**B.** Traduis : « Je préfère rester chez moi plutôt que sortir. » et « Commençons, d'accord ? » (avec tag).\n\n**C.** Écris un mini-dialogue de quatre répliques : une suggestion, un refus poli, une contre-proposition, une acceptation.","bareme":[{"critere":"Quatre corrections expliquées","points":8},{"critere":"Deux traductions justes (I'd rather stay home than go out ; Let's start, shall we?)","points":6},{"critere":"Dialogue cohérent et correct","points":6}],"dureeMin":14,"corrige":"**A.** 1. *How about going out tonight?* (-ING). 2. *Why don't we meet at six?* (base verbale). 3. *Let's not waste time.* 4. *I'd rather stay home.* (sans *to*).\n\n**B.** *I'd rather stay home than go out.* — *Let's start, shall we?*\n\n**C.** Exemple : *Let's go swimming. — I'd rather not. — Why don't we play chess? — Good idea!*"}$exo$::jsonb),
  ('200816cc-bdef-5387-9a4c-9ab47decf2a0'::uuid, 1, 'traduction', $exo${"titre":"Would like et wish","consigne":"Réponds en anglais, phrase par phrase.","enonce":"**Complète avec la bonne forme du verbe.**\n\n1. I'd like (travel) to Japan.\n2. Would you like (have) a drink?\n3. I wish I (have) more time. (regret sur le présent)\n4. I wish I (be) taller.","bareme":[{"critere":"Would like + to + verbe (travel → to travel, to have)","points":8},{"critere":"Wish + prétérit (had)","points":6},{"critere":"Wish + were","points":6}],"dureeMin":6,"corrige":"1. *to travel* (would like + to + verbe).\n2. *to have* : *Would you like to have a drink?*\n3. *had* : regret sur le présent, on recule d'un temps.\n4. *were* : la forme irréelle de be est were à toutes les personnes.\n\n**Points attendus.** Would like + to + verbe (travel → to travel, to have) (8 pts) ; Wish + prétérit (had) (6 pts) ; Wish + were (6 pts)."}$exo$::jsonb),
  ('200816cc-bdef-5387-9a4c-9ab47decf2a0'::uuid, 2, 'traduction', $exo${"titre":"Regrets d'Emma","consigne":"Réponds en anglais.","enonce":"**Situation.** Emma a mal aux pieds après une longue marche.\n\n> Emma: I have no time to rest and it is raining. I didn't take my coat this morning.\n\n**A.** Écris trois regrets d'Emma avec *I wish* : un sur le présent, un sur le passé, un sur un changement souhaité (*would*).\n\n**B.** Écris une phrase avec *If only*.\n\n**C.** Écris ce qu'Emma aurait dû faire (should have).","bareme":[{"critere":"Wish + prétérit pour le présent","points":5},{"critere":"Wish + past perfect pour le passé","points":5},{"critere":"Wish + would pour le changement souhaité","points":4},{"critere":"If only construit juste","points":3},{"critere":"Should have + participe passé","points":3}],"dureeMin":10,"corrige":"**A.** *I wish I had more time.* — *I wish I had taken my coat.* — *I wish it would stop raining.*\n\n**B.** *If only I had my coat!* (ou *If only I had taken my coat!*)\n\n**C.** *I should have taken my coat.*\n\nRègle : on recule d'un temps (présent → prétérit ; passé → past perfect)."}$exo$::jsonb),
  ('200816cc-bdef-5387-9a4c-9ab47decf2a0'::uuid, 3, 'traduction', $exo${"titre":"Souhaits, regrets et pièges","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Corrige et explique.\n\n1. I wish I am taller.\n2. I would want a coffee, please.\n3. I wish I will be there.\n\n**B.** *I wish you a happy birthday.* Ce cas suit-il la règle du recul d'un temps ? Explique.\n\n**C.** Traduis.\n\n4. « Je regrette de lui avoir dit ça. »\n5. « J'aimerais que tu arrêtes de parler ! » (souhait de changement)\n6. « Si seulement j'avais écouté ! »","bareme":[{"critere":"Trois corrections expliquées (were ; I'd like ; would / were)","points":8},{"critere":"Wish you a happy birthday : exception, souhait ordinaire","points":4},{"critere":"Traductions 4 à 6 justes (regret saying ; wish you would stop ; If only I had listened)","points":8}],"dureeMin":14,"corrige":"**A.** 1. *I wish I were taller.* (recul + were). 2. *I'd like a coffee, please.* : would like est la forme polie. 3. *I wish I could be there.* ou *I wish I were there.* : wish n'est jamais suivi de will.\n\n**B.** Non : c'est la **seule** construction de wish qui ne recule pas d'un temps ; elle exprime un souhait ordinaire.\n\n**C.** 4. *I regret saying that to him.* 5. *I wish you would stop talking!* 6. *If only I had listened!*"}$exo$::jsonb),
  ('3cba9e1a-c179-56a4-aad7-d5420522fe23'::uuid, 1, 'traduction', $exo${"titre":"Certitude et possibilité","consigne":"Réponds en anglais.","enonce":"**Complète avec must, can't ou may.**\n\n1. He is yawning: he … be tired. (sûr)\n2. She is at school today, so she … be ill. (impossible)\n3. Take an umbrella: it … rain. (possible)\n4. Traduis : « Il doit être fatigué. »","bareme":[{"critere":"Must pour la certitude","points":5},{"critere":"Can't pour l'impossibilité","points":5},{"critere":"May (ou might) pour la possibilité","points":5},{"critere":"Traduction juste (He must be tired)","points":5}],"dureeMin":6,"corrige":"1. *must*.\n2. *can't* (certitude négative, pas *mustn't*).\n3. *may* (ou *might*).\n4. *He must be tired.*\n\n**Points attendus.** Must pour la certitude (5 pts) ; Can't pour l'impossibilité (5 pts) ; May (ou might) pour la possibilité (5 pts) ; Traduction juste (He must be tired) (5 pts)."}$exo$::jsonb),
  ('3cba9e1a-c179-56a4-aad7-d5420522fe23'::uuid, 2, 'traduction', $exo${"titre":"Qui a mangé le gâteau ?","consigne":"Réponds en anglais.","enonce":"**Situation.** Le gâteau a disparu. Tu fais des hypothèses.\n\n**A.** Écris trois déductions sur le passé, avec *must have*, *can't have* et *may have* + participe passé (eat, take, forget).\n\n**B.** Écris une phrase avec *probably* et une avec *be likely to*.\n\n**C.** Dis en français ce que signifie *He might know* par rapport à *He must know*.","bareme":[{"critere":"Trois structures modal + have + participe passé","points":9},{"critere":"Probably bien placé ; be likely to + BV","points":6},{"critere":"Might = doute plus grand que must","points":5}],"dureeMin":10,"corrige":"**A.** Exemples : *Tom must have eaten it.* — *The dog can't have taken it: it was outside.* — *Mum may have forgotten to buy it.*\n\n**B.** *He's probably at work.* (après be) — *It's likely to rain.*\n\n**C.** *He might know* : peut-être, avec un doute ; *He must know* : quasi-certitude."}$exo$::jsonb),
  ('3cba9e1a-c179-56a4-aad7-d5420522fe23'::uuid, 3, 'traduction', $exo${"titre":"L'échelle de la certitude","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Range du plus sûr au moins sûr : *may / must / might / can't / should*, puis dis ce qui distingue *can't* et *mustn't*.\n\n**B.** Traduis.\n\n1. « Ils ne peuvent pas être déjà arrivés. »\n2. « Il a dû rater le train. »\n3. « Elle est peut-être partie. » (may)\n\n**C.** Corrige : *He mustn't be at home.* (sens : il ne peut pas être chez lui) et *He must missed the bus.*","bareme":[{"critere":"Échelle juste (must, should, may/might, can't à part) avec la distinction can't/mustn't","points":6},{"critere":"Traductions 1 à 3 justes","points":8},{"critere":"Deux corrections (can't ; must have missed)","points":6}],"dureeMin":14,"corrige":"**A.** Certitude positive : *must* ; forte probabilité : *should* ; possibilité : *may*, *might* (un peu plus faible) ; certitude négative : *can't*. *Can't* dit « c'est impossible » ; *mustn't* garde le sens d'interdiction.\n\n**B.**\n1. *They can't have arrived yet.*\n2. *He must have missed the train.*\n3. *She may have left.*\n\n**C.** *He can't be at home.* — *He must have missed the bus.* (modal + have + participe passé)."}$exo$::jsonb),
  ('ff6c8aa1-5651-59b8-a45f-94ce5740e2a6'::uuid, 1, 'traduction', $exo${"titre":"Make, let, have","consigne":"Réponds en anglais.","enonce":"**Complète avec la bonne forme du verbe.**\n\n1. My parents make me (do) my homework.\n2. She let me (borrow) her bike.\n3. I had my hair (cut) yesterday.\n4. The film made me (cry).","bareme":[{"critere":"Base verbale après make et let","points":10},{"critere":"Participe passé après have (cut)","points":6},{"critere":"Aucun « to » ajouté","points":4}],"dureeMin":6,"corrige":"1. *do* (make + complément + base verbale).\n2. *borrow* (let + complément + base verbale).\n3. *cut* (have + complément + participe passé : quelqu'un d'autre coupe).\n4. *cry*.\n\n**Points attendus.** Base verbale après make et let (10 pts) ; Participe passé après have (cut) (6 pts) ; Aucun « to » ajouté (4 pts)."}$exo$::jsonb),
  ('ff6c8aa1-5651-59b8-a45f-94ce5740e2a6'::uuid, 2, 'traduction', $exo${"titre":"Chez le coiffeur","consigne":"Réponds en anglais.","enonce":"**Situation.** Nina raconte : « Mon frère m'a obligée à attendre. J'ai fait couper mes cheveux et réparer mon téléphone. Ma mère m'a laissée sortir. »\n\n**A.** Traduis chaque idée en anglais avec make, have, get ou let.\n\n**B.** Que signifie *I cut my hair* comparé à *I had my hair cut* ? Explique en français.","bareme":[{"critere":"Make me wait","points":4},{"critere":"Had my hair cut","points":4},{"critere":"Got/had my phone repaired","points":4},{"critere":"Let me go out","points":4},{"critere":"Différence expliquée (moi-même / fait faire)","points":4}],"dureeMin":10,"corrige":"**A.** *My brother made me wait.* — *I had my hair cut.* — *I got my phone repaired.* (ou *I had my phone repaired*) — *My mum let me go out.*\n\n**B.** *I cut my hair* : je l'ai coupée moi-même. *I had my hair cut* : quelqu'un d'autre l'a fait à ma demande (« je me suis fait couper les cheveux »)."}$exo$::jsonb),
  ('ff6c8aa1-5651-59b8-a45f-94ce5740e2a6'::uuid, 3, 'traduction', $exo${"titre":"Faire faire : constructions et pièges","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Corrige et explique.\n\n1. I made him to wait.\n2. She let me to go.\n3. We had the car repair.\n\n**B.** Passe à la voix passive et explique ce qui change.\n\n4. They made him wait. → …\n5. Ils ne me laissaient pas sortir. → utilise *allowed*.\n\n**C.** Que signifie *I got him to help me* ? Compare avec *I made him help me*.","bareme":[{"critere":"Trois corrections expliquées","points":6},{"critere":"Passif de make avec to (He was made to wait)","points":5},{"critere":"Let remplacé par be allowed to","points":4},{"critere":"Nuance get to (convaincre) / make (obliger)","points":5}],"dureeMin":14,"corrige":"**A.** 1. *I made him wait.* : pas de *to* après make actif. 2. *She let me go.* 3. *We had the car repaired.* : participe passé.\n\n**B.** 4. *He was made to wait.* : au passif, *to* réapparaît. 5. *I wasn't allowed to go out.* : let n'a pas de passif.\n\n**C.** *I got him to help me* : je l'ai **convaincu** de m'aider. *I made him help me* : je l'ai **obligé**."}$exo$::jsonb),
  ('457554b1-6e8a-5d7b-a6f0-8115da8fe992'::uuid, 1, 'traduction', $exo${"titre":"To ou -ING ?","consigne":"Réponds en anglais.","enonce":"**Complète avec to + verbe, base verbale ou -ING.**\n\n1. I enjoy (read).\n2. She decided (leave).\n3. You must (go).\n4. He is good at (swim).\n5. I went to the shop (buy) bread.","bareme":[{"critere":"-ING après enjoy et après préposition","points":8},{"critere":"to + verbe après decide et pour le but","points":8},{"critere":"Base verbale après modal","points":4}],"dureeMin":6,"corrige":"1. *reading* (enjoy + -ING).\n2. *to leave* (decide + to).\n3. *go* (modal + base verbale).\n4. *swimming* (préposition + -ING).\n5. *to buy* (infinitif de but).\n\n**Points attendus.** -ING après enjoy et après préposition (8 pts) ; to + verbe après decide et pour le but (8 pts) ; Base verbale après modal (4 pts)."}$exo$::jsonb),
  ('457554b1-6e8a-5d7b-a6f0-8115da8fe992'::uuid, 2, 'traduction', $exo${"titre":"Vacances de Tim","consigne":"Réponds en anglais.","enonce":"**Situation.** Tim écrit : « I love (play) football. I hope (visit) London. I'm looking forward to (see) you. Before (leave), I always finish (pack). »\n\n**A.** Recopie le texte en mettant chaque verbe à la bonne forme.\n\n**B.** Explique en français pourquoi *look forward to* est suivi de -ING.","bareme":[{"critere":"Love + -ING ; hope + to","points":6},{"critere":"Look forward to + -ING ; before + -ING","points":6},{"critere":"Finish + -ING","points":3},{"critere":"Explication : to est une préposition ici","points":5}],"dureeMin":10,"corrige":"**A.** *I love playing football. I hope to visit London. I'm looking forward to seeing you. Before leaving, I always finish packing.*\n\n**B.** Dans *look forward to*, *to* est une **préposition**, pas la marque de l'infinitif : après une préposition on emploie -ING."}$exo$::jsonb),
  ('457554b1-6e8a-5d7b-a6f0-8115da8fe992'::uuid, 3, 'traduction', $exo${"titre":"Le sens change","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Explique la différence de sens en français.\n\n1. *stop to smoke* / *stop smoking*\n2. *remember to lock the door* / *remember locking the door*\n3. *try to open the window* / *try opening the window*\n\n**B.** Corrige.\n\n4. I avoid to talk to him.\n5. She's good at to swim.\n6. I went to the shop for buying bread.\n\n**C.** Traduis : « Il suggère de partir. » et « Je suis allé au magasin pour acheter du pain. »","bareme":[{"critere":"Trois nuances de sens expliquées","points":9},{"critere":"Trois corrections (avoid + -ING ; at + -ING ; to buy)","points":6},{"critere":"Traductions justes","points":5}],"dureeMin":14,"corrige":"**A.** 1. s'arrêter **pour** fumer / arrêter de fumer. 2. penser à fermer / se souvenir d'avoir fermé. 3. essayer d'ouvrir / essayer en ouvrant, pour voir.\n\n**B.** 4. *I avoid talking to him.* 5. *She's good at swimming.* 6. *I went to the shop to buy bread.*\n\n**C.** *He suggests leaving.* — *I went to the shop to buy bread.* (infinitif de but, jamais *for buying*)."}$exo$::jsonb),
  ('5888f3ad-232f-517b-a4c4-10af3352c997'::uuid, 1, 'traduction', $exo${"titre":"Former des adverbes","consigne":"Réponds en anglais.","enonce":"**Donne l'adverbe de chaque adjectif.**\n\n1. slow  2. happy  3. good  4. fast  5. simple\n\n**Complète.** She is a good singer: she sings … .","bareme":[{"critere":"Slowly, happily, simply","points":9},{"critere":"Well pour good","points":5},{"critere":"Fast identique","points":4},{"critere":"She sings well","points":2}],"dureeMin":5,"corrige":"1. *slowly* 2. *happily* 3. *well* 4. *fast* (identique) 5. *simply*.\n\n*She sings well.* Good donne well ; fast, hard, late, early ne changent pas.\n\n**Points attendus.** Slowly, happily, simply (9 pts) ; Well pour good (5 pts) ; Fast identique (4 pts) ; She sings well (2 pts)."}$exo$::jsonb),
  ('5888f3ad-232f-517b-a4c4-10af3352c997'::uuid, 2, 'traduction', $exo${"titre":"Où placer l'adverbe ?","consigne":"Réponds en anglais.","enonce":"**A.** Place l'adverbe entre parenthèses.\n\n1. I get up early. (always)\n2. She is late. (never)\n3. I have been there. (never)\n4. I speak English. (well)\n\n**B.** Ordonne : *sang / beautifully / she / last night / at the concert.*","bareme":[{"critere":"Adverbes de fréquence bien placés (1 à 3)","points":9},{"critere":"English well : après le complément","points":5},{"critere":"Ordre manière, lieu, temps","points":6}],"dureeMin":9,"corrige":"**A.**\n1. *I always get up early.* (avant le verbe lexical)\n2. *She is never late.* (après be)\n3. *I have never been there.* (après l'auxiliaire)\n4. *I speak English well.* (jamais entre le verbe et son complément)\n\n**B.** *She sang beautifully at the concert last night.* (manière, lieu, temps)"}$exo$::jsonb),
  ('5888f3ad-232f-517b-a4c4-10af3352c997'::uuid, 3, 'traduction', $exo${"titre":"Faux amis et pièges des adverbes","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Que signifient *hardly* et *lately* ? Donne une phrase pour chacun.\n\n**B.** Corrige et explique.\n\n1. He drives careful.\n2. She speaks English fluent.\n3. I can't run enough fast.\n4. He works hardly. (il travaille dur)\n\n**C.** Écris trois phrases avec *always*, *very* et *enough* qui montrent la place de chacun.","bareme":[{"critere":"Hardly (à peine) et lately (récemment) avec phrases","points":6},{"critere":"Quatre corrections expliquées (carefully ; fluently ; fast enough ; hard)","points":8},{"critere":"Trois phrases : always avant le verbe, very devant l'adjectif, enough après","points":6}],"dureeMin":14,"corrige":"**A.** *hardly* = à peine (*I can hardly see*) ; *lately* = récemment (*I haven't seen him lately*).\n\n**B.** 1. *carefully* (adverbe de manière). 2. *fluently*. 3. *fast enough* : enough après l'adjectif. 4. *He works hard.* : *hard* est identique ; *hardly* = à peine.\n\n**C.** Exemples : *She always eats fruit.* — *It is very cold.* — *He isn't tall enough.*"}$exo$::jsonb),
  ('c28cc7d0-2f2a-5a7a-9c0b-fabb9d4596df'::uuid, 1, 'traduction', $exo${"titre":"Présent simple ou en -ING ?","consigne":"Réponds en anglais.","enonce":"**Choisis la bonne forme.**\n\n1. Look! It (rains / is raining).\n2. She (goes / is going) to school by bus every day.\n3. Water (boils / is boiling) at 100 °C.\n4. I (know / am knowing) the answer.","bareme":[{"critere":"Is raining (en cours)","points":5},{"critere":"Goes (habitude)","points":5},{"critere":"Boils (vérité générale)","points":5},{"critere":"Know (verbe d'état)","points":5}],"dureeMin":5,"corrige":"1. *is raining* (action en cours).\n2. *goes* (habitude).\n3. *boils* (vérité générale).\n4. *know* : les verbes d'état n'acceptent pas -ING.\n\n**Points attendus.** Is raining (en cours) (5 pts) ; Goes (habitude) (5 pts) ; Boils (vérité générale) (5 pts) ; Know (verbe d'état) (5 pts)."}$exo$::jsonb),
  ('c28cc7d0-2f2a-5a7a-9c0b-fabb9d4596df'::uuid, 2, 'traduction', $exo${"titre":"Une journée à Londres","consigne":"Réponds en anglais.","enonce":"**Situation.** Sam est en séjour linguistique.\n\n> Every morning Sam (get up) at seven. Today he (stay) with his host family because it (rain). He (study) English and (watch) TV. He (not / like) rainy days.\n\n**A.** Mets les verbes à la bonne forme (présent simple ou BE + -ING).\n\n**B.** Écris la 3e personne de *watch* et *study* et explique l'orthographe.","bareme":[{"critere":"Gets up (habitude)","points":3},{"critere":"Is staying, is raining, is studying, is watching","points":8},{"critere":"Doesn't like","points":4},{"critere":"Orthographe watches / studies expliquée","points":5}],"dureeMin":10,"corrige":"**A.** *gets up* — *is staying* — *is raining* — *is studying* — *is watching* — *doesn't like*.\n\n**B.** *watches* (-ch → -es) ; *studies* (consonne + y → -ies).\n\nHabituel → présent simple ; en train de se faire → be + -ING.\n\n**Points attendus.** Gets up (habitude) (3 pts) ; Is staying, is raining, is studying, is watching (8 pts) ; Doesn't like (4 pts) ; Orthographe watches / studies expliquée (5 pts)."}$exo$::jsonb),
  ('c28cc7d0-2f2a-5a7a-9c0b-fabb9d4596df'::uuid, 3, 'traduction', $exo${"titre":"Deux présents, deux sens","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Explique la différence de sens.\n\n1. *I play tennis.* / *I am playing tennis.*\n2. *He loses his keys.* / *He is always losing his keys!*\n\n**B.** Corrige et explique.\n\n3. She don't works here.\n4. I am wanting a coffee.\n5. We are meet Tom tonight.\n\n**C.** Traduis : « Le train part à six heures. » et « Nous retrouvons Tom ce soir. » (projet organisé).","bareme":[{"critere":"Deux différences de sens expliquées","points":6},{"critere":"Trois corrections expliquées","points":8},{"critere":"Traductions justes (The train leaves at six ; We are meeting Tom tonight)","points":6}],"dureeMin":14,"corrige":"**A.** 1. habitude / action en cours. 2. fait ponctuel / agacement face à une habitude répétée.\n\n**B.** 3. *She doesn't work here.* 4. *I want a coffee.* : want est un verbe d'état. 5. *We are meeting Tom tonight.*\n\n**C.** *The train leaves at six.* (programme fixe : présent simple) — *We are meeting Tom tonight.* (projet organisé : be + -ING)."}$exo$::jsonb),
  ('603f58c2-40a0-5b2d-9022-e13965f7bda1'::uuid, 1, 'traduction', $exo${"titre":"Mettre au prétérit","consigne":"Réponds en anglais.","enonce":"**Mets les verbes au prétérit simple.**\n\n1. I (play) football yesterday.\n2. She (study) last night.\n3. We (stop) at the shop.\n4. He (go) to Paris in 2019.\n5. They (see) a film last week.","bareme":[{"critere":"Played, studied, stopped (orthographe)","points":9},{"critere":"Went, saw (irréguliers)","points":8},{"critere":"Même forme à toutes les personnes","points":3}],"dureeMin":6,"corrige":"1. *played* 2. *studied* (consonne + y → -ied) 3. *stopped* (consonne doublée) 4. *went* 5. *saw*.\n\nLe prétérit a la même forme à toutes les personnes (sauf be : was/were).\n\n**Points attendus.** Played, studied, stopped (orthographe) (9 pts) ; Went, saw (irréguliers) (8 pts) ; Même forme à toutes les personnes (3 pts)."}$exo$::jsonb),
  ('603f58c2-40a0-5b2d-9022-e13965f7bda1'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Kim","consigne":"Réponds en anglais.","enonce":"**Situation.** Kim raconte son week-end.\n\n> Last Saturday I (get up) late. I (not / do) my homework. I (visit) my cousin and we (play) video games. Did you (have) a good weekend too?\n\n**A.** Mets les verbes au prétérit simple (négation et question comprises).\n\n**B.** Écris la question : *Did Kim … ?* avec *visit her cousin*.\n\n**C.** Que signifie *We used to play together every summer* ?","bareme":[{"critere":"Got up, didn't do, visited, played","points":8},{"critere":"Did you have (base verbale)","points":4},{"critere":"Did Kim visit her cousin ?","points":3},{"critere":"Used to = habitude passée qui n'a plus cours","points":5}],"dureeMin":10,"corrige":"**A.** *got up* — *didn't do* — *visited* — *played* — *Did you have* : après did/didn't, base verbale.\n\n**B.** *Did Kim visit her cousin?*\n\n**C.** *Nous jouions ensemble chaque été* : habitude passée qui n'a plus cours aujourd'hui."}$exo$::jsonb),
  ('603f58c2-40a0-5b2d-9022-e13965f7bda1'::uuid, 3, 'traduction', $exo${"titre":"Prétérit ou present perfect ?","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Corrige et explique.\n\n1. I have seen him yesterday.\n2. She didn't went to school.\n3. Did you saw the film?\n4. They stoped at six.\n\n**B.** Prononciation de -ed : classe *wanted, played, worked* selon [t], [d] ou [ɪd].\n\n**C.** Écris un petit récit de 3 phrases (*She opened…, took…, left*) et explique pourquoi on n'y met pas de past perfect. Ajoute une phrase avec *used to*.","bareme":[{"critere":"Quatre corrections expliquées","points":8},{"critere":"Prononciations justes : wanted [ɪd], played [d], worked [t]","points":4},{"critere":"Récit à trois prétérits et explication (ordre chronologique clair)","points":5},{"critere":"Phrase avec used to + base verbale","points":3}],"dureeMin":14,"corrige":"**A.** 1. *I saw him yesterday.* : un repère précis (*yesterday*) impose le prétérit. 2. *She didn't go to school.* 3. *Did you see the film?* 4. *They stopped at six.* (consonne doublée).\n\n**B.** *wanted* [ɪd] (t/d) ; *played* [d] (sonore) ; *worked* [t] (sourd).\n\n**C.** Ex. : *She opened the door, took her coat and left.* : l'ordre est déjà clair, trois prétérits suffisent. *I used to play football.*"}$exo$::jsonb),
  ('9be9b70b-6d29-5be3-ad11-8f8a571d6523'::uuid, 1, 'traduction', $exo${"titre":"Prétérit en -ING : la forme","consigne":"Réponds en anglais.","enonce":"**Complète avec was / were + verbe en -ING.**\n\n1. At eight o'clock, I (watch) TV.\n2. They (play) in the garden.\n3. She (not / work).\n4. (you / sleep) at ten?","bareme":[{"critere":"Was watching, were playing","points":8},{"critere":"Wasn't working","points":6},{"critere":"Were you sleeping ?","points":6}],"dureeMin":5,"corrige":"1. *was watching* 2. *were playing* 3. *wasn't working* 4. *Were you sleeping?*\n\nForme : was/were + verbe en -ING ; négation wasn't/weren't ; question par inversion.\n\n**Points attendus.** Was watching, were playing (8 pts) ; Wasn't working (6 pts) ; Were you sleeping ? (6 pts)."}$exo$::jsonb),
  ('9be9b70b-6d29-5be3-ad11-8f8a571d6523'::uuid, 2, 'traduction', $exo${"titre":"Décor et événement","consigne":"Réponds en anglais.","enonce":"**Situation.** Théo raconte un accident.\n\n> I (walk) home when it (start) to rain. While I (run), I (see) my friend. She (wait) for the bus.\n\n**A.** Complète avec le prétérit simple ou le prétérit en BE + -ING.\n\n**B.** Quelle est l'action décor, quelle est l'action événement dans la première phrase ? Justifie.","bareme":[{"critere":"Was walking, started","points":6},{"critere":"Was running, saw","points":6},{"critere":"Was waiting","points":3},{"critere":"Décor (long, -ING) et événement (court, prétérit simple) justifiés","points":5}],"dureeMin":10,"corrige":"**A.** *was walking* — *started* — *was running* — *saw* — *was waiting*.\n\n**B.** Décor : *I was walking* (action longue, en cours) ; événement : *it started to rain* (action courte qui survient). Ce qui encadre est en -ING, ce qui survient est au prétérit simple."}$exo$::jsonb),
  ('9be9b70b-6d29-5be3-ad11-8f8a571d6523'::uuid, 3, 'traduction', $exo${"titre":"Simultané, interrompu, terminé","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Traduis.\n\n1. « Elle cuisinait pendant qu'il faisait ses devoirs. »\n2. « Le téléphone a sonné pendant que je lisais. »\n\n**B.** Explique la différence : *I watched a film last night* / *I was watching a film last night.*\n\n**C.** Corrige : *I was knowing the answer.* et *They didn't were playing.* et *Was you working?*","bareme":[{"critere":"Traduction 1 (deux -ING avec while)","points":5},{"critere":"Traduction 2 (while I was reading, the phone rang)","points":5},{"critere":"Différence expliquée (film fini / en cours)","points":5},{"critere":"Trois corrections (knew ; weren't playing ; Were you)","points":5}],"dureeMin":14,"corrige":"**A.** 1. *She was cooking while he was doing his homework.* 2. *While I was reading, the phone rang.* (ou *The phone rang while I was reading.*)\n\n**B.** *I watched a film* : le film est fini. *I was watching a film* : on ne sait pas si je suis allé au bout.\n\n**C.** *I knew the answer.* (verbe d'état) — *They weren't playing.* — *Were you working?*"}$exo$::jsonb),
  ('46244cfd-d0c6-5842-9ffa-3decc7d0c6b1'::uuid, 1, 'traduction', $exo${"titre":"Present perfect : la forme","consigne":"Réponds en anglais.","enonce":"**Mets les verbes au present perfect.**\n\n1. I (finish) my homework.\n2. She (go) to Paris.\n3. We (not / see) him.\n4. (you / eat) sushi?\n5. Complète : I have lived here … five years / … 2020.","bareme":[{"critere":"Have finished, has gone","points":6},{"critere":"Haven't seen, Have you eaten ?","points":8},{"critere":"For une durée, since un point de départ","points":6}],"dureeMin":6,"corrige":"1. *have finished* 2. *has gone* 3. *haven't seen* 4. *Have you eaten sushi?* 5. *for* five years / *since* 2020.\n\nForme : have/has + participe passé (3e colonne des irréguliers).\n\n**Points attendus.** Have finished, has gone (6 pts) ; Haven't seen, Have you eaten ? (8 pts) ; For une durée, since un point de départ (6 pts)."}$exo$::jsonb),
  ('46244cfd-d0c6-5842-9ffa-3decc7d0c6b1'::uuid, 2, 'traduction', $exo${"titre":"Un séjour à Londres","consigne":"Réponds en anglais.","enonce":"**Situation.** Zoé écrit un message.\n\n> I ___ (be) in London for two weeks. I ___ (already / visit) the museum. I ___ (not / see) the palace yet. Last Monday I ___ (go) to a concert.\n\n**A.** Complète avec le prétérit ou le present perfect.\n\n**B.** Place *just* dans : *I have arrived.* et *yet* dans : *Have you finished?*\n\n**C.** Pourquoi *went* dans la dernière phrase ? Réponds en français.","bareme":[{"critere":"Have been, have already visited","points":6},{"critere":"Haven't seen yet, went","points":5},{"critere":"Just et yet bien placés","points":5},{"critere":"Justification : Last Monday = repère précis → prétérit","points":4}],"dureeMin":10,"corrige":"**A.** *have been* — *have already visited* — *haven't seen* (… *yet*) — *went*.\n\n**B.** *I have just arrived.* (entre l'auxiliaire et le participe) — *Have you finished yet?* (yet en fin de phrase).\n\n**C.** *Last Monday* est un repère passé précis : il impose le prétérit, jamais le present perfect."}$exo$::jsonb),
  ('46244cfd-d0c6-5842-9ffa-3decc7d0c6b1'::uuid, 3, 'traduction', $exo${"titre":"Present perfect ou prétérit ?","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Corrige et explique.\n\n1. I have seen him yesterday.\n2. She has lived here since five years.\n3. I has seen that film.\n4. Have you ever ate sushi?\n\n**B.** Traduis.\n\n5. « Elle travaille ici depuis 2020. »\n6. « Je n'ai jamais été au Japon. »\n7. « Nous avons perdu nos clés (et nous ne les avons toujours pas). »\n\n**C.** Explique en deux phrases la différence entre *I have lost my keys* et *I lost my keys yesterday.*","bareme":[{"critere":"Quatre corrections expliquées","points":8},{"critere":"Trois traductions justes","points":6},{"critere":"Différence : résultat présent / date passée coupée du présent","points":6}],"dureeMin":14,"corrige":"**A.** 1. *I saw him yesterday.* (repère précis). 2. *for five years.* 3. *I have seen…* : have avec I. 4. *Have you ever eaten sushi?*\n\n**B.** 5. *She has worked here since 2020.* 6. *I have never been to Japan.* 7. *We have lost our keys.*\n\n**C.** Le present perfect relie le passé au présent (je n'ai plus mes clés maintenant) ; le prétérit avec *yesterday* raconte un fait daté et coupé du présent."}$exo$::jsonb),
  ('4e207dd7-f3ec-5d24-a5e2-a222e57211ef'::uuid, 1, 'traduction', $exo${"titre":"Past perfect : la forme","consigne":"Réponds en anglais.","enonce":"**Complète avec le past perfect.**\n\n1. When I arrived, the train (already / leave).\n2. She (not / finish) her homework.\n3. (you / see) him before?\n4. Que signifie la contraction dans *I'd finished* ?","bareme":[{"critere":"Had already left","points":6},{"critere":"Hadn't finished","points":5},{"critere":"Had you seen ... ?","points":5},{"critere":"'d = had (suivi d'un participe passé)","points":4}],"dureeMin":5,"corrige":"1. *had already left* 2. *hadn't finished* 3. *Had you seen him before?* 4. *I'd finished* = *I had finished*.\n\nForme : had + participe passé, à toutes les personnes.\n\n**Points attendus.** Had already left (6 pts) ; Hadn't finished (5 pts) ; Had you seen ... ? (5 pts) ; 'd = had (suivi d'un participe passé) (4 pts)."}$exo$::jsonb),
  ('4e207dd7-f3ec-5d24-a5e2-a222e57211ef'::uuid, 2, 'traduction', $exo${"titre":"Avant ou après ?","consigne":"Réponds en anglais.","enonce":"**Situation.** Ali raconte : « I arrived at the station at six. The train left at five fifty. She was upset. She failed the test. »\n\n**A.** Relie les phrases avec *when* et *because* en mettant l'action antérieure au past perfect.\n\n**B.** Explique en français pourquoi *When I arrived, the train left* change le sens.\n\n**C.** Écris : *After / eat / go out* avec le past perfect.","bareme":[{"critere":"When I arrived, the train had already left","points":6},{"critere":"She was upset because she had failed the test","points":6},{"critere":"Explication de l'ordre chronologique","points":4},{"critere":"After he had eaten, he went out","points":4}],"dureeMin":10,"corrige":"**A.** *When I arrived, the train had already left.* — *She was upset because she had failed the test.*\n\n**B.** Sans past perfect, on comprendrait que le train est parti **après** mon arrivée.\n\n**C.** *After he had eaten, he went out.*"}$exo$::jsonb),
  ('4e207dd7-f3ec-5d24-a5e2-a222e57211ef'::uuid, 3, 'traduction', $exo${"titre":"Le passé du passé","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Discours indirect : transforme.\n\n1. « I saw him. » → He said …\n2. « I have finished. » → She said …\n\n**B.** Traduis.\n\n3. « Si j'avais su, je serais venu. »\n4. « Je voudrais avoir mieux étudié. »\n\n**C.** Corrige et explique : *When I had arrived, the train left already.* Puis dis dans quel cas le past perfect n'est pas nécessaire (exemple à l'appui).","bareme":[{"critere":"Discours indirect : had seen, had finished","points":6},{"critere":"Traductions 3 et 4 justes (had known, would have come ; wish I had studied better)","points":6},{"critere":"Correction et explication de l'antériorité","points":4},{"critere":"Cas où il est inutile (ordre chronologique clair) avec exemple","points":4}],"dureeMin":14,"corrige":"**A.** 1. *He said he had seen him.* 2. *She said she had finished.* (le temps recule d'un cran)\n\n**B.** 3. *If I had known, I would have come.* 4. *I wish I had studied harder.*\n\n**C.** *When I arrived, the train had already left.* : l'action la plus ancienne prend le past perfect, la plus récente le prétérit. Inutile quand l'ordre est clair : *She opened the door, took her coat and left.*"}$exo$::jsonb),
  ('5bf23e62-b833-599e-a78a-f76019c10ed0'::uuid, 1, 'traduction', $exo${"titre":"Will, going to, présent","consigne":"Réponds en anglais.","enonce":"**Choisis la bonne forme.**\n\n1. The phone is ringing: I (will get / am getting) it! (décision immédiate)\n2. Look at those clouds: it (will rain / is going to rain).\n3. The train (leaves / will leave) at 7.15. (horaire)\n4. I (am meeting / will meet) Sarah at six. (rendez-vous)","bareme":[{"critere":"Will get","points":5},{"critere":"Is going to rain","points":5},{"critere":"Leaves","points":5},{"critere":"Am meeting","points":5}],"dureeMin":6,"corrige":"1. *I'll get it* (décision prise au moment de parler). 2. *it's going to rain* (indice présent). 3. *leaves* (horaire officiel : présent simple). 4. *I am meeting Sarah* (rendez-vous organisé).\n\n**Points attendus.** Will get (5 pts) ; Is going to rain (5 pts) ; Leaves (5 pts) ; Am meeting (5 pts)."}$exo$::jsonb),
  ('5bf23e62-b833-599e-a78a-f76019c10ed0'::uuid, 2, 'traduction', $exo${"titre":"Projets de vacances","consigne":"Réponds en anglais.","enonce":"**Situation.** Léa parle de son été.\n\n**A.** Écris une phrase pour chaque idée : (1) une intention déjà formée ; (2) un rendez-vous organisé avec une heure ; (3) une promesse.\n\n**B.** Complète : *I'll call you when I (arrive).* et *As soon as she (come), we'll leave.*\n\n**C.** Traduis : « J'allais t'appeler, mais j'ai oublié. »","bareme":[{"critere":"Be going to pour l'intention","points":4},{"critere":"Be + -ING pour le rendez-vous","points":4},{"critere":"Will pour la promesse","points":3},{"critere":"Présent après when / as soon as","points":5},{"critere":"Was going to","points":4}],"dureeMin":10,"corrige":"**A.** *I'm going to learn to surf.* — *I'm meeting Tom at six.* — *I will always help you.*\n\n**B.** *arrive* — *comes* : après when / as soon as, on emploie le présent, jamais will.\n\n**C.** *I was going to call you, but I forgot.*"}$exo$::jsonb),
  ('5bf23e62-b833-599e-a78a-f76019c10ed0'::uuid, 3, 'traduction', $exo${"titre":"Choisir la bonne forme du futur","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Pour chaque phrase, dis quelle forme du futur est employée et ce qu'elle exprime.\n\n1. *I'll have the pizza.* (au restaurant)\n2. *We are going to move house next month.*\n3. *The film starts at eight.*\n\n**B.** Corrige et explique.\n\n4. I'll wait until she will come.\n5. It rains tomorrow, I think.\n\n**C.** Écris un mini-dialogue de trois répliques qui utilise will, be going to et be + -ING.","bareme":[{"critere":"Trois formes identifiées et justifiées","points":8},{"critere":"Deux corrections expliquées","points":6},{"critere":"Dialogue cohérent avec les trois formes","points":6}],"dureeMin":14,"corrige":"**A.** 1. *will* : décision prise sur le moment. 2. *be going to* : intention déjà formée. 3. présent simple : horaire officiel.\n\n**B.** 4. *until she comes* : présent après until. 5. *I think it will rain tomorrow.* : prédiction avec will.\n\n**C.** Ex. : *What are you doing tonight? — I'm meeting Sam. We're going to see a film. — Great, I'll come too!*"}$exo$::jsonb),
  ('6729549c-84de-5b94-a173-23caf85f21f6'::uuid, 1, 'traduction', $exo${"titre":"Type 1, 2 ou 3 ?","consigne":"Réponds en anglais.","enonce":"**Complète avec la bonne forme.**\n\n1. If it (rain), I will stay home.\n2. If I (have) more time, I would travel.\n3. If I (be) you, I would apologise.\n4. If she had studied, she (pass) the exam.","bareme":[{"critere":"Rains (type 1)","points":4},{"critere":"Had (type 2)","points":5},{"critere":"Were (type 2)","points":5},{"critere":"Would have passed (type 3)","points":6}],"dureeMin":6,"corrige":"1. *rains* (if + présent, will). 2. *had* (if + prétérit, would). 3. *were* (à toutes les personnes). 4. *would have passed* (if + past perfect, would have + participe passé).\n\n**Points attendus.** Rains (type 1) (4 pts) ; Had (type 2) (5 pts) ; Were (type 2) (5 pts) ; Would have passed (type 3) (6 pts)."}$exo$::jsonb),
  ('6729549c-84de-5b94-a173-23caf85f21f6'::uuid, 2, 'traduction', $exo${"titre":"Que se passerait-il ?","consigne":"Réponds en anglais.","enonce":"**Situation.** Mia pense à son avenir.\n\n**A.** Écris une phrase de chaque type avec *If*.\n\n1. Type 1 : possible (study / pass)\n2. Type 2 : irréel du présent (win a lot of money / travel)\n3. Type 3 : regret (revise / pass)\n\n**B.** Où met-on la virgule ? Écris la phrase 1 dans l'autre ordre.","bareme":[{"critere":"Type 1 juste","points":5},{"critere":"Type 2 juste","points":5},{"critere":"Type 3 juste","points":5},{"critere":"Virgule et inversion des propositions","points":5}],"dureeMin":10,"corrige":"**A.** *If she studies, she will pass.* — *If I won a lot of money, I would travel.* — *If I had revised, I would have passed.*\n\n**B.** *She will pass if she studies.* : pas de virgule quand la principale ouvre la phrase ; avec *If* en tête, on met une virgule."}$exo$::jsonb),
  ('6729549c-84de-5b94-a173-23caf85f21f6'::uuid, 3, 'traduction', $exo${"titre":"Le conditionnel en action","consigne":"Réponds en anglais ; justifie en français.","enonce":"**A.** Corrige et explique.\n\n1. If I will have time, I will come.\n2. If I was you, I will apologise.\n3. If I would know, I would tell you.\n4. If he had known, he would come.\n\n**B.** Que signifie *If I had studied, I would have passed* ? Ce qui s'est réellement passé ?\n\n**C.** Écris une phrase avec *would like*, une avec *would rather*, et une avec *wish … could*.","bareme":[{"critere":"Quatre corrections expliquées","points":8},{"critere":"Sens du type 3 (je n'ai pas étudié, j'ai échoué)","points":5},{"critere":"Trois phrases (would like, would rather, wish + could)","points":7}],"dureeMin":14,"corrige":"**A.** 1. *If I have time, I will come.* : jamais will après if. 2. *If I were you, I would apologise.* 3. *If I knew, I would tell you.* : jamais would après if. 4. *If he had known, he would have come.* (type 3).\n\n**B.** Je n'ai pas étudié et j'ai échoué : c'est un regret sur le passé.\n\n**C.** *I'd like a coffee.* — *I'd rather stay home.* — *I wish I could come.*"}$exo$::jsonb),
  ('a4a0a655-c66d-5180-9dba-7afc5b3d5891'::uuid, 1, 'redaction', $exo${"titre":"Chanson de geste ou roman de chevalerie ?","consigne":"Lis les deux résumés (écrits pour l’exercice), puis réponds par des phrases complètes.","enonce":"> **Résumé A.** Le comte Aubry tient seul le pont avec l’arrière-garde de l’empereur. Il refuse d’appeler du renfort, persuadé d’être assez fort. Ses compagnons tombent un à un ; l’empereur, prévenu trop tard, revient venger les morts.\n>\n> **Résumé B.** Pour mériter le regard de sa dame, le chevalier Erwan quitte la cour. Dans une forêt enchantée, une fée lui offre un anneau magique. Après bien des épreuves, il revient plus sage.\n\n1. Indique si chaque résumé évoque plutôt une **chanson de geste** ou un **roman de chevalerie**. Justifie par deux éléments du texte pour chacun.\n2. Quelle valeur du chevalier le comte Aubry oublie-t-il ? Comment s’appelle son défaut ?","bareme":[{"critere":"Résumé A reconnu comme chanson de geste (exploits guerriers, fidélité à l’empereur) avec justification","points":6},{"critere":"Résumé B reconnu comme roman de chevalerie (amour, quête, merveilleux) avec justification","points":6},{"critere":"Défaut nommé : la démesure (comparée à l’orgueil de Roland), et lien avec le refus d’appeler à l’aide","points":8}],"dureeMin":6,"corrige":"1. **Résumé A** : c’est une **chanson de geste**. Il raconte un **exploit guerrier** (tenir un pont contre l’ennemi) et la **fidélité au seigneur** : l’empereur vient venger les siens. Le ton rappelle *La Chanson de Roland*.\n**Résumé B** : c’est un **roman de chevalerie**. Il tourne autour de l’**amour** (la dame) et d’une **quête** intérieure (le chevalier revient plus sage) ; le **merveilleux** est présent (la forêt enchantée, la fée, l’anneau magique). Ce genre, illustré par Chrétien de Troyes, est écrit pour être **lu**.\n\n2. Le comte Aubry oublie la **mesure** : il refuse l’aide par orgueil. Son défaut s’appelle la **démesure**, exactement comme Roland qui refuse de sonner l’olifant à temps : ses hommes en meurent. Un héros médiéval doit être exemplaire, pas seulement fort."}$exo$::jsonb),
  ('a4a0a655-c66d-5180-9dba-7afc5b3d5891'::uuid, 2, 'redaction', $exo${"titre":"Les valeurs du chevalier Baudouin","consigne":"Lis le portrait (écrit pour l’exercice), puis réponds en justifiant.","enonce":"> **Portrait.** Baudouin défend jusqu’au bout le seigneur qui l’a adoubé, même quand la bataille est perdue. Le matin, il partage sa bourse avec un paysan affamé. Devant la dame du château, il s’incline avec grâce et parle avec douceur. Avant le combat, il prie. Puis il charge seul contre dix ennemis.\n\n1. Associe chaque comportement à l’une des cinq valeurs du chevalier : **prouesse, loyauté, foi, largesse, courtoisie**. Une phrase par valeur.\n2. Le dernier comportement peut être admirable, mais aussi dangereux. Explique pourquoi en utilisant le mot **démesure**.\n3. Pourquoi dit-on que le héros médiéval est « exemplaire » et pas seulement fort ?","bareme":[{"critere":"Les cinq valeurs correctement associées aux cinq comportements","points":10},{"critere":"Explication du risque de démesure pour la charge solitaire, avec la référence à Roland","points":6},{"critere":"Idée que la vie du héros sert de modèle à ceux qui l’écoutent","points":4}],"dureeMin":10,"corrige":"1. **Loyauté** : il défend le seigneur qui l’a adoubé (lien vassalique). **Largesse** : il partage sa bourse avec le paysan affamé. **Courtoisie** : il s’incline et parle avec douceur devant la dame. **Foi** : il prie avant de combattre, le chevalier chrétien combat pour Dieu. **Prouesse** : il charge seul contre dix, courage et force au combat.\n\n2. Charger seul contre dix montre la prouesse, mais peut virer à la **démesure** : refuser toute prudence par orgueil. C’est la faute de **Roland**, qui refuse de sonner l’olifant, et tous ses hommes en meurent. La démesure est le défaut à éviter.\n\n3. Le héros médiéval est **exemplaire** : sa vie sert de **modèle** aux auditeurs ou aux lecteurs. Il faut donc qu’il réunisse plusieurs valeurs (loyauté, foi, largesse, courtoisie) et pas seulement la force au combat."}$exo$::jsonb),
  ('a4a0a655-c66d-5180-9dba-7afc5b3d5891'::uuid, 3, 'redaction', $exo${"titre":"Roland est-il un héros parfait ?","consigne":"Rédige un paragraphe argumenté de 10 à 15 lignes, en t’appuyant sur le rappel ci-dessous.","enonce":"**Rappel.** L’arrière-garde de Charlemagne est attaquée à Roncevaux. Olivier, compagnon de Roland, lui conseille de sonner du cor pour appeler l’armée. Roland refuse. Quand il se décide enfin, il est trop tard : il meurt le visage tourné vers l’ennemi, et Charlemagne vient venger les siens. *La Chanson de Roland* est écrite en **laisses**, sur une même **assonance**.\n\n**Sujet.** « Roland est-il un héros parfait ? » Réponds par un paragraphe organisé : une thèse, au moins deux arguments illustrés par des faits du récit, et une conclusion. Emploie au moins trois de ces mots : *démesure, olifant, loyauté, prouesse, exemplaire, laisse*.","bareme":[{"critere":"Thèse claire et nuancée (héros admirable mais imparfait)","points":4},{"critere":"Deux arguments au moins illustrés par des faits précis (refus de l’olifant, mort face à l’ennemi, fidélité à Charlemagne)","points":7},{"critere":"Emploi juste de la notion de démesure et de la valeur d’exemplarité","points":5},{"critere":"Paragraphe organisé, vocabulaire du cours (trois mots au moins), langue correcte","points":4}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : Roland est un héros admirable, mais pas un héros parfait, car sa démesure cause la mort de ses hommes.\n\n**Arguments** :\n- Ses qualités : il possède la **prouesse** (il se bat jusqu’à sa mort, le visage tourné vers l’ennemi) et la **loyauté** envers son seigneur Charlemagne, qui vient le venger.\n- Son défaut : par **orgueil**, il refuse de **sonner l’olifant** malgré le conseil d’Olivier. Il sonne trop tard et l’arrière-garde est massacrée. C’est la **démesure**, défaut que le héros médiéval doit éviter.\n- Le poème, en **laisses** (strophes de longueur variable sur une même assonance), n’en fait pas un modèle sans faille : il montre sa grandeur et sa faute.\n\n**Conclusion** : le héros médiéval est exemplaire par ses valeurs, mais la mesure lui est aussi indispensable que la force. Est acceptée toute copie qui défend la thèse inverse (Roland est parfait) si elle reconnaît la faute et l’argumente avec le récit."}$exo$::jsonb),
  ('01669d26-296b-5577-bdc5-f80eaba6227d'::uuid, 1, 'redaction', $exo${"titre":"À chaque héros son monstre","consigne":"Réponds par des phrases courtes.","enonce":"1. Associe chaque monstre à son vainqueur : le **Cyclope**, l’**Hydre**, le **Minotaure**, **Méduse**. Les héros à choisir sont : Persée, Thésée, Héraclès, Ulysse.\n2. Complète la définition : « Un héros antique est un personnage exceptionnel, souvent né d’un ….. et d’une ….. , qui accomplit des exploits surhumains mais qui ….. »\n3. Qui aide Thésée à sortir du labyrinthe, et comment ?","bareme":[{"critere":"Les quatre monstres associés à leur vainqueur","points":8},{"critere":"Définition du héros antique complétée (dieu, mortelle, meurt)","points":6},{"critere":"Ariane et son fil","points":6}],"dureeMin":6,"corrige":"1. Le **Cyclope** : Ulysse. L’**Hydre** : Héraclès. Le **Minotaure** : Thésée. **Méduse** : Persée.\n\n2. Un héros antique est un personnage exceptionnel, souvent né d’un **dieu** et d’une **mortelle**, qui accomplit des exploits surhumains mais qui **meurt** : il n’est ni tout à fait dieu, ni tout à fait homme.\n\n3. **Ariane** aide Thésée à sortir du labyrinthe grâce à un **fil** : il le déroule en entrant et le suit pour retrouver son chemin après avoir tué le Minotaure."}$exo$::jsonb),
  ('01669d26-296b-5577-bdc5-f80eaba6227d'::uuid, 2, 'redaction', $exo${"titre":"Achille ou Ulysse ?","consigne":"Lis les deux portraits (écrits pour l’exercice), puis réponds en justifiant.","enonce":"> **Portrait 1.** Ce guerrier est le meilleur de son armée. On lui a prédit deux destins : rentrer chez lui et vivre longtemps sans gloire, ou rester au combat et mourir jeune, mais couvert d’honneur. Il choisit de rester.\n>\n> **Portrait 2.** Ce roi met dix ans à rentrer dans son île. Pour échapper à un géant qui l’a enfermé, il invente une ruse ; pour prendre une ville, il fait construire un cheval de bois. Il survit à tout et retrouve les siens.\n\n1. Identifie chaque héros et donne l’œuvre à laquelle il appartient.\n2. Présente sous forme de tableau **trois oppositions** entre ces deux modèles d’héroïsme.\n3. Quel choix fait Achille, et qu’est-ce que cela révèle de sa conception de l’héroïsme ?","bareme":[{"critere":"Identification des deux héros et de l’Iliade / l’Odyssée","points":4},{"critere":"Trois oppositions justes (force/ruse, gloire/retour, mort jeune/survie)","points":10},{"critere":"Choix d’Achille expliqué : préférer la gloire à la longévité","points":6}],"dureeMin":10,"corrige":"1. **Portrait 1** : Achille, dans l’*Iliade*. **Portrait 2** : Ulysse, dans l’*Odyssée* (le géant est le Cyclope, le cheval de bois celui de Troie).\n\n2. | Achille | Ulysse |\n|---|---|\n| La **force** | La **ruse** |\n| La **gloire** | Le **retour** |\n| La **mort jeune** | La **survie** |\n\n3. Achille choisit une **vie courte et glorieuse** plutôt qu’une vie longue et obscure. Pour lui, l’héroïsme est dans l’exploit qui reste dans la mémoire, même au prix de la mort ; c’est l’opposé d’Ulysse, qui veut avant tout rentrer chez lui."}$exo$::jsonb),
  ('01669d26-296b-5577-bdc5-f80eaba6227d'::uuid, 3, 'redaction', $exo${"titre":"Le héros antique est-il un modèle moral ?","consigne":"Rédige un paragraphe argumenté de 10 à 15 lignes.","enonce":"**Sujet.** « Le héros antique est un modèle moral irréprochable. » Discute cette affirmation en t’appuyant sur **au moins deux** héros vus en cours parmi Achille, Ulysse et Héraclès.\n\n**Rappels.**\n- L’*hybris* désigne la démesure, l’orgueil excessif, qui est toujours punie par les dieux.\n- La colère d’Achille en est l’exemple le plus célèbre.\n- Les douze travaux d’Héraclès sont l’expiation d’une faute.\n- Ulysse est admiré pour sa ruse et sa ténacité.\n\nTa réponse doit comporter une thèse, des arguments illustrés d’exemples précis et une conclusion.","bareme":[{"critere":"Thèse claire : le héros est admirable mais faillible, donc pas irréprochable","points":4},{"critere":"Un premier exemple précis et expliqué (Achille et l’hybris, ou Héraclès et sa faute)","points":5},{"critere":"Un second exemple précis d’un autre héros (qualité admirée et limite)","points":5},{"critere":"Emploi juste du mot hybris et conclusion sur l’ambiguïté du héros","points":3},{"critere":"Organisation et qualité de la langue","points":3}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : l’affirmation est fausse : le héros antique est **admirable et faillible à la fois**. Cette ambiguïté le rend inépuisable.\n\n**Exemples possibles** :\n- **Achille** : le meilleur guerrier, invulnérable sauf au talon, mais sa **colère** est un cas d’**hybris** (démesure, orgueil) qui coûte cher aux siens et à lui-même. Il choisit une vie courte et glorieuse.\n- **Héraclès** : ses **douze travaux** sont l’**expiation d’une faute** : le héros a donc commis une faute grave.\n- **Ulysse** : admirable par sa **ruse** et sa **ténacité** (dix ans pour rentrer), mais sa ruse est une qualité d’intelligence, pas de pureté morale.\n\n**Conclusion** : le héros antique ne donne pas un modèle de conduite parfait ; il montre la grandeur humaine avec ses défauts, et l’hybris est toujours punie par les dieux. Toute nuance argumentée est acceptée."}$exo$::jsonb),
  ('6a380608-689d-5a2d-b67e-70358a89b0d7'::uuid, 1, 'redaction', $exo${"titre":"La machine vivante","consigne":"Lis le texte (écrit pour l’exercice), puis réponds.","enonce":"> La locomotive s’ébrouait dans la gare. Elle soufflait, toussait, avalait son charbon avec un grondement de bête affamée. Autour d’elle, les ouvriers, alignés comme des rouages, répétaient les mêmes gestes sans un mot.\n\n1. Relève **deux verbes** qui donnent à la machine des gestes d’être vivant.\n2. Comment s’appelle ce procédé ?\n3. Comment les ouvriers sont-ils décrits ? Quel renversement cela produit-il ?","bareme":[{"critere":"Deux verbes justes relevés (s’ébrouait, soufflait, toussait, avalait, grondement)","points":6},{"critere":"Personnification nommée","points":6},{"critere":"Ouvriers comparés à des rouages (des choses) et renversement machine vivante / homme mécanisé","points":8}],"dureeMin":6,"corrige":"1. Par exemple : **s’ébrouait**, **soufflait**, **toussait**, **avalait** (deux suffisent).\n\n2. C’est une **personnification** : la machine reçoit un corps et une volonté (elle respire, avale, gronde).\n\n3. Les ouvriers sont « **alignés comme des rouages** » : ils sont réduits à des **choses**, à des pièces de mécanisme, sans parole. C’est un **renversement** : la machine devient vivante et l’ouvrier devient une chose. Le repérer, c’est comprendre le texte."}$exo$::jsonb),
  ('6a380608-689d-5a2d-b67e-70358a89b0d7'::uuid, 2, 'redaction', $exo${"titre":"Deux regards sur le train","consigne":"Lis les deux textes (écrits pour l’exercice), puis réponds.","enonce":"> **Texte A.** En trois heures, on traverse la moitié du pays. La nuit ne fait plus peur, la distance est vaincue : le train est le plus beau poème du siècle.\n>\n> **Texte B.** Le train a coupé la prairie en deux. Les vaches ne broutent plus qu’au bord d’un rideau de fumée noire, et l’air a un goût de suie.\n\n1. Dis quelle attitude face au progrès exprime chaque texte, en justifiant par un mot ou une expression.\n2. Cite un écrivain du XIXe siècle vu en cours qui a pu écrire comme le texte A, et un autre comme le texte B (avec une œuvre).\n3. Que représente la nature pour les romantiques, et en quoi le texte B en est-il proche ?\n4. Pourquoi ces textes posent-ils la question : « l’homme est-il maître de la nature ? »","bareme":[{"critere":"Attitudes justes (enthousiasme / inquiétude) justifiées par le texte","points":6},{"critere":"Deux auteurs et une œuvre bien associés (Verne ou Hugo ; Zola)","points":5},{"critere":"Nature refuge et miroir de l’âme, lien avec le texte B","points":5},{"critere":"Réflexion sur la maîtrise de la nature par l’homme","points":4}],"dureeMin":10,"corrige":"1. **Texte A** : **enthousiasme** (« le plus beau poème du siècle », « la distance est vaincue »). **Texte B** : **inquiétude** (« coupé la prairie », « fumée noire », « goût de suie »).\n\n2. Texte A : **Jules Verne** (le progrès comme matière de romans) ou **Hugo**, qui salue le train comme un poème. Texte B : **Zola** (*Germinal*, où la mine est une bête goulue, ou *La Bête humaine*).\n\n3. Pour les romantiques (Rousseau, Lamartine, Hugo), la nature est un **refuge** et un **miroir de l’âme**. Le texte B regrette la prairie détruite : il défend cette nature menacée.\n\n4. L’homme transforme le paysage à grande échelle : est-il **maître** de la nature, ou en fait-il **partie** et la détruit-il ? Les textes du XIXe siècle formulent déjà les questions écologiques d’aujourd’hui."}$exo$::jsonb),
  ('6a380608-689d-5a2d-b67e-70358a89b0d7'::uuid, 3, 'redaction', $exo${"titre":"La mine qui a faim","consigne":"Lis le texte (écrit pour l’exercice), puis réponds par un devoir organisé.","enonce":"> La mine avait faim. Chaque matin, elle avalait sa ration d’hommes par le puits, les mâchait dans ses galeries, et les recrachait le soir, vidés. Eux, ils descendaient à la file, pareils à des wagonnets, sans un cri.\n\n1. Relève les mots qui donnent vie à la mine et ceux qui transforment les hommes en objets. Nomme les deux procédés.\n2. Explique en quelques lignes le **renversement** produit par ces deux choix d’écriture.\n3. Quel roman de Zola le texte rappelle-t-il, et de quelle inquiétude est-il le signe ?\n4. En un paragraphe, dis ce que ce texte répond à la question : « l’être humain est-il maître de la nature ? »","bareme":[{"critere":"Relevé juste (avait faim, avalait, mâchait, recrachait / à la file, wagonnets) et procédés nommés (personnification, comparaison)","points":4},{"critere":"Renversement expliqué : machine vivante, homme chose","points":6},{"critere":"Germinal (1885) et inquiétude face à l’industrie","points":4},{"critere":"Paragraphe argumenté sur la maîtrise de la nature, avec au moins une nuance","points":6}],"dureeMin":15,"corrige":"1. **La mine** : « avait faim », « avalait », « mâchait », « recrachait » : **personnification** (elle a un corps et une volonté). **Les hommes** : « pareils à des wagonnets », « à la file », « sans un cri » : **comparaison** qui en fait des choses.\n\n2. **Renversement** : la machine (ou la mine) est vivante, l’ouvrier est réduit à un objet. Celui qui devait commander la machine est dévoré par elle.\n\n3. Le texte rappelle ***Germinal*** (1885), où Zola décrit la mine comme une « bête goulue » qui dévore les hommes. Il traduit l’**inquiétude** : le progrès épuise les corps.\n\n4. Réponse attendue : ici, l’homme n’est pas maître : il a fabriqué un monde qu’il ne contrôle plus, où la machine paraît plus vivante que lui. On peut nuancer (le progrès promettait aussi de vaincre la maladie et la distance). Le texte annonce, un siècle et demi à l’avance, les questions écologiques d’aujourd’hui."}$exo$::jsonb),
  ('f4b8a80c-f446-52cc-b212-3153a99aa0ac'::uuid, 1, 'redaction', $exo${"titre":"Verne, Wells et l’anticipation","consigne":"Réponds par des phrases courtes.","enonce":"1. Définis en une phrase un **roman d’anticipation**.\n2. Associe chaque auteur à son type d’anticipation : **Jules Verne** / **H. G. Wells**, et *technique, documentée, optimiste* / *sociale et morale, souvent inquiète*. Donne aussi un titre de chacun.\n3. Un roman d’anticipation qui se trompe dans ses prédictions a-t-il échoué ? Explique.","bareme":[{"critere":"Définition juste (futur, évolution déjà commencée)","points":7},{"critere":"Deux auteurs correctement associés avec un titre chacun","points":7},{"critere":"Explication : prédire n’est pas le but","points":6}],"dureeMin":6,"corrige":"1. Un **roman d’anticipation** situe son récit dans le **futur** et imagine les conséquences d’une **évolution déjà commencée**.\n\n2. **Jules Verne** : anticipation **technique**, documentée, **optimiste** (*De la Terre à la Lune*, *Vingt mille lieues sous les mers*). **H. G. Wells** : anticipation **sociale et morale**, souvent **inquiète** (*La Machine à explorer le temps*, *La Guerre des mondes*).\n\n3. **Non** : l’anticipation ne prédit pas l’avenir, elle prend une tendance du présent et demande « et si cela continuait ? ». Les erreurs de prédiction n’invalident donc pas le roman."}$exo$::jsonb),
  ('f4b8a80c-f446-52cc-b212-3153a99aa0ac'::uuid, 2, 'redaction', $exo${"titre":"Les bracelets de Lyon","consigne":"Lis l’extrait (écrit pour l’exercice), puis réponds.","enonce":"> En 2140, les rues de Lyon sont silencieuses. Chaque habitant porte au poignet un « somnomètre » qui mesure son sommeil et transmet chaque matin le résultat à l’administration. Ceux qui dorment mal reçoivent un avertissement, puis une amende.\n\n1. Relève la **date** du récit et dis à quoi elle sert.\n2. Relève un **néologisme** et explique son rôle.\n3. Quelle **tendance actuelle** le texte pousse-t-il à l’extrême ? Que redoute l’auteur ?\n4. Cite un thème du cours auquel ce texte se rattache.","bareme":[{"critere":"Date relevée (2140) et rôle : ancrer le récit, le rendre mesurable","points":5},{"critere":"Néologisme « somnomètre » et rôle (mot nouveau pour une réalité nouvelle, cadre crédible)","points":5},{"critere":"Tendance actuelle (objets connectés, mesure de soi) et crainte de l’auteur (contrôle, perte de liberté)","points":6},{"critere":"Thème rattaché : surveillance et perte des libertés","points":4}],"dureeMin":10,"corrige":"1. La date est **2140**. Elle **ancre** le récit dans le futur et le rend **mesurable** : on peut comparer avec notre époque.\n\n2. **Somnomètre** est un **néologisme** : un mot nouveau inventé pour désigner une réalité nouvelle. Il donne au futur un vocabulaire technique crédible.\n\n3. Le texte pousse à l’extrême la mesure permanente de soi par des objets connectés. L’auteur **redoute** que la surveillance et le contrôle de l’administration prennent la place des choix personnels, jusque dans le sommeil.\n\n4. Thème : la **surveillance** et la **perte des libertés** (aussi le progrès technique et ses effets non prévus)."}$exo$::jsonb),
  ('f4b8a80c-f446-52cc-b212-3153a99aa0ac'::uuid, 3, 'redaction', $exo${"titre":"Une ville qui flotte","consigne":"Lis l’extrait (écrit pour l’exercice), puis réponds.","enonce":"> En 2090, la ville flotte au-dessus des eaux qui ont recouvert les plaines. Sur le quai, le vieil Ilan explique à Mara, tout juste arrivée : « Ici, l’air se vend en cabines, à l’heure. Chez toi, on le respirait gratuitement, non ? » Mara regarde les tours-serres et n’ose pas répondre.\n\n1. Relève trois procédés d’écriture qui rendent ce futur crédible ou compréhensible (date, personnage guide, vocabulaire, contraste). Explique chacun.\n2. Applique à ce texte les quatre questions de la **lecture critique** du cours.\n3. Explique pourquoi ce texte appartient à l’anticipation et non à un simple récit fantastique.","bareme":[{"critere":"Trois procédés relevés et expliqués (date, guide et nouvelle venue, vocabulaire, contraste avec notre monde)","points":7},{"critere":"Quatre questions de lecture critique appliquées : tendance poussée à l’extrême, crainte, espoir, ce que dit le futur de notre monde","points":7},{"critere":"Justification : extrapolation d’une évolution déjà commencée et proximité avec le présent","points":3},{"critere":"Précision et clarté des réponses","points":3}],"dureeMin":15,"corrige":"1. **La date** (2090) ancre le récit. **Le personnage guide** (Ilan) explique le monde à Mara, la nouvelle venue, donc au lecteur. **Le contraste** avec notre monde (« chez toi, on le respirait gratuitement ») produit le sens. On peut aussi relever le **vocabulaire** inventé (« tours-serres », « cabines » d’air).\n\n2. **Quelle tendance est poussée à l’extrême ?** La pollution et la montée des eaux, la marchandisation de ressources vitales. **Que redoute l’auteur ?** Que l’air devienne une marchandise et que le climat détruise les plaines. **Qu’espère-t-il ?** Peut-être que le lecteur agisse avant : l’avertissement suppose un espoir. **Que dit ce futur du monde où il est écrit ?** Il en dénonce l’insouciance écologique.\n\n3. Ce n’est pas du fantastique : rien n’y est surnaturel. Le texte **extrapole** une évolution **déjà commencée** (le climat), avec une grande **proximité avec le présent**, ce qui caractérise l’anticipation."}$exo$::jsonb),
  ('720b0dcc-d36b-5605-8a79-d187aef534b0'::uuid, 1, 'redaction', $exo${"titre":"Trois époques, trois façons de voir la nature","consigne":"Réponds par des phrases courtes.","enonce":"1. Associe chaque élément à une époque (**Moyen Âge**, **Renaissance**, **XVIIe siècle**) : la *perspective*, le *jardin de Versailles*, le *jardin clos*.\n2. Que signifie *hortus conclusus* et que symbolise ce jardin ?\n3. Comment la nature est-elle peinte dans les enluminures médiévales ?","bareme":[{"critere":"Les trois éléments associés à leur époque","points":6},{"critere":"Hortus conclusus : jardin entouré de murs, utile, image du paradis","points":7},{"critere":"Nature sans profondeur, en aplats sur fond d’or, comme un signe","points":7}],"dureeMin":6,"corrige":"1. **Perspective** : Renaissance. **Jardin de Versailles** : XVIIe siècle. **Jardin clos** : Moyen Âge.\n\n2. *Hortus conclusus* désigne un **jardin clos** de murs : protégé et utile (herbes, légumes), il est aussi l’**image du paradis**.\n\n3. Dans les enluminures, la nature est peinte **sans profondeur**, en **aplats**, sur **fond d’or** : c’est un **signe** et non un paysage, par intention et non par maladresse."}$exo$::jsonb),
  ('720b0dcc-d36b-5605-8a79-d187aef534b0'::uuid, 2, 'redaction', $exo${"titre":"Un jardin de roi","consigne":"Lis la description (écrite pour l’exercice), puis réponds.","enonce":"> Du perron du château, le regard suit une allée rectiligne longue d’un kilomètre. De part et d’autre, des parterres dessinent des figures géométriques ; les arbres sont taillés en cubes et en cônes ; un grand bassin rectangulaire reflète le ciel. Rien ne dépasse, rien ne pousse au hasard.\n\n1. Quel type de jardin est décrit ? Nomme le jardinier célèbre qui a dessiné le plus fameux et son lieu.\n2. Relève trois indices de la maîtrise de la nature.\n3. Selon le cours, que démontre ce jardin sur le pouvoir ?\n4. Quelle formule de Descartes correspond à cet idéal ?","bareme":[{"critere":"Jardin à la française, Le Nôtre, Versailles","points":4},{"critere":"Trois indices relevés (allée rectiligne, parterres géométriques, arbres taillés, bassin)","points":6},{"critere":"Le jardin comme démonstration du pouvoir du roi","points":6},{"critere":"Formule de Descartes citée : « maître et possesseur de la nature »","points":4}],"dureeMin":10,"corrige":"1. C’est un **jardin à la française**. Le plus célèbre, celui de **Versailles**, est dessiné par **Le Nôtre**.\n\n2. Exemples : l’**allée rectiligne**, les **parterres géométriques**, les **arbres taillés**, le **bassin rectangulaire** (trois suffisent) : la nature est dominée par la géométrie.\n\n3. Le jardin est une **démonstration de pouvoir** : ce que le roi fait aux arbres, il le fait au royaume. La maîtrise de la nature dit celle du roi.\n\n4. Descartes : l’homme doit se rendre « comme **maître et possesseur de la nature** »."}$exo$::jsonb),
  ('720b0dcc-d36b-5605-8a79-d187aef534b0'::uuid, 3, 'redaction', $exo${"titre":"Du jardin clos au jardin à l’anglaise","consigne":"Rédige un paragraphe argumenté de 10 à 15 lignes.","enonce":"**Sujet.** « La façon dont une époque représente la nature dit ce qu’elle en pense. » Justifie cette phrase en comparant **au moins trois moments** : le jardin clos, le jardin à la française, le jardin à l’anglaise.\n\n**Rappels.**\n- Le jardin à l’anglaise du XVIIIe siècle prend le contre-pied de Versailles : allées sinueuses, faux désordre, ruines artificielles.\n- La Renaissance observe la nature (Léonard de Vinci) et invente la perspective.\n- « Jardin clos → jardin observé → jardin dompté. »\n\nTa réponse doit comporter une thèse, une comparaison précise et une conclusion.","bareme":[{"critere":"Thèse claire reliant le jardin à la pensée de l’époque","points":3},{"critere":"Jardin clos correctement présenté (protégé, utile, paradis, signe)","points":4},{"critere":"Jardin à la française présenté comme nature soumise, avec Le Nôtre ou Descartes","points":4},{"critere":"Jardin à l’anglaise opposé à Versailles (nature à rêver, faux désordre)","points":5},{"critere":"Organisation, vocabulaire et langue","points":4}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : chaque jardin traduit un rapport à la nature : encadrée, dominée, puis rêvée.\n\n**Jardin clos (Moyen Âge)** : entouré de murs, protégé et utile (herbes, légumes), image du **paradis** ; la nature y est un **signe**, comme dans les enluminures peintes en aplats sur fond d’or. La forêt, au contraire, reste le lieu du danger et du merveilleux.\n\n**Jardin à la française (XVIIe)** : Le Nôtre, à **Versailles** : axes de symétrie, parterres géométriques, arbres taillés, eaux domptées. C’est la nature **soumise**, une démonstration du pouvoir du roi, en écho à Descartes (« maître et possesseur de la nature »).\n\n**Jardin à l’anglaise (XVIIIe)** : allées sinueuses, faux désordre, ruines artificielles : la nature n’est plus à soumettre mais à **rêver**.\n\n**Conclusion** : du jardin clos au jardin dompté puis rêvé, on passe de la protection à la maîtrise, puis à la sensibilité ; la Renaissance a joué le rôle intermédiaire de l’observation."}$exo$::jsonb),
  ('3a7a28dd-117c-5eac-9606-4dc594d578b4'::uuid, 1, 'redaction', $exo${"titre":"Repérer un conte","consigne":"Lis le début de conte (écrit pour l’exercice), puis réponds.","enonce":"> Il était une fois, dans un royaume sans nom, un meunier qui avait trois fils. Le plus jeune reçut en héritage une paire de bottes de sept lieues et un chat qui parlait. Personne ne s’en étonna, pas même le meunier.\n\n1. Relève la **formule d’ouverture** et un **nombre symbolique**.\n2. Relève un **objet magique** et un **personnage type**.\n3. Ce conte est-il merveilleux ou fantastique ? Justifie.","bareme":[{"critere":"Formule d’ouverture et nombre symbolique relevés","points":6},{"critere":"Objet magique (bottes de sept lieues) et personnage type relevés","points":6},{"critere":"Merveilleux justifié : le surnaturel est admis sans étonner personne","points":8}],"dureeMin":6,"corrige":"1. Formule d’ouverture : « **Il était une fois** » ; nombre symbolique : **trois** fils ou **sept** lieues.\n\n2. Objet magique : les **bottes de sept lieues** ; personnage type : le **meunier** ou le **plus jeune fils**, le héros (on accepte aussi le chat qui parle comme figure de conte).\n\n3. Il est **merveilleux** : le chat parle et « personne ne s’en étonna ». Dans le fantastique, le surnaturel ferait irruption dans un monde réaliste et provoquerait le **doute**."}$exo$::jsonb),
  ('3a7a28dd-117c-5eac-9606-4dc594d578b4'::uuid, 2, 'redaction', $exo${"titre":"Le schéma d’un conte","consigne":"Lis le conte résumé (écrit pour l’exercice), puis réponds.","enonce":"> Dans un village, la petite Naïa vit heureuse avec sa grand-mère (1). Un hiver, la grand-mère tombe malade : seule une pomme d’argent, gardée par un ogre, peut la guérir (2). Naïa part. Une fée lui prête un manteau invisible, mais l’ogre la poursuit à travers la forêt (3). Elle trompe l’ogre en lui offrant une soupe endormie et prend la pomme (4). La grand-mère guérit, et le village fête Naïa (5).\n\n1. Nomme les cinq étapes du **schéma narratif** et associe-les aux numéros (1) à (5).\n2. Complète le **schéma actanciel** : sujet, objet, adjuvant, opposant.\n3. Qui joue le rôle du **destinataire** ?","bareme":[{"critere":"Cinq étapes du schéma narratif correctement nommées et associées","points":8},{"critere":"Schéma actanciel : Naïa, pomme d’argent, fée, ogre","points":8},{"critere":"Destinataire : la grand-mère (celle qui profite du résultat)","points":4}],"dureeMin":10,"corrige":"1. (1) **Situation initiale** ; (2) **élément perturbateur** (la maladie) ; (3) **péripéties** (le manteau, la poursuite) ; (4) **élément de résolution** (la soupe endormie, la pomme prise) ; (5) **situation finale** (guérison, fête).\n\n2. **Sujet** : Naïa. **Objet** : la pomme d’argent. **Adjuvant** : la fée (et son manteau). **Opposant** : l’ogre.\n\n3. Le **destinataire** est celui qui profite du résultat : la **grand-mère** (et, si l’on veut, le village). Le destinateur est la maladie ou l’appel de la grand-mère, qui envoie Naïa en quête."}$exo$::jsonb),
  ('3a7a28dd-117c-5eac-9606-4dc594d578b4'::uuid, 3, 'redaction', $exo${"titre":"Le conte est-il naïf ?","consigne":"Lis le résumé (écrit pour l’exercice), puis rédige un paragraphe argumenté.","enonce":"> Une famille très pauvre n’a plus de pain. Le père, à contrecœur, mène ses deux enfants au cœur de la forêt et les abandonne. Les enfants trouvent leur chemin grâce à des cailloux blancs, puis rencontrent une sorcière qui veut les manger. Ils la trompent, s’enfuient, et rentrent riches et heureux.\n\n**Sujet.** « Le conte merveilleux est une histoire naïve, sans profondeur. » Discute-en en 10 à 15 lignes, en t’appuyant sur ce résumé et sur le cours.\n\n**Rappels.** Un conte divertit, mais il enseigne aussi ; il met en scène des peurs profondes. Perrault publie ses *Contes* en 1697, les frères Grimm collectent des contes au XIXe siècle.","bareme":[{"critere":"Thèse claire (le conte n’est pas naïf)","points":4},{"critere":"Peurs profondes relevées dans le résumé (faim, abandon, cruauté des adultes, mort)","points":5},{"critere":"Marques du conte repérées (formule, fin heureuse, personnages types, nombre ou objets)","points":3},{"critere":"Rôle du conte (divertir et enseigner : prudence, courage, méfiance des apparences)","points":4},{"critere":"Organisation et langue","points":4}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : le conte est simple dans sa forme, mais il traite de choses très graves ; il n’est pas naïf.\n\n**Arguments** :\n- Le résumé met en scène la **faim**, l’**abandon** par les parents, le danger de **mort** (la sorcière) : ce sont des peurs profondes, ainsi que la cruauté des adultes.\n- Les marques du conte sont là (personnages types : père, sorcière ; épreuves ; **fin heureuse**), mais cette forme simple sert à parler de choses sérieuses.\n- Le conte **divertit** et **enseigne** : prudence (les cailloux), ruse et courage face au danger, méfiance envers les apparences. Perrault ajoute parfois une moralité, et les Grimm ont recueilli des versions parfois très dures.\n\n**Conclusion** : « le conte n’est pas naïf : c’est une histoire simple qui traite de choses très graves. »"}$exo$::jsonb),
  ('c841f7b9-62c1-579c-9266-06e8246818e5'::uuid, 1, 'redaction', $exo${"titre":"Le mot et le cadre de l’utopie","consigne":"Réponds par des phrases courtes.","enonce":"1. Que signifie le mot **utopie** ? Qui l’a inventé, et en quelle année ?\n2. Donne **trois éléments du cadre** d’une utopie (lieu, temps, personnage qui la découvre).\n3. Pourquoi dit-on qu’une utopie ne décrit jamais vraiment un ailleurs ?","bareme":[{"critere":"Sens du mot (ou-topos, « en aucun lieu »), auteur Thomas More, date 1516","points":7},{"critere":"Trois éléments du cadre : lieu isolé, hors du temps, voyageur-guide","points":7},{"critere":"Idée que l’utopie critique la société de son auteur par contraste","points":6}],"dureeMin":6,"corrige":"1. **Utopie** vient du grec *ou-topos*, « **en aucun lieu** ». Le mot est inventé par **Thomas More** dans *L’Utopie* (**1516**).\n\n2. Le cadre : un **lieu isolé** (île, vallée, planète), **hors du temps** ordinaire, découvert par un **voyageur** qui sert de guide au lecteur.\n\n3. Parce qu’elle **critique la société de son auteur** par contraste : montrer ce qui pourrait être pour faire voir ce qui ne va pas. C’est une argumentation **indirecte**."}$exo$::jsonb),
  ('c841f7b9-62c1-579c-9266-06e8246818e5'::uuid, 2, 'redaction', $exo${"titre":"L’île d’Élysia","consigne":"Lis le texte (écrit pour l’exercice), puis réponds.","enonce":"> Sur l’île d’Élysia, nul n’est riche ni pauvre : les biens sont communs, chacun travaille six heures par jour, tous les enfants vont à l’école et les lois tiennent en une page. Les villes sont bâties sur le même plan, avec des rues droites et des maisons identiques. Un marin échoué sur cette île a raconté tout cela à son retour.\n\n1. Relève **trois traits** qui montrent qu’il s’agit d’une utopie.\n2. Quel est le rôle du marin ?\n3. Que reproche sans doute l’auteur à sa propre société ? Explique le fonctionnement de cette argumentation indirecte.\n4. Un détail du texte annonce déjà une limite de l’utopie. Lequel, et pourquoi ?","bareme":[{"critere":"Trois traits relevés (égalité, propriété commune, travail limité, éducation, lois simples, organisation rationnelle)","points":6},{"critere":"Marin : voyageur qui sert de guide au lecteur","points":4},{"critere":"Critique implicite de l’inégalité, de la misère et de la complexité des lois, par contraste","points":6},{"critere":"Détail d’uniformité (villes identiques) qui prépare la dystopie","points":4}],"dureeMin":10,"corrige":"1. Par exemple : **égalité** (nul n’est riche ni pauvre) ; **propriété commune** ; **travail** partagé et limité (six heures) ; **éducation** pour tous ; **lois simples** (une page) ; organisation **rationnelle** (villes sur le même plan). Trois suffisent.\n\n2. Le marin est le **voyageur** qui découvre l’île et la raconte : il sert de **guide** au lecteur.\n\n3. L’auteur reproche à sa société ses **inégalités**, sa **misère**, ses lois compliquées. Il ne les attaque pas de front : il montre une société qui fonctionne autrement, et le lecteur en tire la comparaison (comme More visait l’Angleterre de son temps).\n\n4. « **Maisons identiques** » et « villes bâties sur le même plan » : une société parfaite suppose que tout le monde veuille la même chose ; l’**uniformité** devient vite oppressante et mène vers la **dystopie**."}$exo$::jsonb),
  ('c841f7b9-62c1-579c-9266-06e8246818e5'::uuid, 3, 'redaction', $exo${"titre":"Toute utopie contient son inquiétude","consigne":"Rédige un paragraphe argumenté de 10 à 15 lignes.","enonce":"**Sujet.** « Toute utopie contient sa propre inquiétude : qui décide de ce qui est parfait, et que fait-on de ceux qui ne sont pas d’accord ? » Explique et discute cette phrase.\n\n**Rappels.**\n- Chez Rabelais, l’abbaye de Thélème a une règle unique : « Fais ce que voudras ».\n- Une société parfaite suppose que tout le monde veuille la même chose.\n- Le schéma : utopie → uniformité nécessaire → surveillance → dystopie.\n- Chez More, l’île vise l’Angleterre de son temps.\n\nAppuie-toi sur au moins deux de ces éléments.","bareme":[{"critere":"Thèse claire (l’utopie est une critique, mais elle porte un risque)","points":3},{"critere":"Explication du passage de l’utopie à l’uniformité puis à la surveillance","points":6},{"critere":"Un exemple précis mobilisé (More et l’Angleterre, Thélème, ou traits utopiques)","points":5},{"critere":"Réponse à la question « qui décide ? » et aux dissidents","points":3},{"critere":"Organisation et langue","points":3}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : l’utopie critique un monde injuste, mais son idéal a un revers : pour être parfaite, elle doit réduire les différences.\n\n**Arguments** :\n- Une utopie (égalité, propriété commune, travail partagé, lois simples, organisation rationnelle) suppose que **tout le monde veuille la même chose**. Ce qui garantit l’ordre, **uniformité, surveillance, absence de choix**, devient vite oppressant : c’est le glissement vers la **dystopie**.\n- **Exemple** : chez More, l’île sans propriété privée vise l’**Angleterre de son temps** ; mais les villes identiques et les horaires réglés suggèrent déjà l’uniformité. Chez Rabelais, Thélème (« Fais ce que voudras ») montre au contraire une utopie qui mise sur la liberté de choix.\n- **Qui décide ?** Il faut bien quelqu’un pour définir la perfection ; les opposants n’ont plus de place.\n\n**Conclusion** : l’utopie est une argumentation indirecte qui fait réfléchir, mais elle doit laisser place au désaccord pour ne pas devenir une prison."}$exo$::jsonb),
  ('6b657546-53d8-51cd-8eaf-0b914516971f'::uuid, 1, 'redaction', $exo${"titre":"Auteurs et dystopies","consigne":"Réponds par des phrases courtes.","enonce":"1. Associe chaque œuvre à son auteur : *Nous autres* (1920), *Le Meilleur des mondes* (1932), *1984* (1949), *Fahrenheit 451* (1953). Auteurs : Bradbury, Huxley, Orwell, Zamiatine.\n2. Définis une **dystopie** en une phrase.\n3. Cite deux traits du genre (surveillance, propagande, etc.).","bareme":[{"critere":"Quatre œuvres associées à leur auteur","points":10},{"critere":"Définition : société en apparence parfaite, en réalité totalitaire","points":6},{"critere":"Deux traits du genre justes","points":4}],"dureeMin":6,"corrige":"1. *Nous autres* : **Zamiatine** (premier du genre). *Le Meilleur des mondes* : **Huxley**. *1984* : **Orwell**. *Fahrenheit 451* : **Bradbury**.\n\n2. Une **dystopie** décrit une société en apparence parfaite, et en réalité **totalitaire**, l’inverse (et le prolongement) de l’utopie.\n\n3. Par exemple : un régime qui contrôle tout, la **surveillance** permanente, la **propagande** et la réécriture du passé, l’**uniformisation** (numéros), l’élimination des opposants, un héros qui échoue."}$exo$::jsonb),
  ('6b657546-53d8-51cd-8eaf-0b914516971f'::uuid, 2, 'redaction', $exo${"titre":"Le matricule 4471","consigne":"Lis l’extrait (écrit pour l’exercice), puis réponds.","enonce":"> Dans la Cité, chaque habitant porte un numéro. Des écrans diffusent partout les mêmes nouvelles, que le Ministère corrige chaque nuit : hier, le pain n’a jamais manqué. Dans les manuels, les phrases sont raccourcies et le mot « liberté » a disparu. Un jeune homme, le 4471, commence à douter.\n\n1. Relève **trois traits** du genre dystopique dans cet extrait.\n2. Quel procédé de *1984* la disparition des mots rappelle-t-elle ? Quel est son but ?\n3. Que va probablement devenir le 4471 dans la suite du récit ?\n4. Quelle tendance actuelle ce texte pousse-t-il à l’extrême ?","bareme":[{"critere":"Trois traits relevés (uniformisation par numéros, propagande, réécriture du passé, contrôle)","points":6},{"critere":"Novlangue : langue appauvrie qui rend la révolte impensable","points":5},{"critere":"Héros qui prend conscience et, très souvent, échoue","points":4},{"critere":"Tendance actuelle nommée (propagande, désinformation, contrôle de l’information)","points":5}],"dureeMin":10,"corrige":"1. **Numéros** à la place des noms (uniformisation) ; **propagande** et **réécriture du passé** (les nouvelles corrigées la nuit, le pain « n’a jamais manqué ») ; **contrôle** de l’information par le Ministère.\n\n2. La disparition de mots rappelle la **novlangue** de *1984* : une langue appauvrie pour rendre la révolte **littéralement impensable** (sans le mot « liberté », comment la désirer ?).\n\n3. Le 4471, héros qui prend conscience, va très probablement **échouer** : c’est la fin habituelle du genre.\n\n4. Par exemple la **propagande** et la manipulation de l’information, ou la **surveillance** : la dystopie prend une tendance de son époque et la pousse à l’extrême pour la rendre visible."}$exo$::jsonb),
  ('6b657546-53d8-51cd-8eaf-0b914516971f'::uuid, 3, 'redaction', $exo${"titre":"Obéir par peur ou par plaisir","consigne":"Lis les deux extraits (écrits pour l’exercice), puis rédige.","enonce":"> **Extrait A.** Dans la Ville-Sans-Nuit, des caméras suivent chaque citoyen. Un mot de travers, et la police vient chercher l’imprudent. Personne ne parle plus, même chez soi.\n>\n> **Extrait B.** Dans la Ville-Sourire, chacun reçoit chaque soir un divertissement et une pilule de bonheur. On ne se plaint jamais : on n’en a plus l’idée. Les livres dorment sur les étagères, personne ne les ouvre.\n\n1. Rattache chaque extrait à un auteur du cours (Orwell ou Huxley) et nomme la forme d’oppression décrite.\n2. Rédige un paragraphe de 8 à 12 lignes qui compare ces deux formes d’oppression et dit lequel te paraît le plus proche de notre monde, en justifiant.\n3. Explique ce que la dystopie « fait » à une tendance de son époque.","bareme":[{"critere":"Extraits correctement attribués (A : Orwell, peur ; B : Huxley, plaisir)","points":4},{"critere":"Comparaison claire des deux formes d’oppression, avec mention de la surveillance et de la torture d’un côté, du divertissement et du confort de l’autre","points":6},{"critere":"Prise de position argumentée sur notre monde","points":4},{"critere":"Explication : elle prend une tendance et la pousse à l’extrême pour la rendre visible","points":3},{"critere":"Langue et organisation","points":3}],"dureeMin":15,"corrige":"1. **Extrait A** : **Orwell** (*1984*) : on obéit par **peur**, grâce à la surveillance permanente et à la contrainte. **Extrait B** : **Huxley** (*Le Meilleur des mondes*) : on obéit par **plaisir**, par conditionnement, divertissement et drogue.\n\n2. Comparaison attendue : chez Orwell, le pouvoir surveille, punit et torture ; chez Huxley, il n’a même plus besoin d’interdire, puisque le confort et le divertissement suppriment l’envie de penser. Huxley redoutait qu’on n’ait plus envie de lire les livres. La prise de position est libre (surveillance en ligne, ou divertissement de masse), à condition d’être argumentée par des exemples concrets.\n\n3. La dystopie **ne prédit pas** : elle prend une **tendance de son époque** (propagande, technique, surveillance, divertissement de masse) et la **pousse à l’extrême** pour la rendre **visible**."}$exo$::jsonb),
  ('8f784bec-0277-5d05-b70e-7d47fb81e7bc'::uuid, 1, 'redaction', $exo${"titre":"Voyageurs et récits","consigne":"Réponds par des phrases courtes.","enonce":"1. Associe chaque voyageur à son texte : **Marco Polo**, **Christophe Colomb**, **Jean de Léry**. Textes : *Histoire d’un voyage en terre de Brésil*, *Le Devisement du monde*, un journal de bord.\n2. À quelle personne un récit de voyage est-il en général écrit ? Pourquoi ?\n3. Quel procédé permet de faire imaginer l’inconnu au lecteur ?","bareme":[{"critere":"Trois associations correctes","points":9},{"critere":"Première personne, « je » qui se porte garant de ce qu’il rapporte","points":6},{"critere":"Comparaison avec le connu","points":5}],"dureeMin":6,"corrige":"1. **Marco Polo** : *Le Devisement du monde* (vers 1298, ses années en Chine, dictées en prison). **Christophe Colomb** : son **journal de bord** (1492). **Jean de Léry** : *Histoire d’un voyage en terre de Brésil* (1578).\n\n2. À la **première personne** : le narrateur dit « **je** » et se porte garant de ce qu’il rapporte.\n\n3. La **comparaison** avec ce que le lecteur connaît déjà : c’est le seul moyen de faire imaginer l’inconnu."}$exo$::jsonb),
  ('8f784bec-0277-5d05-b70e-7d47fb81e7bc'::uuid, 2, 'redaction', $exo${"titre":"Un animal jamais vu","consigne":"Lis l’extrait (écrit pour l’exercice), puis réponds.","enonce":"> Le 12 mars, j’ai aperçu au bord du fleuve une bête de la taille d’un cheval, avec un cou long comme celui d’un cygne et une peau tachetée comme celle du léopard. Mes hommes n’avaient jamais vu pareille merveille. Je l’ai observée trois heures avant qu’elle ne s’enfuie.\n\n1. Relève les marques d’un récit de voyage : narrateur, ordre du récit, vocabulaire de l’étonnement.\n2. Repère deux comparaisons. Pourquoi le voyageur y recourt-il ?\n3. Pourquoi le voyageur donne-t-il des précisions (date, durée) ? Quelle est la limite de ces précisions ?","bareme":[{"critere":"Marques relevées : « j’ » (première personne), date (ordre chronologique daté), « merveille », « jamais vu »","points":5},{"critere":"Deux comparaisons relevées (cheval, cygne, léopard) et rôle : faire imaginer l’inconnu par le connu","points":5},{"critere":"Précisions pour être cru ; possibilité d’embellir ou de mêler l’imaginé","points":5},{"critere":"Correction et clarté des réponses","points":5}],"dureeMin":10,"corrige":"1. **Narrateur** à la première personne (« j’ai aperçu ») ; ordre **chronologique daté** (« Le 12 mars », « trois heures ») ; vocabulaire de l’**étonnement** (« jamais vu pareille merveille »).\n\n2. Comparaisons : « de la taille d’un **cheval** », « long comme celui d’un **cygne** », « tachetée comme celle du **léopard** ». Le voyageur décrit l’inconnu avec des éléments que son lecteur connaît, seule façon de le lui faire imaginer.\n\n3. Le voyageur veut être **cru** : d’où les détails précis. Mais il peut aussi **embellir** pour tenir son lecteur, et certains récits mêlent l’observé et l’imaginé sans le dire."}$exo$::jsonb),
  ('8f784bec-0277-5d05-b70e-7d47fb81e7bc'::uuid, 3, 'redaction', $exo${"titre":"Regarder l’autre","consigne":"Rédige un paragraphe argumenté de 10 à 15 lignes.","enonce":"**Sujet.** « Un récit de voyage renseigne autant sur celui qui regarde que sur ce qu’il regarde. » Explique et discute cette phrase.\n\n**Rappels.**\n- Le voyageur décrit toujours depuis sa propre culture : son regard va de l’émerveillement au mépris.\n- Montaigne, dans « Des cannibales » (*Essais*, 1580), invente la figure du « bon sauvage » pour critiquer sa propre société.\n- Jean de Léry porte l’un des premiers regards ethnographiques sur le Brésil (1578).\n- Le voyageur veut être cru, mais il embellit aussi.\n\nUtilise au moins deux de ces éléments.","bareme":[{"critere":"Thèse claire et reformulation de la phrase","points":4},{"critere":"Regard du voyageur situé dans sa culture, entre émerveillement et mépris","points":4},{"critere":"Exemple précis (Montaigne et le bon sauvage, ou Léry)","points":5},{"critere":"Nuance sur la vérité et l’invention dans le récit","points":3},{"critere":"Organisation et langue","points":4}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : le récit de voyage parle de l’ailleurs, mais aussi, et parfois surtout, du regard et de la société du voyageur.\n\n**Arguments** :\n- Le voyageur décrit **depuis sa culture** : entre **émerveillement** et **mépris**, il compare toujours à ce qu’il connaît, donc se révèle.\n- **Montaigne**, dans « Des cannibales » (1580), invente le **bon sauvage** pour **critiquer sa propre société** : les vrais barbares ne sont peut-être pas ceux qu’on croit. **Léry** (1578) porte un regard plus ethnographique sur le Brésil.\n- Le voyageur veut être **cru** (détails, dates, mesures) mais **embellit** : le récit mêle observé et imaginé, et reflète autant l’auteur que ce qu’il décrit.\n\n**Conclusion** : lire un récit de voyage, c’est lire deux choses à la fois : un lieu et un regard."}$exo$::jsonb),
  ('4366ab9b-8872-567d-bf24-2f2eb9c1a9ea'::uuid, 1, 'redaction', $exo${"titre":"Rêver, fuir ou regretter","consigne":"Réponds par des phrases courtes.","enonce":"1. Associe chaque poète à sa façon de traiter le voyage : **Baudelaire** (« L’Invitation au voyage ») et **Du Bellay** (*Les Regrets*) ; façons : *le voyage rêvé* / *le retour et le regret*.\n2. Complète le vers : « Heureux qui, comme Ulysse, a fait un beau ….. » Qui l’a écrit ?\n3. Que désigne le mot **exotisme** ?","bareme":[{"critere":"Deux poètes associés à leur façon de traiter le voyage","points":8},{"critere":"Vers complété (voyage) et Du Bellay","points":6},{"critere":"Exotisme : l’ailleurs comme promesse","points":6}],"dureeMin":6,"corrige":"1. **Baudelaire** : le voyage **rêvé** (le pays décrit n’existe pas, il est fait du désir du poète). **Du Bellay** : le **retour et le regret** (le mal du pays, écrit depuis Rome).\n\n2. « Heureux qui, comme Ulysse, a fait un beau **voyage** » : vers de **Du Bellay**, *Les Regrets* (1558).\n\n3. L’**exotisme** est l’ailleurs présenté comme une **promesse** séduisante."}$exo$::jsonb),
  ('4366ab9b-8872-567d-bf24-2f2eb9c1a9ea'::uuid, 2, 'redaction', $exo${"titre":"Vers Zanzibar","consigne":"Lis le quatrain (écrit pour l’exercice), puis réponds.","enonce":"> Mon amie, viens, partons !\n> Vers Zanzibar, vers Samarcande,\n> Les voiles bercent l’horizon\n> Et la mer chante, douce et grande.\n\n1. Relève l’**apostrophe** et l’**impératif**. Quel est leur effet ?\n2. Quel est l’effet des **noms propres** exotiques ?\n3. Relève une **image** ou un effet de **musicalité** qui imite le bercement du départ.\n4. De quel type de voyage s’agit-il : rêvé, fuite ou retour ? Justifie.","bareme":[{"critere":"Apostrophe « Mon amie » et impératif « viens, partons » relevés, effet d’invitation","points":5},{"critere":"Noms propres (Zanzibar, Samarcande) : rêver par la sonorité","points":5},{"critere":"Image (la mer qui chante, les voiles qui bercent) ou musicalité (rythme, rime, sons)","points":5},{"critere":"Voyage rêvé justifié (pays lointain sans détail réel, promesse)","points":5}],"dureeMin":10,"corrige":"1. **Apostrophe** : « Mon amie ». **Impératif** : « viens », « partons ». Ils créent une **invitation** directe au lecteur ou à l’aimée, comme dans « L’Invitation au voyage ».\n\n2. « Zanzibar » et « Samarcande » font **rêver par leur seule sonorité** : ils évoquent l’ailleurs sans le décrire.\n\n3. « Les voiles **bercent** l’horizon », « la mer **chante** » : personnification et image qui transforment le paysage en état d’âme ; la **musicalité** (rythme régulier, rimes) imite le bercement du départ.\n\n4. C’est un voyage **rêvé** : l’ailleurs est une **promesse** faite de noms qui sonnent, sans description précise."}$exo$::jsonb),
  ('4366ab9b-8872-567d-bf24-2f2eb9c1a9ea'::uuid, 3, 'redaction', $exo${"titre":"Deux poèmes, deux voyages","consigne":"Lis les deux poèmes courts (écrits pour l’exercice), puis rédige.","enonce":"> **Poème A.** Viens, mon enfant, viens sous le ciel d’Orient : / les palmiers t’attendent, le soleil est doux ; / là-bas, tout est lumière et repos.\n>\n> **Poème B.** Loin de mon village, sous le ciel étranger, / je pense au toit de mes pères et à son ombre paisible. / Que ne suis-je rentré, le cœur enfin léger !\n\n1. Rattache chaque poème à une façon de traiter le voyage (rêve, fuite, retour et regret) et à un poète du cours.\n2. Rédige un paragraphe de 10 à 12 lignes qui compare les deux poèmes : procédés, sentiment exprimé, rapport à l’ailleurs.\n3. Explique en quoi Ulysse est la « figure matrice » du voyageur poétique.","bareme":[{"critere":"Poème A : voyage rêvé (Baudelaire) ; poème B : retour et regret (Du Bellay)","points":4},{"critere":"Comparaison des procédés : impératif et apostrophe, énumération ou images d’un côté, plainte et regret de l’autre","points":6},{"critere":"Comparaison du rapport à l’ailleurs : promesse séduisante / manque du pays natal","points":4},{"critere":"Ulysse : voyageur qui rentre, le voyage vaut par le retour et la transformation","points":3},{"critere":"Organisation et langue","points":3}],"dureeMin":15,"corrige":"1. **Poème A** : le voyage **rêvé**, comme chez **Baudelaire** (« L’Invitation au voyage ») : impératif « viens », l’ailleurs comme promesse. **Poème B** : le **retour et le regret**, comme chez **Du Bellay** (*Les Regrets*, écrits depuis Rome) : le poète préfère le séjour de ses aïeux.\n\n2. Attendu : A emploie l’**apostrophe** et l’**impératif**, des **images** de douceur et de lumière ; il fait de l’ailleurs une **promesse** (exotisme). B exprime la **plainte** et le **regret** : la distance fait sentir le **manque** ; le poète voudrait revenir, alors que le poème A invite à partir. La poésie du voyage dit rarement un lieu : elle dit un **manque** ou un désir.\n\n3. Depuis l’*Odyssée*, le voyageur poétique est un homme **qui rentre** : le voyage vaut moins par les terres traversées que par le **retour** et par ce qu’il a fait de celui qui part. Du Bellay se réclame explicitement d’Ulysse."}$exo$::jsonb),
  ('6c916708-6b4d-586a-bacf-4aaff6a2264f'::uuid, 1, 'redaction', $exo${"titre":"Les vitesses du récit","consigne":"Réponds par des phrases courtes.","enonce":"1. Définis la **scène**, le **sommaire**, l’**ellipse** et la **pause**.\n2. Associe chaque auteur à son roman : **Daniel Defoe**, **Robert Louis Stevenson** ; romans : *Robinson Crusoé*, *L’Île au trésor*.\n3. Pourquoi les fins de chapitre sont-elles importantes dans un roman d’aventures ?","bareme":[{"critere":"Quatre notions définies","points":10},{"critere":"Deux auteurs associés à leur roman","points":5},{"critere":"Suspense entretenu par les fins de chapitre","points":5}],"dureeMin":7,"corrige":"1. **Scène** : le récit prend le temps de l’action, dialogue compris. **Sommaire** : plusieurs jours résumés en quelques lignes. **Ellipse** : un passage de temps passé sous silence. **Pause** : une description qui suspend l’action.\n\n2. **Defoe** : *Robinson Crusoé* (1719). **Stevenson** : *L’Île au trésor* (1883).\n\n3. Elles entretiennent le **suspense** : on s’arrête à un moment de danger, ce qui donne envie de continuer."}$exo$::jsonb),
  ('6c916708-6b4d-586a-bacf-4aaff6a2264f'::uuid, 2, 'redaction', $exo${"titre":"Échoué sur une plage inconnue","consigne":"Lis l’extrait (écrit pour l’exercice), puis réponds.","enonce":"> La tempête se leva le lendemain. Trois semaines passèrent ; quand je repris connaissance, j’étais échoué sur une plage inconnue. Autour de moi, des palmiers immenses, un sable presque rose, un silence étrange que rien ne troublait, pas même le vent. Soudain, des pas.\n\n1. Relève le passage qui est une **ellipse** ou un **sommaire**, et celui qui est une **pause**. Justifie.\n2. Quel est le **narrateur** ? Relève un indice et dis l’effet produit.\n3. Quel effet produit la dernière phrase ?","bareme":[{"critere":"Ellipse ou sommaire (« Trois semaines passèrent ») et pause (description de la plage) justifiées","points":6},{"critere":"Narrateur interne (« je », « j’étais échoué ») et effet : aventure vive, lecteur proche du héros","points":6},{"critere":"Dernière phrase : accélération, suspense","points":3},{"critere":"Précision et clarté","points":5}],"dureeMin":10,"corrige":"1. « **Trois semaines passèrent** » est une **ellipse** (ou un **sommaire** très bref : un temps passé sous silence). « Autour de moi, des palmiers immenses… » est une **pause** : une description qui suspend l’action pour faire voir.\n\n2. Le narrateur est **interne** : c’est le héros qui raconte (« quand je repris connaissance », « j’étais échoué »). L’aventure est plus **vive** et le lecteur plus **proche** du héros.\n\n3. « Soudain, des pas. » : phrase courte, l’action **accélère** et crée le **suspense** : le récit alterne pause et danger."}$exo$::jsonb),
  ('6c916708-6b4d-586a-bacf-4aaff6a2264f'::uuid, 3, 'redaction', $exo${"titre":"Le mousse qui devient marin","consigne":"Lis le résumé (écrit pour l’exercice), puis rédige.","enonce":"> Tom, quatorze ans, s’engage comme mousse sur un navire marchand pour échapper à un oncle sévère. Une tempête, puis une mutinerie, le laissent seul sur une île. Il apprend à chasser, à construire une cabane, à ruser avec des pirates. Trois ans plus tard, un navire le recueille : il rentre chez lui, plus grand, plus calme, et capable de pardonner à son oncle.\n\n**Sujet.** « Le roman d’aventures est presque toujours un récit d’apprentissage. » Explique cette phrase en 10 à 15 lignes en t’appuyant sur le résumé, puis cite au moins deux ingrédients du genre.\n\n**Rappels.** Le héros est jeune, courageux, souvent seul ; les péripéties entretiennent le suspense ; l’île, la jungle ou la mer sont des épreuves qui le construisent.","bareme":[{"critere":"Thèse claire (aventure = apprentissage)","points":4},{"critere":"Analyse du résumé : départ, épreuves, retour transformé","points":6},{"critere":"Deux ingrédients du genre justement cités (héros jeune et seul, péripéties, suspense)","points":4},{"critere":"Un titre du cours cité à l’appui (Robinson Crusoé, L’Île au trésor…)","points":2},{"critere":"Organisation et langue","points":4}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : sous les tempêtes et les trésors, le roman d’aventures raconte ce que c’est que **grandir**.\n\n**Arguments** :\n- Schéma : un **héros jeune** (Tom, quatorze ans) → un **départ** vers l’inconnu → des **épreuves** (tempête, mutinerie, solitude, pirates) → un retour **transformé** (plus calme, capable de pardonner) : il part enfant et revient adulte.\n- Les **épreuves** (l’île, la mer) le **construisent** : il apprend à chasser, construire, ruser.\n- Ingrédients : héros jeune et souvent seul ; **péripéties** ; **suspense** entretenu par les fins de chapitre.\n- Titre cité : *Robinson Crusoé* (Defoe, 1719), le naufragé qui reconstruit une civilisation, ou *L’Île au trésor* (Stevenson, 1883).\n\n**Conclusion** : l’île est moins un décor qu’une école."}$exo$::jsonb),
  ('fde4fddf-3208-557a-829e-0de6fa170325'::uuid, 1, 'redaction', $exo${"titre":"La comédie classique et Arnolphe","consigne":"Réponds par des phrases courtes.","enonce":"1. Que signifie la devise *Castigat ridendo mores* ? Quel est donc le but de la comédie classique ?\n2. Comment Arnolphe a-t-il fait élever Agnès, et pourquoi ?\n3. Comment la pièce se termine-t-elle pour Arnolphe ?","bareme":[{"critere":"Devise traduite (corriger les mœurs par le rire) et but de la comédie","points":7},{"critere":"Agnès élevée dans l’ignorance depuis ses quatre ans pour en faire une épouse docile","points":7},{"critere":"Arnolphe échoue et reste seul","points":6}],"dureeMin":6,"corrige":"1. *Castigat ridendo mores* : « **corriger les mœurs par le rire** ». La comédie classique veut faire rire pour corriger les défauts des hommes.\n\n2. Arnolphe a fait élever Agnès dans l’**ignorance** depuis ses quatre ans, pour en faire une épouse **docile**, qu’il compte épouser.\n\n3. Il **échoue** : Agnès lui échappe pour Horace, et Arnolphe **reste seul**."}$exo$::jsonb),
  ('fde4fddf-3208-557a-829e-0de6fa170325'::uuid, 2, 'redaction', $exo${"titre":"Le confident malheureux","consigne":"Lis la scène (écrite pour l’exercice, inspirée de la situation de la pièce), puis réponds.","enonce":"> **Horace.** — Monsieur, un vieux jaloux garde une jeune fille sous clef, mais je la verrai cette nuit !\n> **Arnolphe** (à part). — Quel malheur ! C’est ma propre pupille qu’il me raconte.\n> **Horace.** — Vous êtes bien pâle, monsieur.\n> **Arnolphe.** — Moi ? Non, non, je vous écoute avec plaisir…\n\n1. Comment s’appelle l’effet comique produit par cette situation ? Explique-le.\n2. Quels types de comique voit-on ici (de mots, de gestes, de situation, de caractère, de répétition) ? Justifie.\n3. Qu’est-ce que cette scène nous apprend sur Arnolphe ?\n4. Quelle ironie structure toute la pièce ?","bareme":[{"critere":"Quiproquo / ironie dramatique expliquée : Horace ignore qu’il parle à son rival","points":5},{"critere":"Comique de situation identifié et justifié, et autre type possible (caractère)","points":5},{"critere":"Arnolphe piégé par son propre défaut, dissimulant sa rage, jaloux et orgueilleux","points":5},{"critere":"Ironie de la pièce : Horace raconte ses progrès amoureux au rival","points":5}],"dureeMin":10,"corrige":"1. Un **quiproquo** dramatique : Horace ne sait pas qu’Arnolphe est le « vieux jaloux » dont il parle ; le spectateur, lui, le sait, ce qui le fait rire.\n\n2. **Comique de situation** : personnage qui entend tout sans pouvoir réagir, malentendu. On peut ajouter le comique de **caractère** : Arnolphe pousse sa jalousie jusqu’à l’absurde.\n\n3. Arnolphe est **piégé** par son propre projet : il cache sa colère et écoute son rival raconter ses progrès. C’est un défaut poussé à l’extrême, sa jalousie, qui le rend comique.\n\n4. L’**ironie** de la pièce : Horace raconte naïvement ses progrès amoureux à Arnolphe, sans savoir qu’il parle à son rival."}$exo$::jsonb),
  ('fde4fddf-3208-557a-829e-0de6fa170325'::uuid, 3, 'redaction', $exo${"titre":"L’École des femmes est-elle une simple farce ?","consigne":"Rédige un paragraphe argumenté de 10 à 15 lignes.","enonce":"**Sujet.** « *L’École des femmes* (1662) n’est qu’une farce pour faire rire. » Discute cette affirmation.\n\n**Rappels.**\n- Arnolphe aime réellement Agnès ; il échoue et reste seul.\n- La pièce interroge l’éducation des filles, le mariage forcé et la liberté de choisir sa vie.\n- Elle a déclenché une violente querelle : Molière a répondu par *La Critique de l’École des femmes* et *L’Impromptu de Versailles*.\n- La comédie classique respecte les trois unités et se termine bien.\n\nAppuie-toi sur au moins trois de ces éléments.","bareme":[{"critere":"Thèse claire (la pièce est drôle mais pas seulement une farce)","points":4},{"critere":"Éléments comiques reconnus (caractère, situation, quiproquo)","points":4},{"critere":"Arnolphe qui aime réellement Agnès, échec et solitude","points":4},{"critere":"Enjeux : éducation des filles, mariage forcé, liberté ; querelle et réponse par deux pièces","points":5},{"critere":"Organisation et langue","points":3}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : la pièce fait rire, mais elle est plus qu’une farce : elle pose de vraies questions.\n\n**Arguments** :\n- Le comique est présent : comique de **caractère** (la jalousie d’Arnolphe poussée jusqu’à l’absurde), de **situation** (le quiproquo : Horace raconte ses progrès à son rival).\n- Pourtant Arnolphe **aime réellement** Agnès : il échoue et reste **seul**, ce qui empêche la pièce d’être une simple farce.\n- Elle interroge l’**éducation des filles** (faut-il les instruire ou les tenir dans l’ignorance ?), le **mariage forcé** et la **liberté** : c’est l’ignorance, non la nature, qui tenait Agnès enfermée.\n- La **querelle** violente qu’elle déclenche montre qu’on l’a prise au sérieux ; Molière a répondu par deux pièces, *La Critique de l’École des femmes* et *L’Impromptu de Versailles* : le théâtre se défend par le théâtre.\n\n**Conclusion** : une comédie qui corrige les mœurs par le rire, selon la devise *castigat ridendo mores*."}$exo$::jsonb),
  ('6599efec-fefb-5c60-86a9-b028fa4f86ed'::uuid, 1, 'redaction', $exo${"titre":"Le pacte autobiographique","consigne":"Réponds par des phrases courtes.","enonce":"1. Définis le **pacte autobiographique**. Quel critique l’a défini ?\n2. Associe chaque auteur à son œuvre : **Rousseau**, **Marcel Pagnol**, **Hervé Bazin** ; œuvres : *Les Confessions*, *La Gloire de mon père*, *Vipère au poing*.\n3. Quel temps du passé sert au décor et aux habitudes dans un récit d’enfance ?","bareme":[{"critere":"Pacte : auteur, narrateur et personnage principal ne font qu’un ; Philippe Lejeune","points":7},{"critere":"Trois auteurs associés à leur œuvre","points":7},{"critere":"L’imparfait","points":6}],"dureeMin":6,"corrige":"1. Le **pacte autobiographique** : l’**auteur**, le **narrateur** et le **personnage principal** sont la **même personne**. Il a été défini par **Philippe Lejeune**.\n\n2. **Rousseau** : *Les Confessions* (1782). **Pagnol** : *La Gloire de mon père*. **Bazin** : *Vipère au poing*.\n\n3. L’**imparfait** (décor, habitudes) ; le passé simple ou le passé composé servent aux événements."}$exo$::jsonb),
  ('6599efec-fefb-5c60-86a9-b028fa4f86ed'::uuid, 2, 'redaction', $exo${"titre":"La cuisine de ma grand-mère","consigne":"Lis l’extrait (écrit pour l’exercice), puis réponds.","enonce":"> Je revois la cuisine de ma grand-mère : l’odeur du café brûlé, le tic-tac de l’horloge, la lumière jaune. Ce jour-là, j’ai cassé son vase préféré ; je ne savais pas encore qu’elle ne me gronderait jamais. Aujourd’hui, je souris de ma terreur.\n\n1. Distingue le **je narrant** et le **je narré** : relève un indice de chacun.\n2. Quelles **sensations** font revenir le souvenir ?\n3. Relève et explique une **anticipation**.\n4. Quel sentiment naît de l’écart entre les deux « je » ?","bareme":[{"critere":"Je narrant (« Aujourd’hui, je souris », « je revois ») et je narré (« j’ai cassé », « ma terreur »)","points":5},{"critere":"Sensations : odeur du café brûlé, tic-tac, lumière jaune","points":5},{"critere":"Anticipation « je ne savais pas encore que… » expliquée : l’adulte annonce ce qu’il sait","points":5},{"critere":"Écart : tendresse ou ironie légère","points":5}],"dureeMin":10,"corrige":"1. **Je narrant** : l’adulte qui écrit et commente : « je revois », « Aujourd’hui, je souris de ma terreur ». **Je narré** : l’enfant : « j’ai cassé son vase », sa « terreur ».\n\n2. **Odeur** du café brûlé, **bruit** du tic-tac, **lumière** jaune : les sensations font revenir le souvenir plus sûrement que les faits.\n\n3. « Je ne savais pas encore qu’elle ne me gronderait jamais » : c’est une **anticipation** : l’adulte sait ce que l’enfant ignorait.\n\n4. L’écart crée de la **tendresse** (et un peu d’ironie) : l’adulte sourit de la peur de l’enfant."}$exo$::jsonb),
  ('6599efec-fefb-5c60-86a9-b028fa4f86ed'::uuid, 3, 'redaction', $exo${"titre":"Un récit d’enfance est-il fidèle au passé ?","consigne":"Rédige un paragraphe argumenté de 10 à 15 lignes.","enonce":"**Sujet.** « Un récit d’enfance restitue fidèlement le passé. » Discute cette affirmation.\n\n**Rappels.**\n- La mémoire n’enregistre pas, elle reconstruit.\n- L’autobiographie promet la vérité ; le roman autobiographique s’en inspire mais assume la fiction ; l’autofiction mêle les deux volontairement.\n- Le je narrant (l’adulte) et le je narré (l’enfant) ne savent pas la même chose.\n- Les adultes sont souvent vus d’en bas, agrandis par le regard de l’enfant.\n\nAppuie-toi sur au moins trois de ces éléments.","bareme":[{"critere":"Thèse claire et nuancée","points":4},{"critere":"Mémoire qui reconstruit, invention non par mensonge mais par nature","points":5},{"critere":"Distinction autobiographie, roman autobiographique, autofiction","points":4},{"critere":"Deux voix (je narrant, je narré) et portrait des adultes vus d’en bas","points":4},{"critere":"Organisation et langue","points":3}],"dureeMin":15,"corrige":"Réponse attendue (à adapter) :\n\n**Thèse** : un récit d’enfance cherche la vérité, mais il ne peut pas être une copie fidèle du passé.\n\n**Arguments** :\n- La **mémoire n’enregistre pas, elle reconstruit** : tout récit d’enfance est en partie une **invention**, non par mensonge mais par nature.\n- **Genres** : l’**autobiographie** promet la vérité (pacte de Lejeune) ; le **roman autobiographique** s’inspire de la vie mais assume la fiction ; l’**autofiction** mêle volontairement les deux.\n- **Deux voix** : le **je narrant** (l’adulte) commente et sait la suite ; le **je narré** (l’enfant) ne sait pas : l’écart produit ironie, tendresse ou regret. Les **adultes** sont **vus d’en bas**, agrandis par le regard de l’enfant.\n\n**Conclusion** : le récit d’enfance restitue moins le passé lui-même que la façon dont l’adulte le voit."}$exo$::jsonb),
  ('a84a4b01-c102-5366-ad58-5feb28ac9c50'::uuid, 1, 'redaction', $exo${"titre":"Les repères de l’islam","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Que se passe-t-il en 622 ? Pourquoi cette date est-elle l’an 1 du calendrier musulman ?\n2. Comment s’appelle le livre sacré de l’islam ? Cite trois des cinq piliers de l’islam.\n3. Qui sont les califes ?","bareme":[{"critere":"622 : l’Hégire, départ de Muhammad de La Mecque pour Médine, début du calendrier musulman","points":7},{"critere":"Coran et trois piliers justes","points":7},{"critere":"Califes : successeurs de Muhammad, chefs de la communauté et de l’empire","points":6}],"dureeMin":7,"corrige":"1. En **622**, Muhammad, chassé de **La Mecque**, rejoint **Médine** : c’est l'**Hégire**. Elle marque l’an 1 du calendrier musulman.\n\n2. Le livre sacré est le **Coran**. Trois piliers au choix parmi : la **profession de foi**, les **cinq prières quotidiennes**, l’**aumône**, le **jeûne du ramadan**, le **pèlerinage à La Mecque**.\n\n3. Les **califes** sont les **successeurs de Muhammad**, après sa mort en **632**. Ils dirigent la communauté musulmane et conquièrent l’Arabie, la Syrie, l’Égypte, la Perse, l’Afrique du Nord et l’Espagne (al-Andalus)."}$exo$::jsonb),
  ('a84a4b01-c102-5366-ad58-5feb28ac9c50'::uuid, 2, 'redaction', $exo${"titre":"Deux dynasties, deux capitales","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"Voici un tableau de synthèse incomplet.\n\n| La dynastie | Sa capitale | Date |\n| Les Omeyyades | ? | avant 750 |\n| Les Abbassides | ? | à partir de 750 |\n\n1. Complète le tableau.\n2. Jusqu’où s’étend l’empire musulman vers 750 ? Cite une limite à l’est et une limite à l’ouest.\n3. Pourquoi peut-on dire que la ville de Bagdad est brillante au IXe siècle ? Donne deux éléments.","bareme":[{"critere":"Damas pour les Omeyyades, Bagdad pour les Abbassides","points":5},{"critere":"Empire de l’Indus (est) aux Pyrénées (ouest)","points":5},{"critere":"Bagdad : très peuplée (peut-être un million d’habitants), premier élément juste","points":5},{"critere":"Maison de la Sagesse (traductions des savoirs grecs, perses, indiens) ou savants (Al-Khwarizmi, Avicenne)","points":5}],"dureeMin":10,"corrige":"1. Les **Omeyyades** ont pour capitale **Damas** ; les **Abbassides** ont pour capitale **Bagdad**, depuis **750**.\n\n2. Vers 750, l’empire va de l’**Indus** (à l’est) aux **Pyrénées** (à l’ouest).\n\n3. Deux éléments parmi : Bagdad compte **peut-être un million d’habitants** au IXe siècle ; la **Maison de la Sagesse** y traduit et prolonge les savoirs **grecs, perses et indiens** ; des savants comme **Al-Khwarizmi** (l’algèbre) ou **Avicenne** (médecine) y travaillent."}$exo$::jsonb),
  ('a84a4b01-c102-5366-ad58-5feb28ac9c50'::uuid, 3, 'redaction', $exo${"titre":"Un empire passeur de savoirs","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Extrait d’un récit (texte écrit pour l’exercice).**\n> « Nous sommes à Bagdad, au IXe siècle. Dans la Maison de la Sagesse, des traducteurs, musulmans, chrétiens et juifs, copient sur du papier des livres venus de Grèce, de Perse et d’Inde. Un savant y calcule avec des chiffres nouveaux et écrit un traité sur les équations. À la porte de la ville, un marchand chrétien paie l’impôt réservé à ceux de sa religion, mais personne ne l’empêche de prier. »\n\n1. Identifie deux savoirs ou objets que l’empire arabo-musulman a reçus d’autres civilisations.\n2. Qui est le savant qui « écrit un traité sur les équations » ? Quelle discipline fonde-t-il ?\n3. Comment appelle-t-on le marchand chrétien qui paie cet impôt ? Explique son statut.\n4. Rédige un paragraphe (6 à 8 lignes) pour expliquer pourquoi l’empire arabo-musulman est appelé un « passeur » entre l’Antiquité et l’Europe.","bareme":[{"critere":"Deux emprunts justes : savoirs grecs, perses, indiens, chiffres d’Inde, papier de Chine","points":4},{"critere":"Al-Khwarizmi et l’algèbre","points":4},{"critere":"Dhimmis ; statut inférieur mais protégé, ni égalité ni persécution","points":5},{"critere":"Paragraphe argumenté : traduction, prolongement, transmission des chiffres, du papier, de la médecine à l’Europe","points":7}],"dureeMin":15,"corrige":"1. Deux éléments au choix : les **savoirs grecs, perses et indiens** traduits à la Maison de la Sagesse ; les **chiffres venus d’Inde** ; le **papier venu de Chine**.\n\n2. Il s’agit d’**Al-Khwarizmi**, qui fonde l’**algèbre**.\n\n3. C’est un **dhimmi** : les chrétiens et les juifs conservent leur religion **contre un impôt spécifique**. Leur statut est **inférieur mais protégé** : ce n’est ni l’égalité, ni la persécution.\n\n4. Paragraphe attendu : l’empire ne fait pas que conquérir, il **transmet**. Il **traduit et prolonge** les savoirs grecs, perses et indiens à Bagdad ; les **chiffres d’Inde** et le **papier de Chine** passent par lui avant d’arriver en Europe ; l’**algèbre** d’Al-Khwarizmi et le **canon de médecine** d’Avicenne sont ensuite lus en Europe (cinq siècles pour Avicenne). Ainsi l’Europe médiévale retrouve des savoirs qu’elle avait perdus."}$exo$::jsonb),
  ('cb4b906e-b154-5ff3-860a-44f2acb13084'::uuid, 1, 'redaction', $exo${"titre":"Les repères de Byzance","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle est la capitale de l’Empire byzantin ? Qui la fonde en 330 ?\n2. Comment appelle-t-on l’empereur byzantin ?\n3. Cite deux réalisations de l’empereur Justinien.","bareme":[{"critere":"Constantinople, fondée par Constantin en 330","points":7},{"critere":"Le basileus","points":5},{"critere":"Deux réalisations justes : reconquête, Code justinien, Sainte-Sophie","points":8}],"dureeMin":7,"corrige":"1. La capitale est **Constantinople**, fondée en **330** par l’empereur **Constantin** sur l’ancienne Byzance.\n\n2. L’empereur s’appelle le **basileus**.\n\n3. Deux au choix parmi : la **reconquête** de l’Occident (tentée), le **Code justinien** qui rassemble le droit romain, la construction de **Sainte-Sophie**. Justinien règne de 527 à 565."}$exo$::jsonb),
  ('cb4b906e-b154-5ff3-860a-44f2acb13084'::uuid, 2, 'redaction', $exo${"titre":"Constantinople, une ville qui résiste","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Notes d’un voyageur (texte écrit pour l’exercice).**\n> « Nous arrivons par la mer. La ville est posée entre deux continents. De hautes murailles, triples, la protègent. Dans les rues, on parle grec ; des marchands vénitiens, arabes et slaves se croisent sur les marchés. Au centre, une immense église, Sainte-Sophie, et l’hippodrome. »\n\n1. Sur quel détroit et entre quels continents est située la ville ?\n2. Relève deux atouts de Constantinople dans ce texte et explique comment ils font sa puissance.\n3. Quelle langue parle-t-on à Byzance ? Que disent d’eux-mêmes les « Byzantins » ?","bareme":[{"critere":"Bosphore, entre Europe et Asie","points":4},{"critere":"Deux atouts justes (position, murailles, commerce) expliqués","points":8},{"critere":"Le grec","points":3},{"critere":"Ils se disent Romains ; mot « byzantin » forgé plus tard par des historiens occidentaux","points":5}],"dureeMin":10,"corrige":"1. Constantinople est sur le **Bosphore**, entre l’**Europe** et l’**Asie**.\n\n2. Atouts au choix : sa **position**, à la charnière de la Méditerranée et de la mer Noire, en fait un carrefour de routes ; ses **triples murailles** lui permettent de résister aux sièges jusqu’en 1204 ; ses **marchés** attirent des marchands de tous horizons, donc de la richesse.\n\n3. On y parle le **grec**. Les Byzantins se disent **Romains** : le mot « byzantin » a été forgé bien plus tard par des historiens occidentaux."}$exo$::jsonb),
  ('cb4b906e-b154-5ff3-860a-44f2acb13084'::uuid, 3, 'redaction', $exo${"titre":"Un empire chrétien, un empereur puissant","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"Un élève écrit : « L’empereur byzantin ressemble au pape : il ne s’occupe que de religion. » Un autre répond : « Au contraire, il cumule tous les pouvoirs, et l’Église orthodoxe s’est séparée de celle de Rome. »\n\n1. Explique pourquoi le second élève a raison : que cumule le basileus ? Comment appelle-t-on son pouvoir ?\n2. Cite deux différences entre l’Église orthodoxe et l’Église catholique.\n3. Quelle est la date du schisme ? Donne aussi les dates de la quatrième croisade contre Constantinople et de sa chute définitive.\n4. Rédige quelques lignes pour expliquer pourquoi la quatrième croisade est un événement paradoxal.","bareme":[{"critere":"Basileus : chef politique, militaire et de l’Église, nomme le patriarche ; pouvoir théocratique","points":6},{"critere":"Deux différences justes (grec/latin, mariage des prêtres, autorité du pape)","points":4},{"critere":"1054, 1204, 1453","points":4},{"critere":"Paradoxe : des croisés chrétiens pillent une ville chrétienne","points":6}],"dureeMin":15,"corrige":"1. Le **basileus** est **chef politique, chef militaire et chef de l’Église** : il **nomme le patriarche**. Son pouvoir est dit **théocratique** : il représente Dieu sur terre. Le second élève a donc raison.\n\n2. Deux au choix : **langue grecque** contre **latine** ; **mariage des prêtres** autorisé contre **célibat** ; **refus de l’autorité du pape** contre autorité du pape.\n\n3. Le **schisme** date de **1054**. La quatrième croisade pille Constantinople en **1204** ; la ville tombe aux mains des Ottomans le **29 mai 1453**.\n\n4. En **1204**, des croisés venus d’Occident, censés aller combattre pour Jérusalem, **pillent Constantinople**, une ville **chrétienne**. Des chrétiens attaquent des chrétiens : l’événement approfondit la rupture entre Rome et Byzance, déjà séparées depuis 1054."}$exo$::jsonb),
  ('3280f054-7ef7-5642-b8da-6b2cfef55564'::uuid, 1, 'redaction', $exo${"titre":"Les repères de Charlemagne","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. En quelle année Pépin le Bref fonde-t-il la dynastie carolingienne ?\n2. Quand et où Charlemagne est-il couronné empereur ? Par qui ?\n3. Quelle est la capitale de son empire ?","bareme":[{"critere":"751","points":5},{"critere":"25 décembre 800, à Rome, par le pape Léon III","points":10},{"critere":"Aix-la-Chapelle","points":5}],"dureeMin":6,"corrige":"1. En **751**, Pépin le Bref écarte les Mérovingiens et fonde la dynastie carolingienne, avec l’appui du pape.\n\n2. Charlemagne est couronné empereur le **25 décembre 800**, à **Rome**, par le pape **Léon III**.\n\n3. La capitale est **Aix-la-Chapelle**."}$exo$::jsonb),
  ('3280f054-7ef7-5642-b8da-6b2cfef55564'::uuid, 2, 'redaction', $exo${"titre":"Gouverner un empire immense","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"Charlemagne règne de 768 à 814 sur un empire qui va de la Catalogne à la Saxe.\n\n1. Comment l’empire est-il découpé pour être administré ? Qui dirige chaque partie ?\n2. Qui sont les missi dominici ? Comment voyagent-ils et que contrôlent-ils ?\n3. Qu’appelle-t-on capitulaires ?\n4. Pourquoi Charlemagne a-t-il besoin de tels outils ?","bareme":[{"critere":"Comtés dirigés par des comtes","points":4},{"critere":"Missi dominici : envoyés de l’empereur, par deux (un laïc, un religieux), contrôlent les comtes","points":6},{"critere":"Capitulaires : lois écrites de l’empereur","points":4},{"critere":"Empire trop vaste pour être tenu sans relais ni contrôle","points":6}],"dureeMin":10,"corrige":"1. L’empire est découpé en **comtés**, dirigés par des **comtes**.\n\n2. Les **missi dominici** (« envoyés du maître ») sont des envoyés de l’empereur. Ils vont **par deux, un laïc et un religieux**, pour **contrôler les comtes**.\n\n3. Les **capitulaires** sont les **lois écrites** de l’empereur.\n\n4. L’empire est **immense** (France, Allemagne, Italie du Nord, Catalogne) : sans **relais locaux** (les comtes) ni **contrôle** (les missi), l’empereur ne pourrait ni faire appliquer ses lois ni empêcher les abus."}$exo$::jsonb),
  ('3280f054-7ef7-5642-b8da-6b2cfef55564'::uuid, 3, 'redaction', $exo${"titre":"La renaissance carolingienne et le partage","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Témoignage d’un moine (texte écrit pour l’exercice).**\n> « Dans notre monastère, l’empereur veut des écoles. Des savants venus de loin nous apprennent à mieux lire. Nous copions les livres anciens dans une écriture nouvelle, claire, aux lettres bien séparées. Sans nous, dit-on, les textes des Romains disparaîtraient. »\n\n1. Comment appelle-t-on cette période culturelle ? Quels sont les trois moyens que le texte et le cours donnent pour la mener ?\n2. Comment s’appelle l’écriture nouvelle ? Pourquoi est-elle importante pour nous ?\n3. Quelle est la date du traité de Verdun ? Entre qui l’empire est-il partagé ? Nomme les trois parts.\n4. Rédige un paragraphe pour montrer que ce traité est « la naissance de la carte de l’Europe ».","bareme":[{"critere":"Renaissance carolingienne ; écoles dans les monastères, savants (Alcuin), copie des textes antiques dans les scriptoria","points":5},{"critere":"Minuscule caroline, ancêtre de nos minuscules, transmet des textes latins","points":4},{"critere":"843, trois petits-fils de Charlemagne, Francie occidentale, orientale, Lotharingie","points":5},{"critere":"Paragraphe : trois parts devenues France, Allemagne et bande centrale, unité de l’Occident rompue","points":6}],"dureeMin":15,"corrige":"1. C’est la **renaissance carolingienne**. Moyens : ouvrir des **écoles dans les monastères**, faire venir des **savants** comme Alcuin, **copier les textes antiques** dans les scriptoria.\n\n2. C’est la **minuscule caroline**, écriture plus lisible, **ancêtre de nos minuscules**. Beaucoup de textes latins ne nous sont parvenus que par ces **copies carolingiennes**.\n\n3. Le traité de Verdun date de **843**. Il partage l’empire entre les **trois fils de Louis le Pieux**, petits-fils de Charlemagne. Les parts : **Francie occidentale**, **Francie orientale** et **Lotharingie**.\n\n4. Paragraphe attendu : la Francie occidentale deviendra la **France**, la Francie orientale l’**Allemagne**, la Lotharingie une **longue bande** entre les deux. L’**unité de l’Occident** est rompue pour mille ans : ce partage dessine les grandes lignes de la carte de l’Europe."}$exo$::jsonb),
  ('d08c84fe-8112-5b6b-bb75-0870d4b1c883'::uuid, 1, 'redaction', $exo${"titre":"Les repères des croisades","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qui appelle à la première croisade et en quelle année ?\n2. Que fait la première croisade en 1099 ?\n3. Quel chef musulman reprend Jérusalem en 1187 ?","bareme":[{"critere":"Urbain II, 1095","points":7},{"critere":"Prise de Jérusalem, création des États latins d’Orient","points":7},{"critere":"Saladin","points":6}],"dureeMin":6,"corrige":"1. Le pape **Urbain II** appelle à la première croisade en **1095**.\n\n2. En **1099**, les croisés **prennent Jérusalem** et fondent les **États latins d’Orient**.\n\n3. C’est **Saladin** qui reprend Jérusalem en **1187**."}$exo$::jsonb),
  ('d08c84fe-8112-5b6b-bb75-0870d4b1c883'::uuid, 2, 'redaction', $exo${"titre":"Le commerce malgré les guerres","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Carnet d’un marchand (texte écrit pour l’exercice).**\n> « Je pars de Venise. Dans ma cale : des draps de laine et du bois. Je reviens d’Orient avec de la soie, des épices et du sucre. Nos comptoirs nous accueillent de port en port. Pour ne pas transporter mon argent, je remets une lettre à mon associé : il sera payé à l’arrivée. »\n\n1. Quelles marchandises viennent d’Orient ? Lesquelles viennent d’Occident, selon le document ?\n2. Quelles villes italiennes dominent ce commerce ? Que sont les comptoirs ?\n3. Quel instrument bancaire le marchand utilise-t-il pour ne pas transporter son argent ? Cite une autre invention des marchands italiens.","bareme":[{"critere":"Orient : soie, épices, sucre ; Occident : draps de laine, bois","points":6},{"critere":"Venise, Gênes, Pise ; comptoirs = installations commerciales dans les ports du bassin","points":6},{"critere":"Lettre de change ; comptabilité en partie double ou assurance maritime","points":8}],"dureeMin":10,"corrige":"1. Venues d’**Orient** : **soie**, **épices**, **sucre** (et parfums, papier, porcelaine). Venues d’**Occident** : **draps de laine** et **bois** (et métaux).\n\n2. **Venise, Gênes et Pise** dominent le commerce. Les **comptoirs** sont des installations commerciales établies dans les ports de tout le bassin méditerranéen.\n\n3. Le marchand utilise la **lettre de change**. Autres inventions : la **comptabilité en partie double** et l’**assurance maritime**."}$exo$::jsonb),
  ('d08c84fe-8112-5b6b-bb75-0870d4b1c883'::uuid, 3, 'redaction', $exo${"titre":"Frontière et pont","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"« La Méditerranée médiévale est à la fois une frontière et un pont. »\n\n1. Cite les trois civilisations en présence et leurs centres.\n2. Donne trois dates ou événements des croisades qui montrent que la Méditerranée est une frontière. Explique pourquoi la quatrième croisade (1204) est particulière.\n3. Explique par quel chemin les textes grecs reviennent en Occident. Nomme un lieu de traduction.\n4. Rédige un paragraphe qui justifie la phrase de l’énoncé, en t’appuyant sur des exemples précis.","bareme":[{"critere":"Chrétienté latine (Rome), orthodoxe (Constantinople), monde musulman (Damas, Bagdad, Le Caire, Cordoue)","points":4},{"critere":"Trois événements justes (1095, 1099, 1187, 1291…) ; 1204 : des chrétiens contre des chrétiens","points":5},{"critere":"Textes grecs conservés et traduits en arabe puis retraduits en latin ; Tolède ou Sicile","points":5},{"critere":"Paragraphe : guerres (frontière) et commerce, traductions, numération, boussole (pont)","points":6}],"dureeMin":15,"corrige":"1. La chrétienté **latine** (Rome), la chrétienté **orthodoxe** (Byzance, Constantinople) et le monde **musulman** (Damas, puis Bagdad, Le Caire, Cordoue).\n\n2. Trois exemples au choix : **1095** appel d’Urbain II ; **1099** prise de Jérusalem ; **1187** Saladin reprend Jérusalem ; **1291** chute de Saint-Jean-d’Acre ; **1492** prise de Grenade. La quatrième croisade (**1204**) est particulière : elle **pille Constantinople**, des **chrétiens contre des chrétiens**.\n\n3. Les **textes grecs** sont conservés et **traduits en arabe**, puis **retraduits en latin** à **Tolède** (ou en Sicile) par des chrétiens, des juifs et des musulmans ; l’Occident les redécouvre.\n\n4. Paragraphe attendu : **frontière**, car les croisades et la Reconquista opposent chrétiens et musulmans ; **pont**, car le commerce ne s’arrête jamais (Venise, Gênes, Pise, comptoirs, lettre de change) et les savoirs circulent (numération indo-arabe, zéro, algèbre, médecine d’Avicenne, boussole, papier). Le vocabulaire en garde la trace : algèbre, alcool, chiffre, amiral, sucre."}$exo$::jsonb),
  ('0465db80-dd5d-5ee7-81ab-7be62edcfd41'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire de la faim","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle est la différence entre sous-nutrition et malnutrition ?\n2. Environ combien de personnes souffrent de la faim dans le monde ?\n3. Qu’est-ce que l’agriculture vivrière ?","bareme":[{"critere":"Sous-nutrition = manque de calories ; malnutrition = mal manger, carences","points":8},{"critere":"Environ 800 millions","points":5},{"critere":"Agriculture vivrière : produire pour nourrir sa famille","points":7}],"dureeMin":7,"corrige":"1. La **sous-nutrition**, c’est ne pas manger assez de **calories**. La **malnutrition**, c’est **mal manger** : carences en protéines, vitamines, fer.\n\n2. Environ **800 millions** de personnes souffrent de la faim.\n\n3. L’agriculture **vivrière** est destinée à **nourrir le producteur et sa famille**, avec peu de moyens."}$exo$::jsonb),
  ('0465db80-dd5d-5ee7-81ab-7be62edcfd41'::uuid, 2, 'redaction', $exo${"titre":"Deux modèles agricoles","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"| Le modèle | Ses moyens | Ses rendements |\n| Agriculture A | Peu de moyens, produire pour se nourrir | Faibles |\n| Agriculture B | Mécanisation, engrais, irrigation, sélection | Élevés |\n\n1. Donne le nom de chaque modèle (A et B).\n2. Qu’est-ce que la révolution verte ? Où a-t-elle eu lieu et à quel prix ?\n3. Pourquoi l’agriculture A est-elle très exposée aux aléas ?","bareme":[{"critere":"A = vivrière, B = productiviste et commerciale","points":5},{"critere":"Révolution verte : hausse des rendements en Asie (1960-1980) ; forte consommation d’eau et d’intrants","points":8},{"critere":"Faibles moyens et rendements : sécheresse ou catastrophe = disette","points":7}],"dureeMin":10,"corrige":"1. **A** : agriculture **vivrière**. **B** : agriculture **productiviste et commerciale**, pour le marché mondial.\n\n2. La **révolution verte** (années **1960-1980**) a fortement augmenté les **rendements en Asie** grâce aux engrais, à l’irrigation et aux variétés sélectionnées. Elle s’est faite au prix d’une **forte consommation d’eau et d’intrants**.\n\n3. L’agriculture vivrière a **peu de moyens** et des **rendements faibles** : une sécheresse ou une catastrophe peut détruire la récolte et laisser la famille sans nourriture."}$exo$::jsonb),
  ('0465db80-dd5d-5ee7-81ab-7be62edcfd41'::uuid, 3, 'redaction', $exo${"titre":"Le paradoxe de la faim","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Extrait d’un rapport (texte écrit pour l’exercice).**\n> « La planète produit assez de nourriture pour tous. Pourtant, environ 800 millions de personnes souffrent de la faim, tandis que plus de 2 milliards sont en surpoids. Près d’un tiers de la nourriture produite est perdue ou gaspillée. L’agriculture occupe la moitié des terres habitables et prélève 70 % de l’eau douce. »\n\n1. Quel paradoxe le texte décrit-il ? Pourquoi peut-on dire que « le problème n’est pas la quantité produite » ?\n2. Cite trois causes de la faim.\n3. Pourquoi produire toujours plus n’est-il pas une solution sans limite ?\n4. Rédige un paragraphe qui propose et justifie trois pistes pour nourrir 10 milliards d’humains sans épuiser la planète.","bareme":[{"critere":"Paradoxe : faim et surpoids côte à côte ; le problème est l’accès, pas la production","points":5},{"critere":"Trois causes justes (pauvreté, conflits, sécheresses, manque de routes ou de stockage, spéculation)","points":4},{"critere":"Moitié des terres, 70 % de l’eau, gaz à effet de serre, déforestation","points":4},{"critere":"Trois pistes justifiées (agroécologie, réduction du gaspillage, moins de viande, stockage, circuits courts…)","points":7}],"dureeMin":15,"corrige":"1. Le texte décrit le **paradoxe** suivant : environ 800 millions de personnes ont faim alors que plus de 2 milliards sont en surpoids. La planète produit **assez** pour tous : le problème est l’**accès** à la nourriture, pas la quantité produite.\n\n2. Trois causes au choix : la **pauvreté**, les **conflits armés**, les **sécheresses et catastrophes**, l’**absence de routes et de stockage**, la **spéculation sur les prix**.\n\n3. Produire plus demande de la terre (**la moitié des terres habitables** est déjà occupée), de l’**eau** (**70 %** des prélèvements) et contribue aux **gaz à effet de serre** et à la **déforestation**. Sans précaution, on épuise sols, eau et climat.\n\n4. Trois pistes au choix, expliquées : **réduire le gaspillage** (un tiers perdu) ; **limiter la consommation de viande** (beaucoup de terres, d’eau et de céréales) ; **améliorer stockage et transports au Sud** ; **agroécologie**, **circuits courts**, **sécuriser le foncier des paysans**. Conclusion : nourrir 10 milliards d’humains en 2060 est possible, mais sans épuiser sols, eau et climat."}$exo$::jsonb),
  ('d4196e09-df46-5618-b0c1-b914f610834c'::uuid, 1, 'redaction', $exo${"titre":"L’eau sur la planète","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle part de l’eau de la planète est douce ?\n2. À partir de quel volume par habitant et par an parle-t-on de stress hydrique ?\n3. Quel secteur consomme le plus d’eau ? Quelle part des prélèvements ?","bareme":[{"critere":"2,5 %","points":6},{"critere":"Moins de 1 700 m³ par habitant et par an","points":7},{"critere":"L’agriculture, environ 70 %","points":7}],"dureeMin":6,"corrige":"1. **2,5 %** de l’eau de la planète est douce (97,5 % est salée).\n\n2. On parle de **stress hydrique** sous **1 700 m³** par habitant et par an.\n\n3. C’est l’**agriculture** (irrigation) : environ **70 %** des prélèvements."}$exo$::jsonb),
  ('d4196e09-df46-5618-b0c1-b914f610834c'::uuid, 2, 'redaction', $exo${"titre":"L’eau cachée dans nos objets","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"| Le produit | Son eau virtuelle |\n| 1 kg de bœuf | 15 000 litres |\n| 1 tee-shirt en coton | 2 700 litres |\n| 1 tasse de café | 140 litres |\n\n1. Que veut dire « eau virtuelle » ?\n2. Calcule combien de tasses de café représentent l’eau virtuelle d’un tee-shirt en coton (arrondis à l’entier le plus proche). Puis compare l’eau de 1 kg de bœuf à celle d’un tee-shirt.\n3. Explique la phrase : « Importer un produit, c’est importer l’eau qui a servi à le faire. »","bareme":[{"critere":"Eau virtuelle : eau nécessaire pour produire un bien","points":5},{"critere":"2 700 divisé par 140 ≈ 19 tasses ; 15 000 litres pour le bœuf, soit plus de cinq fois le tee-shirt","points":8},{"critere":"Explication : un pays qui importe économise sa propre eau, l’eau est consommée ailleurs","points":7}],"dureeMin":10,"corrige":"1. L’**eau virtuelle** est l’**eau nécessaire pour produire** un bien.\n\n2. 2 700 ÷ 140 ≈ **19,3**, soit environ **19 tasses** de café. Le bœuf (15 000 L) demande plus de **5 fois** l’eau d’un tee-shirt (15 000 ÷ 2 700 ≈ 5,6).\n\n3. Un produit fabriqué ailleurs a consommé l’eau du pays producteur. Le pays qui l’importe **reçoit** donc, sans la voir, toute cette eau : l’eau circule sous forme de marchandises."}$exo$::jsonb),
  ('d4196e09-df46-5618-b0c1-b914f610834c'::uuid, 3, 'redaction', $exo${"titre":"Une ressource rare, mal répartie","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Extrait d’un article (texte écrit pour l’exercice).**\n> « Dans une région d’Asie centrale, un lac autrefois immense a presque disparu : les fleuves qui l’alimentaient sont détournés pour irriguer les champs de coton. Plus au sud, deux pays riverains d’un même fleuve se disputent chaque barrage. Pourtant, ailleurs, l’eau reste abondante. »\n\n1. Quel lac a connu cette disparition ? Quelle activité en est la cause ?\n2. Cite deux causes de tension autour de l’eau, en ajoutant un exemple de fleuve partagé.\n3. Explique la phrase du cours : « L’eau ne manque pas partout ; elle manque là où l’on en a besoin, au moment où l’on en a besoin. »\n4. Rédige un paragraphe présentant trois solutions pour mieux gérer l’eau, en précisant leurs limites si tu en connais.","bareme":[{"critere":"Mer d’Aral ; irrigation / surexploitation agricole","points":4},{"critere":"Deux causes (surexploitation, pollution, glaciers, conflits) + fleuve (Nil, Jourdain, Tigre, Euphrate)","points":5},{"critere":"Inégale répartition dans l’espace et dans le temps : problème de gestion autant que de stock","points":5},{"critere":"Trois solutions expliquées (goutte-à-goutte, recyclage, dessalement, coopération, protection des nappes) et une limite (dessalement coûteux et énergivore)","points":6}],"dureeMin":15,"corrige":"1. Il s’agit de la **mer d’Aral**, asséchée par la **surexploitation** de l’eau pour l’**irrigation** (le coton).\n\n2. Deux causes au choix : **surexploitation des nappes**, **pollution** agricole et industrielle, **fonte des glaciers** qui alimentent les grands fleuves, **conflits entre pays riverains**. Fleuves partagés : **Nil**, **Jourdain**, **Tigre et Euphrate**.\n\n3. Neuf pays concentrent 60 % des réserves, alors que le Proche-Orient, le Sahel et l’Asie centrale manquent d’eau : la **répartition est inégale**, dans l’espace **et** dans le temps. C’est un problème de **gestion** autant que de stock.\n\n4. Trois solutions au choix : **économiser** (goutte-à-goutte, réparation des fuites, tarification), **recycler** les eaux usées, **dessaler** l’eau de mer (**coûteux et énergivore**), **protéger** nappes et zones humides, **coopérer** entre États riverains."}$exo$::jsonb),
  ('cae7a8b6-8739-5d2d-b9a3-5893ff36c18e'::uuid, 1, 'redaction', $exo${"titre":"Les familles d’énergies","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle part du mix énergétique mondial les énergies fossiles représentent-elles environ ?\n2. Cite trois énergies fossiles ou non renouvelables.\n3. Quelle est la première énergie renouvelable dans le monde ?","bareme":[{"critere":"Environ 80 %","points":6},{"critere":"Trois énergies justes (pétrole, charbon, gaz naturel, uranium)","points":8},{"critere":"L’hydraulique","points":6}],"dureeMin":6,"corrige":"1. Les énergies fossiles pèsent encore environ **80 %** du mix mondial.\n\n2. Trois au choix : **pétrole**, **charbon**, **gaz naturel**, **uranium** (non renouvelable).\n\n3. La première énergie renouvelable est l’**hydraulique**."}$exo$::jsonb),
  ('cae7a8b6-8739-5d2d-b9a3-5893ff36c18e'::uuid, 2, 'redaction', $exo${"titre":"Le problème de chaque énergie","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"| L’énergie | Un inconvénient |\n| Les fossiles | ? |\n| Le nucléaire | ? |\n| L’éolien et le solaire | ? |\n\n1. Complète le tableau (un inconvénient par ligne ; pour les fossiles, donne celui qui concerne le climat).\n2. Quelles catastrophes de 1986 et de 2011 illustrent le risque nucléaire ?\n3. Pourquoi les énergies renouvelables ne sont-elles pas « sans impact » ?","bareme":[{"critere":"Fossiles : CO₂ ; nucléaire : déchets ou accident ; éolien-solaire : intermittence","points":8},{"critere":"Tchernobyl (1986) et Fukushima (2011)","points":5},{"critere":"Espace, matériaux rares, intermittence : aucune source n’est sans impact","points":7}],"dureeMin":10,"corrige":"1. **Fossiles** : leur combustion émet du **CO₂**, première cause du réchauffement. **Nucléaire** : les **déchets** et le **risque d’accident**. **Éolien et solaire** : l’**intermittence**.\n\n2. **Tchernobyl** (**1986**) et **Fukushima** (**2011**).\n\n3. Les renouvelables sont **gourmandes en espace et en matériaux rares** et **intermittentes**. Aucune source n’est sans impact : la première énergie propre est celle qu’on ne consomme pas."}$exo$::jsonb),
  ('cae7a8b6-8739-5d2d-b9a3-5893ff36c18e'::uuid, 3, 'redaction', $exo${"titre":"Consommer plus, émettre moins","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Constat d’un rapport (texte écrit pour l’exercice).**\n> « La consommation mondiale d’énergie a été multipliée par plus de dix en un siècle. Un Nord-Américain consomme plusieurs dizaines de fois plus qu’un habitant du Sahel. Environ 700 millions de personnes n’ont toujours pas d’électricité. »\n\n1. Donne trois raisons de l’explosion de la consommation.\n2. Que dit le texte des inégalités d’accès ? Où vivent surtout les personnes privées d’électricité ?\n3. Nomme les trois leviers de la transition énergétique dans l’ordre et explique-les.\n4. Rédige un paragraphe : comment donner accès à l’énergie à ces 700 millions de personnes sans aggraver le réchauffement ?","bareme":[{"critere":"Trois raisons : démographie, industrialisation, niveau de vie","points":4},{"critere":"Inégalités Nord-Sahel ; Afrique subsaharienne","points":4},{"critere":"Sobriété, efficacité, substitution, expliquées dans l’ordre","points":6},{"critere":"Paragraphe : accès direct aux renouvelables sans passer par l’étape fossile, argumenté","points":6}],"dureeMin":15,"corrige":"1. **Croissance démographique**, **industrialisation**, **élévation du niveau de vie**.\n\n2. Un Nord-Américain consomme **plusieurs dizaines de fois** plus qu’un habitant du Sahel ; environ **700 millions** de personnes n’ont pas d’électricité, principalement en **Afrique subsaharienne**.\n\n3. Dans l’ordre : **sobriété** (consommer moins : isolation, transports collectifs), **efficacité** (consommer mieux : meilleurs rendements, réseaux intelligents), **substitution** (remplacer les fossiles par des énergies décarbonées).\n\n4. Paragraphe attendu : leur développement passe par l’énergie ; l’enjeu est de leur donner accès **directement aux renouvelables** (solaire, éolien, hydraulique), **sans passer par l’étape fossile** qui a alimenté le réchauffement chez les pays riches. Cela demande des financements et des réseaux adaptés, et n’exonère pas les pays riches de faire d’abord sobriété et efficacité."}$exo$::jsonb),
  ('e9026b5d-4908-5eaf-9eb1-22885e5f9dbc'::uuid, 1, 'redaction', $exo${"titre":"Définir le développement durable","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Comment définit-on le développement durable ?\n2. Quels sont les trois piliers ?\n3. Combien d’objectifs de développement durable l’ONU adopte-t-elle en 2015, pour quelle échéance ?","bareme":[{"critere":"Répond aux besoins du présent sans compromettre ceux des générations futures","points":7},{"critere":"Économique, social, environnemental","points":7},{"critere":"17 objectifs, à atteindre en 2030","points":6}],"dureeMin":6,"corrige":"1. Un développement qui répond aux **besoins du présent** **sans compromettre** la capacité des **générations futures** à répondre aux leurs (rapport Brundtland, 1987).\n\n2. Les piliers : **économique**, **social**, **environnemental**.\n\n3. **17** objectifs de développement durable (ODD), à atteindre en **2030**."}$exo$::jsonb),
  ('e9026b5d-4908-5eaf-9eb1-22885e5f9dbc'::uuid, 2, 'redaction', $exo${"titre":"Les indicateurs du développement","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"| L’indicateur | Ce qu’il mesure |\n| PIB par habitant | ? |\n| IDH | ? |\n| Empreinte écologique | ? |\n\n1. Complète le tableau.\n2. Quelle est la limite de l’IDH ?\n3. Qu’apprend-on quand on dit que l’humanité vivrait comme un Français moyen ?","bareme":[{"critere":"PIB : richesse produite ; IDH : richesse, espérance de vie, éducation ; empreinte : surface nécessaire pour produire et absorber les déchets","points":8},{"critere":"IDH ignore les inégalités à l’intérieur du pays","points":5},{"critere":"Près de trois planètes seraient nécessaires","points":7}],"dureeMin":10,"corrige":"1. **PIB par habitant** : la **richesse produite**. **IDH** : **richesse**, **espérance de vie** et **éducation** (entre 0 et 1). **Empreinte écologique** : la **surface nécessaire** pour produire ce qu’on consomme et absorber ses déchets.\n\n2. L’IDH est une moyenne : il **ignore les inégalités à l’intérieur d’un pays**.\n\n3. Il faudrait **près de trois planètes** : notre mode de vie dépasse ce que la Terre peut fournir. Ce constat est à l’origine du développement durable."}$exo$::jsonb),
  ('e9026b5d-4908-5eaf-9eb1-22885e5f9dbc'::uuid, 3, 'redaction', $exo${"titre":"Un projet est-il durable ?","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Projet local (texte écrit pour l’exercice).**\n> « Une commune veut construire un grand parc de loisirs qui créera 200 emplois. Il faudra détruire un bois où vivent des espèces protégées. Les habitants du quartier voisin, peu aisés, ne pourront pas payer l’entrée. »\n\n1. Pour chaque pilier (économique, social, environnemental), dis si le projet le satisfait ou non.\n2. Ce projet est-il durable ? Justifie avec la règle du cours.\n3. Comment appelle-t-on les exigences nées du croisement des piliers ? Lesquelles sont ici mises à mal ?\n4. Rédige un paragraphe proposant deux modifications du projet, à l’échelle locale, pour le rendre plus durable, puis cite un exemple d’action à l’échelle mondiale.","bareme":[{"critere":"Économique oui (emplois), social non (quartier exclu), environnemental non (bois détruit)","points":5},{"critere":"Non durable : il faut les trois piliers à la fois","points":4},{"critere":"Viable, équitable, vivable ; équitable et vivable mises à mal","points":5},{"critere":"Deux modifications cohérentes et un exemple mondial (accord de Paris, ODD, sommet)","points":6}],"dureeMin":15,"corrige":"1. **Économique** : oui (200 emplois). **Social** : non (les habitants du quartier pauvre sont exclus). **Environnemental** : non (destruction d’un bois abritant des espèces protégées).\n\n2. Le projet n’est **pas durable** : il n’est durable que s’il satisfait les **trois piliers à la fois**.\n\n3. **Viable** (économie + environnement), **équitable** (économie + social), **vivable** (social + environnement). Ici, il n’est ni **équitable** (le quartier est exclu), ni **vivable** (le cadre de vie et l’environnement sont dégradés) ; il est aussi peu **viable** car il détruit la biodiversité.\n\n4. Modifications au choix : **déplacer le parc** sur un terrain déjà aménagé ou **préserver le bois** ; **tarif réduit** ou accès gratuit pour les habitants ; **transports en commun**. À l’échelle mondiale : **accord de Paris (2015)**, **ODD**, sommet de Rio (1992). Le développement durable se joue du local au mondial."}$exo$::jsonb),
  ('ec7397cc-48b8-5347-ba45-a9bc9806dc43'::uuid, 1, 'redaction', $exo${"titre":"Les mots de la démographie","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Que signifie « accroissement naturel » ?\n2. Quel est le seuil de renouvellement des générations ?\n3. Combien d’humains la Terre compte-t-elle en 2022 ? Sur quel continent vit près de 60 % de l’humanité ?","bareme":[{"critere":"Natalité moins mortalité","points":7},{"critere":"2,1 enfants par femme","points":5},{"critere":"8 milliards ; Asie","points":8}],"dureeMin":6,"corrige":"1. L’**accroissement naturel** est la différence entre le **taux de natalité** et le **taux de mortalité**.\n\n2. Le seuil est de **2,1 enfants par femme**.\n\n3. **8 milliards** en 2022 ; près de **60 %** de l’humanité vit en **Asie**."}$exo$::jsonb),
  ('ec7397cc-48b8-5347-ba45-a9bc9806dc43'::uuid, 2, 'redaction', $exo${"titre":"La transition démographique","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"| La phase | La natalité | La mortalité | La population |\n| 1 | Forte | Forte | ? |\n| 2 | Forte | ? | ? |\n| 3 | ? | Faible | ? |\n\n1. Complète le tableau.\n2. Explique pourquoi la mortalité chute pendant la phase 2.\n3. Quelle région du monde est encore en phase 2 ? Laquelle a achevé sa transition ?","bareme":[{"critere":"Tableau complété : stagne / chute, explose / baisse, se stabilise","points":8},{"critere":"Médecine, vaccins, eau potable, alimentation","points":6},{"critere":"Afrique subsaharienne en phase 2 ; Europe a achevé","points":6}],"dureeMin":10,"corrige":"1. Phase 1 : population qui **stagne**. Phase 2 : mortalité qui **chute**, population qui **explose**. Phase 3 : natalité qui **baisse**, population qui se **stabilise**.\n\n2. La mortalité recule grâce à la **médecine**, aux **vaccins**, à l’**eau potable** et à l’**alimentation**.\n\n3. L’**Afrique subsaharienne** est encore en pleine phase 2 ; l’**Europe** a **achevé** sa transition."}$exo$::jsonb),
  ('ec7397cc-48b8-5347-ba45-a9bc9806dc43'::uuid, 3, 'redaction', $exo${"titre":"Deux mondes démographiques","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Comparaison (texte écrit pour l’exercice).**\n> « Dans le pays X, une femme a en moyenne 5 enfants et la moitié de la population a moins de 20 ans. Dans le pays Y, une femme a en moyenne 1,3 enfant et un habitant sur quatre a plus de 65 ans. »\n\n1. Compare la fécondité de X et de Y avec le seuil de renouvellement. Que va-t-il arriver à la population de chacun, sans migrations ?\n2. Dans quelle phase de la transition démographique est plutôt X ? Y ?\n3. Cite un défi majeur pour X et un défi majeur pour Y.\n4. Rédige un paragraphe expliquant pourquoi ces deux pays n’ont pas besoin des mêmes politiques.","bareme":[{"critere":"X très au-dessus de 2,1 (population croît), Y en dessous (elle diminue et vieillit)","points":5},{"critere":"X phase 2, Y phase 3 ou après","points":3},{"critere":"Défi X : nourrir, loger, scolariser, urbanisation ; défi Y : vieillissement, retraites","points":5},{"critere":"Paragraphe : jeunesse nombreuse contre population vieillissante, politiques différentes justifiées","points":7}],"dureeMin":15,"corrige":"1. X : **5** enfants par femme, très **au-dessus** de **2,1** : la population va **croître fortement**. Y : **1,3**, **en dessous** de 2,1 : la population va **diminuer** et **vieillir**.\n\n2. X ressemble à la **phase 2** (natalité forte, mortalité en baisse) ; Y à la **phase 3** (natalité basse, population qui vieillit), comme l’Europe.\n\n3. X : **nourrir, loger, scolariser, soigner** une population qui croît vite, **urbanisation** rapide ; pression sur l’eau, les sols, l’énergie. Y : **vieillissement** et **financement des retraites**.\n\n4. Paragraphe attendu : deux mondes coexistent. L’un doit gérer une **jeunesse nombreuse** : écoles, emplois, logements, santé. L’autre une **population qui vieillit** : retraites, soins aux personnes âgées, main-d’œuvre. Ce ne sont **pas les mêmes politiques**."}$exo$::jsonb),
  ('0afccf60-b288-5dbc-a319-d50cfb5c2997'::uuid, 1, 'redaction', $exo${"titre":"Les groupes de pays","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"Pour comparer les pays du monde, on les range en groupes et on mesure leur développement.\n\n1. Qu’est-ce qu’un pays émergent ? Cite un exemple.\n2. Que désigne le sigle PMA ? Dans quel continent en trouve-t-on surtout ?\n3. Que combine l’IDH ?","bareme":[{"critere":"Émergent : croissance rapide, industrialisation, inégalités ; exemple Chine, Inde, Brésil, Afrique du Sud","points":7},{"critere":"Pays les moins avancés","points":6},{"critere":"Richesse, santé (espérance de vie), éducation","points":7}],"dureeMin":6,"corrige":"1. Un pays **émergent** a une **croissance rapide** et s’industrialise, mais reste très **inégalitaire**. Exemples : **Chine**, **Inde**, **Brésil**, **Afrique du Sud**.\n\n2. **PMA** : les **pays les moins avancés** (une cinquantaine, surtout en Afrique).\n\n3. L’**IDH** combine **richesse**, **santé** (espérance de vie) et **éducation**."}$exo$::jsonb),
  ('0afccf60-b288-5dbc-a319-d50cfb5c2997'::uuid, 2, 'redaction', $exo${"titre":"Riches et pauvres, partout","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Reportage (texte écrit pour l’exercice).**\n> « Dans une grande ville d’un pays émergent, un quartier d’affaires aux tours de verre se trouve à deux kilomètres d’un bidonville. À la campagne, des villages restent isolés, sans école ni dispensaire. »\n\n1. Quelles inégalités à l’intérieur du pays le texte montre-t-il ?\n2. Pourquoi l’opposition Nord/Sud ne suffit-elle plus ?\n3. Cite deux leviers qui réduisent les écarts.","bareme":[{"critere":"Bidonville et quartier d’affaires ; ville et campagne isolée","points":7},{"critere":"Nord/Sud ne dit rien de la Chine ni des inégalités internes","points":7},{"critere":"Deux leviers justes (scolarisation des filles, soins, microcrédits, transferts, aide)","points":6}],"dureeMin":10,"corrige":"1. Le texte montre l’opposition **bidonvilles / quartiers d’affaires** dans la même ville, et **villes / campagnes isolées**.\n\n2. L’opposition **Nord/Sud** ne rend compte ni de la **Chine** ou des **émergents**, ni des **inégalités à l’intérieur** de chaque pays : il y a des pauvres dans les pays riches et des très riches dans les pays pauvres.\n\n3. Deux leviers au choix : **scolarisation** (surtout des filles), **accès aux soins et à l’eau potable**, **microcrédits**, **transferts des migrants**, **aide** internationale et **ONG**."}$exo$::jsonb),
  ('0afccf60-b288-5dbc-a319-d50cfb5c2997'::uuid, 3, 'redaction', $exo${"titre":"Un monde plus riche mais inégal","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Chiffres de synthèse (écrits pour l’exercice, d’après le cours).**\n> « Norvège : IDH supérieur à 0,95. Plusieurs pays d’Afrique subsaharienne : IDH inférieur à 0,45. Environ 700 millions de personnes vivent en pauvreté extrême. En trente ans, l’extrême pauvreté a fortement reculé. »\n\n1. Que montrent ces chiffres sur les écarts entre pays ? Comment lit-on un IDH (échelle) ?\n2. Pourquoi les transferts d’argent des migrants sont-ils un levier important ?\n3. Donne deux progrès réels du monde depuis 1990.\n4. Rédige un paragraphe pour répondre à la question : « Le monde est-il plus inégal ou plus juste qu’il y a trente ans ? », en montrant les progrès et les inégalités qui restent.","bareme":[{"critere":"Grands écarts d’IDH entre pays ; IDH entre 0 et 1","points":4},{"critere":"Transferts supérieurs à l’aide publique au développement","points":4},{"critere":"Deux progrès justes (pauvreté extrême, espérance de vie, scolarisation)","points":4},{"critere":"Paragraphe nuancé : progrès et inégalités qui demeurent","points":8}],"dureeMin":15,"corrige":"1. La **Norvège** dépasse **0,95** quand plusieurs pays d’Afrique subsaharienne restent **sous 0,45** : les écarts sont considérables. L’IDH se lit **entre 0 et 1**.\n\n2. Les **transferts des migrants** vers leur pays d’origine sont **supérieurs à l’aide publique au développement**.\n\n3. Deux progrès : **recul de l’extrême pauvreté**, **hausse de l’espérance de vie mondiale**, **progrès de la scolarisation**.\n\n4. Paragraphe attendu, nuancé : progrès réels (pauvreté extrême en recul, espérance de vie, scolarisation) mais **inégalités** qui demeurent : 700 millions en pauvreté extrême, PMA, inégalités entre pays et à l’intérieur des pays (bidonvilles, campagnes, hommes et femmes). Le monde de 2020 n’est pas celui de 1990, mais l’écart reste grand."}$exo$::jsonb),
  ('0aa371be-c900-5ad2-860f-cd710f11d87d'::uuid, 1, 'redaction', $exo${"titre":"Le mécanisme de l’effet de serre","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. L’effet de serre est-il un phénomène naturel ? Que serait la température de la Terre sans lui ?\n2. De combien la température moyenne a-t-elle augmenté depuis l’ère préindustrielle ?\n3. Quel organisme produit l’expertise scientifique sur le climat ?","bareme":[{"critere":"Oui, naturel et indispensable ; −18 °C sans lui","points":8},{"critere":"Environ +1,2 °C","points":6},{"critere":"GIEC","points":6}],"dureeMin":6,"corrige":"1. Oui : l’effet de serre est **naturel** et **indispensable**. Sans lui, la Terre serait à **−18 °C**. Le problème est son **renforcement** par les émissions humaines.\n\n2. Environ **+1,2 °C** depuis l’ère préindustrielle.\n\n3. Le **GIEC**."}$exo$::jsonb),
  ('0aa371be-c900-5ad2-860f-cd710f11d87d'::uuid, 2, 'redaction', $exo${"titre":"Des effets très inégaux","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"| La région | Ce qu’elle subit |\n| États insulaires du Pacifique | ? |\n| Sahel | ? |\n| Grands deltas (Bangladesh, Nil, Mékong) | ? |\n\n1. Complète le tableau.\n2. Explique pourquoi on dit que « ceux qui émettent le moins subissent souvent le plus ».\n3. Quelles deux causes expliquent la hausse du niveau des mers ?","bareme":[{"critere":"Submersion ; sécheresse aggravée ; densément peuplés et exposés","points":7},{"critere":"Justice climatique : pays peu émetteurs très exposés","points":6},{"critere":"Dilatation de l’eau et fonte des glaces continentales","points":7}],"dureeMin":10,"corrige":"1. **États insulaires** : menacés de **submersion**. **Sahel** : la **sécheresse s’aggrave**. **Deltas** : **densément peuplés et exposés** (montée des eaux).\n\n2. Les pays les plus exposés (îles, Sahel, deltas) sont souvent **peu responsables** des émissions : c’est le cœur du problème de **justice climatique**.\n\n3. La **dilatation de l’eau** (qui se réchauffe) et la **fonte des glaces continentales**."}$exo$::jsonb),
  ('0aa371be-c900-5ad2-860f-cd710f11d87d'::uuid, 3, 'redaction', $exo${"titre":"Atténuer et s’adapter","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Situation d’une île (texte écrit pour l’exercice).**\n> « Sur une petite île du Pacifique, la mer avance chaque année et l’eau des puits devient salée. Le gouvernement hésite : faut-il investir dans des digues, ou pousser les grands pays à réduire leurs émissions ? »\n\n1. Quel effet du changement global est ici décrit ?\n2. Quelle action relève de l’atténuation, laquelle de l’adaptation ? Définis les deux mots.\n3. Pourquoi ne faut-il pas choisir entre les deux ?\n4. Rédige un paragraphe qui explique pourquoi la négociation internationale est difficile (rôle des COP, accord de Paris de 2015 et notion de bien commun).","bareme":[{"critere":"Hausse du niveau des mers, submersion, salinisation","points":3},{"critere":"Atténuation : réduire les émissions ; adaptation : vivre avec les effets inévitables ; digues = adaptation","points":6},{"critere":"On n’évitera pas tout et on ne s’adaptera pas à tout : il faut les deux","points":4},{"critere":"Paragraphe : COP annuelles, accord de Paris 2015, climat bien commun, chacun attend l’effort des autres","points":7}],"dureeMin":15,"corrige":"1. La **hausse du niveau des mers** menace l’île de **submersion**.\n\n2. **Atténuation** : **réduire les émissions** de gaz à effet de serre (pousser les grands pays à réduire les leurs). **Adaptation** : **vivre avec** les effets déjà inévitables (les **digues**).\n\n3. On **n’évitera pas tout** et on **ne s’adaptera pas à tout** : atténuer et s’adapter ne s’opposent pas, il faut **les deux**.\n\n4. Paragraphe attendu : le **GIEC** apporte l’expertise, les **COP** organisent la négociation **chaque année**, l’**accord de Paris (2015)** engage les États. Mais le climat est un **bien commun** : chaque État est tenté d’**attendre l’effort des autres**, d’où la difficulté d’agir collectivement."}$exo$::jsonb),
  ('78be057d-ebc3-57b0-bb56-40a5eb2b9854'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire du risque","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"Pour parler des catastrophes, les géographes utilisent des mots précis.\n\n1. Définis l’aléa et la vulnérabilité.\n2. Quelle formule relie l’aléa, la vulnérabilité et le risque ?\n3. Cite deux catastrophes industrielles ou nucléaires avec leur date.","bareme":[{"critere":"Aléa : événement dangereux possible ; vulnérabilité : fragilité de ce qui est exposé","points":8},{"critere":"Risque = aléa × vulnérabilité","points":5},{"critere":"Deux catastrophes justes avec date (Bhopal 1984, AZF 2001, Tchernobyl 1986, Fukushima 2011, Lubrizol 2019)","points":7}],"dureeMin":7,"corrige":"1. L’**aléa** est l’événement dangereux **possible**. La **vulnérabilité** est la **fragilité** de ce qui est exposé : population, bâtiments, activités.\n\n2. **Risque = aléa × vulnérabilité**.\n\n3. Deux au choix : **Bhopal** (Inde, **1984**), **Tchernobyl** (**1986**), **AZF** à Toulouse (**2001**), **Fukushima** (**2011**), Lubrizol à Rouen (**2019**)."}$exo$::jsonb),
  ('78be057d-ebc3-57b0-bb56-40a5eb2b9854'::uuid, 2, 'redaction', $exo${"titre":"Un site dangereux près de la ville","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Article de presse (texte écrit pour l’exercice).**\n> « Depuis vingt ans, des lotissements ont été construits juste à côté de l’usine chimique de la ville. Les habitants n’ont jamais participé à un exercice d’évacuation. Ce week-end, un incendie s’est déclaré sur le site. »\n\n1. Où se trouve l’aléa dans cette situation ? Où se trouve la vulnérabilité ?\n2. Quelle directive européenne encadre les sites industriels dangereux ? Qu’est-ce qu’un PPRT ?\n3. Propose deux actions de prévention pour cette commune.","bareme":[{"critere":"Aléa : incendie ou accident de l’usine ; vulnérabilité : habitants et lotissements proches","points":6},{"critere":"Seveso ; PPRT interdit ou encadre les constructions autour d’un site dangereux","points":7},{"critere":"Deux actions justes (exercices, sirènes, plan d’urgence, limiter la construction, informer)","points":7}],"dureeMin":10,"corrige":"1. L’**aléa** est l’**incendie** (ou l’accident) sur le site chimique. La **vulnérabilité** est celle des **habitants** et des **lotissements** construits tout près, non préparés.\n\n2. La directive **Seveso** encadre les sites dangereux. Un **PPRT** (plan de prévention des risques technologiques) **interdit ou encadre les constructions** autour d’un site.\n\n3. Deux au choix : **exercices d’évacuation** et **sirènes**, **consignes** aux habitants, **plan d’urgence** dimensionné, **limiter les constructions** autour du site, cartographier les zones exposées."}$exo$::jsonb),
  ('78be057d-ebc3-57b0-bb56-40a5eb2b9854'::uuid, 3, 'redaction', $exo${"titre":"Les mêmes usines, pas les mêmes risques","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Comparaison (texte écrit pour l’exercice).**\n> « Deux usines identiques produisent le même produit chimique. L’une est dans un pays riche, entourée d’une zone où on ne peut plus construire, avec des sirènes et des exercices. L’autre, dans un pays pauvre, est entourée de quartiers denses ; les secours sont peu nombreux. »\n\n1. À aléa égal, laquelle des deux situations est la plus vulnérable ? Pourquoi ?\n2. Cite une catastrophe industrielle du cours qui illustre le risque dans un pays pauvre.\n3. Pourquoi Fukushima (2011) montre-t-il que les risques naturels et technologiques peuvent se combiner ?\n4. Rédige un paragraphe sur le paradoxe de l’acceptabilité : ces installations sont dangereuses et pourtant utiles, alors comment une société décide-t-elle du risque qu’elle accepte ?","bareme":[{"critere":"Usine du pays pauvre : quartiers denses, normes moins strictes, secours limités","points":5},{"critere":"Bhopal (Inde, 1984)","points":3},{"critere":"Fukushima : séisme et tsunami ont déclenché l’accident nucléaire","points":4},{"critere":"Paragraphe : utilité (emplois, énergie, produits) contre danger ; décision collective, conditions","points":8}],"dureeMin":15,"corrige":"1. La situation la plus vulnérable est celle du **pays pauvre** : installations dangereuses à côté de **quartiers denses**, **normes moins strictes**, **secours limités**. À aléa égal, la vulnérabilité y est bien plus grande.\n\n2. **Bhopal** (Inde, 1984, plusieurs milliers de morts).\n\n3. À **Fukushima**, un **séisme** et un **tsunami** (risques naturels) ont provoqué un **accident nucléaire** (risque technologique) : les deux se combinent.\n\n4. Paragraphe attendu : ces installations sont **dangereuses** mais **utiles** (**emplois**, **énergie**, produits du quotidien). Il faut décider **collectivement** quel niveau de risque une société accepte et à quelles conditions : normes (Seveso), aménagement (PPRT), information des habitants, secours. On ne supprime pas l’aléa : on réduit la vulnérabilité."}$exo$::jsonb),
  ('7cd8c20a-8763-5263-97cc-390c27715457'::uuid, 1, 'redaction', $exo${"titre":"Les trois ordres","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quels sont les trois ordres de la société médiévale ? Donne la fonction de chacun.\n2. Quelle est la différence entre un vilain et un serf ?\n3. Qu’est-ce que la dîme ?","bareme":[{"critere":"Trois ordres : clergé (prier), seigneurs (combattre), paysans (travailler)","points":8},{"critere":"Vilain libre, serf attaché à la terre","points":6},{"critere":"Dîme : environ un dixième de la récolte versé à l’Église","points":6}],"dureeMin":6,"corrige":"1. Le **clergé** (ceux qui **prient**), les **seigneurs** (ceux qui **combattent**) et les **paysans** (ceux qui **travaillent**, environ **90 %** de la population).\n\n2. Le **vilain** est **libre** (il peut partir, se marier, transmettre son bien). Le **serf** est **attaché à la terre** et a des obligations supplémentaires.\n\n3. La **dîme** est une redevance d’environ **un dixième** de la récolte, versée à l’**Église**."}$exo$::jsonb),
  ('7cd8c20a-8763-5263-97cc-390c27715457'::uuid, 2, 'redaction', $exo${"titre":"Ce que le paysan doit","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Compte d’un paysan (texte écrit pour l’exercice).**\n> « Cette année, j’ai donné au seigneur trois journées de travail sur ses champs, une gerbe sur dix, et quelques pièces. Pour moudre mon blé et cuire mon pain, j’ai payé. Enfin, le curé a pris sa part de la récolte. »\n\n1. Associe chaque élément du texte à son nom : journées de travail, gerbe sur dix pour le seigneur, pièces, paiement du moulin et du four, part du curé.\n2. Comment appelle-t-on la partie de la seigneurie exploitée directement par le seigneur ? Et celle qui est confiée aux paysans ?\n3. Que désigne le mot « ban » ?","bareme":[{"critere":"Corvée, champart, cens, banalités, dîme","points":8},{"critere":"Réserve ; tenures","points":6},{"critere":"Ban : droit de commander, juger et punir","points":6}],"dureeMin":10,"corrige":"1. Journées de travail = **corvée**. Une part de la récolte pour le seigneur = **champart**. Pièces = **cens**. Moulin et four payants = **banalités**. Part du curé = **dîme**.\n\n2. La **réserve** est exploitée directement pour le seigneur ; les **tenures** sont confiées aux paysans contre des redevances.\n\n3. Le **ban** est le droit du seigneur de **commander, de juger et de punir**."}$exo$::jsonb),
  ('7cd8c20a-8763-5263-97cc-390c27715457'::uuid, 3, 'redaction', $exo${"titre":"Une société qui change","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Chronique (texte écrit pour l’exercice).**\n> « Autrefois, on défrichait peu et on labourait mal. Depuis peu, la charrue retourne mieux la terre, le cheval tire mieux grâce à un nouveau harnais, des moulins tournent sur nos rivières, et on laisse reposer les champs par rotations. Les enfants sont plus nombreux dans nos villages. »\n\n1. Quels progrès agricoles sont cités ou évoqués ? Donne-en trois avec leur nom exact.\n2. Quelle conséquence sur la population entre 1000 et 1300 ?\n3. Quelle crise touche l’Europe au XIVe siècle ? Donne deux dates ou événements et la part de la population emportée.\n4. Rédige un paragraphe : pourquoi la crise du XIVe siècle ébranle-t-elle le système seigneurial ?","bareme":[{"critere":"Trois progrès nommés : charrue à versoir, collier d’épaule, moulins, assolement triennal","points":5},{"critere":"Population de l’Europe doublée","points":3},{"critere":"Peste noire 1347-1352, guerre de Cent Ans 1337-1453, un tiers de la population","points":5},{"critere":"Paragraphe : famines, peste, guerre, moins de paysans, système seigneurial ébranlé","points":7}],"dureeMin":15,"corrige":"1. Trois au choix : **charrue à versoir**, **collier d’épaule**, **moulins à eau et à vent**, **assolement triennal**, **défrichements**.\n\n2. La population de l’Europe **double** entre **1000 et 1300**.\n\n3. Au XIVe siècle : la **peste noire** (**1347-1352**), la **guerre de Cent Ans** (**1337-1453**) et des **famines**. Elles emportent **un tiers** de la population européenne.\n\n4. Paragraphe attendu : famines, peste et guerre font disparaître **un tiers** de la population ; il manque des paysans pour cultiver les tenures et payer les redevances ; l’équilibre de la seigneurie est **ébranlé durablement**."}$exo$::jsonb),
  ('f25a8430-454c-5d1f-928a-4dbd248c7a27'::uuid, 1, 'redaction', $exo${"titre":"L’Église au quotidien","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Combien y a-t-il de sacrements ? Cite-en trois.\n2. Quelle est la différence entre clergé séculier et clergé régulier ?\n3. Quels ordres apparaissent au XIIIe siècle et prêchent dans les villes ?","bareme":[{"critere":"Sept sacrements, trois exemples justes","points":6},{"critere":"Séculier : au contact des fidèles ; régulier : selon une règle, à l’écart","points":8},{"critere":"Ordres mendiants : franciscains et dominicains","points":6}],"dureeMin":7,"corrige":"1. **Sept** sacrements. Trois au choix : **baptême**, **confirmation**, **eucharistie**, **pénitence**, **mariage**, **ordre**, **extrême-onction**.\n\n2. Le clergé **séculier** vit « dans le siècle », au contact des fidèles (curé, évêque, pape). Le clergé **régulier** vit selon une **règle**, à l’écart du monde (moines).\n\n3. Les **ordres mendiants** : **franciscains** et **dominicains**."}$exo$::jsonb),
  ('f25a8430-454c-5d1f-928a-4dbd248c7a27'::uuid, 2, 'redaction', $exo${"titre":"Lire une cathédrale","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Description (texte écrit pour l’exercice).**\n> « Nous entrons dans une cathédrale de pierre claire. Des voûtes croisées s’élèvent très haut, soutenues à l’extérieur par de grands arcs. Les murs, percés de larges baies, laissent passer la lumière colorée des vitraux, qui racontent des scènes de la Bible. »\n\n1. De quel style est cette église ? Justifie avec deux éléments du texte et donne un nom de cathédrale du même style.\n2. Pourquoi les vitraux et les sculptures racontent-ils la Bible ?\n3. Comment ce style se distingue-t-il du style roman ?","bareme":[{"critere":"Gothique ; deux éléments (voûtes croisées d’ogives, arcs-boutants, vitraux) ; une cathédrale","points":8},{"critere":"Population qui ne sait pas lire","points":5},{"critere":"Roman : plein cintre, murs épais, petites ouvertures, sombre","points":7}],"dureeMin":10,"corrige":"1. C’est le style **gothique** : **croisée d’ogives** (voûtes croisées), **arcs-boutants** (grands arcs extérieurs), murs allégés avec de larges baies et **vitraux**. Exemples : **Chartres**, **Reims**, **Amiens**, **Notre-Dame de Paris**.\n\n2. Parce que la **population ne sait pas lire** : les images sont un livre pour ceux qui ne lisent pas.\n\n3. Le style **roman** (XIe-XIIe siècles) a des voûtes en **plein cintre**, des **murs épais**, de **petites ouvertures** : des églises sombres et massives."}$exo$::jsonb),
  ('f25a8430-454c-5d1f-928a-4dbd248c7a27'::uuid, 3, 'redaction', $exo${"titre":"Une puissance qui encadre la vie","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"« Au Moyen Âge, être chrétien n’est pas un choix : c’est une condition. L’Église encadre la vie entière. »\n\n1. Montre par deux exemples du cours que l’Église rythme la vie de chacun (sacrements, calendrier).\n2. Cite trois services que l’Église assure à la population, en plus de la religion.\n3. Comment l’Église combat-elle les hérésies ? Nomme un mouvement du XIIIe siècle et deux moyens de répression ou de pression.\n4. Rédige un paragraphe : pourquoi l’Église est-elle à la fois une puissance spirituelle et matérielle ?","bareme":[{"critere":"Deux exemples justes : sept sacrements, cloches, dimanche chômé, fêtes, carême","points":4},{"critere":"Trois services (hôpital, école, aumône, accueil des pèlerins)","points":4},{"critere":"Cathares ; Inquisition, excommunication","points":4},{"critere":"Paragraphe : premier propriétaire foncier, dîme, domaines ; autorité sur les âmes","points":8}],"dureeMin":15,"corrige":"1. Deux au choix : les **sept sacrements** jalonnent l’existence ; les **cloches** sonnent les heures ; le **dimanche** est chômé ; l’année suit **Noël, Pâques, la Toussaint** ; le **carême** impose ses jeûnes.\n\n2. **Hôpital**, **école**, **aumône** aux pauvres, **accueil des pèlerins** (trois au choix).\n\n3. Elle combat les **hérésies** comme celle des **cathares** (XIIIe siècle), avec l’**Inquisition** et l’**excommunication**, qui exclut un fidèle de la communauté.\n\n4. Paragraphe attendu : puissance **spirituelle** (sacrements, calendrier, excommunication, arme redoutable contre un roi) et **matérielle** : premier **propriétaire foncier** d’Occident, elle perçoit la **dîme** et gère des domaines."}$exo$::jsonb),
  ('00b22604-2e14-50cd-827d-fe2754d38f5e'::uuid, 1, 'redaction', $exo${"titre":"Les repères des villes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelles trois causes expliquent la renaissance urbaine des XIe-XIIIe siècles ?\n2. De quoi vivent les villes flamandes comme Bruges et Gand ?\n3. Qu’est-ce qu’une corporation ?","bareme":[{"critere":"Progrès agricoles, croissance de la population, reprise du commerce","points":8},{"critere":"Le drap","points":5},{"critere":"Organisation de métier : règles, qualité, apprentissage","points":7}],"dureeMin":7,"corrige":"1. **Progrès agricoles** (surplus qui nourrissent des non-paysans), **croissance de la population** (elle double entre 1000 et 1300) et **reprise du commerce**.\n\n2. Les villes flamandes vivent du **drap**.\n\n3. Une **corporation** (ou guilde) est une organisation de métier qui fixe les **règles**, la **qualité**, les **prix** et l’**apprentissage**."}$exo$::jsonb),
  ('00b22604-2e14-50cd-827d-fe2754d38f5e'::uuid, 2, 'redaction', $exo${"titre":"L’air de la ville rend libre","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Récit (texte écrit pour l’exercice).**\n> « Un jeune serf a quitté le domaine de son seigneur pour s’installer dans une ville de Flandre. Il y travaille comme apprenti. Un an et un jour plus tard, son seigneur vient le réclamer. Mais les échevins refusent : la charte de la ville protège ses habitants. »\n\n1. Que signifie la phrase « L’air de la ville rend libre » ? Comment le texte l’illustre-t-il ?\n2. Qu’est-ce qu’une charte de franchises ? Quels droits donne-t-elle ?\n3. Quelles sont les trois étapes d’un artisan dans une corporation ?","bareme":[{"critere":"Serf qui vit un an et un jour en ville sans être réclamé devient libre","points":7},{"critere":"Charte : droit de s’administrer, de rendre la justice, de lever des impôts","points":7},{"critere":"Apprenti, compagnon, maître","points":6}],"dureeMin":10,"corrige":"1. Un **serf** qui vivait **un an et un jour** en ville sans être réclamé devenait **libre**. Ici, le serf est installé depuis un an et un jour et le seigneur ne peut plus le récupérer.\n\n2. Une **charte de franchises** donne à la ville le droit de **s’administrer**, de rendre la **justice** et de lever des **impôts**. Elle élit des **échevins** ou des **consuls**.\n\n3. **Apprenti**, puis **compagnon**, puis **maître**."}$exo$::jsonb),
  ('00b22604-2e14-50cd-827d-fe2754d38f5e'::uuid, 3, 'redaction', $exo${"titre":"La ville, un statut nouveau","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Description d’une ville (texte écrit pour l’exercice).**\n> « Autour de la ville, des remparts. Dans les rues étroites, des maisons à colombages, une place du marché, un beffroi. Les drapiers riches siègent au conseil ; les artisans se plaignent de leurs décisions. Des étudiants venus de loin y étudient le droit. Pourtant, les incendies et les maladies frappent souvent. »\n\n1. Relève quatre éléments du paysage urbain.\n2. Quels groupes sociaux distingue-t-on ? Où se trouve une tension sociale dans le texte ?\n3. Cite deux lieux d’universités et deux disciplines enseignées.\n4. Rédige un paragraphe pour expliquer pourquoi la ville médiévale attire malgré ses dangers, et en quoi elle est « un statut ».","bareme":[{"critere":"Quatre éléments : remparts, rues étroites, maisons à colombages, place du marché, beffroi","points":4},{"critere":"Bourgeois riches (drapiers), artisans ; tension riches marchands contre artisans","points":4},{"critere":"Deux universités (Bologne, Paris, Oxford) et deux disciplines (droit, médecine, théologie)","points":4},{"critere":"Paragraphe : commerce, liberté, chartes, air de la ville rend libre ; danger mais attirance","points":8}],"dureeMin":15,"corrige":"1. Quatre au choix : **remparts**, **rues étroites**, **maisons à colombages**, **place du marché**, **beffroi** (ou halle), cathédrale.\n\n2. Les **bourgeois** (drapiers riches qui dominent la vie politique), les **artisans** dans les **corporations**, et les universitaires. La tension : **riches marchands contre artisans** (comme maîtres contre compagnons ou ville contre seigneur).\n\n3. **Bologne**, **Paris**, **Oxford** (deux au choix) ; disciplines : **droit** (juristes), **médecine**, **théologie**.\n\n4. Paragraphe attendu : la ville est **sale, dense, exposée aux incendies et aux épidémies**, mais elle attire pour le **commerce**, le travail et surtout la **liberté** : chartes de franchises, « l’air de la ville rend libre ». C’est un **statut** : y habiter change ce qu’on est."}$exo$::jsonb),
  ('b1d4380b-2584-56a7-a9d1-4656989540e2'::uuid, 1, 'redaction', $exo${"titre":"Les repères capétiens","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. En quelle année Hugues Capet est-il élu roi ?\n2. Où les rois de France sont-ils sacrés ?\n3. Quelles sont les dates de la guerre de Cent Ans ?","bareme":[{"critere":"987","points":6},{"critere":"Reims","points":6},{"critere":"1337-1453","points":8}],"dureeMin":5,"corrige":"1. En **987** : Hugues Capet est élu roi des Francs, à la tête d’un domaine réduit à une bande de terre autour de Paris.\n\n2. À **Reims** : le sacre y fait du roi un oint de Dieu, roi par la grâce de Dieu.\n\n3. La guerre de Cent Ans dure de **1337 à 1453**, soit 116 ans, entre les Valois et le roi d’Angleterre qui revendique la couronne."}$exo$::jsonb),
  ('b1d4380b-2584-56a7-a9d1-4656989540e2'::uuid, 2, 'redaction', $exo${"titre":"Un roi qui bâtit un État","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Portrait d’un roi (texte écrit pour l’exercice, d’après le cours).**\n> « Ce roi rend la justice sous un chêne et impose la monnaie royale. Il envoie dans le nord du royaume des agents qui rendent la justice et lèvent l’impôt en son nom. »\n\n1. Quel roi est décrit ? Donne les dates de son règne.\n2. Comment s’appellent les agents royaux du nord du royaume ? Et ceux du sud ?\n3. Cite deux autres institutions ou éléments de l’État royal en construction.","bareme":[{"critere":"Saint Louis, 1226-1270","points":6},{"critere":"Baillis (nord), sénéchaux (sud)","points":7},{"critere":"Deux éléments justes (Parlement, Chambre des comptes, impôt permanent, armée permanente)","points":7}],"dureeMin":10,"corrige":"1. **Saint Louis** (**1226-1270**).\n\n2. Les **baillis** au nord, les **sénéchaux** au sud.\n\n3. Deux au choix : le **Parlement**, la **Chambre des comptes**, l’**impôt** permanent, l’**armée** permanente."}$exo$::jsonb),
  ('b1d4380b-2584-56a7-a9d1-4656989540e2'::uuid, 3, 'redaction', $exo${"titre":"De Hugues Capet à Charles VII","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Frise (écrite pour l’exercice).**\n> 987 : Hugues Capet, élu roi · 1180-1223 : Philippe Auguste · 1214 : Bouvines · 1285-1314 : Philippe le Bel, États généraux en 1302 · 1337-1453 : guerre de Cent Ans · 1429 : Jeanne d’Arc à Reims\n\n1. Pourquoi peut-on dire qu’Hugues Capet n’est d’abord qu’un seigneur parmi d’autres ? Donne un exemple de vassal plus puissant que lui.\n2. Cite les quatre moyens par lesquels les rois affirment leur pouvoir.\n3. Que fait Philippe le Bel ? Que sont les États généraux ?\n4. Rédige un paragraphe : comment la guerre de Cent Ans, malgré les défaites, renforce-t-elle l’État royal ?","bareme":[{"critere":"Roi faible : duc de Normandie ou comte de Flandre plus puissants","points":4},{"critere":"Hérédité, sacre, agrandissement du domaine, construction d’un État","points":4},{"critere":"Philippe le Bel : conflit avec le pape, États généraux 1302, légistes ; États généraux : réunion convoquée par le roi","points":4},{"critere":"Paragraphe : armée et impôt permanents, sentiment national naissant, Jeanne d’Arc","points":8}],"dureeMin":15,"corrige":"1. Plusieurs vassaux d’Hugues Capet, le **duc de Normandie** ou le **comte de Flandre**, sont **bien plus puissants que lui** : il n’est d’abord qu’un seigneur parmi d’autres.\n\n2. L’**hérédité**, le **sacre à Reims**, l’**agrandissement du domaine**, la **construction d’un État**.\n\n3. **Philippe le Bel** s’oppose au **pape**, réunit les premiers **États généraux** en **1302** et s’entoure de **légistes**. Les États généraux sont une assemblée réunie par le roi.\n\n4. Paragraphe attendu : après les défaites de **Crécy** et d’**Azincourt**, le sursaut porté par **Jeanne d’Arc** (le sacre de Charles VII à Reims en **1429**) chasse les Anglais en **1453**. Le royaume en sort avec une **armée permanente**, un **impôt permanent** et un **sentiment national** naissant : l’État moderne est en place."}$exo$::jsonb),
  ('b87941ad-849e-5b72-92c4-bb5492270bcc'::uuid, 1, 'redaction', $exo${"titre":"Les repères des grandes découvertes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quel navigateur atteint l’Amérique en 1492 ? Que cherchait-il ?\n2. Quel navigateur atteint l’Inde par la mer en 1498 ?\n3. Que fait le traité de Tordesillas en 1494 ?","bareme":[{"critere":"Christophe Colomb, cherchait les Indes","points":7},{"critere":"Vasco de Gama","points":5},{"critere":"Partage du monde à découvrir entre le Portugal et l’Espagne","points":8}],"dureeMin":7,"corrige":"1. **Christophe Colomb** atteint l’Amérique en **1492** en cherchant les **Indes**.\n\n2. **Vasco de Gama** en **1498**.\n\n3. Le traité de **Tordesillas** (**1494**) **partage le monde à découvrir** entre le **Portugal** et l’**Espagne**."}$exo$::jsonb),
  ('b87941ad-849e-5b72-92c4-bb5492270bcc'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi partir, comment partir","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Mémoire d’un armateur (texte écrit pour l’exercice).**\n> « Depuis que Constantinople est tombée aux mains des Turcs, les routes vers l’Asie sont plus difficiles. Nous voulons aller chercher directement les épices et l’or. Nos nouveaux navires, les caravelles, sont plus rapides. Le pilote se guide avec la boussole et l’astrolabe. »\n\n1. Quel événement de 1453 est ici évoqué ? Quelle en est la conséquence ?\n2. Cite trois innovations techniques mentionnées dans le texte ou dans le cours.\n3. Quelle rivalité politique pousse aussi à partir ?","bareme":[{"critere":"Prise de Constantinople (1453) gêne les routes terrestres vers l’Asie","points":7},{"critere":"Trois innovations (caravelle, boussole, astrolabe, portulan, gouvernail d’étambot)","points":7},{"critere":"Rivalité Portugal-Espagne","points":6}],"dureeMin":10,"corrige":"1. La **prise de Constantinople** par les Ottomans en **1453** gêne les routes terrestres vers l’Asie : on veut atteindre directement les **épices**, la **soie** et l’**or**.\n\n2. **Caravelle**, **boussole**, **astrolabe** (aussi portulan, gouvernail d’étambot).\n\n3. La rivalité entre le **Portugal** et l’**Espagne**."}$exo$::jsonb),
  ('b87941ad-849e-5b72-92c4-bb5492270bcc'::uuid, 3, 'redaction', $exo${"titre":"La rencontre de deux mondes","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Témoignage (texte écrit pour l’exercice).**\n> « Nous étions peu nombreux, quelques centaines d’hommes avec des chevaux et des armes à feu. Des peuples soumis à l’empire se sont alliés à nous. Mais ce sont surtout des maladies venues d’Europe qui ont vidé les villages. »\n\n1. Quel conquistador et quel empire ce texte peut-il évoquer ? Donne la date de la chute de cet empire.\n2. Explique les trois causes de la victoire des conquistadors.\n3. Cite trois conséquences des grandes découvertes en Europe ou en Amérique.\n4. Rédige un paragraphe pour expliquer pourquoi le mot « découverte » est un mot européen.","bareme":[{"critere":"Cortés, empire aztèque, 1521 (ou Pizarro, Incas, 1533)","points":4},{"critere":"Armes à feu et chevaux, alliances, maladies","points":5},{"critere":"Trois conséquences (effondrement amérindien, traite atlantique, échange colombien, afflux d’or et d’argent, Atlantique)","points":5},{"critere":"Paragraphe : terres habitées et organisées depuis des millénaires","points":6}],"dureeMin":15,"corrige":"1. **Cortés** et l’empire **aztèque**, au Mexique, en **1521** (ou **Pizarro** et l’empire **inca** au Pérou en **1533**).\n\n2. **Armes à feu et chevaux**, **alliances** avec des peuples soumis, et surtout les **maladies** (variole, rougeole) contre lesquelles ces populations n’avaient aucune immunité.\n\n3. Trois au choix : **effondrement démographique** amérindien (peut-être **80 à 90 %** en un siècle), **traite atlantique**, **échange colombien** (maïs, pomme de terre, tomate ; blé, canne à sucre, chevaux), **afflux d’or et d’argent** (Potosí), déplacement du centre de gravité vers l’**Atlantique**.\n\n4. Paragraphe attendu : ces terres étaient **habitées, peuplées et organisées** depuis des millénaires : ce que les Européens appellent une « découverte » est pour ceux qui y vivaient une **invasion**. Le mot montre le point de vue européen."}$exo$::jsonb),
  ('36e2f416-291a-5fc1-a50d-9c3639acc046'::uuid, 1, 'redaction', $exo${"titre":"Deux souverains","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. En quelle année Charles Quint est-il élu empereur ?\n2. Quel est le sultan ottoman qui porte l’empire à son apogée au XVIe siècle ?\n3. Quelle ville Soliman assiège-t-il en 1529 ?","bareme":[{"critere":"1519","points":7},{"critere":"Soliman le Magnifique","points":7},{"critere":"Vienne","points":6}],"dureeMin":5,"corrige":"1. En **1519** : Charles Quint, déjà maître de l’Espagne, des Pays-Bas et des terres autrichiennes des Habsbourg, est élu empereur.\n\n2. **Soliman le Magnifique** (sultan de 1520 à 1566), qui porte l’empire ottoman à son apogée.\n\n3. **Vienne**, en **1529** : il l’assiège sans la prendre."}$exo$::jsonb),
  ('36e2f416-291a-5fc1-a50d-9c3639acc046'::uuid, 2, 'redaction', $exo${"titre":"Un empire où le soleil ne se couche jamais","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Carte décrite (texte écrit pour l’exercice).**\n> « Sur la carte, on repère les possessions de Charles Quint : l’Espagne, l’Italie du sud, les Pays-Bas, la Franche-Comté, les terres des Habsbourg en Autriche, et de l’autre côté de l’Atlantique, l’Amérique espagnole. »\n\n1. Explique comment Charles Quint a réuni tous ces territoires.\n2. Quels sont ses trois adversaires ou difficultés ?\n3. Que fait-il en 1556 ?","bareme":[{"critere":"Série d’héritages","points":6},{"critere":"France de François Ier, Réforme protestante, Ottomans","points":8},{"critere":"Il abdique et partage : Philippe II (Espagne), Ferdinand (Autriche)","points":6}],"dureeMin":10,"corrige":"1. Par une **série d’héritages**.\n\n2. La **France de François Ier** (Marignan, Pavie), la **Réforme protestante** qui déchire l’Allemagne, les **Ottomans** qui le menacent à l’est.\n\n3. En **1556**, épuisé, il **abdique** et partage son empire entre son fils **Philippe II** (Espagne) et son frère **Ferdinand** (Autriche)."}$exo$::jsonb),
  ('36e2f416-291a-5fc1-a50d-9c3639acc046'::uuid, 3, 'redaction', $exo${"titre":"Un roi très chrétien et un sultan","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Lettre imaginée (texte écrit pour l’exercice).**\n> « Nous savons que le roi de France, tout chrétien qu’il soit, s’entend avec le sultan des Turcs contre l’empereur. On s’en scandalise partout. Mais le roi répond qu’il faut desserrer l’étau qui l’enserre. »\n\n1. Quel roi de France et quel sultan sont concernés ? Contre qui s’allient-ils ?\n2. Pourquoi cette alliance scandalise-t-elle ? Que montre-t-elle sur les relations entre États ?\n3. Comment Soliman est-il appelé en Occident et en turc ? Que signifie chaque surnom ?\n4. Rédige un paragraphe comparant les deux empires « universels » : étendue, difficultés, fin ou apogée.","bareme":[{"critere":"François Ier et Soliman contre Charles Quint","points":4},{"critere":"Scandale : alliance chrétien-musulman ; la politique l’emporte sur la religion","points":5},{"critere":"Le Magnifique (splendeur) ; Kanuni, législateur (droit)","points":4},{"critere":"Paragraphe comparatif : Charles Quint divisé et abdique ; Soliman à son apogée","points":7}],"dureeMin":15,"corrige":"1. **François Ier** et **Soliman le Magnifique** s’allient contre **Charles Quint**.\n\n2. Une alliance entre un roi « très chrétien » et un sultan musulman **scandalise** l’Europe : elle montre que la **politique** l’emporte sur la **religion**.\n\n3. En Occident, **« le Magnifique »** (sa splendeur) ; en turc, **Kanuni**, **« le législateur »**, car il réorganise le **droit** de l’empire.\n\n4. Paragraphe attendu : **Charles Quint** règne sur l’Espagne, les Pays-Bas, l’Autriche, l’Empire et l’Amérique, mais il est **épuisé** par la France, la Réforme et les Ottomans, et **abdique en 1556**. **Soliman** porte l’empire ottoman à son **apogée** (Balkans, Hongrie, Égypte, Syrie, Irak, Afrique du Nord, lieux saints) ; Istanbul devient magnifique (Sinan). Lépante (1571) arrête ensuite l’expansion ottomane en Méditerranée occidentale."}$exo$::jsonb),
  ('af955002-5f19-5321-a3ad-46abccf42a43'::uuid, 1, 'redaction', $exo${"titre":"Définir l’humanisme","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu’est-ce que l’humanisme ? Dans quel pays naît-il ?\n2. Qui met au point l’imprimerie à caractères mobiles vers 1450 ?\n3. Que prône Copernic en 1543 ?","bareme":[{"critere":"Mouvement plaçant l’être humain et sa raison au centre, sans rompre avec la foi ; Italie","points":8},{"critere":"Gutenberg","points":6},{"critere":"La Terre tourne autour du Soleil (héliocentrisme)","points":6}],"dureeMin":7,"corrige":"1. L’**humanisme** est un mouvement intellectuel qui place l’**être humain** et sa **raison** au centre, **sans rompre avec la foi**. Il naît en **Italie** au XVe siècle.\n\n2. **Gutenberg**, à Mayence.\n\n3. Que la **Terre tourne autour du Soleil** : c’est l’**héliocentrisme**."}$exo$::jsonb),
  ('af955002-5f19-5321-a3ad-46abccf42a43'::uuid, 2, 'redaction', $exo${"titre":"L’imprimerie change tout","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Constat (texte écrit pour l’exercice, d’après le cours).**\n> « Avant l’imprimerie, un livre copié à la main coûtait très cher. Après, on en produit par centaines, et il en circule plus de vingt millions en Europe avant 1500. »\n\n1. Quelles sont les quatre conséquences de l’imprimerie ?\n2. Pourquoi l’Église perd-elle le contrôle de la diffusion des textes ?\n3. Pourquoi cela pèsera-t-il lourd pendant la Réforme ?","bareme":[{"critere":"Prix du livre baisse, circulation des idées, alphabétisation, contrôle de l’Église échappe","points":8},{"critere":"Impossible de surveiller ce que les gens lisent","points":6},{"critere":"Idées de la Réforme diffusées vite","points":6}],"dureeMin":10,"corrige":"1. Le **prix** du livre s’effondre ; les idées **circulent** vite et loin ; l’**alphabétisation** progresse ; le **contrôle** de l’Église lui échappe.\n\n2. Aucun pouvoir ne peut plus **surveiller ce que les gens lisent** : les livres sont trop nombreux et circulent partout.\n\n3. Les idées des réformateurs (Luther, sa Bible traduite) se **diffusent très vite** par l’imprimé, ce qui pèsera lourd pendant la **Réforme**."}$exo$::jsonb),
  ('af955002-5f19-5321-a3ad-46abccf42a43'::uuid, 3, 'redaction', $exo${"titre":"Érasme, un humaniste","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Fiche biographique (texte écrit pour l’exercice, d’après le cours).**\n> « Érasme de Rotterdam est surnommé le prince des humanistes. Il publie le Nouveau Testament en grec et écrit L’Éloge de la folie. Il croit à l’éducation et pense qu’on ne naît pas homme accompli, on le devient. »\n\n1. Quels sont les quatre principes de l’humanisme ? Illustre-en deux avec la fiche d’Érasme.\n2. Cite deux autres humanistes et leur œuvre ou leur rôle.\n3. Comment les mécènes ont-ils favorisé la Renaissance artistique ? Donne deux exemples de mécènes.\n4. Rédige un paragraphe : pourquoi peut-on dire que l’humanisme ne rompt pas avec la foi ?","bareme":[{"critere":"Quatre principes (retour aux textes antiques, critique des sources, éducation, curiosité universelle) ; deux illustrations","points":5},{"critere":"Deux autres humanistes justes (More Utopie, Rabelais, Montaigne, Budé, Léonard de Vinci)","points":3},{"critere":"Mécènes financent les artistes : Médicis, papes, François Ier","points":4},{"critere":"Paragraphe : Érasme publie le Nouveau Testament en grec, retour aux textes sacrés, raison et foi","points":8}],"dureeMin":15,"corrige":"1. Principes : **retourner aux textes antiques** dans leur langue d’origine, **critiquer** les sources, croire en l’**éducation**, s’intéresser à **tout**. Avec Érasme : le **Nouveau Testament en grec** (retour aux textes) ; « on ne naît pas homme accompli, on le devient » (éducation).\n\n2. Au choix : **Thomas More**, *Utopie* ; **Rabelais**, **Montaigne**, **Guillaume Budé** en France ; **Léonard de Vinci**, l’« homme universel ».\n\n3. Les **mécènes** financent les artistes : les **Médicis** à Florence, les **papes** à Rome, **François Ier** en France.\n\n4. Paragraphe attendu : l’humanisme place l’homme et sa raison au centre **sans rompre avec la foi**. Érasme publie le **Nouveau Testament en grec** pour revenir aux textes sacrés eux-mêmes et les critiquer : il veut mieux comprendre la foi chrétienne, pas la rejeter."}$exo$::jsonb),
  ('445027f4-5377-5bdc-9603-a8f5af992480'::uuid, 1, 'redaction', $exo${"titre":"Luther et Calvin","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Que dénonce Luther en 1517 dans ses 95 thèses ?\n2. Selon Luther, quelle est la seule autorité en matière de foi ?\n3. Dans quelle ville Calvin développe-t-il sa doctrine ? Qu’est-ce que la prédestination ?","bareme":[{"critere":"Le commerce des indulgences","points":5},{"critere":"La Bible","points":5},{"critere":"Genève ; Dieu a choisi d’avance ceux qui seront sauvés","points":10}],"dureeMin":7,"corrige":"1. Le **commerce des indulgences** : la remise des peines contre de l’argent. Luther les dénonce dans ses **95 thèses**, en **1517**.\n\n2. La **Bible** seule : Luther la traduit en allemand pour que tous la lisent.\n\n3. À **Genève**, où Jean Calvin est réfugié. La **prédestination** : Dieu a **choisi d’avance** ceux qui seront sauvés."}$exo$::jsonb),
  ('445027f4-5377-5bdc-9603-a8f5af992480'::uuid, 2, 'redaction', $exo${"titre":"La Saint-Barthélemy à l’édit de Nantes","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Frise (écrite pour l’exercice, d’après le cours).**\n> 1562 : début des guerres de Religion · 1572 : massacre de la Saint-Barthélemy · 1589 : Henri IV roi · 1593 : il se convertit · 1598 : édit de Nantes\n\n1. Quels sont les deux camps des guerres de Religion en France ? Comment appelle-t-on les protestants français ?\n2. Que se passe-t-il en 1572 ?\n3. Que fait Henri IV en 1593 ? Pourquoi ?\n4. Que garantit l’édit de Nantes ? Pourquoi n’est-ce pas la tolérance moderne ?","bareme":[{"critere":"Catholiques et protestants ; huguenots","points":5},{"critere":"Massacre de milliers de protestants à Paris et en province","points":5},{"critere":"Il se convertit au catholicisme pour pacifier le royaume","points":5},{"critere":"Liberté de conscience, culte encadré, places de sûreté ; coexistence pour arrêter la guerre, pas tolérance moderne","points":5}],"dureeMin":10,"corrige":"1. **Catholiques** et **protestants** (les **huguenots**).\n\n2. En **1572**, le massacre de la **Saint-Barthélemy** : des **milliers de protestants** sont tués à Paris et en province.\n\n3. En **1593**, Henri IV, devenu roi en 1589, se **convertit au catholicisme** pour **pacifier le royaume**.\n\n4. L’**édit de Nantes** (**1598**) accorde aux protestants la **liberté de conscience**, un **culte encadré** et des **places de sûreté**. Ce n’est pas la tolérance moderne : il organise une **coexistence** pour arrêter la guerre. Louis XIV le révoquera en 1685."}$exo$::jsonb),
  ('445027f4-5377-5bdc-9603-a8f5af992480'::uuid, 3, 'redaction', $exo${"titre":"Réforme protestante et réaction catholique","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Tableau (écrit pour l’exercice).**\n> | | Luthériens | Calvinistes | Catholiques après Trente |\n> | Autorité | ? | ? | ? |\n> | Culte | ? | ? | ? |\n\n1. Recopie et complète le tableau : dis, pour chaque groupe, ce qu’il affirme (autorité, sacrements ou culte, doctrine principale). Tu peux répondre par une phrase par colonne.\n2. Que réaffirme le concile de Trente (1545-1563) ? Que crée-t-il ?\n3. Quel rôle jouent les jésuites ? À quoi sert l’Index ?\n4. Rédige un paragraphe expliquant comment une critique religieuse devient en quelques années une guerre civile.","bareme":[{"critere":"Luthériens : foi seule, Bible, deux sacrements ; calvinistes : prédestination, culte dépouillé, cité réglée à Genève","points":6},{"critere":"Trente : dogmes réaffirmés, séminaires","points":4},{"critere":"Jésuites : enseignement et missions (Loyola) ; Index : livres interdits","points":4},{"critere":"Paragraphe : indulgences, 1517, imprimerie, princes, Calvin, guerres de Religion en France 1562-1598","points":6}],"dureeMin":15,"corrige":"1. **Luthériens** : le salut par la **foi seule**, la **Bible** comme seule autorité, seulement **deux sacrements** (baptême et eucharistie), mariage des pasteurs. **Calvinistes** : la **prédestination**, un **culte dépouillé**, une cité strictement réglée à **Genève**. **Catholiques** : le **concile de Trente** réaffirme les dogmes.\n\n2. Le concile de Trente (**1545-1563**) **réaffirme les dogmes** et crée les **séminaires**.\n\n3. Les **jésuites**, fondés par **Ignace de Loyola**, se consacrent à l’**enseignement** et aux **missions**. L’**Index** liste les **livres interdits**.\n\n4. Paragraphe attendu : la critique des **indulgences** (95 thèses de 1517) se propage grâce à l’**imprimerie** ; Luther est protégé par des **princes** allemands ; Calvin gagne la France, l’Écosse, les Pays-Bas ; en France, le conflit devient les **guerres de Religion** (**1562-1598**), avec la Saint-Barthélemy (1572), jusqu’à l’édit de Nantes."}$exo$::jsonb),
  ('a2ec4edc-e919-54ad-be52-a5e38bcf152e'::uuid, 1, 'redaction', $exo${"titre":"Définir la monarchie absolue","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu’est-ce que la monarchie absolue ?\n2. En quelle année Louis XIV décide-t-il de gouverner seul ?\n3. Que signifie « absolu » ? Le roi peut-il tout faire ?","bareme":[{"critere":"Roi détient tous les pouvoirs, sans comptes à rendre sinon à Dieu (droit divin)","points":8},{"critere":"1661","points":5},{"critere":"Absolu ne veut pas dire arbitraire : lois fondamentales et coutumes","points":7}],"dureeMin":7,"corrige":"1. Un régime où le roi détient **tous les pouvoirs** (législatif, exécutif, judiciaire), sans comptes à rendre sinon à **Dieu** : c’est le **droit divin**.\n\n2. En **1661**, à la mort de Mazarin.\n\n3. **Absolu ne signifie pas arbitraire** : le roi est tenu par les **lois fondamentales** du royaume et par les coutumes. Il ne peut ni changer l’ordre de succession, ni aliéner le domaine royal."}$exo$::jsonb),
  ('a2ec4edc-e919-54ad-be52-a5e38bcf152e'::uuid, 2, 'redaction', $exo${"titre":"Versailles, outil du roi","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur ton cours.","enonce":"> **Document — Récit imaginé (texte écrit pour l’exercice).**\n> « À Versailles, les grands seigneurs se pressent chaque matin autour du roi pour l’aider à s’habiller, obéissent à des règles strictes de préséance et se disputent une faveur. Ils n’ont plus le temps de comploter. Le roi se fait appeler le Roi-Soleil ; des artistes chantent sa gloire. »\n\n1. À quoi sert l’étiquette de Versailles ?\n2. Que signifie « Roi-Soleil » ? Comment l’image du roi est-elle fabriquée ?\n3. Qui est Colbert ? Quelle politique économique met-il en œuvre ?","bareme":[{"critere":"Étiquette : domestiquer la noblesse en l’occupant à la cour","points":7},{"critere":"Roi-Soleil : image, portraits, fêtes, académies, artistes pensionnés","points":6},{"critere":"Colbert, mercantilisme : manufactures royales, marine, colonies, protectionnisme","points":7}],"dureeMin":10,"corrige":"1. L’**étiquette** sert à **domestiquer la noblesse** en l’occupant à la cour, loin de ses terres, au lieu de comploter (souvenir de la **Fronde**).\n\n2. Le **Roi-Soleil** est l’**image** du roi au centre du royaume : **portraits**, **fêtes**, **académies**, **artistes pensionnés**.\n\n3. **Colbert**, ministre de Louis XIV, met en œuvre le **mercantilisme** : **manufactures royales**, **marine**, **colonies**, **protectionnisme**."}$exo$::jsonb),
  ('a2ec4edc-e919-54ad-be52-a5e38bcf152e'::uuid, 3, 'redaction', $exo${"titre":"Un règne brillant, un bilan lourd","consigne":"Rédige des réponses complètes et argumentées, en t’appuyant sur le document et sur tes connaissances.","enonce":"> **Document — Bilan (texte écrit pour l’exercice, d’après le cours).**\n> « Louis XIV règne en personne pendant cinquante-quatre ans. Il révoque l’édit de Nantes en 1685. Ses guerres sont incessantes et coûteuses ; des famines frappent le royaume en 1693 et en 1709. À sa mort, le royaume est affaibli. »\n\n1. De quelle année à quelle année dure le règne personnel de Louis XIV ? Vérifie le chiffre de cinquante-quatre ans.\n2. Que fait la révocation de l’édit de Nantes ? Pourquoi est-ce un désastre économique autant qu’humain ?\n3. Cite deux instruments du pouvoir de Louis XIV autres que la révocation.\n4. Rédige un paragraphe : ce roi a-t-il réussi ? Montre les réussites et les limites de la monarchie absolue.","bareme":[{"critere":"1661-1715 : 1715 − 1661 = 54","points":3},{"critere":"Révocation en 1685 : des dizaines de milliers de protestants quittent le royaume, souvent artisans et commerçants qualifiés","points":5},{"critere":"Deux instruments justes (Versailles, image du roi, Colbert, armée permanente, Vauban)","points":4},{"critere":"Paragraphe nuancé : puissance et modèle imité en Europe, mais guerres, famines, finances épuisées","points":8}],"dureeMin":15,"corrige":"1. Le règne personnel va de **1661** à la mort du roi en **1715** : 1715 − 1661 = **54 ans**, le plus long de l’histoire de France.\n\n2. La **révocation de l’édit de Nantes** (**1685**) interdit le protestantisme et chasse du royaume des **dizaines de milliers de protestants**, souvent des **artisans et commerçants qualifiés** : c’est un désastre **économique** autant qu’**humain**.\n\n3. Deux au choix : **Versailles et l’étiquette**, l’**image du Roi-Soleil**, **Colbert** et le mercantilisme, l’**armée permanente** et **Vauban**.\n\n4. Paragraphe attendu, nuancé : **réussites** : pouvoir concentré, noblesse domestiquée, armée forte, modèle absolutiste imité dans toute l’Europe. **Limites** : guerres incessantes et coûteuses, famines de **1693** et **1709**, finances épuisées, contestations ; à sa mort le royaume est **affaibli**."}$exo$::jsonb),
  ('13f44ff5-7e98-4c4b-b011-7489878011c5'::uuid, 1, 'traduction', $exo${"titre":"Les cas et la fonction","consigne":"Réponds en français.","enonce":"**A.** Associe chaque cas à sa fonction : nominatif, accusatif, génitif, datif, ablatif ; fonctions : COD · complément du nom (de) · sujet · compléments circonstanciels (avec, par, dans) · COI (à, pour).\n\n**B.** Dans *Video rosam* (« je vois la rose »), à quel cas est *rosam* ? Pourquoi ?","bareme":[{"critere":"Cinq cas associés à la bonne fonction (nominatif sujet, accusatif COD, génitif complément du nom, datif COI, ablatif circonstanciels)","points":10},{"critere":"Rosam identifié à l'accusatif","points":5},{"critere":"Justification : c'est le COD de video, la terminaison -am l'indique","points":5}],"dureeMin":6,"corrige":"**A.** Nominatif = **sujet** ; accusatif = **COD** ; génitif = **complément du nom** (idée de « de ») ; datif = **COI** (« à, pour ») ; ablatif = **compléments circonstanciels** (« avec, par, dans »).\n\n**B.** *Rosam* est à l'**accusatif** : c'est le complément d'objet direct du verbe *video* (« je vois quoi ? la rose »), et la terminaison **-am** l'indique."}$exo$::jsonb),
  ('13f44ff5-7e98-4c4b-b011-7489878011c5'::uuid, 2, 'traduction', $exo${"titre":"Une langue à terminaisons","consigne":"Réponds en français ; complète le tableau demandé.","enonce":"**A.** Voici deux phrases latines.\n\n> *Puella rosam amat.*\n> *Rosam puella amat.*\n\n1. Traduis-les en français (*puella* = la jeune fille ; *amat* = elle aime).\n2. Quel est le sujet ? le COD ? Comment le sais-tu ?\n3. Pourquoi ces deux phrases ont-elles le même sens ?\n\n**B.** Décline *rosa* : donne le génitif singulier, le génitif pluriel, l'accusatif pluriel, et le nominatif pluriel.","bareme":[{"critere":"Traduction juste des deux phrases : la jeune fille aime la rose","points":4},{"critere":"Sujet (puella) et COD (rosam) identifiés grâce aux terminaisons","points":5},{"critere":"Explication : c'est la terminaison, non la place, qui indique la fonction","points":4},{"critere":"Quatre formes justes : rosae, rosarum, rosas, rosae","points":7}],"dureeMin":10,"corrige":"**A.**\n1. Les deux phrases signifient : *La jeune fille aime la rose.*\n2. *Puella* est le **sujet** (nominatif, terminaison -a) ; *rosam* est le **COD** (accusatif, terminaison -am).\n3. En latin, c'est la **terminaison** de chaque mot, et non sa place, qui indique sa fonction. On peut donc changer l'ordre des mots sans changer le sens.\n\n**B.** Génitif singulier : *rosae* ; génitif pluriel : *rosarum* ; accusatif pluriel : *rosas* ; nominatif pluriel : *rosae*."}$exo$::jsonb),
  ('13f44ff5-7e98-4c4b-b011-7489878011c5'::uuid, 3, 'traduction', $exo${"titre":"Décliner à partir du dictionnaire","consigne":"Réponds en français ; les formes latines doivent être complètes.","enonce":"Dans un dictionnaire, on lit : *puella, ae, f.* (la jeune fille).\n\n1. Que signifient les trois indications *puella*, *ae* et *f.* ?\n2. Comment trouve-t-on le radical ? Donne le radical de *puella*.\n3. Donne le nominatif pluriel, l'accusatif singulier et le génitif pluriel de *puella*.\n4. Traduis *color rosae*, *video rosas* et *puellae rosam amant* (*amant* = elles aiment). Dans la dernière phrase, à quel cas est *puellae* ? Justifie.\n5. Explique la différence entre le français et le latin pour indiquer la fonction d'un mot.","bareme":[{"critere":"Lecture du dictionnaire : nominatif, génitif, genre féminin","points":3},{"critere":"Radical puell- trouvé en retirant -ae du génitif","points":3},{"critere":"Trois formes justes : puellae, puellam, puellarum","points":5},{"critere":"Traductions justes : la couleur de la rose ; je vois les roses ; puellae sujet pluriel (les jeunes filles aiment la rose)","points":5},{"critere":"Différence français (place) et latin (terminaison) expliquée","points":4}],"dureeMin":15,"corrige":"1. *puella* est le **nominatif** singulier, *ae* la terminaison du **génitif** singulier, *f.* indique le genre **féminin**.\n2. On enlève **-ae** du génitif : le radical de *puella* est **puell-**.\n3. Nominatif pluriel : *puellae* ; accusatif singulier : *puellam* ; génitif pluriel : *puellarum*.\n4. *Color rosae* = « la couleur de la rose » (génitif, complément du nom) ; *video rosas* = « je vois les roses » (accusatif pluriel, COD). *Puellae rosam amant* : *puellae* est au **nominatif pluriel** (sujet), car *amant* est à la 3e personne du pluriel ; on traduit « les jeunes filles aiment la rose ».\n5. En français, la fonction d'un mot dépend surtout de sa **place** dans la phrase. En latin, elle dépend de sa **terminaison** (le cas) : on décline les mots."}$exo$::jsonb),
  ('ad4e7917-78ed-4bac-8f1b-c34826845bb5'::uuid, 1, 'traduction', $exo${"titre":"La maison romaine","consigne":"Réponds en français.","enonce":"**A.** Donne le nom latin de :\n\n1. la grande maison d'une riche famille ;\n2. l'immeuble où s'entasse le peuple ;\n3. la pièce centrale de la maison, ouverte sur le toit ;\n4. la salle à manger.\n\n**B.** Cite dans l'ordre les trois repas de la journée d'un Romain, et dis lequel est le plus important.","bareme":[{"critere":"Quatre noms justes : domus, insula, atrium, triclinium","points":8},{"critere":"Trois repas cités dans l'ordre : ientaculum, prandium, cena","points":8},{"critere":"Cena identifiée comme le repas le plus important (le soir)","points":4}],"dureeMin":7,"corrige":"**A.** 1. la **domus** ; 2. l'**insula** (pluriel *insulae*) ; 3. l'**atrium**, avec le *compluvium* (ouverture du toit) et l'*impluvium* (bassin qui recueille l'eau de pluie) ; 4. le **triclinium**.\n\n**B.** Le **ientaculum** (petit-déjeuner léger, au lever), le **prandium** (déjeuner rapide, vers midi), la **cena** (grand repas du soir). La **cena** est le plus important."}$exo$::jsonb),
  ('ad4e7917-78ed-4bac-8f1b-c34826845bb5'::uuid, 2, 'traduction', $exo${"titre":"Une journée de Marcus","consigne":"Réponds en phrases complètes, en t'appuyant sur le texte et sur ton cours.","enonce":"*Texte écrit pour l'exercice.*\n\n> Marcus est un citoyen romain qui habite une domus. Il se lève tôt et salue ses protecteurs. Il se rend au forum pour ses affaires, prend un déjeuner rapide, puis va aux thermes. Le soir, il s'allonge dans le triclinium pour le grand repas, servi par des esclaves.\n\n1. Quel vêtement porte Marcus sur sa tunique pour montrer qu'il est citoyen ? Comment s'appelle-t-il en latin ?\n2. Comment s'appelle le déjeuner rapide ? le grand repas du soir ?\n3. Que fait-on au forum ? aux thermes ?\n4. Pourquoi Marcus est-il « allongé » pour manger ? Quelle particularité des banquets romains cela illustre-t-il ?\n5. Qui dirige la famille de Marcus ? Quel est son rôle ?","bareme":[{"critere":"Toge (toga) indiquée comme vêtement du citoyen, portée sur la tunique","points":4},{"critere":"Prandium et cena nommés justement","points":4},{"critere":"Forum (place publique, affaires) et thermes (bains publics, détente) expliqués","points":4},{"critere":"Convives allongés sur des lits de table autour d'une table basse","points":4},{"critere":"Pater familias : chef tout-puissant sur femme, enfants et esclaves","points":4}],"dureeMin":11,"corrige":"1. Il porte la **toge** (*toga*), longue pièce de laine blanche drapée, signe du citoyen romain, par-dessus la **tunique** (*tunica*).\n2. Le déjeuner rapide est le **prandium** ; le grand repas du soir est la **cena**.\n3. Le **forum** est la grande place publique, cœur de la vie de la cité, où l'on traite ses affaires. Les **thermes** sont les bains publics, où l'on se lave et se détend, souvent l'après-midi.\n4. Lors des banquets, les convives **s'allongent** sur des lits de table autour d'une table basse, dans le triclinium : ils ne mangent pas assis sur des chaises.\n5. La famille est dirigée par le **pater familias**, chef tout-puissant, qui a autorité sur sa femme, ses enfants et ses esclaves."}$exo$::jsonb),
  ('ad4e7917-78ed-4bac-8f1b-c34826845bb5'::uuid, 3, 'traduction', $exo${"titre":"Riches et pauvres à Rome","consigne":"Rédige un paragraphe argumenté d'une dizaine de lignes, avec des exemples du cours.","enonce":"**Sujet.** Décris la vie quotidienne d'une riche famille romaine et compare-la avec celle du peuple.\n\nDans ton paragraphe :\n- décris le logement de chacun (noms latins) ;\n- présente l'organisation de la famille et le rôle des esclaves ;\n- parle des repas et des vêtements ;\n- conclus en une phrase sur les différences.","bareme":[{"critere":"Logements distingués : domus (atrium, tablinum, triclinium) et insulae","points":5},{"critere":"Famille : pater familias, mater familias, esclaves qui font la plupart des tâches","points":5},{"critere":"Repas (ientaculum, prandium, cena, banquet allongé) et vêtements (tunica, toga, stola) corrects","points":5},{"critere":"Paragraphe organisé, avec comparaison et conclusion","points":5}],"dureeMin":18,"corrige":"Éléments attendus : la riche famille habite une **domus**, avec l'**atrium** (compluvium, impluvium), le **tablinum** (bureau du maître) et le **triclinium** ; le peuple s'entasse souvent dans des **insulae**. Le **pater familias** est le chef tout-puissant ; la **mater familias** dirige la maison et l'éducation des jeunes enfants ; les **esclaves** accomplissent la plupart des tâches. Trois repas : **ientaculum**, **prandium**, **cena** (le plus important), pris allongé lors des banquets, avec pain, légumes, olives, poisson, viande et **garum**. La **tunica** est portée par tous ; le citoyen drape la **toga** ; les femmes portent la **stola**. Conclusion : le cadre de vie dépend du statut et de la richesse, mais tous rythment leur journée entre forum, thermes et repas du soir."}$exo$::jsonb),
  ('eaa2e8cd-a6f3-419c-9a21-a4a759ab8830'::uuid, 1, 'traduction', $exo${"titre":"Romulus et Remus","consigne":"Réponds en français par des phrases courtes.","enonce":"1. Qui sont Romulus et Remus ? Qui est leur père, selon la légende ?\n2. Sur quel fleuve sont-ils abandonnés ?\n3. Quel animal les allaite ? Comment dit-on cet animal en latin ?\n4. Qui devient le premier roi de Rome ? Comment ?\n5. En quelle année la tradition situe-t-elle la fondation de Rome ?","bareme":[{"critere":"Jumeaux, fils de Mars et de la princesse Rhéa Silvia (Mars suffit)","points":4},{"critere":"Fleuve nommé : le Tibre","points":3},{"critere":"Louve (lupa)","points":4},{"critere":"Romulus devient roi en tuant son frère Remus, et donne son nom à Rome","points":5},{"critere":"753 avant Jésus-Christ","points":4}],"dureeMin":6,"corrige":"1. Romulus et Remus sont des **frères jumeaux**, fils du dieu de la guerre **Mars** (et de la princesse Rhéa Silvia).\n2. Ils sont abandonnés dans un panier sur le **Tibre**.\n3. Une **louve** (*lupa*) les allaite.\n4. **Romulus** tue son frère **Remus**, devient le premier roi et donne son nom à la ville : *Roma*, Rome.\n5. La tradition fixe la fondation à **753 avant J.-C.**"}$exo$::jsonb),
  ('eaa2e8cd-a6f3-419c-9a21-a4a759ab8830'::uuid, 2, 'traduction', $exo${"titre":"Raconter la fondation","consigne":"Rédige avec tes mots, en phrases complètes.","enonce":"1. Raconte en cinq phrases la légende de la fondation de Rome, de l'abandon des jumeaux à la fondation de la ville.\n2. Que symbolise la louve pour Rome ?\n3. Pourquoi les deux frères se disputent-ils ? Comment finit la dispute ?\n4. Cette légende est-elle un fait prouvé ? Justifie ta réponse.","bareme":[{"critere":"Récit de cinq phrases cohérent : abandon sur le Tibre, louve, fondation, dispute, Romulus roi (753 av. J.-C.)","points":8},{"critere":"Louve = symbole de Rome","points":3},{"critere":"Dispute sur qui régnera ; Romulus tue Remus","points":4},{"critere":"Légende (mythe), non fait prouvé : merveilleux, archéologues","points":5}],"dureeMin":10,"corrige":"1. Exemple : Un roi jaloux fait abandonner les jumeaux Romulus et Remus, fils de Mars, dans un panier sur le Tibre. Une louve les recueille et les allaite, puis un berger les élève. Devenus grands, ils décident de fonder une ville là où ils ont été sauvés. Ils se disputent pour savoir qui régnera. Romulus tue Remus, devient le premier roi et donne son nom à Rome, en 753 av. J.-C.\n2. La louve allaitant les jumeaux est le **symbole de Rome**.\n3. Ils se disputent pour savoir **qui régnera** ; **Romulus tue son frère Remus**.\n4. Non : c'est un **mythe** (une légende). La louve, le dieu Mars et les jumeaux relèvent du récit merveilleux ; les archéologues montrent que Rome est née peu à peu du regroupement de villages sur des collines."}$exo$::jsonb),
  ('eaa2e8cd-a6f3-419c-9a21-a4a759ab8830'::uuid, 3, 'traduction', $exo${"titre":"Mythe ou histoire ?","consigne":"Réponds en français, en justifiant avec des éléments du cours.","enonce":"*Document écrit pour l'exercice.*\n\n> « Les Romains disaient que leur ville avait été fondée par Romulus en 753 avant Jésus-Christ, après que lui et son frère avaient été sauvés par une louve. Mais les fouilles montrent des villages installés sur les collines au bord du Tibre, qui se sont peu à peu rapprochés. »\n\n1. Dans ce texte, relève un élément qui vient de la légende et un élément qui vient des découvertes des archéologues.\n2. Explique la différence entre un mythe et un fait historique prouvé.\n3. Pourquoi, à ton avis, les Romains ont-ils voulu donner à leur ville une origine divine ?\n4. Rédige une conclusion de trois phrases : que retient-on de la naissance de Rome ?","bareme":[{"critere":"Un élément légendaire (louve, Romulus, Mars) et un élément archéologique (villages sur les collines) relevés","points":4},{"critere":"Différence mythe (récit merveilleux) / fait prouvé expliquée","points":5},{"critere":"Origine glorieuse et divine : donner à Rome un passé prestigieux (fils de Mars)","points":5},{"critere":"Conclusion cohérente de trois phrases, avec les deux points de vue","points":6}],"dureeMin":14,"corrige":"1. Légende : la **louve** qui sauve les jumeaux (ou Romulus fondateur en 753 av. J.-C.). Archéologie : des **villages installés sur les collines** au bord du Tibre, qui se sont rapprochés peu à peu.\n2. Un **mythe** est un récit merveilleux (la louve, le dieu Mars, les jumeaux) qui n'est pas prouvé ; un fait historique s'appuie sur des traces vérifiables, comme les fouilles des archéologues.\n3. Le mythe donnait à Rome une origine **glorieuse et divine** : les fondateurs sont fils de **Mars**, dieu de la guerre, ce qui donne du prestige à la ville.\n4. Exemple de conclusion : La légende raconte que Romulus, fils de Mars, a fondé Rome en 753 av. J.-C. après avoir tué Remus. En réalité, Rome est née du regroupement progressif de villages sur les collines du Tibre. Le mythe n'est pas un fait prouvé, mais il montre comment les Romains voulaient se voir."}$exo$::jsonb),
  ('8d9ae244-c659-5946-9fac-e27dddca6eeb'::uuid, 1, 'probleme', $exo${"titre":"Le cube et la boîte","consigne":"Réponds à chaque question en écrivant la formule, le calcul et l’unité.","enonce":"**Situation.** Nino range ses jouets dans deux boîtes : un cube d’arête 6 cm et une boîte en forme de pavé droit de 10 cm sur 4 cm sur 5 cm.\n\n1. Calcule le volume du cube.\n2. Calcule le volume du pavé droit.\n3. Quelle boîte a le plus grand volume ? De combien ?","bareme":[{"critere":"Volume du cube : formule c³ et résultat 216 cm³","points":7},{"critere":"Volume du pavé : formule L × l × h et résultat 200 cm³","points":7},{"critere":"Comparaison correcte : le cube est plus grand de 16 cm³","points":6}],"dureeMin":6,"corrige":"1. Volume du cube : V = c³ = 6 × 6 × 6 = **216 cm³**.\n\n2. Volume du pavé droit : V = L × l × h = 10 × 4 × 5 = **200 cm³**.\n\n3. 216 est plus grand que 200 : c’est **le cube** qui a le plus grand volume, de 216 − 200 = **16 cm³**."}$exo$::jsonb),
  ('8d9ae244-c659-5946-9fac-e27dddca6eeb'::uuid, 2, 'probleme', $exo${"titre":"La piscine de Camille","consigne":"Justifie tes calculs et n’oublie pas les unités.","enonce":"**Situation.** La piscine de Camille est un pavé droit : elle mesure 5 m de long, 3 m de large et 1,2 m de profondeur. Elle est remplie à ras bord.\n\n1. Calcule le volume de la piscine en m³.\n2. Combien de litres d’eau contient-elle ?\n3. Un robinet remplit 600 litres par heure. Combien de temps faut-il pour remplir la piscine vide ?","bareme":[{"critere":"Volume en m³ : 5 × 3 × 1,2 = 18 m³","points":7},{"critere":"Conversion en litres : 18 m³ = 18 000 L (1 m³ = 1 000 L)","points":6},{"critere":"Durée : 18 000 ÷ 600 = 30 heures","points":7}],"dureeMin":9,"corrige":"1. V = L × l × h = 5 × 3 × 1,2 = **18 m³**.\n\n2. 1 m³ = 1 000 L (1 m³ = 1 000 dm³ et 1 dm³ = 1 L), donc 18 m³ = 18 × 1 000 = **18 000 L**.\n\n3. Durée : le robinet donne 600 L par heure et il faut 18 000 L, donc 18 000 ÷ 600 = **30 heures**. Le résultat est cohérent : 600 L par heure est un petit débit pour une grande piscine."}$exo$::jsonb),
  ('8d9ae244-c659-5946-9fac-e27dddca6eeb'::uuid, 3, 'probleme', $exo${"titre":"Le pavé de sable et la pyramide","consigne":"Rédige avec soin : chaque volume est justifié par sa formule.","enonce":"**Situation.** Un pavé droit en verre a pour base un carré de 6 cm de côté et pour hauteur 9 cm. On le remplit de sable. Une pyramide en verre a la même base et la même hauteur.\n\n1. Calcule le volume du pavé.\n2. Calcule le volume de la pyramide.\n3. Combien de pyramides pleines de sable faut-il verser pour remplir le pavé ? Explique.\n4. Un élève calcule le volume d’une pyramide de base rectangulaire 4 m sur 3 m et de hauteur 50 cm ainsi : (4 × 3 × 50) ÷ 3 = 200 m³. Repère l’erreur et donne le bon résultat.","bareme":[{"critere":"Volume du pavé : 6 × 6 × 9 = 324 cm³","points":4},{"critere":"Volume de la pyramide : (36 × 9) ÷ 3 = 108 cm³","points":4},{"critere":"Trois pyramides, expliqué par le tiers (324 ÷ 108 = 3)","points":4},{"critere":"Erreur d’unités repérée (50 cm = 0,5 m) et volume corrigé : 2 m³","points":8}],"dureeMin":15,"corrige":"1. Volume du pavé : V = 6 × 6 × 9 = **324 cm³**.\n\n2. Volume de la pyramide : aire de la base = 6 × 6 = 36 cm², V = (36 × 9) ÷ 3 = 324 ÷ 3 = **108 cm³**.\n\n3. 324 ÷ 108 = 3 : il faut **3 pyramides** pleines. C’est normal, une pyramide occupe le **tiers** du prisme de même base et de même hauteur.\n\n4. L’élève a mélangé les unités : 4 m et 3 m sont en mètres mais 50 cm est en centimètres. Il faut convertir : 50 cm = 0,5 m. Alors V = (4 × 3 × 0,5) ÷ 3 = 6 ÷ 3 = **2 m³** (et non 200 m³)."}$exo$::jsonb),
  ('919b0978-98e3-5e9a-b3d4-f47e56e59d01'::uuid, 1, 'probleme', $exo${"titre":"Le jardin de Léa","consigne":"Écris les formules utilisées et les unités.","enonce":"**Situation.** Le jardin de Léa est un rectangle de 12 m de long et 7 m de large. Au fond, elle a aménagé un coin en forme de triangle de base 10 m et de hauteur 6 m.\n\n1. Calcule le périmètre du jardin.\n2. Calcule l’aire du jardin.\n3. Calcule l’aire du coin triangulaire.","bareme":[{"critere":"Périmètre du rectangle : 2 × (12 + 7) = 38 m","points":6},{"critere":"Aire du rectangle : 12 × 7 = 84 m²","points":7},{"critere":"Aire du triangle : (10 × 6) ÷ 2 = 30 m²","points":7}],"dureeMin":6,"corrige":"1. Périmètre : P = 2 × (L + l) = 2 × (12 + 7) = 2 × 19 = **38 m**.\n\n2. Aire : A = L × l = 12 × 7 = **84 m²**.\n\n3. Aire du triangle : (base × hauteur) ÷ 2 = (10 × 6) ÷ 2 = 60 ÷ 2 = **30 m²**. On n’oublie pas le ÷ 2, et l’unité d’une aire est le m², pas le m."}$exo$::jsonb),
  ('919b0978-98e3-5e9a-b3d4-f47e56e59d01'::uuid, 2, 'probleme', $exo${"titre":"La terrasse à carreler","consigne":"Justifie chaque étape de ton calcul.","enonce":"**Situation.** Une terrasse a la forme d’un rectangle de 10 m sur 6 m, auquel on a retiré un coin carré de 3 m de côté (pour un arbre). Le carrelage coûte 25 € le m².\n\n1. Calcule l’aire de la terrasse en soustrayant le coin.\n2. Le périmètre de la terrasse est-il plus petit que celui du rectangle de départ ? Calcule-le.\n3. Calcule le prix du carrelage pour toute la terrasse.","bareme":[{"critere":"Aire : 10 × 6 − 3 × 3 = 51 m²","points":7},{"critere":"Périmètre 32 m, identique à celui du rectangle, avec une explication","points":7},{"critere":"Prix : 51 × 25 = 1 275 €","points":6}],"dureeMin":10,"corrige":"1. Aire du rectangle : 10 × 6 = 60 m². Aire du coin carré : 3 × 3 = 9 m². Aire de la terrasse : 60 − 9 = **51 m²**.\n\n2. Le contour de la terrasse est formé de deux côtés de 10 et 6 m, plus deux côtés de 3 m qui remplacent exactement le morceau de 3 + 3 m enlevé au coin. Le périmètre est donc celui du rectangle : 2 × (10 + 6) = **32 m**. Il n’est pas plus petit, alors que l’aire, elle, a diminué.\n\n3. Prix : 51 × 25 = **1 275 €**."}$exo$::jsonb),
  ('919b0978-98e3-5e9a-b3d4-f47e56e59d01'::uuid, 3, 'probleme', $exo${"titre":"La plaque et le disque","consigne":"Prends π ≈ 3,14. Justifie chaque résultat.","enonce":"**Situation.** Dans une plaque de bois carrée de 20 cm de côté, un menuisier découpe le plus grand disque possible : il a pour rayon 10 cm.\n\n1. Calcule l’aire de la plaque, puis l’aire du disque (avec π ≈ 3,14).\n2. Quelle est l’aire des chutes de bois ?\n3. Calcule le périmètre du disque, puis celui de la plaque. Lequel est le plus grand ?\n4. Exprime l’aire de la plaque en m².","bareme":[{"critere":"Aire du carré 400 cm² et du disque 3,14 × 10² = 314 cm²","points":5},{"critere":"Chutes : 400 − 314 = 86 cm²","points":5},{"critere":"Périmètres 62,8 cm et 80 cm, comparaison correcte","points":5},{"critere":"Conversion : 400 cm² = 0,04 m² (de 10 000 en 10 000)","points":5}],"dureeMin":15,"corrige":"1. Aire de la plaque : c² = 20 × 20 = **400 cm²**. Aire du disque : π × R² = 3,14 × 10 × 10 = **314 cm²**.\n\n2. Chutes : 400 − 314 = **86 cm²**.\n\n3. Périmètre du disque : 2 × π × R = 2 × 3,14 × 10 = **62,8 cm**. Périmètre de la plaque : 4 × c = 4 × 20 = **80 cm**. C’est le contour de la plaque qui est le plus long.\n\n4. 1 m² = 10 000 cm², donc 400 cm² = 400 ÷ 10 000 = **0,04 m²**. Attention : les aires se convertissent de 100 en 100, pas de 10 en 10."}$exo$::jsonb),
  ('a036ccde-d2a4-5998-a620-ea1145e71a89'::uuid, 1, 'probleme', $exo${"titre":"Faces, arêtes et sommets","consigne":"Réponds par des phrases courtes ou un petit tableau.","enonce":"**Situation.** Voici quatre solides : le cube, la pyramide à base carrée, le cylindre et la sphère.\n\n1. Donne le nombre de faces, d’arêtes et de sommets du cube.\n2. Donne le nombre de faces, d’arêtes et de sommets de la pyramide à base carrée.\n3. Range chacun des quatre solides dans la bonne famille : polyèdre ou solide de révolution.","bareme":[{"critere":"Cube : 6 faces, 12 arêtes, 8 sommets","points":6},{"critere":"Pyramide à base carrée : 5 faces, 8 arêtes, 5 sommets","points":7},{"critere":"Cube et pyramide : polyèdres ; cylindre et sphère : solides de révolution","points":7}],"dureeMin":6,"corrige":"1. Cube : **6 faces, 12 arêtes, 8 sommets**.\n\n2. Pyramide à base carrée : **5 faces** (la base et 4 triangles), **8 arêtes** (4 sur la base et 4 latérales), **5 sommets**.\n\n3. Le cube et la pyramide ont toutes leurs faces planes : ce sont des **polyèdres**. Le cylindre et la sphère s’obtiennent en faisant tourner une figure autour d’un axe : ce sont des **solides de révolution**."}$exo$::jsonb),
  ('a036ccde-d2a4-5998-a620-ea1145e71a89'::uuid, 2, 'probleme', $exo${"titre":"Le patron de la boîte de conserve","consigne":"Prends π ≈ 3,14 et arrondis au centième si besoin.","enonce":"**Situation.** Une boîte de conserve a la forme d’un cylindre de rayon 3 cm et de hauteur 8 cm. On veut construire son patron.\n\n1. De quelles figures se compose le patron d’un cylindre ?\n2. Quelles sont les dimensions du rectangle du patron ?\n3. Calcule l’aire de ce rectangle.","bareme":[{"critere":"Patron : deux disques et un rectangle","points":6},{"critere":"Rectangle : longueur 2 × π × 3 ≈ 18,84 cm (périmètre de la base), largeur 8 cm","points":8},{"critere":"Aire du rectangle : 18,84 × 8 = 150,72 cm²","points":6}],"dureeMin":9,"corrige":"1. Le patron d’un cylindre se compose de **deux disques** (les bases) et d’**un rectangle** (la surface latérale déroulée).\n\n2. Un côté du rectangle est le tour de la base : 2 × π × R = 2 × 3,14 × 3 = **18,84 cm**. L’autre côté est la hauteur : **8 cm**.\n\n3. Aire du rectangle : 18,84 × 8 = **150,72 cm²**."}$exo$::jsonb),
  ('a036ccde-d2a4-5998-a620-ea1145e71a89'::uuid, 3, 'probleme', $exo${"titre":"Le cube en perspective","consigne":"Réponds avec précision, en utilisant le vocabulaire du cours.","enonce":"**Situation.** Zoé dessine un cube d’arête 4 cm en perspective cavalière. Elle choisit de réduire les fuyantes de moitié.\n\n1. Quelle face doit-elle dessiner en vraie grandeur ? Quelle est alors la forme de cette face sur sa feuille ?\n2. Quelle longueur donne-t-elle aux fuyantes ? Sont-elles parallèles entre elles ?\n3. Combien d’arêtes sont cachées ? Comment les trace-t-elle ?\n4. Sur son dessin, la face du dessus est un parallélogramme et non un carré. Est-ce une erreur ? Combien de faces aurait le patron d’une pyramide dont la base a 5 côtés ?","bareme":[{"critere":"Face avant en vraie grandeur : un carré de 4 cm","points":5},{"critere":"Fuyantes de 2 cm, parallèles entre elles","points":5},{"critere":"3 arêtes cachées tracées en pointillés","points":5},{"critere":"Le parallélogramme n’est pas une erreur ; 1 + 5 = 6 faces","points":5}],"dureeMin":15,"corrige":"1. Elle dessine la **face avant** en vraie grandeur : un **carré de 4 cm de côté**.\n\n2. Les fuyantes sont réduites de moitié : 4 ÷ 2 = **2 cm**. Elles sont **parallèles entre elles** et tracées selon un même angle.\n\n3. Un cube a **3 arêtes cachées** (celles qui partent du sommet caché). Elles se tracent **en pointillés**.\n\n4. Ce n’est **pas une erreur** : en perspective cavalière, le parallélisme est conservé mais pas les angles droits (hors face avant), donc une face carrée apparaît comme un parallélogramme. Le patron d’une pyramide à base pentagonale comporte la base et 5 triangles, soit **6 faces**."}$exo$::jsonb),
  ('aa054ed6-5670-5eaa-9c54-52e601153f2b'::uuid, 1, 'probleme', $exo${"titre":"Le prisme triangulaire","consigne":"Réponds en justifiant avec le cours.","enonce":"**Situation.** Un prisme droit a pour base un triangle rectangle d’aire 6 cm². Sa hauteur est de 10 cm.\n\n1. Quelle est la nature des faces latérales d’un prisme droit ?\n2. Combien ce prisme a-t-il de faces au total ?\n3. Calcule son volume.","bareme":[{"critere":"Faces latérales : des rectangles","points":5},{"critere":"Nombre de faces : 3 rectangles + 2 bases = 5","points":5},{"critere":"Volume : 6 × 10 = 60 cm³","points":10}],"dureeMin":6,"corrige":"1. Les faces latérales d’un prisme droit sont des **rectangles**.\n\n2. La base est un triangle (n = 3), donc le prisme a n + 2 = **5 faces** : 3 rectangles latéraux et 2 bases.\n\n3. V = aire de la base × hauteur = 6 × 10 = **60 cm³**."}$exo$::jsonb),
  ('aa054ed6-5670-5eaa-9c54-52e601153f2b'::uuid, 2, 'probleme', $exo${"titre":"La boîte de soupe","consigne":"Prends π ≈ 3,14. Écris la formule avant de calculer.","enonce":"**Situation.** Une boîte de soupe est un cylindre de rayon 4 cm et de hauteur 10 cm. L’étiquette annonce « contenance : 0,5 L ».\n\n1. Calcule l’aire du disque de base.\n2. Calcule le volume de la boîte.\n3. Exprime ce volume en millilitres. La boîte peut-elle contenir 0,5 L de soupe ?","bareme":[{"critere":"Aire de la base : 3,14 × 4² = 50,24 cm²","points":6},{"critere":"Volume : 50,24 × 10 = 502,4 cm³","points":7},{"critere":"Conversion 502,4 mL et conclusion : oui, 502,4 mL > 500 mL","points":7}],"dureeMin":10,"corrige":"1. Aire de la base : π × R² = 3,14 × 4 × 4 = **50,24 cm²**.\n\n2. Volume : V = aire de la base × hauteur = 50,24 × 10 = **502,4 cm³**.\n\n3. 1 cm³ = 1 mL, donc le volume est **502,4 mL**. Comme 502,4 mL est supérieur à 500 mL (0,5 L), la boîte **peut contenir** 0,5 L de soupe, avec un petit peu de marge."}$exo$::jsonb),
  ('aa054ed6-5670-5eaa-9c54-52e601153f2b'::uuid, 3, 'probleme', $exo${"titre":"Le prisme et son patron","consigne":"Justifie chaque calcul avec une formule du cours.","enonce":"**Situation.** Un prisme droit a pour base un triangle rectangle dont les côtés mesurent 3 cm, 4 cm et 5 cm. L’aire de ce triangle est de 6 cm². La hauteur du prisme est de 10 cm.\n\n1. Calcule l’aire latérale du prisme.\n2. Calcule son aire totale.\n3. Calcule son volume.\n4. Le patron de sa surface latérale est un rectangle : donne ses dimensions.","bareme":[{"critere":"Aire latérale : périmètre 12 cm × 10 cm = 120 cm²","points":4},{"critere":"Aire totale : 120 + 2 × 6 = 132 cm²","points":5},{"critere":"Volume : 6 × 10 = 60 cm³","points":5},{"critere":"Rectangle de 12 cm (périmètre de la base) sur 10 cm (hauteur)","points":6}],"dureeMin":15,"corrige":"1. Périmètre de la base : 3 + 4 + 5 = 12 cm. Aire latérale = périmètre de la base × hauteur = 12 × 10 = **120 cm²**.\n\n2. Aire totale = aire latérale + 2 × aire de la base = 120 + 2 × 6 = 120 + 12 = **132 cm²**.\n\n3. Volume = aire de la base × hauteur = 6 × 10 = **60 cm³** (pas de division par 3 pour un prisme).\n\n4. La surface latérale déroulée est un rectangle dont la longueur est le **périmètre de la base**, soit **12 cm**, et la largeur la **hauteur**, soit **10 cm**."}$exo$::jsonb),
  ('0663da05-a754-5e88-94c1-0c33cd7640fc'::uuid, 1, 'probleme', $exo${"titre":"Deux parallèles et une sécante","consigne":"Nomme la propriété utilisée à chaque question.","enonce":"**Situation.** Les droites (d) et (d′) sont parallèles. Une sécante (s) les coupe. Un des huit angles formés mesure 50°.\n\n1. Que mesure son angle alterne-interne ?\n2. Que mesure son angle correspondant ?\n3. Que mesure l’angle qui lui est supplémentaire et adjacent ?","bareme":[{"critere":"Alterne-interne : 50°, avec la propriété des droites parallèles citée","points":7},{"critere":"Correspondant : 50°, avec la propriété citée","points":7},{"critere":"Angle supplémentaire adjacent : 180 − 50 = 130°","points":6}],"dureeMin":6,"corrige":"1. Les droites (d) et (d′) sont parallèles, donc les angles alternes-internes sont égaux : **50°**.\n\n2. Les droites étant parallèles, les angles correspondants sont égaux : **50°**.\n\n3. Deux angles supplémentaires ont une somme de 180° : 180 − 50 = **130°**."}$exo$::jsonb),
  ('0663da05-a754-5e88-94c1-0c33cd7640fc'::uuid, 2, 'probleme', $exo${"titre":"Parallèles ou pas ?","consigne":"Cite la propriété qui te permet de conclure.","enonce":"**Situation.** Deux figures sont dessinées à main levée. Dans chacune, les droites (AB) et (CD) sont coupées par la sécante (AC), avec B et D de part et d’autre de (AC).\n\n- Figure 1 : l’angle BAC mesure 72° et l’angle ACD mesure 72°.\n- Figure 2 : l’angle BAC mesure 72° et l’angle ACD mesure 68°.\n\n1. Dans la figure 1, les droites (AB) et (CD) sont-elles parallèles ? Justifie.\n2. Dans la figure 2, les droites sont-elles parallèles ? Justifie.\n3. Dans quel cas utilise-t-on une propriété pour calculer un angle, dans quel cas pour démontrer un parallélisme ?","bareme":[{"critere":"Figure 1 : alternes-internes égaux, donc droites parallèles (propriété citée)","points":7},{"critere":"Figure 2 : alternes-internes différents (72° ≠ 68°), donc droites non parallèles","points":7},{"critere":"Calculer : on part du parallélisme ; démontrer : on part de l’égalité des angles","points":6}],"dureeMin":10,"corrige":"1. Les angles BAC et ACD sont **alternes-internes** (de part et d’autre de la sécante (AC), entre les deux droites) et ils sont égaux (72°). **Si deux angles alternes-internes sont égaux, alors les droites sont parallèles** : (AB) // (CD).\n\n2. Ici les angles alternes-internes valent 72° et 68°, ils ne sont pas égaux. Si les droites étaient parallèles, ils le seraient : donc (AB) et (CD) **ne sont pas parallèles** (contraposée).\n\n3. On **calcule** un angle quand on sait déjà que les droites sont parallèles (les angles alternes-internes ou correspondants sont alors égaux). On **démontre** un parallélisme quand on sait que des angles alternes-internes ou correspondants sont égaux."}$exo$::jsonb),
  ('0663da05-a754-5e88-94c1-0c33cd7640fc'::uuid, 3, 'probleme', $exo${"titre":"La somme des angles retrouvée","consigne":"Rédige une démonstration en citant les propriétés.","enonce":"**Situation.** Soit ABC un triangle. Par le sommet A, on trace la droite (xy) parallèle à (BC), avec x du côté de B et y du côté de C. On mesure l’angle xAB = 48° et l’angle yAC = 67°.\n\n1. Que mesure l’angle ABC ? Justifie.\n2. Que mesure l’angle ACB ? Justifie.\n3. Calcule l’angle BAC.\n4. Quelle propriété du triangle retrouves-tu ? Écris-la avec les trois angles.","bareme":[{"critere":"Angle ABC = 48° : alternes-internes, (xy) // (BC)","points":4},{"critere":"Angle ACB = 67° : alternes-internes, (xy) // (BC)","points":4},{"critere":"Angle BAC = 180 − 48 − 67 = 65° (les trois angles forment un angle plat)","points":6},{"critere":"Somme des angles du triangle : 48° + 67° + 65° = 180°","points":6}],"dureeMin":15,"corrige":"1. (xy) et (BC) sont parallèles et (AB) est une sécante : les angles xAB et ABC sont **alternes-internes**, donc égaux. **ABC = 48°**.\n\n2. De même avec la sécante (AC) : les angles yAC et ACB sont alternes-internes, donc **ACB = 67°**.\n\n3. Les angles xAB, BAC et yAC forment un angle plat (180°) : BAC = 180 − 48 − 67 = **65°**.\n\n4. Les trois angles du triangle mesurent 48°, 67° et 65° et 48 + 67 + 65 = **180°**. On retrouve que la **somme des angles d’un triangle vaut 180°**."}$exo$::jsonb),
  ('4e4a9465-55d7-51be-92de-8f9113f15a47'::uuid, 1, 'probleme', $exo${"titre":"Trois triangles à classer","consigne":"Réponds pour chacun des trois triangles.","enonce":"**Situation.** Voici trois triangles : le triangle A a trois côtés de 5 cm ; le triangle B a des côtés de 4 cm, 4 cm et 6 cm ; le triangle C a des côtés de 3 cm, 4 cm et 5 cm et un angle droit.\n\n1. Donne la nature de chaque triangle.\n2. Combien d’axes de symétrie a chacun des triangles A et B ?\n3. Que mesure chaque angle du triangle A ?","bareme":[{"critere":"Natures : A équilatéral, B isocèle, C rectangle","points":8},{"critere":"Axes : 3 pour A, 1 pour B","points":6},{"critere":"Angles du triangle A : 60° chacun","points":6}],"dureeMin":6,"corrige":"1. A a trois côtés égaux : **équilatéral**. B a deux côtés égaux : **isocèle**. C a un angle droit : **rectangle**.\n\n2. Le triangle équilatéral A a **3 axes de symétrie** ; le triangle isocèle B (non équilatéral) en a **1**.\n\n3. Un triangle équilatéral a trois angles égaux, de 180 ÷ 3 = **60°** chacun."}$exo$::jsonb),
  ('4e4a9465-55d7-51be-92de-8f9113f15a47'::uuid, 2, 'probleme', $exo${"titre":"Le triangle existe-t-il ?","consigne":"Justifie avec l’inégalité triangulaire.","enonce":"**Situation.** Sami voudrait construire des triangles avec les longueurs suivantes : (a) 4 cm, 5 cm et 10 cm ; (b) 4 cm, 6 cm et 10 cm ; (c) 5 cm, 6 cm et 10 cm.\n\n1. Pour chaque cas, dis si le triangle existe, s’il est impossible, ou si les trois points sont alignés.\n2. Pour le cas (c), décris les instruments et les étapes de la construction.\n3. Quelle est la nature du triangle (c) selon ses côtés ?","bareme":[{"critere":"Verdicts : (a) impossible, (b) points alignés, (c) triangle possible, avec les sommes","points":8},{"critere":"Construction de (c) : croquis, segment de 10 cm, arcs de compas de 5 cm et 6 cm","points":6},{"critere":"Le triangle (c) est quelconque (trois côtés différents)","points":6}],"dureeMin":10,"corrige":"1. On compare le plus grand côté à la somme des deux autres :\n   - (a) 4 + 5 = 9, inférieur à 10 : **le triangle est impossible** ;\n   - (b) 4 + 6 = 10, égal à 10 : **les trois points sont alignés** ;\n   - (c) 5 + 6 = 11, supérieur à 10 : **le triangle existe**.\n\n2. On fait un croquis avec les longueurs codées, puis on trace un segment de 10 cm. Avec le compas, on trace un arc de cercle de rayon 5 cm centré sur une extrémité et un arc de rayon 6 cm centré sur l’autre : leur intersection donne le troisième sommet. On relie.\n\n3. Ses trois côtés (5, 6 et 10 cm) sont différents : c’est un triangle **quelconque**."}$exo$::jsonb),
  ('4e4a9465-55d7-51be-92de-8f9113f15a47'::uuid, 3, 'probleme', $exo${"titre":"Le triangle isocèle ABC","consigne":"Rédige avec des propriétés du cours.","enonce":"**Situation.** Le triangle ABC est isocèle en A, avec AB = AC = 7 cm et BC = 5 cm. On suppose que l’angle BAC mesure 50°.\n\n1. Vérifie que ce triangle peut exister.\n2. Quel est son axe de symétrie ? Pourquoi passe-t-il par A ?\n3. Que mesurent les angles B et C ?\n4. Le triangle ABC est-il rectangle ? Justifie.","bareme":[{"critere":"Inégalité triangulaire : 7 + 5 > 7 (et 7 + 7 > 5)","points":4},{"critere":"Axe de symétrie : la médiatrice de [BC], qui passe par le sommet principal A","points":5},{"critere":"Angles B et C : (180 − 50) ÷ 2 = 65° chacun","points":5},{"critere":"Non rectangle : angles de 50°, 65° et 65°, aucun n’est droit","points":6}],"dureeMin":15,"corrige":"1. Le plus grand côté mesure 7 cm. On a 7 + 5 = 12 > 7 (et 7 + 7 = 14 > 5) : **le triangle existe**.\n\n2. L’axe de symétrie est la **médiatrice de la base [BC]**. Elle passe par le sommet principal A car AB = AC : A est à égale distance de B et de C. C’est aussi la hauteur, la médiane et la bissectrice issues de A.\n\n3. Un triangle isocèle a ses deux angles à la base égaux : B = C = (180 − 50) ÷ 2 = 130 ÷ 2 = **65°**.\n\n4. Ses angles mesurent 50°, 65° et 65° : **aucun n’est droit**, donc le triangle **n’est pas rectangle**."}$exo$::jsonb),
  ('0d5f4625-9e1c-58d4-8ddf-4562775b253a'::uuid, 1, 'probleme', $exo${"titre":"Les quatre droites du triangle","consigne":"Complète en rédigeant des phrases courtes.","enonce":"**Situation.** Dans un triangle, on peut tracer quatre familles de droites : les médiatrices, les hauteurs, les médianes et les bissectrices.\n\n1. Donne la définition de chacune de ces quatre droites.\n2. Pour chaque famille, donne le nom du point de concours (ou ce que ce point est le centre).\n3. Dans un triangle isocèle, que peut-on dire des droites issues du sommet principal ?","bareme":[{"critere":"Quatre définitions justes","points":8},{"critere":"Points de concours : centre du cercle circonscrit, orthocentre, centre de gravité, centre du cercle inscrit","points":6},{"critere":"Dans un isocèle, les quatre droites issues du sommet principal sont confondues","points":6}],"dureeMin":7,"corrige":"1. **Médiatrice** : perpendiculaire à un côté en son milieu. **Hauteur** : issue d’un sommet, perpendiculaire au côté opposé. **Médiane** : joint un sommet au milieu du côté opposé. **Bissectrice** : partage un angle en deux angles égaux.\n\n2. Les médiatrices se coupent au **centre du cercle circonscrit** ; les hauteurs à l’**orthocentre** ; les médianes au **centre de gravité** ; les bissectrices au **centre du cercle inscrit**.\n\n3. Dans un triangle isocèle, la droite issue du sommet principal est **à la fois médiatrice, hauteur, médiane et bissectrice** : les quatre sont confondues."}$exo$::jsonb),
  ('0d5f4625-9e1c-58d4-8ddf-4562775b253a'::uuid, 2, 'probleme', $exo${"titre":"La médiane et le centre de gravité","consigne":"Justifie avec les propriétés du cours.","enonce":"**Situation.** Dans le triangle ABC, la base BC mesure 8 cm et la hauteur issue de A mesure 6 cm. M est le milieu de [BC]. La médiane [AM] mesure 15 cm et G est le centre de gravité du triangle.\n\n1. Calcule l’aire du triangle ABC.\n2. La médiane (AM) partage le triangle en deux triangles ABM et AMC. Quelle est l’aire de chacun ? Justifie.\n3. Où est situé G sur [AM] ? Calcule AG et GM.","bareme":[{"critere":"Aire du triangle ABC : (8 × 6) ÷ 2 = 24 cm²","points":7},{"critere":"Aire de chaque triangle : 12 cm², car une médiane partage l’aire en deux","points":6},{"critere":"G aux deux tiers depuis A : AG = 10 cm et GM = 5 cm","points":7}],"dureeMin":10,"corrige":"1. Aire = (base × hauteur) ÷ 2 = (8 × 6) ÷ 2 = 48 ÷ 2 = **24 cm²**.\n\n2. Une médiane coupe le triangle en deux triangles de **même aire** : chacun a pour aire 24 ÷ 2 = **12 cm²**. (Ils ont des bases BM et MC égales et la même hauteur.)\n\n3. Le centre de gravité est aux **deux tiers de la médiane en partant du sommet** : AG = 15 × 2/3 = **10 cm**, donc GM = 15 − 10 = **5 cm**."}$exo$::jsonb),
  ('0d5f4625-9e1c-58d4-8ddf-4562775b253a'::uuid, 3, 'probleme', $exo${"titre":"Un triangle isocèle et ses points remarquables","consigne":"Rédige ta démonstration avec les propriétés du cours.","enonce":"**Situation.** Le triangle ABC est isocèle en A, avec BC = 10 cm. M est le milieu de [BC] et la droite (AM) mesure 12 cm entre A et M. G désigne le centre de gravité, O le centre du cercle circonscrit et I le centre du cercle inscrit.\n\n1. Montre que (AM) est à la fois la médiane, la hauteur, la médiatrice et la bissectrice issues de A.\n2. Calcule l’aire du triangle ABC.\n3. Calcule AG et GM.\n4. Sur quelle droite se trouvent les points G, O et I ? Pourquoi ?","bareme":[{"critere":"(AM) est médiane par définition, axe de symétrie donc médiatrice, hauteur et bissectrice","points":5},{"critere":"Aire : (10 × 12) ÷ 2 = 60 cm²","points":5},{"critere":"AG = 12 × 2/3 = 8 cm et GM = 4 cm","points":5},{"critere":"G, O et I sont sur (AM), l’axe de symétrie, avec une justification","points":5}],"dureeMin":15,"corrige":"1. M est le milieu de [BC] donc (AM) est **la médiane** issue de A. Le triangle est isocèle en A : la médiatrice de [BC] passe par A et par M, c’est donc (AM) ; elle est aussi **hauteur** (perpendiculaire à [BC]) et **bissectrice** de l’angle A. Les quatre droites sont confondues.\n\n2. Comme (AM) est la hauteur : aire = (10 × 12) ÷ 2 = **60 cm²**.\n\n3. G est aux deux tiers de la médiane en partant de A : AG = 12 × 2/3 = **8 cm**, donc GM = 12 − 8 = **4 cm**.\n\n4. Les points G (médianes), O (médiatrices) et I (bissectrices) sont sur chacune de ces droites, qui sont toutes confondues avec (AM), **l’axe de symétrie du triangle**. Ils se trouvent donc sur la droite (AM)."}$exo$::jsonb),
  ('9086e61e-ef07-5002-b9ff-0af6236e657d'::uuid, 1, 'probleme', $exo${"titre":"Le troisième angle","consigne":"Écris le calcul et une phrase de conclusion.","enonce":"**Situation.** On étudie trois triangles. Le triangle ABC a un angle A de 65° et un angle B de 40°. Le triangle DEF est rectangle en D et son angle E mesure 28°. Le triangle GHI est équilatéral.\n\n1. Calcule l’angle C du triangle ABC.\n2. Calcule l’angle F du triangle DEF.\n3. Que mesure chaque angle du triangle GHI ?","bareme":[{"critere":"Angle C : 180 − 65 − 40 = 75°","points":7},{"critere":"Angle F : 90 − 28 = 62° (angles aigus complémentaires)","points":7},{"critere":"Angles de GHI : 180 ÷ 3 = 60°","points":6}],"dureeMin":6,"corrige":"1. La somme des angles d’un triangle vaut 180° : C = 180 − 65 − 40 = **75°**.\n\n2. Le triangle DEF est rectangle en D : ses angles aigus sont complémentaires, donc F = 90 − 28 = **62°**. (Vérification : 90 + 28 + 62 = 180.)\n\n3. Le triangle GHI est équilatéral : trois angles égaux, 180 ÷ 3 = **60°** chacun."}$exo$::jsonb),
  ('9086e61e-ef07-5002-b9ff-0af6236e657d'::uuid, 2, 'probleme', $exo${"titre":"Triangles isocèles","consigne":"Justifie chaque résultat par une propriété.","enonce":"**Situation.** On considère deux triangles isocèles. Le triangle ABC est isocèle en A avec un angle au sommet de 40°. Le triangle DEF est isocèle en D avec des angles à la base de 35°. Le triangle GHI est rectangle et isocèle en G.\n\n1. Calcule les angles à la base du triangle ABC.\n2. Calcule l’angle au sommet du triangle DEF. Quelle est la nature de ce triangle selon ses angles ?\n3. Donne les trois angles du triangle GHI.","bareme":[{"critere":"Base de ABC : (180 − 40) ÷ 2 = 70° chacun","points":7},{"critere":"Sommet de DEF : 180 − 35 − 35 = 110° ; triangle obtusangle","points":7},{"critere":"GHI : 90°, 45° et 45°","points":6}],"dureeMin":10,"corrige":"1. Les angles à la base d’un triangle isocèle sont égaux : (180 − 40) ÷ 2 = 140 ÷ 2 = **70°** chacun.\n\n2. Les deux angles à la base valent 35° : l’angle au sommet est 180 − 35 − 35 = **110°**. Il est obtus : DEF est **obtusangle**.\n\n3. GHI est rectangle en G, donc les deux angles aigus sont complémentaires ; comme le triangle est isocèle ils sont égaux : 90 ÷ 2 = 45°. Les angles sont **90°, 45° et 45°**."}$exo$::jsonb),
  ('9086e61e-ef07-5002-b9ff-0af6236e657d'::uuid, 3, 'probleme', $exo${"titre":"L’angle extérieur","consigne":"Rédige avec les propriétés du cours.","enonce":"**Situation.** Dans le triangle ABC, l’angle A mesure 52° et l’angle B mesure 61°. Le point D est placé sur le prolongement de [BC], au-delà de C.\n\n1. Calcule l’angle ACB.\n2. Calcule l’angle extérieur ACD.\n3. Vérifie que ACD est égal à la somme des angles A et B.\n4. Un élève affirme qu’il existe un triangle dont les angles mesurent 95°, 60° et 30°. A-t-il raison ? Justifie.","bareme":[{"critere":"Angle ACB : 180 − 52 − 61 = 67°","points":4},{"critere":"Angle extérieur ACD : 180 − 67 = 113°","points":5},{"critere":"Vérification : 52 + 61 = 113°, énoncé de la propriété","points":5},{"critere":"95 + 60 + 30 = 185 ≠ 180 : le triangle n’existe pas","points":6}],"dureeMin":15,"corrige":"1. La somme des angles vaut 180° : ACB = 180 − 52 − 61 = **67°**.\n\n2. Les angles ACB et ACD forment un angle plat (D est sur le prolongement de [BC]) : ACD = 180 − 67 = **113°**.\n\n3. 52 + 61 = **113°** : l’angle extérieur est bien égal à la **somme des deux angles intérieurs non adjacents**.\n\n4. 95 + 60 + 30 = 185°. Or la somme des angles d’un triangle vaut toujours 180° : **l’élève a tort**, ce triangle n’existe pas."}$exo$::jsonb),
  ('19cfb78c-c238-52eb-b5fd-40f855ef8e6d'::uuid, 1, 'probleme', $exo${"titre":"Miroir et demi-tour","consigne":"Réponds avec des mesures et des phrases courtes.","enonce":"**Situation.** Un point M est situé à 3 cm d’une droite (d). Un point P est situé à 4 cm d’un point O.\n\n1. Le point M′ est le symétrique de M par rapport à la droite (d). À quelle distance de (d) est-il ? Que mesure [MM′] ?\n2. Quel rôle joue la droite (d) pour le segment [MM′] ?\n3. Le point P′ est le symétrique de P par rapport au point O. Que représente O pour [PP′] ? Que mesure [PP′] ?","bareme":[{"critere":"M′ à 3 cm de (d) de l’autre côté, MM′ = 6 cm","points":7},{"critere":"(d) est la médiatrice de [MM′]","points":6},{"critere":"O est le milieu de [PP′] et PP′ = 8 cm","points":7}],"dureeMin":7,"corrige":"1. M′ est à **3 cm** de (d), de l’autre côté de la droite : MM′ = 3 + 3 = **6 cm**.\n\n2. La droite (d) est la **médiatrice** du segment [MM′] : elle lui est perpendiculaire en son milieu.\n\n3. O est le **milieu** de [PP′], donc OP′ = OP = 4 cm et PP′ = **8 cm**."}$exo$::jsonb),
  ('19cfb78c-c238-52eb-b5fd-40f855ef8e6d'::uuid, 2, 'probleme', $exo${"titre":"Quelles symétries ?","consigne":"Justifie brièvement chaque réponse.","enonce":"**Situation.** On étudie les symétries de quelques figures : le carré, le rectangle, le losange (non carré) et le parallélogramme (non rectangle et non losange).\n\n1. Complète un tableau donnant, pour chaque figure, son nombre d’axes de symétrie et si elle a un centre de symétrie.\n2. Explique pourquoi le parallélogramme n’a aucun axe de symétrie mais un centre.\n3. On applique au mot « ÉCOLE » une symétrie axiale, puis une symétrie centrale. Que devient le texte dans chaque cas ?","bareme":[{"critere":"Tableau exact : carré 4 axes et centre, rectangle 2 et centre, losange 2 et centre, parallélogramme 0 et centre","points":8},{"critere":"Le centre est l’intersection des diagonales, qui se coupent en leur milieu ; aucun axe car la figure n’est pas superposable à son retournée","points":6},{"critere":"Axiale : texte inversé comme dans un miroir ; centrale : texte à l’envers dans le bon ordre","points":6}],"dureeMin":10,"corrige":"1. Tableau :\n   | Figure | Axes | Centre |\n   | Carré | 4 | oui |\n   | Rectangle | 2 | oui |\n   | Losange | 2 | oui |\n   | Parallélogramme | 0 | oui |\n\n2. Le centre de symétrie du parallélogramme est le point d’intersection de ses diagonales, qui se coupent en leur milieu. En revanche, en le pliant le long d’une droite on ne peut pas superposer ses deux moitiés (le retourner l’incline dans l’autre sens) : il n’a **aucun axe**.\n\n3. La **symétrie axiale retourne** le texte comme dans un miroir (il est inversé). La **symétrie centrale** le fait pivoter d’un demi-tour : le texte est **à l’envers mais dans le bon ordre de lecture**."}$exo$::jsonb),
  ('19cfb78c-c238-52eb-b5fd-40f855ef8e6d'::uuid, 3, 'probleme', $exo${"titre":"Le triangle et son image","consigne":"Justifie chaque réponse par une propriété de la symétrie centrale.","enonce":"**Situation.** Le triangle ABC a pour dimensions AB = 5 cm, BC = 6 cm, un angle en B de 40° et une aire de 12 cm². Le triangle A′B′C′ est son symétrique par rapport à un point O.\n\n1. Donne A′B′, B′C′, l’angle en B′ et l’aire de A′B′C′. Justifie.\n2. Sachant que OA = 3,5 cm, que mesure [AA′] ? Que peut-on dire des points A, O et A′ ?\n3. Le triangle A′B′C′ est-il « retourné » par rapport à ABC ? Compare avec une symétrie axiale.\n4. Les deux triangles sont-ils superposables ?","bareme":[{"critere":"A′B′ = 5 cm, B′C′ = 6 cm, angle 40° et aire 12 cm², par conservation","points":6},{"critere":"AA′ = 7 cm, points A, O, A′ alignés, O milieu","points":5},{"critere":"Pas de retournement pour la centrale ; l’axiale retourne","points":5},{"critere":"Les deux triangles sont superposables","points":4}],"dureeMin":15,"corrige":"1. La symétrie centrale conserve les longueurs, les angles et les aires : **A′B′ = 5 cm**, **B′C′ = 6 cm**, l’angle en B′ mesure **40°** et l’aire est de **12 cm²**.\n\n2. O est le milieu de [AA′] : OA′ = OA = 3,5 cm, donc AA′ = 2 × 3,5 = **7 cm**. Les points A, O et A′ sont **alignés**.\n\n3. La symétrie centrale est un demi-tour : la figure **n’est pas retournée** (le sens de rotation A → B → C est conservé), contrairement à la symétrie axiale qui retourne comme un miroir.\n\n4. Oui : une figure et son image par une symétrie sont **toujours superposables**."}$exo$::jsonb),
  ('976943e2-0af9-5422-9763-97684cd3b157'::uuid, 1, 'probleme', $exo${"titre":"Un parallélogramme ABCD","consigne":"Cite la propriété utilisée à chaque question.","enonce":"**Situation.** ABCD est un parallélogramme avec AB = 6 cm, BC = 4 cm et un angle A de 70°.\n\n1. Donne les longueurs CD et AD.\n2. Donne les angles C et B.\n3. Calcule le périmètre de ABCD.","bareme":[{"critere":"CD = 6 cm et AD = 4 cm : côtés opposés de même longueur","points":6},{"critere":"C = 70° (angles opposés) et B = 110° (angles consécutifs supplémentaires)","points":8},{"critere":"Périmètre : 2 × (6 + 4) = 20 cm","points":6}],"dureeMin":6,"corrige":"1. Les côtés opposés d’un parallélogramme ont la même longueur : **CD = AB = 6 cm** et **AD = BC = 4 cm**.\n\n2. Les angles opposés sont égaux : **C = A = 70°**. Deux angles consécutifs sont supplémentaires : **B = 180 − 70 = 110°**.\n\n3. Périmètre = 2 × (6 + 4) = 2 × 10 = **20 cm**."}$exo$::jsonb),
  ('976943e2-0af9-5422-9763-97684cd3b157'::uuid, 2, 'probleme', $exo${"titre":"Les diagonales parlent","consigne":"Justifie avec le tableau des diagonales du cours.","enonce":"**Situation.** Les diagonales [AC] et [BD] du quadrilatère ABCD se coupent en O, avec OA = OC = 3 cm et OB = OD = 4 cm. De plus, l’angle AOB mesure 90°.\n\n1. Montre que ABCD est un parallélogramme.\n2. Que mesurent les diagonales AC et BD ? Le quadrilatère est-il un rectangle ?\n3. Quelle est la nature exacte de ABCD ? Calcule son aire.","bareme":[{"critere":"Parallélogramme : les diagonales se coupent en leur milieu (OA = OC et OB = OD)","points":7},{"critere":"AC = 6 cm et BD = 8 cm, différentes donc pas un rectangle","points":7},{"critere":"Losange (diagonales perpendiculaires) et aire (6 × 8) ÷ 2 = 24 cm²","points":6}],"dureeMin":10,"corrige":"1. O est le milieu de [AC] (OA = OC) et de [BD] (OB = OD) : les diagonales se coupent en leur milieu, donc **ABCD est un parallélogramme**.\n\n2. AC = 3 + 3 = **6 cm** et BD = 4 + 4 = **8 cm**. Elles n’ont pas la même longueur : ABCD **n’est pas un rectangle**.\n\n3. Les diagonales sont perpendiculaires (angle AOB = 90°) : un parallélogramme aux diagonales perpendiculaires est un **losange**. Son aire est (D × d) ÷ 2 = (6 × 8) ÷ 2 = **24 cm²**."}$exo$::jsonb),
  ('976943e2-0af9-5422-9763-97684cd3b157'::uuid, 3, 'probleme', $exo${"titre":"Du parallélogramme au carré","consigne":"Rédige chaque étape de la démonstration.","enonce":"**Situation.** Dans le quadrilatère EFGH, les diagonales [EG] et [FH] se coupent en O. On sait que EO = OG = 5 cm et FO = OH = 5 cm, et que l’angle EOF mesure 90°.\n\n1. Démontre que EFGH est un parallélogramme.\n2. Démontre que EFGH est un rectangle.\n3. Démontre que EFGH est un losange.\n4. Quelle est la nature exacte de EFGH ? Combien a-t-il d’axes de symétrie ? Calcule son aire avec la formule du losange.","bareme":[{"critere":"Parallélogramme : diagonales de même milieu O","points":5},{"critere":"Rectangle : diagonales de même longueur EG = FH = 10 cm","points":5},{"critere":"Losange : diagonales perpendiculaires","points":5},{"critere":"Carré, 4 axes, aire (10 × 10) ÷ 2 = 50 cm²","points":5}],"dureeMin":15,"corrige":"1. O est le milieu de [EG] et de [FH] : les diagonales se coupent en leur milieu, donc **EFGH est un parallélogramme**.\n\n2. EG = 5 + 5 = 10 cm et FH = 5 + 5 = 10 cm : ses diagonales ont la **même longueur**, donc c’est un **rectangle**.\n\n3. L’angle EOF mesure 90° : ses diagonales sont **perpendiculaires**, donc c’est un **losange**.\n\n4. EFGH est à la fois un rectangle et un losange : c’est un **carré**. Il a **4 axes de symétrie**. Son aire, avec la formule du losange : (D × d) ÷ 2 = (10 × 10) ÷ 2 = **50 cm²**."}$exo$::jsonb),
  ('5e261956-9f14-5c71-af61-e6c3c4bf7470'::uuid, 1, 'probleme', $exo${"titre":"Décimaux et fractions","consigne":"Écris chaque résultat sous la forme demandée.","enonce":"**Situation.** Voici des nombres à écrire autrement.\n\n1. Écris sous forme de fractions décimales : 0,9 ; 0,03 ; 4,7.\n2. Simplifie les fractions 25/100 et 50/100 pour obtenir des fractions irréductibles.\n3. Donne l’écriture décimale de 27/10 et de 9/100.","bareme":[{"critere":"0,9 = 9/10, 0,03 = 3/100 et 4,7 = 47/10","points":6},{"critere":"25/100 = 1/4 et 50/100 = 1/2","points":7},{"critere":"27/10 = 2,7 et 9/100 = 0,09","points":7}],"dureeMin":6,"corrige":"1. Le nombre de chiffres après la virgule donne le nombre de zéros du dénominateur : 0,9 = **9/10** ; 0,03 = **3/100** ; 4,7 = **47/10**.\n\n2. 25/100 = 25 ÷ 25 sur 100 ÷ 25 = **1/4**. 50/100 = **1/2**.\n\n3. 27/10 : la virgule recule d’un rang, **2,7**. 9/100 : la virgule recule de deux rangs, **0,09**."}$exo$::jsonb),
  ('5e261956-9f14-5c71-af61-e6c3c4bf7470'::uuid, 2, 'probleme', $exo${"titre":"Fractions décimales ou non","consigne":"Justifie tes réponses avec le cours.","enonce":"**Situation.** On étudie l’écriture de plusieurs nombres.\n\n1. Donne l’écriture décimale de 3/4 et de 7/20.\n2. L’écriture décimale de 1/3 s’arrête-t-elle ? Explique pourquoi.\n3. Donne la fraction irréductible égale à 0,45, puis celle égale à 1,6.","bareme":[{"critere":"3/4 = 0,75 et 7/20 = 0,35, avec passage par 75/100 et 35/100","points":7},{"critere":"1/3 = 0,333… illimitée : dénominateur 3 (ni 2 ni 5)","points":7},{"critere":"0,45 = 9/20 et 1,6 = 8/5","points":6}],"dureeMin":10,"corrige":"1. 3/4 = 75/100 = **0,75** (on multiplie haut et bas par 25). 7/20 = 35/100 = **0,35** (on multiplie par 5).\n\n2. Non : 1/3 = 0,3333… est une écriture illimitée périodique. Son dénominateur irréductible est 3, il ne contient ni 2 ni 5 : on ne peut pas le transformer en puissance de 10.\n\n3. 0,45 = 45/100 = **9/20** (on simplifie par 5). 1,6 = 16/10 = **8/5** (on simplifie par 2)."}$exo$::jsonb),
  ('5e261956-9f14-5c71-af61-e6c3c4bf7470'::uuid, 3, 'probleme', $exo${"titre":"Ranger et comparer","consigne":"Rédige chaque étape.","enonce":"**Situation.** Voici quatre nombres : 0,6 ; 5/8 ; 3/5 ; 0,65.\n\n1. Donne l’écriture décimale de 5/8 en passant par une fraction décimale.\n2. Range ces quatre nombres du plus petit au plus grand.\n3. Quels sont les deux nombres égaux ?\n4. La fraction 1/6 a-t-elle une écriture décimale qui s’arrête ? Justifie.","bareme":[{"critere":"5/8 = 625/1000 = 0,625 (multiplication par 125)","points":5},{"critere":"Rangement : 0,6 = 3/5 < 5/8 < 0,65","points":5},{"critere":"0,6 et 3/5 sont égaux (3/5 = 6/10)","points":5},{"critere":"1/6 : non, car 6 contient le facteur 3","points":5}],"dureeMin":15,"corrige":"1. On multiplie haut et bas par 125 : 5/8 = 625/1000 = **0,625**.\n\n2. 3/5 = 6/10 = 0,6 ; 5/8 = 0,625. Rangement : 0,6 = 3/5 < 5/8 = 0,625 < 0,65. Soit **3/5 = 0,6 < 5/8 < 0,65**.\n\n3. Les nombres égaux sont **0,6 et 3/5**, car 3/5 = 6/10 = 0,6.\n\n4. **Non** : 1/6 est irréductible et son dénominateur 6 = 2 × 3 contient le facteur 3, différent de 2 et 5 ; son écriture est illimitée (0,1666…)."}$exo$::jsonb),
  ('2b0f3c50-6f65-5f0d-930c-e8516b2a6f9a'::uuid, 1, 'probleme', $exo${"titre":"Quatre calculs posés","consigne":"Pose les opérations et donne le résultat.","enonce":"**Situation.** Voici quatre calculs à effectuer sans calculatrice.\n\n1. 14,3 + 2,85\n2. 9,2 − 4,75\n3. 3,2 × 1,5\n4. Que devient 0,7 quand on le multiplie par 100 ? Et quand on le divise par 10 ?","bareme":[{"critere":"Addition alignée : 17,15","points":5},{"critere":"Soustraction alignée : 4,45","points":5},{"critere":"Produit : 4,8 (32 × 15 = 480, deux décimales)","points":5},{"critere":"0,7 × 100 = 70 et 0,7 ÷ 10 = 0,07","points":5}],"dureeMin":7,"corrige":"1. On aligne les virgules : 14,30 + 2,85 = **17,15**.\n\n2. 9,20 − 4,75 = **4,45**.\n\n3. 32 × 15 = 480 ; il y a 1 + 1 = 2 décimales, donc 3,2 × 1,5 = 4,80 = **4,8**.\n\n4. Multiplier par 100 déplace la virgule de 2 rangs vers la droite : 0,7 × 100 = **70**. Diviser par 10 la déplace d’un rang vers la gauche : 0,7 ÷ 10 = **0,07**."}$exo$::jsonb),
  ('2b0f3c50-6f65-5f0d-930c-e8516b2a6f9a'::uuid, 2, 'probleme', $exo${"titre":"Au magasin de fournitures","consigne":"Écris tes calculs en entier.","enonce":"**Situation.** Yanis achète 3 cahiers à 2,35 € l’un et un stylo à 1,80 €. Il paie avec un billet de 10 €.\n\n1. Estime d’abord le total avec des nombres arrondis.\n2. Calcule le prix exact de ses achats.\n3. Calcule la monnaie que le vendeur lui rend.","bareme":[{"critere":"Estimation cohérente : environ 3 × 2 + 2 = 8 à 9 €","points":6},{"critere":"Prix exact : 3 × 2,35 + 1,80 = 8,85 €","points":8},{"critere":"Monnaie : 10 − 8,85 = 1,15 €","points":6}],"dureeMin":9,"corrige":"1. Estimation : 2,35 ≈ 2,4 et 1,80 ≈ 2 ; on trouve environ 3 × 2,4 + 2 = 9,2 €, un peu moins de 9 €. (Toute estimation proche de 9 € est acceptée.)\n\n2. 3 × 2,35 = **7,05 €**, puis 7,05 + 1,80 = **8,85 €**.\n\n3. 10 − 8,85 = **1,15 €** rendus. Le résultat est cohérent avec l’estimation."}$exo$::jsonb),
  ('2b0f3c50-6f65-5f0d-930c-e8516b2a6f9a'::uuid, 3, 'probleme', $exo${"titre":"Priorités et ordre de grandeur","consigne":"Écris chaque étape de calcul.","enonce":"**Situation.** On étudie plusieurs calculs.\n\n1. Calcule A = 4 + 2,5 × (8 − 3,2) en respectant les priorités.\n2. Calcule B = 7,5 ÷ 0,25 en transformant la division.\n3. Donne un ordre de grandeur de 19,8 × 4,9, puis calcule le produit exact.\n4. Arrondis le résultat exact de la question 3 au dixième.","bareme":[{"critere":"A : parenthèses, puis multiplication, puis addition, A = 16","points":6},{"critere":"B : 750 ÷ 25 = 30 (on multiplie dividende et diviseur par 100)","points":4},{"critere":"Ordre de grandeur 20 × 5 = 100 et produit exact 97,02","points":5},{"critere":"Arrondi au dixième : 97,0","points":5}],"dureeMin":15,"corrige":"1. Parenthèses : 8 − 3,2 = 4,8. Multiplication : 2,5 × 4,8 = 12. Addition : 4 + 12 = **16**.\n\n2. On multiplie le dividende **et** le diviseur par 100 : 7,5 ÷ 0,25 = 750 ÷ 25 = **30**.\n\n3. Ordre de grandeur : 19,8 ≈ 20 et 4,9 ≈ 5, donc environ 20 × 5 = **100**. Produit exact : 198 × 49 = 9 702, avec 1 + 1 = 2 décimales : **97,02** (cohérent avec 100).\n\n4. 97,02 arrondi au dixième : le chiffre des centièmes est 2 (inférieur à 5), donc **97,0**."}$exo$::jsonb),
  ('0eb10cf5-2361-577a-9473-8508eadd3c86'::uuid, 1, 'probleme', $exo${"titre":"Lire une fraction décimale","consigne":"Réponds avec l’écriture demandée.","enonce":"**Situation.** On travaille sur les fractions décimales et les décimaux.\n\n1. Donne l’écriture décimale de 3/10, de 47/100 et de 8/1000.\n2. Écris 0,9 et 0,05 sous forme de fractions décimales.\n3. Décompose 2,35 en une somme d’un entier et de fractions décimales.","bareme":[{"critere":"3/10 = 0,3 ; 47/100 = 0,47 ; 8/1000 = 0,008","points":6},{"critere":"0,9 = 9/10 et 0,05 = 5/100","points":7},{"critere":"2,35 = 2 + 3/10 + 5/100","points":7}],"dureeMin":6,"corrige":"1. 3/10 = **0,3** ; 47/100 = **0,47** ; 8/1000 = **0,008** (le nombre de zéros donne le nombre de rangs).\n\n2. 0,9 = **9/10** ; 0,05 = **5/100**.\n\n3. Dans 2,35, le 3 vaut 3 dixièmes et le 5 vaut 5 centièmes : 2,35 = **2 + 3/10 + 5/100**."}$exo$::jsonb),
  ('0eb10cf5-2361-577a-9473-8508eadd3c86'::uuid, 2, 'probleme', $exo${"titre":"Additionner des fractions décimales","consigne":"Mets au même dénominateur avant d’additionner.","enonce":"**Situation.** Nora calcule avec des fractions décimales.\n\n1. Calcule 3/10 + 47/100 et donne le résultat en écriture décimale.\n2. Calcule 5/100 + 2/10 et donne le résultat en écriture décimale.\n3. Transforme 1/4 et 3/5 en fractions décimales, puis en écritures décimales.","bareme":[{"critere":"3/10 + 47/100 = 77/100 = 0,77","points":7},{"critere":"5/100 + 2/10 = 25/100 = 0,25","points":7},{"critere":"1/4 = 25/100 = 0,25 et 3/5 = 6/10 = 0,6","points":6}],"dureeMin":9,"corrige":"1. On met au même dénominateur : 3/10 = 30/100, donc 30/100 + 47/100 = **77/100 = 0,77**.\n\n2. 2/10 = 20/100, donc 5/100 + 20/100 = **25/100 = 0,25**.\n\n3. 1/4 : on multiplie haut et bas par 25, 1/4 = 25/100 = **0,25**. 3/5 : on multiplie par 2, 3/5 = 6/10 = **0,6**."}$exo$::jsonb),
  ('0eb10cf5-2361-577a-9473-8508eadd3c86'::uuid, 3, 'probleme', $exo${"titre":"Décimale ou pas ?","consigne":"Justifie avec le cours.","enonce":"**Situation.** On étudie des fractions qui se transforment (ou non) en fractions décimales.\n\n1. Transforme 7/8 en fraction décimale, puis en écriture décimale.\n2. Transforme 3/20 en fraction décimale.\n3. Explique pourquoi 1/3 ne peut pas s’écrire comme une fraction décimale.\n4. Calcule 1/2 + 3/10 + 7/100 en écriture fractionnaire décimale, puis décimale.","bareme":[{"critere":"7/8 = 875/1000 = 0,875 (multiplication par 125)","points":5},{"critere":"3/20 = 15/100","points":5},{"critere":"1/3 : 3 n’est pas un facteur de 10, jamais une puissance de 10","points":5},{"critere":"1/2 + 3/10 + 7/100 = 87/100 = 0,87","points":5}],"dureeMin":15,"corrige":"1. On multiplie haut et bas par 125 : 7/8 = **875/1000 = 0,875**.\n\n2. On multiplie haut et bas par 5 : 3/20 = **15/100** (= 0,15).\n\n3. Le dénominateur 3 est un facteur premier différent de 2 et de 5. Aucun nombre entier multiplié par 3 ne donne 10, 100, 1 000… : **1/3 n’est pas une fraction décimale** (1/3 = 0,3333… est illimité).\n\n4. Au même dénominateur : 50/100 + 30/100 + 7/100 = **87/100 = 0,87**."}$exo$::jsonb),
  ('4cc572e1-c45b-5a06-a419-e98582fa33a0'::uuid, 1, 'probleme', $exo${"titre":"Les températures de la semaine","consigne":"Réponds à chaque question en justifiant avec le cours.","enonce":"**Situation.** Voici les températures relevées à midi dans une ville : lundi −3 °C, mardi +2 °C, mercredi −8 °C, jeudi 0 °C.\n\n1. Quel jour a-t-il fait le plus froid ? Justifie.\n2. Range ces quatre températures dans l’ordre croissant.\n3. Donne la distance à zéro de −8 et l’opposé de −3.","bareme":[{"critere":"Mercredi, avec la justification : −8 est le plus petit","points":6},{"critere":"Rangement −8 < −3 < 0 < +2","points":7},{"critere":"Distance à zéro de −8 : 8 ; opposé de −3 : +3","points":7}],"dureeMin":6,"corrige":"1. C’est **mercredi** : entre deux négatifs, le plus petit est celui qui a la plus grande distance à zéro. −8 est plus petit que −3, que 0 et que +2.\n\n2. Ordre croissant : les négatifs d’abord (−8 puis −3), puis zéro, puis les positifs : **−8 < −3 < 0 < +2**.\n\n3. La distance à zéro de −8 est le nombre sans son signe : **8**. L’opposé de −3 est le nombre symétrique par rapport à zéro : **+3**."}$exo$::jsonb),
  ('4cc572e1-c45b-5a06-a419-e98582fa33a0'::uuid, 2, 'probleme', $exo${"titre":"Le rectangle du repère","consigne":"Justifie avec le vocabulaire du repère (abscisse, ordonnée).","enonce":"**Situation.** Dans un repère, on place les points A(2 ; 3), B(−3 ; 3) et C(−3 ; −1). On veut placer D pour que ABCD soit un rectangle dont les côtés sont parallèles aux axes.\n\n1. Quelles sont les coordonnées de D ? Justifie.\n2. Calcule les longueurs AB et BC (en unités du repère).\n3. Calcule le périmètre et l’aire du rectangle ABCD.","bareme":[{"critere":"D(2 ; −1) : abscisse de A et ordonnée de C","points":6},{"critere":"AB = 2 + 3 = 5 unités et BC = 3 + 1 = 4 unités","points":7},{"critere":"Périmètre 2 × (5 + 4) = 18 et aire 5 × 4 = 20","points":7}],"dureeMin":10,"corrige":"1. Les côtés sont parallèles aux axes : D est sur la même verticale que A (même abscisse, **2**) et sur la même horizontale que C (même ordonnée, **−1**). Donc **D(2 ; −1)**.\n\n2. A et B ont la même ordonnée : AB est horizontal. Un point est à 2 à droite de l’origine et l’autre à 3 à gauche : AB = 2 + 3 = **5 unités**. B et C ont la même abscisse : BC = 3 + 1 = **4 unités** (l’un est à 3 au-dessus de l’axe, l’autre à 1 en dessous).\n\n3. Périmètre : 2 × (5 + 4) = **18 unités**. Aire : 5 × 4 = **20 unités d’aire**."}$exo$::jsonb),
  ('4cc572e1-c45b-5a06-a419-e98582fa33a0'::uuid, 3, 'probleme', $exo${"titre":"Les altitudes","consigne":"Rédige et justifie chaque comparaison.","enonce":"**Situation.** Quatre lieux ont pour altitudes : A −40 m, B +120 m, C −15 m et D −75 m.\n\n1. Range ces lieux du plus haut au plus bas.\n2. Quelle est la différence d’altitude entre B et D ? Explique ton calcul avec une droite graduée.\n3. Quelle est la différence d’altitude entre A et D ?\n4. Un élève écrit « −75 est plus grand que −40 car 75 est plus grand que 40 ». Explique son erreur.","bareme":[{"critere":"Rangement B, C, A, D","points":4},{"critere":"Écart B–D : 120 + 75 = 195 m (de part et d’autre de zéro)","points":5},{"critere":"Écart A–D : 75 − 40 = 35 m (du même côté de zéro)","points":5},{"critere":"Erreur expliquée : chez les négatifs, la plus grande distance à zéro donne le plus petit nombre","points":6}],"dureeMin":14,"corrige":"1. Du plus haut au plus bas : **B (+120) > C (−15) > A (−40) > D (−75)**.\n\n2. B est à 120 m au-dessus de zéro et D à 75 m en dessous : sur la droite graduée, on additionne les deux distances : 120 + 75 = **195 m**.\n\n3. A et D sont du même côté de zéro : on soustrait les distances à zéro, 75 − 40 = **35 m**.\n\n4. L’élève compare les distances à zéro, pas les nombres. Pour deux négatifs, c’est **la plus petite distance à zéro qui gagne** : −40 est à droite de −75 sur la droite graduée, donc −40 > −75."}$exo$::jsonb),
  ('3a29e274-c9bd-5317-a564-a73bb4d3c07e'::uuid, 1, 'probleme', $exo${"titre":"Trois calculs de relatifs","consigne":"Écris chaque calcul et conclus par une phrase.","enonce":"**Situation.** Voici trois calculs de nombres relatifs à effectuer sans calculatrice. Pour chacun, écris le calcul avec les signes bien visibles, applique la règle du cours (mêmes signes, signes différents, soustraction) et donne le résultat.\n\n1. (−7) + (−5)\n2. (+8) + (−11)\n3. 6 − (−2)","bareme":[{"critere":"(−7) + (−5) = −12 : mêmes signes, on additionne les distances","points":6},{"critere":"(+8) + (−11) = −3 : signes différents, signe du plus fort","points":7},{"critere":"6 − (−2) = 6 + 2 = 8 : soustraire, c’est ajouter l’opposé","points":7}],"dureeMin":6,"corrige":"1. Mêmes signes : on additionne les distances à zéro (7 + 5 = 12) et on garde le signe commun. (−7) + (−5) = **−12**.\n\n2. Signes différents : on soustrait la plus petite distance de la plus grande (11 − 8 = 3) et on garde le signe du plus « fort », ici le négatif. (+8) + (−11) = **−3**.\n\n3. Soustraire, c’est ajouter l’opposé : 6 − (−2) = 6 + (+2) = **8**."}$exo$::jsonb),
  ('3a29e274-c9bd-5317-a564-a73bb4d3c07e'::uuid, 2, 'probleme', $exo${"titre":"Le compte de Malik","consigne":"Écris chaque opération sous forme de somme de relatifs.","enonce":"**Situation.** Le solde du compte de Malik est de +45 €. Il fait successivement : un achat de 60 € (−60), un virement reçu de 100 € (+100), puis un prélèvement de 30 € (−30).\n\n1. Donne le solde après chaque opération.\n2. Écris le bilan complet sous forme d’un seul calcul et vérifie le solde final.\n3. Quel a été le solde le plus bas ? Que signifie ce résultat ?","bareme":[{"critere":"Soldes successifs : −15 €, +85 €, +55 €","points":8},{"critere":"Bilan : 45 + (−60) + 100 + (−30) = 55 €","points":6},{"critere":"Solde le plus bas : −15 €, le compte est à découvert","points":6}],"dureeMin":9,"corrige":"1. Après l’achat : 45 + (−60) = **−15 €**. Après le virement : −15 + 100 = **+85 €**. Après le prélèvement : 85 + (−30) = **+55 €**.\n\n2. Bilan : 45 + (−60) + 100 + (−30). Les positifs : 45 + 100 = 145. Les négatifs : 60 + 30 = 90. Bilan : 145 − 90 = **55 €**, comme au 1.\n\n3. Le solde le plus bas est **−15 €** après l’achat : un solde négatif signifie que le compte est **à découvert** (Malik doit 15 € à la banque)."}$exo$::jsonb),
  ('3a29e274-c9bd-5317-a564-a73bb4d3c07e'::uuid, 3, 'probleme', $exo${"titre":"Simplifier et calculer","consigne":"Écris chaque étape et corrige l’erreur demandée.","enonce":"**Situation.** On étudie plusieurs expressions.\n\n1. Simplifie les signes puis calcule A = 3 + (−5) − (−2) − (+7).\n2. Calcule B = −9 + 14 − 6 + 5 − 8 en regroupant les positifs et les négatifs.\n3. Calcule C = (−4) − (−7) − (+3).\n4. Un élève a écrit 5 − (−3) = 2. Explique son erreur et donne le bon résultat.","bareme":[{"critere":"A = 3 − 5 + 2 − 7 = −7","points":5},{"critere":"B : positifs 19, négatifs 23, résultat −4","points":5},{"critere":"C = −4 + 7 − 3 = 0","points":5},{"critere":"Erreur : il a soustrait 3 au lieu d’ajouter l’opposé ; 5 − (−3) = 8","points":5}],"dureeMin":14,"corrige":"1. + (−5) devient − 5, − (−2) devient + 2, − (+7) devient − 7 : A = 3 − 5 + 2 − 7 = **−7**.\n\n2. Positifs : 14 + 5 = 19. Négatifs : 9 + 6 + 8 = 23. Bilan : 19 − 23 = **−4**.\n\n3. C = −4 + 7 − 3 = 3 − 3 = **0**.\n\n4. L’élève a traité 5 − (−3) comme 5 − 3. Or **soustraire un nombre négatif revient à ajouter** son opposé : 5 − (−3) = 5 + 3 = **8**. Un ordre de grandeur le confirme : retirer une dette augmente la somme."}$exo$::jsonb),
  ('71c00a27-1e6e-5ead-a387-bdb5b1e7cbaf'::uuid, 1, 'probleme', $exo${"titre":"Simplifier et prendre une fraction","consigne":"Justifie chaque simplification.","enonce":"**Situation.** On travaille sur trois fractions.\n\n1. Simplifie 18/30 jusqu’à la fraction irréductible.\n2. Simplifie 12/16 jusqu’à la fraction irréductible.\n3. Combien font les 3/4 de 40 ?","bareme":[{"critere":"18/30 = 3/5 (division par 6)","points":6},{"critere":"12/16 = 3/4 (division par 4)","points":7},{"critere":"3/4 de 40 : 40 ÷ 4 × 3 = 30","points":7}],"dureeMin":6,"corrige":"1. On divise le numérateur et le dénominateur par 6 : 18/30 = **3/5**, qui est irréductible.\n\n2. On divise par 4 : 12/16 = **3/4**, irréductible.\n\n3. Un quart de 40 vaut 40 ÷ 4 = 10, donc les trois quarts valent 10 × 3 = **30**."}$exo$::jsonb),
  ('71c00a27-1e6e-5ead-a387-bdb5b1e7cbaf'::uuid, 2, 'probleme', $exo${"titre":"Les activités de la classe","consigne":"Justifie chaque calcul avec une fraction.","enonce":"**Situation.** Dans une classe de 28 élèves, les 3/7 font du sport et 1/4 font de la musique. Aucun élève ne fait les deux.\n\n1. Combien d’élèves font du sport ?\n2. Combien d’élèves font de la musique ?\n3. Combien d’élèves ne font ni sport ni musique ? Quelle fraction de la classe cela représente-t-il ?","bareme":[{"critere":"Sport : 28 ÷ 7 × 3 = 12 élèves","points":7},{"critere":"Musique : 28 ÷ 4 = 7 élèves","points":6},{"critere":"28 − 12 − 7 = 9 élèves, soit 9/28 (irréductible)","points":7}],"dureeMin":9,"corrige":"1. Un septième de 28 vaut 28 ÷ 7 = 4, donc les 3/7 valent 4 × 3 = **12 élèves**.\n\n2. Un quart de 28 vaut 28 ÷ 4 = **7 élèves**.\n\n3. 12 + 7 = 19 élèves font une activité, donc 28 − 19 = **9 élèves** ne font ni l’un ni l’autre. Cela représente **9/28** de la classe ; 9 et 28 n’ont aucun diviseur commun autre que 1, la fraction est irréductible."}$exo$::jsonb),
  ('71c00a27-1e6e-5ead-a387-bdb5b1e7cbaf'::uuid, 3, 'probleme', $exo${"titre":"Le livre de Léa","consigne":"Rédige avec soin chaque étape.","enonce":"**Situation.** Léa lit un livre de 250 pages. Elle a déjà lu les 3/5 du livre.\n\n1. Parmi 7/8, 9/9, 11/10 et 5/6, laquelle est supérieure à 1 ? Justifie.\n2. Simplifie 42/56.\n3. Combien de pages Léa a-t-elle lues ? Combien lui en reste-t-il ? Quelle fraction du livre cela représente-t-il ?\n4. Léa écrit une fraction dont le dénominateur est 0. Pourquoi est-ce impossible ?","bareme":[{"critere":"11/10 est supérieur à 1 car 11 > 10 ; 9/9 vaut 1","points":4},{"critere":"42/56 = 3/4 (division par 14)","points":5},{"critere":"150 pages lues, 100 restantes, soit 2/5","points":6},{"critere":"a/0 n’existe pas : on ne peut pas partager en 0 part","points":5}],"dureeMin":15,"corrige":"1. Une fraction est supérieure à 1 quand son numérateur est plus grand que son dénominateur : **11/10 > 1**. 9/9 = 1, et 7/8 et 5/6 sont inférieures à 1.\n\n2. On divise haut et bas par 14 : 42/56 = **3/4**.\n\n3. Un cinquième de 250 vaut 50, donc les 3/5 valent 150 : Léa a lu **150 pages**. Il lui reste 250 − 150 = **100 pages**, soit 1 − 3/5 = **2/5** du livre (100 = 50 × 2).\n\n4. Le dénominateur dit en combien de parts on partage le tout : on ne peut pas partager en 0 part. Le dénominateur n’est **jamais nul** : a/0 n’existe pas."}$exo$::jsonb),
  ('fe122bf7-3844-58f3-b627-977e58f5cf5c'::uuid, 1, 'probleme', $exo${"titre":"Trois calculs de fractions","consigne":"Réduis au même dénominateur et simplifie.","enonce":"**Situation.** On étudie trois questions sur les fractions.\n\n1. Compare 3/10 et 3/4.\n2. Calcule 1/2 + 1/4.\n3. Calcule 5/6 − 1/3.","bareme":[{"critere":"3/10 < 3/4 : même numérateur, plus petit dénominateur = plus grand","points":6},{"critere":"1/2 + 1/4 = 2/4 + 1/4 = 3/4","points":7},{"critere":"5/6 − 1/3 = 5/6 − 2/6 = 3/6 = 1/2","points":7}],"dureeMin":6,"corrige":"1. Les deux fractions ont le même numérateur : la plus grande est celle dont le dénominateur est le plus petit. **3/4 > 3/10**.\n\n2. On réduit au dénominateur 4 : 1/2 = 2/4, donc 2/4 + 1/4 = **3/4**.\n\n3. On réduit au dénominateur 6 : 1/3 = 2/6, donc 5/6 − 2/6 = 3/6 = **1/2**."}$exo$::jsonb),
  ('fe122bf7-3844-58f3-b627-977e58f5cf5c'::uuid, 2, 'probleme', $exo${"titre":"La recette de Camille","consigne":"Écris les calculs en réduisant au même dénominateur.","enonce":"**Situation.** Pour une recette, Camille verse 1/4 de litre de lait et 1/3 de litre de crème dans un saladier. Elle dispose d’une bouteille de 1 litre de lait.\n\n1. Quel liquide y a-t-elle mis en plus grande quantité ? Justifie.\n2. Quelle fraction de litre y a-t-il dans le saladier ?\n3. Quelle fraction de la bouteille de 1 litre est vide si elle n’utilise que le lait de la recette ?","bareme":[{"critere":"1/3 = 4/12 > 3/12 = 1/4 : plus de crème","points":7},{"critere":"1/4 + 1/3 = 3/12 + 4/12 = 7/12 L","points":7},{"critere":"1 − 1/4 = 3/4 de la bouteille reste plein, donc 1/4 seulement est vide","points":6}],"dureeMin":9,"corrige":"1. Au dénominateur 12 : 1/4 = 3/12 et 1/3 = 4/12. Comme 4/12 > 3/12, elle a mis **plus de crème** que de lait.\n\n2. 1/4 + 1/3 = 3/12 + 4/12 = **7/12 de litre**. Le résultat est plus grand que chacune des deux fractions, comme il se doit pour une addition.\n\n3. Elle n’utilise que 1/4 de litre de lait : **1/4** de la bouteille est vide, et 1 − 1/4 = 3/4 reste plein."}$exo$::jsonb),
  ('fe122bf7-3844-58f3-b627-977e58f5cf5c'::uuid, 3, 'probleme', $exo${"titre":"Le jardin de M. Morel","consigne":"Rédige chaque calcul, avec une vérification.","enonce":"**Situation.** M. Morel partage son jardin de 200 m² : 2/5 pour le potager, 1/4 pour la pelouse, et le reste pour les fleurs.\n\n1. Quelle fraction du jardin occupent le potager et la pelouse ensemble ?\n2. Quelle fraction du jardin reste pour les fleurs ?\n3. Calcule l’aire de chaque zone en m².\n4. Compare le potager et la pelouse. Vérifie que les trois aires font bien 200 m².","bareme":[{"critere":"2/5 + 1/4 = 8/20 + 5/20 = 13/20","points":5},{"critere":"Fleurs : 1 − 13/20 = 7/20","points":5},{"critere":"Potager 80 m², pelouse 50 m², fleurs 70 m²","points":5},{"critere":"Potager plus grand (8/20 > 5/20) et 80 + 50 + 70 = 200","points":5}],"dureeMin":14,"corrige":"1. Au dénominateur 20 : 2/5 = 8/20 et 1/4 = 5/20. Ensemble : 8/20 + 5/20 = **13/20**.\n\n2. Le jardin entier vaut 20/20 : il reste 20/20 − 13/20 = **7/20** pour les fleurs.\n\n3. Un vingtième de 200 m² vaut 10 m². Potager : 8 × 10 = **80 m²**. Pelouse : 5 × 10 = **50 m²**. Fleurs : 7 × 10 = **70 m²**.\n\n4. 8/20 > 5/20 : le potager est plus grand que la pelouse (80 m² > 50 m²). Vérification : 80 + 50 + 70 = **200 m²**."}$exo$::jsonb),
  ('b56ac3d8-82df-5d7c-87e8-d81acb14bc76'::uuid, 1, 'probleme', $exo${"titre":"Divisions et nombres premiers","consigne":"Écris l’égalité de la division euclidienne.","enonce":"**Situation.** On travaille sur la division euclidienne et les nombres premiers.\n\n1. Effectue la division euclidienne de 47 par 6 et écris l’égalité correspondante.\n2. Effectue la division euclidienne de 100 par 9 et écris l’égalité correspondante.\n3. Parmi 15, 17 et 21, quel est le nombre premier ? Justifie.","bareme":[{"critere":"47 = 6 × 7 + 5, avec un reste inférieur à 6","points":7},{"critere":"100 = 9 × 11 + 1","points":7},{"critere":"17 est premier : seulement deux diviseurs, 1 et 17","points":6}],"dureeMin":6,"corrige":"1. 6 × 7 = 42 et 47 − 42 = 5 : **47 = 6 × 7 + 5**. Le reste 5 est bien inférieur au diviseur 6.\n\n2. 9 × 11 = 99 et 100 − 99 = 1 : **100 = 9 × 11 + 1**.\n\n3. **17** est premier : il n’a que deux diviseurs, 1 et 17. Mais 15 = 3 × 5 et 21 = 3 × 7 ont d’autres diviseurs."}$exo$::jsonb),
  ('b56ac3d8-82df-5d7c-87e8-d81acb14bc76'::uuid, 2, 'probleme', $exo${"titre":"Les boîtes de gâteaux","consigne":"Justifie avec la division euclidienne.","enonce":"**Situation.** Une pâtissière a préparé 85 gâteaux. Elle les range dans des boîtes de 6 gâteaux.\n\n1. Combien de boîtes pleines obtient-elle ? Combien de gâteaux restent ? Écris l’égalité de la division euclidienne.\n2. Combien de boîtes doit-elle utiliser pour ranger tous les gâteaux ?\n3. Le nombre 85 est-il divisible par 5 ? par 3 ? Justifie avec les critères de divisibilité.","bareme":[{"critere":"85 = 6 × 14 + 1 : 14 boîtes pleines et 1 gâteau restant","points":7},{"critere":"15 boîtes au total, car il reste un gâteau","points":7},{"critere":"85 divisible par 5 (finit par 5), pas par 3 (8 + 5 = 13)","points":6}],"dureeMin":9,"corrige":"1. 6 × 14 = 84 et 85 − 84 = 1 : **85 = 6 × 14 + 1**. Elle remplit **14 boîtes** et il reste **1 gâteau**.\n\n2. Il reste un gâteau à ranger : il faut une boîte de plus, soit **15 boîtes**.\n\n3. 85 se termine par 5 : il est **divisible par 5** (85 = 5 × 17). La somme de ses chiffres est 8 + 5 = 13, qui n’est pas divisible par 3 : 85 **n’est pas divisible par 3**."}$exo$::jsonb),
  ('b56ac3d8-82df-5d7c-87e8-d81acb14bc76'::uuid, 3, 'probleme', $exo${"titre":"Décomposer pour simplifier","consigne":"Rédige les décompositions étape par étape.","enonce":"**Situation.** On veut simplifier la fraction 84/90 en utilisant les nombres premiers.\n\n1. Décompose 84 en produit de facteurs premiers.\n2. Décompose 90 en produit de facteurs premiers.\n3. Simplifie la fraction 84/90 en la rendant irréductible.\n4. Le nombre 91 est-il premier ? Justifie.","bareme":[{"critere":"84 = 2² × 3 × 7","points":5},{"critere":"90 = 2 × 3² × 5","points":5},{"critere":"84/90 = 14/15 en barrant 2 × 3 = 6","points":6},{"critere":"91 = 7 × 13 : il n’est pas premier","points":4}],"dureeMin":14,"corrige":"1. 84 = 2 × 42 = 2 × 2 × 21 = 2 × 2 × 3 × 7, soit **2² × 3 × 7**.\n\n2. 90 = 2 × 45 = 2 × 3 × 15 = 2 × 3 × 3 × 5, soit **2 × 3² × 5**.\n\n3. Les facteurs communs sont 2 et 3 (produit 6) : 84/90 = (2 × 2 × 3 × 7)/(2 × 3 × 3 × 5) = 14/15. Fraction **irréductible : 14/15**, car 14 = 2 × 7 et 15 = 3 × 5 n’ont aucun facteur commun.\n\n4. 91 = 7 × 13 : il a d’autres diviseurs que 1 et lui-même, donc **91 n’est pas premier** (piège : il ne se termine pas par un chiffre pair et n’est pas dans la table de 3)."}$exo$::jsonb),
  ('e95b3a51-fe38-5927-a6b6-98dc5276e325'::uuid, 1, 'probleme', $exo${"titre":"Remplacer les lettres","consigne":"Écris les calculs en rétablissant les signes ×.","enonce":"**Situation.** On considère l’expression A = 3x + 5.\n\n1. Calcule A pour x = 4, puis pour x = 0.\n2. Réduis l’expression 5x + 2x.\n3. Écris le périmètre d’un carré de côté c avec une lettre, puis calcule-le pour c = 6,5 cm.","bareme":[{"critere":"A(4) = 17 et A(0) = 5","points":6},{"critere":"5x + 2x = 7x","points":7},{"critere":"Périmètre 4c ; pour c = 6,5 : 26 cm","points":7}],"dureeMin":6,"corrige":"1. Pour x = 4 : A = 3 × 4 + 5 = 12 + 5 = **17**. Pour x = 0 : A = 3 × 0 + 5 = **5**.\n\n2. Les deux termes sont de même nature : 5x + 2x = (5 + 2)x = **7x**.\n\n3. Le périmètre d’un carré de côté c est **4 × c**, qui s’écrit 4c. Pour c = 6,5 cm : 4 × 6,5 = **26 cm**."}$exo$::jsonb),
  ('e95b3a51-fe38-5927-a6b6-98dc5276e325'::uuid, 2, 'probleme', $exo${"titre":"Réduire, développer, factoriser","consigne":"Écris les étapes de chaque calcul.","enonce":"**Situation.** Voici quatre transformations d’écriture à effectuer.\n\n1. Réduis 6x + 4 − 2x + 7.\n2. Développe 3(x + 7).\n3. Développe −(2x − 5).\n4. Factorise 8x + 12.","bareme":[{"critere":"Réduction : 4x + 11","points":5},{"critere":"Développement : 3x + 21","points":5},{"critere":"−(2x − 5) = −2x + 5, tous les signes changent","points":5},{"critere":"Factorisation : 8x + 12 = 4(2x + 3)","points":5}],"dureeMin":9,"corrige":"1. On regroupe les termes en x (6x − 2x = 4x) et les nombres (4 + 7 = 11) : **4x + 11**.\n\n2. k(a + b) = ka + kb : 3(x + 7) = 3 × x + 3 × 7 = **3x + 21**.\n\n3. Le signe moins devant la parenthèse change **tous** les signes à l’intérieur : −(2x − 5) = **−2x + 5**.\n\n4. Le facteur commun à 8x et 12 est 4 : 8x = 4 × 2x et 12 = 4 × 3, donc **8x + 12 = 4(2x + 3)**."}$exo$::jsonb),
  ('e95b3a51-fe38-5927-a6b6-98dc5276e325'::uuid, 3, 'probleme', $exo${"titre":"Un programme de calcul","consigne":"Rédige avec des expressions littérales.","enonce":"**Situation.** Voici un programme de calcul : choisir un nombre x, lui ajouter 3, multiplier le résultat par 2, puis soustraire 6.\n\n1. Applique le programme au nombre 5.\n2. Écris une expression littérale qui donne le résultat pour un nombre x.\n3. Développe et réduis cette expression. Que remarques-tu ?\n4. Léa affirme que 3(x + 2) = 3x + 2. Montre qu’elle a tort avec un contre-exemple.","bareme":[{"critere":"Pour x = 5 : (5 + 3) × 2 − 6 = 10","points":4},{"critere":"Expression 2(x + 3) − 6","points":5},{"critere":"2(x + 3) − 6 = 2x : le programme double le nombre choisi","points":6},{"critere":"Contre-exemple x = 0 : 3(0 + 2) = 6 et 3 × 0 + 2 = 2","points":5}],"dureeMin":14,"corrige":"1. Pour x = 5 : 5 + 3 = 8, 8 × 2 = 16, 16 − 6 = **10**.\n\n2. Ajouter 3 donne x + 3 ; multiplier par 2 donne 2(x + 3) ; soustraire 6 donne **2(x + 3) − 6**.\n\n3. On développe : 2(x + 3) − 6 = 2x + 6 − 6 = **2x**. Le programme donne toujours **le double** du nombre choisi, quel que soit x (avec x = 5 : 10).\n\n4. Pour x = 0 : 3(0 + 2) = 6 alors que 3 × 0 + 2 = 2. Un seul contre-exemple suffit : l’égalité est **fausse** (la bonne écriture développée est 3x + 6)."}$exo$::jsonb),
  ('22abdd2d-34e7-5ef4-ad20-2d15880496a8'::uuid, 1, 'probleme', $exo${"titre":"Frères et sœurs","consigne":"Réponds à partir du tableau.","enonce":"**Situation.** On a demandé à 20 élèves combien ils ont de frères et sœurs. Résultats : 0 frère ou sœur : 4 élèves ; 1 : 8 élèves ; 2 : 5 élèves ; 3 : 3 élèves.\n\n1. Vérifie que l’effectif total est bien 20.\n2. Calcule la fréquence des élèves qui ont 1 frère ou sœur, en pourcentage.\n3. Ce caractère est-il quantitatif ou qualitatif ? Calcule l’étendue de la série.","bareme":[{"critere":"Effectif total : 4 + 8 + 5 + 3 = 20","points":6},{"critere":"Fréquence : 8 ÷ 20 = 0,4 = 40 %","points":7},{"critere":"Quantitatif ; étendue 3 − 0 = 3","points":7}],"dureeMin":6,"corrige":"1. 4 + 8 + 5 + 3 = **20** : l’effectif total est bien 20.\n\n2. Fréquence = effectif de la valeur ÷ effectif total = 8 ÷ 20 = 0,4 = **40 %**.\n\n3. Le nombre de frères et sœurs se compte : le caractère est **quantitatif**. Étendue = plus grande valeur − plus petite valeur = 3 − 0 = **3**."}$exo$::jsonb),
  ('22abdd2d-34e7-5ef4-ad20-2d15880496a8'::uuid, 2, 'probleme', $exo${"titre":"Les sports du club","consigne":"Justifie le choix du graphique.","enonce":"**Situation.** Dans un club de 30 élèves, on compte : 12 élèves en football, 9 en danse, 6 en natation et 3 en judo.\n\n1. Calcule la fréquence de chaque sport en pourcentage.\n2. On veut un diagramme circulaire. Calcule l’angle de chaque secteur et vérifie leur somme.\n3. Quel autre graphique conviendrait pour un caractère qualitatif comme le sport pratiqué ?","bareme":[{"critere":"Fréquences : 40 %, 30 %, 20 % et 10 %","points":7},{"critere":"Angles : 144°, 108°, 72°, 36°, de somme 360°","points":7},{"critere":"Diagramme en barres (caractère qualitatif)","points":6}],"dureeMin":9,"corrige":"1. Fréquence = effectif ÷ 30 : football 12/30 = **40 %**, danse 9/30 = **30 %**, natation 6/30 = **20 %**, judo 3/30 = **10 %**.\n\n2. Angle = fréquence × 360° : football 0,40 × 360 = **144°** ; danse 0,30 × 360 = **108°** ; natation 0,20 × 360 = **72°** ; judo 0,10 × 360 = **36°**. Somme : 144 + 108 + 72 + 36 = 360°, ce qui vérifie le travail.\n\n3. Le sport pratiqué est un caractère qualitatif : on peut aussi le représenter par un **diagramme en barres**."}$exo$::jsonb),
  ('22abdd2d-34e7-5ef4-ad20-2d15880496a8'::uuid, 3, 'probleme', $exo${"titre":"Étendue et graphique trompeur","consigne":"Rédige avec méthode.","enonce":"**Situation.** Une série de cinq températures est : 21 °C, 14 °C, 18 °C, 25 °C, 17 °C. Par ailleurs, un journal montre un graphique en barres de ses ventes : la barre de mars représente 92 exemplaires et celle d’avril 96 exemplaires, mais l’axe vertical commence à 90 exemplaires et non à 0.\n\n1. Calcule l’étendue de la série de températures.\n2. Sur le graphique, les hauteurs visibles des barres sont 2 et 6 unités. Que semble-t-il se passer d’avril par rapport à mars ? Est-ce la réalité ?\n3. Quelle vérification aurait dû faire le lecteur avant de comparer les barres ?\n4. Quelle représentation choisir pour suivre l’évolution des ventes mois après mois ?","bareme":[{"critere":"Étendue : 25 − 14 = 11 °C","points":4},{"critere":"Les ventes semblent tripler alors que la hausse réelle n’est que de 4 exemplaires","points":6},{"critere":"Il faut vérifier si l’axe vertical part bien de zéro","points":6},{"critere":"Une courbe pour une évolution dans le temps","points":4}],"dureeMin":14,"corrige":"1. Étendue = plus grande valeur − plus petite valeur = 25 − 14 = **11 °C**.\n\n2. La barre d’avril paraît 3 fois plus haute que celle de mars (6 contre 2), comme si les ventes avaient triplé. C’est trompeur : les ventes passent de 92 à 96, soit **4 exemplaires de plus** seulement.\n\n3. Avant de comparer les hauteurs, le lecteur doit **vérifier que l’axe vertical part bien de zéro** (et lire le titre, les axes et les unités). Un axe tronqué déforme la perception sans falsifier aucun chiffre.\n\n4. Pour une évolution dans le temps, on choisit une **courbe**."}$exo$::jsonb),
  ('4f19059b-1a4a-5ca0-a330-575e1f934b20'::uuid, 1, 'probleme', $exo${"titre":"Les notes de Sarah","consigne":"Écris les calculs en entier.","enonce":"**Situation.** Sarah a obtenu les notes suivantes en mathématiques : 12, 15, 9, 16 et 13.\n\n1. Calcule sa moyenne.\n2. Calcule l’étendue de ses notes.\n3. La moyenne pouvait-elle être 17 ? Justifie sans calculer.","bareme":[{"critere":"Moyenne : 65 ÷ 5 = 13","points":8},{"critere":"Étendue : 16 − 9 = 7","points":6},{"critere":"Non : la moyenne est comprise entre 9 et 16","points":6}],"dureeMin":6,"corrige":"1. Somme : 12 + 15 + 9 + 16 + 13 = 65. Moyenne : 65 ÷ 5 = **13**.\n\n2. Étendue = plus grande note − plus petite note = 16 − 9 = **7**.\n\n3. Une moyenne est toujours **comprise entre la plus petite et la plus grande valeur** de la série, ici entre 9 et 16. Elle ne peut donc pas valoir 17."}$exo$::jsonb),
  ('4f19059b-1a4a-5ca0-a330-575e1f934b20'::uuid, 2, 'probleme', $exo${"titre":"Le bulletin d’Inès","consigne":"Écris la formule de la moyenne pondérée avant de calculer.","enonce":"**Situation.** Inès a en maths 14 (coefficient 4), en français 10 (coefficient 3), en anglais 16 (coefficient 2) et en sport 18 (coefficient 1).\n\n1. Calcule la somme des coefficients.\n2. Calcule sa moyenne pondérée.\n3. Calcule aussi la moyenne simple des quatre notes. Pourquoi est-elle différente ?","bareme":[{"critere":"Somme des coefficients : 10","points":5},{"critere":"Moyenne pondérée : 136 ÷ 10 = 13,6","points":9},{"critere":"Moyenne simple 14,5, différente car les coefficients pèsent différemment","points":6}],"dureeMin":9,"corrige":"1. 4 + 3 + 2 + 1 = **10**.\n\n2. 14 × 4 = 56 ; 10 × 3 = 30 ; 16 × 2 = 32 ; 18 × 1 = 18. Somme : 56 + 30 + 32 + 18 = 136. Moyenne : 136 ÷ 10 = **13,6**.\n\n3. Moyenne simple : (14 + 10 + 16 + 18) ÷ 4 = 58 ÷ 4 = **14,5**. Elle est plus élevée car elle donne le même poids à toutes les notes : en pondérant, le français (10) compte trois fois et le sport (18) une seule fois."}$exo$::jsonb),
  ('4f19059b-1a4a-5ca0-a330-575e1f934b20'::uuid, 3, 'probleme', $exo${"titre":"Deux classes, une moyenne","consigne":"Rédige en repassant par les totaux.","enonce":"**Situation.** La classe de 5e A compte 24 élèves et sa moyenne au contrôle est de 11. La classe de 5e B compte 16 élèves et sa moyenne est de 14.\n\n1. Calcule la somme des notes de chaque classe.\n2. Calcule la moyenne des 40 élèves.\n3. Un élève affirme : « la moyenne est (11 + 14) ÷ 2 = 12,5 ». Explique son erreur.\n4. Dans quel cas aurait-il eu raison ?","bareme":[{"critere":"Sommes : 24 × 11 = 264 et 16 × 14 = 224","points":5},{"critere":"Moyenne globale : 488 ÷ 40 = 12,2","points":5},{"critere":"Erreur : ce n’est pas la moyenne des moyennes, les effectifs diffèrent","points":5},{"critere":"Il aurait raison si les deux classes avaient le même effectif","points":5}],"dureeMin":14,"corrige":"1. Somme des notes de 5e A : 24 × 11 = **264**. Somme des notes de 5e B : 16 × 14 = **224**.\n\n2. Moyenne des 40 élèves : (264 + 224) ÷ 40 = 488 ÷ 40 = **12,2**.\n\n3. La moyenne de plusieurs groupes **n’est pas la moyenne des moyennes** : la classe de 24 élèves pèse plus que celle de 16. L’élève a donné le même poids aux deux classes ; on trouve 12,2 et non 12,5.\n\n4. Il aurait eu raison si les deux classes avaient **le même effectif**, par exemple 20 élèves chacune : ((20 × 11) + (20 × 14)) ÷ 40 = 12,5."}$exo$::jsonb),
  ('dc5ac461-1fee-5788-a97c-a794180325b5'::uuid, 1, 'probleme', $exo${"titre":"Premières formules","consigne":"Écris les formules telles qu’on les saisirait dans le tableur.","enonce":"**Situation.** Dans un tableur, les cellules A1, A2 et A3 contiennent les nombres 5, 7 et 9.\n\n1. Écris la formule qui calcule la somme de ces trois cellules et donne son résultat.\n2. Écris la formule qui calcule leur moyenne et donne son résultat.\n3. Que désigne A1:A3 ? Par quel signe commence toute formule ?","bareme":[{"critere":"=SOMME(A1:A3) donne 21","points":7},{"critere":"=MOYENNE(A1:A3) donne 7","points":7},{"critere":"A1:A3 est une plage (cellules A1, A2, A3) ; une formule commence par =","points":6}],"dureeMin":6,"corrige":"1. **=SOMME(A1:A3)** donne 5 + 7 + 9 = **21**.\n\n2. **=MOYENNE(A1:A3)** donne 21 ÷ 3 = **7**.\n\n3. **A1:A3** est une **plage** : elle désigne toutes les cellules de A1 à A3 (A1, A2 et A3). Toute formule commence **toujours par le signe =**."}$exo$::jsonb),
  ('dc5ac461-1fee-5788-a97c-a794180325b5'::uuid, 2, 'probleme', $exo${"titre":"Les notes dans le tableur","consigne":"Écris les formules et leurs résultats.","enonce":"**Situation.** Les cellules B2 à B6 contiennent les notes 8, 12, 15, 9 et 16.\n\n1. Écris la formule de la moyenne de ces notes et donne son résultat.\n2. Écris la formule de l’étendue avec MAX et MIN et donne son résultat. Quelle formule compte le nombre de notes ?\n3. La cellule C2 contient =B2+B3. On la recopie une ligne plus bas dans C3. Que devient-elle ?","bareme":[{"critere":"=MOYENNE(B2:B6) donne 12","points":7},{"critere":"=MAX(B2:B6)−MIN(B2:B6) donne 8 ; =NB(B2:B6) donne 5","points":7},{"critere":"La formule devient =B3+B4 : les références se décalent","points":6}],"dureeMin":9,"corrige":"1. **=MOYENNE(B2:B6)** : (8 + 12 + 15 + 9 + 16) ÷ 5 = 60 ÷ 5 = **12**.\n\n2. **=MAX(B2:B6)−MIN(B2:B6)** donne 16 − 8 = **8**, l’étendue. **=NB(B2:B6)** compte les valeurs et donne **5**.\n\n3. Les références relatives se décalent à la recopie : **=B2+B3** devient **=B3+B4** dans la cellule C3."}$exo$::jsonb),
  ('dc5ac461-1fee-5788-a97c-a794180325b5'::uuid, 3, 'probleme', $exo${"titre":"Le tableau des effectifs","consigne":"Rédige avec les formules et explique le rôle des dollars.","enonce":"**Situation.** Dans un tableur, les cellules B2 à B5 contiennent les effectifs 4, 8, 5 et 3. On veut calculer l’effectif total dans B6, puis les fréquences dans la colonne C.\n\n1. Écris la formule de B6 et donne son résultat.\n2. Écris la formule de la fréquence en C2, pensée pour être recopiée vers le bas, et explique le rôle des dollars.\n3. Donne les valeurs des fréquences en C2 à C5 et vérifie leur somme.\n4. Quelle vérification faut-il faire avant de faire confiance à toute la colonne ?","bareme":[{"critere":"B6 : =SOMME(B2:B5) donne 20","points":4},{"critere":"C2 : =B2/$B$6 ; les dollars figent la référence du total à la recopie","points":6},{"critere":"Fréquences 0,2 ; 0,4 ; 0,25 ; 0,15 de somme 1","points":5},{"critere":"Vérifier une valeur à la main avant de faire confiance à la colonne","points":5}],"dureeMin":14,"corrige":"1. **=SOMME(B2:B5)** donne 4 + 8 + 5 + 3 = **20**.\n\n2. **=B2/$B$6**. Les dollars rendent la référence **absolue** : à la recopie, B2 devient B3, B4, B5 (elle se décale) mais $B$6 reste figée sur le total. Sans dollars, B6 deviendrait B7, une cellule vide, et les résultats seraient faux.\n\n3. Fréquences : 4 ÷ 20 = **0,2** ; 8 ÷ 20 = **0,4** ; 5 ÷ 20 = **0,25** ; 3 ÷ 20 = **0,15**. Somme : 0,2 + 0,4 + 0,25 + 0,15 = **1**, soit 100 %.\n\n4. Avant de faire confiance à une colonne entière de résultats, on **vérifie une valeur à la main** : un calcul faux peut sembler parfaitement plausible."}$exo$::jsonb),
  ('fa9a49f1-aad9-54c2-a078-5842d14fda23'::uuid, 1, 'probleme', $exo${"titre":"Le lancer de dé","consigne":"Donne chaque probabilité sous forme de fraction irréductible.","enonce":"**Situation.** On lance un dé équilibré à six faces numérotées de 1 à 6.\n\n1. Quelle est la probabilité d’obtenir un 6 ?\n2. Quelle est la probabilité d’obtenir un nombre impair ?\n3. Quelle est la probabilité d’obtenir un nombre supérieur à 4 ?","bareme":[{"critere":"P(6) = 1/6","points":6},{"critere":"P(impair) = 3/6 = 1/2","points":7},{"critere":"P(supérieur à 4) = 2/6 = 1/3, avec les issues 5 et 6","points":7}],"dureeMin":6,"corrige":"Toutes les faces ont la même chance : c’est une situation d’équiprobabilité, P = issues favorables ÷ issues possibles (6 possibles).\n\n1. Une seule issue favorable : P(6) = **1/6**.\n\n2. Les nombres impairs sont 1, 3 et 5 : P = 3/6 = **1/2**.\n\n3. Les nombres supérieurs à 4 sont 5 et 6 : P = 2/6 = **1/3**."}$exo$::jsonb),
  ('fa9a49f1-aad9-54c2-a078-5842d14fda23'::uuid, 2, 'probleme', $exo${"titre":"Le sac de jetons","consigne":"Justifie avec le nombre d’issues favorables et possibles.","enonce":"**Situation.** Un sac contient 10 jetons indiscernables au toucher : 5 rouges, 3 bleus et 2 verts. On tire un jeton au hasard.\n\n1. Quelle est la probabilité de tirer un jeton rouge ?\n2. Quelle est la probabilité de tirer un jeton bleu ?\n3. Quelle est la probabilité de ne pas tirer un jeton vert ? Explique avec l’événement contraire.","bareme":[{"critere":"P(rouge) = 5/10 = 1/2","points":6},{"critere":"P(bleu) = 3/10","points":7},{"critere":"P(non vert) = 1 − 2/10 = 8/10 = 4/5","points":7}],"dureeMin":9,"corrige":"1. 5 issues favorables sur 10 : P(rouge) = 5/10 = **1/2**.\n\n2. 3 issues favorables sur 10 : P(bleu) = **3/10**.\n\n3. L’événement contraire de « ne pas tirer un vert » est « tirer un vert », de probabilité 2/10. Donc P(non vert) = 1 − 2/10 = 8/10 = **4/5**. On retrouve le même résultat en comptant les 5 + 3 = 8 jetons non verts."}$exo$::jsonb),
  ('fa9a49f1-aad9-54c2-a078-5842d14fda23'::uuid, 3, 'probleme', $exo${"titre":"La roue de la chance","consigne":"Rédige en distinguant probabilité et fréquence.","enonce":"**Situation.** Une roue est partagée en 8 secteurs identiques : 1 doré, 3 rouges et 4 bleus. On la fait tourner et on note la couleur du secteur désigné.\n\n1. Quelle est la probabilité d’obtenir le secteur doré ?\n2. Quelle est la probabilité d’obtenir un secteur rouge ou doré ? Et de ne pas obtenir un secteur bleu ?\n3. Sur 40 tours, le doré sort 7 fois. Calcule la fréquence observée et compare-la à la probabilité. Comment l’expliques-tu ?\n4. Le doré n’est pas sorti pendant 5 tours de suite. Est-il plus probable au tour suivant ?","bareme":[{"critere":"P(doré) = 1/8","points":4},{"critere":"P(rouge ou doré) = 4/8 = 1/2 ; P(non bleu) = 1 − 4/8 = 1/2","points":4},{"critere":"Fréquence 7/40 = 0,175 contre 0,125 ; elles se rapprochent avec un grand nombre d’essais","points":6},{"critere":"Non : la roue n’a pas de mémoire, la probabilité reste 1/8","points":6}],"dureeMin":14,"corrige":"1. Un secteur doré sur 8, tous de même taille : **P(doré) = 1/8**.\n\n2. Rouge ou doré : 3 + 1 = 4 secteurs sur 8, soit **1/2**. Ne pas obtenir un bleu : 1 − 4/8 = **1/2** (les 4 secteurs non bleus).\n\n3. La fréquence observée est 7/40 = **0,175**, tandis que la probabilité est 1/8 = 0,125. Sur peu d’essais, fréquence et probabilité ne coïncident pas. Plus on répète l’expérience, plus la fréquence **se rapproche** de la probabilité (loi des grands nombres).\n\n4. **Non** : la roue n’a pas de mémoire. Même après 5 tours sans doré, la probabilité reste **1/8** au tour suivant."}$exo$::jsonb),
  ('e055c662-f098-5023-a349-5df321bc83be'::uuid, 1, 'probleme', $exo${"titre":"Le prix des pommes","consigne":"Utilise la méthode de ton choix et explique-la.","enonce":"**Situation.** 4 kg de pommes coûtent 10 €. Le prix est proportionnel à la masse.\n\n1. Combien coûtent 12 kg de pommes ?\n2. Combien coûtent 2 kg de pommes ?\n3. Quel est le prix d’un kilogramme (le coefficient de proportionnalité) ?","bareme":[{"critere":"12 kg coûtent 30 € (linéarité : masse × 3, prix × 3)","points":7},{"critere":"2 kg coûtent 5 € (moitié de la masse, moitié du prix)","points":6},{"critere":"Prix du kilogramme : 10 ÷ 4 = 2,5 €","points":7}],"dureeMin":6,"corrige":"1. 12 = 4 × 3 : la masse est multipliée par 3, le prix aussi. 10 × 3 = **30 €**.\n\n2. 2 kg est la moitié de 4 kg : le prix est divisé par 2, 10 ÷ 2 = **5 €**.\n\n3. Le coefficient est le prix d’un kilogramme : 10 ÷ 4 = **2,5 € par kg**. On retrouve 12 × 2,5 = 30 € et 2 × 2,5 = 5 €."}$exo$::jsonb),
  ('e055c662-f098-5023-a349-5df321bc83be'::uuid, 2, 'probleme', $exo${"titre":"La recette pour dix personnes","consigne":"Justifie avec le produit en croix ou le coefficient.","enonce":"**Situation.** Une recette pour 4 personnes demande 300 g de farine et 120 g de beurre. Les quantités sont proportionnelles au nombre de personnes.\n\n1. Quelle quantité de farine faut-il pour 10 personnes ?\n2. Quelle quantité de beurre faut-il pour 10 personnes ?\n3. Quelle quantité de farine faut-il pour 6 personnes ?","bareme":[{"critere":"Farine pour 10 personnes : 300 × 10 ÷ 4 = 750 g","points":7},{"critere":"Beurre pour 10 personnes : 120 × 10 ÷ 4 = 300 g","points":7},{"critere":"Farine pour 6 personnes : 300 × 6 ÷ 4 = 450 g","points":6}],"dureeMin":9,"corrige":"1. Produit en croix : 4 × x = 300 × 10, donc x = 3 000 ÷ 4 = **750 g** de farine. (Avec le coefficient : 300 ÷ 4 = 75 g par personne, 75 × 10 = 750.)\n\n2. 120 ÷ 4 = 30 g de beurre par personne, donc 30 × 10 = **300 g** de beurre.\n\n3. 75 g de farine par personne, donc 75 × 6 = **450 g** de farine. Vérification : plus de personnes donne plus de farine, 450 g est compris entre 300 g (4 personnes) et 750 g (10 personnes)."}$exo$::jsonb),
  ('e055c662-f098-5023-a349-5df321bc83be'::uuid, 3, 'probleme', $exo${"titre":"Trois méthodes et un piège","consigne":"Rédige en précisant la méthode utilisée.","enonce":"**Situation.** 7 cahiers coûtent 10,50 €. Le prix est proportionnel au nombre de cahiers. Par ailleurs, une salle de sport propose un tarif : 5 € d’abonnement plus 2 € par entrée.\n\n1. Calcule le prix d’un cahier (passage à l’unité), puis le prix de 12 cahiers.\n2. Calcule le prix de 9 cahiers avec un produit en croix.\n3. Avec le tarif de la salle de sport, calcule le prix de 3 entrées et de 6 entrées.\n4. Ce tarif est-il proportionnel au nombre d’entrées ? Justifie.","bareme":[{"critere":"Un cahier 1,5 € ; 12 cahiers 18 €","points":4},{"critere":"Produit en croix : 7 × x = 10,5 × 9, donc x = 13,5 €","points":5},{"critere":"3 entrées : 11 € et 6 entrées : 17 €","points":5},{"critere":"Non proportionnel : 11 × 2 = 22, différent de 17","points":6}],"dureeMin":14,"corrige":"1. 10,50 ÷ 7 = **1,50 €** le cahier, donc 12 cahiers : 12 × 1,50 = **18 €**.\n\n2. Produit en croix : 7 × x = 10,50 × 9 = 94,50, donc x = 94,50 ÷ 7 = **13,50 €** (contrôle : 9 × 1,50 = 13,50).\n\n3. 3 entrées : 5 + 3 × 2 = **11 €**. 6 entrées : 5 + 6 × 2 = **17 €**.\n\n4. Le tarif **n’est pas proportionnel** : 6 entrées est le double de 3 entrées, or le prix ne double pas (11 × 2 = 22 mais on paie 17 €). L’abonnement fixe casse la proportionnalité : un produit en croix donnerait ici un résultat faux."}$exo$::jsonb),
  ('4e4ec660-7823-5a59-b569-31199749a5cf'::uuid, 1, 'probleme', $exo${"titre":"Calculer un pourcentage","consigne":"Écris le calcul et le résultat.","enonce":"**Situation.** Calcule mentalement en posant ton raisonnement.\n\n1. Calcule 25 % de 80 €.\n2. Calcule 10 % de 250 €.\n3. Calcule 50 % de 36 kg.","bareme":[{"critere":"25 % de 80 = 20 € (80 ÷ 4)","points":6},{"critere":"10 % de 250 = 25 € (250 ÷ 10)","points":7},{"critere":"50 % de 36 = 18 kg (36 ÷ 2)","points":7}],"dureeMin":6,"corrige":"1. 25 % = 1/4 : 80 ÷ 4 = **20 €**.\n\n2. 10 % = 1/10 : 250 ÷ 10 = **25 €**.\n\n3. 50 % = 1/2 : 36 ÷ 2 = **18 kg**.\n\nOn peut aussi multiplier par le coefficient : 80 × 0,25 = 20 ; 250 × 0,10 = 25 ; 36 × 0,50 = 18."}$exo$::jsonb),
  ('4e4ec660-7823-5a59-b569-31199749a5cf'::uuid, 2, 'probleme', $exo${"titre":"Les soldes","consigne":"Justifie avec les coefficients ou les pourcentages.","enonce":"**Situation.** Pendant les soldes, un jean à 60 € est réduit de 20 % et un sweat à 45 € est réduit de 10 %.\n\n1. Calcule le prix du jean soldé.\n2. Calcule le prix du sweat soldé.\n3. Calcule le prix total des deux articles soldés et l’économie réalisée.","bareme":[{"critere":"Jean : 60 × 0,80 = 48 €","points":7},{"critere":"Sweat : 45 × 0,90 = 40,50 €","points":7},{"critere":"Total 88,50 € et économie 16,50 €","points":6}],"dureeMin":9,"corrige":"1. Réduction de 20 % : coefficient 1 − 0,20 = 0,80. 60 × 0,80 = **48 €**.\n\n2. Réduction de 10 % : coefficient 0,90. 45 × 0,90 = **40,50 €**.\n\n3. Total soldé : 48 + 40,50 = **88,50 €**. Prix avant soldes : 60 + 45 = 105 €. Économie : 105 − 88,50 = **16,50 €**."}$exo$::jsonb),
  ('4e4ec660-7823-5a59-b569-31199749a5cf'::uuid, 3, 'probleme', $exo${"titre":"Quatre problèmes de pourcentages","consigne":"Rédige chaque réponse avec une phrase de conclusion.","enonce":"**Situation.** Voici quatre questions.\n\n1. Dans une classe de 25 élèves, il y a 15 filles. Quel pourcentage de la classe représentent-elles ?\n2. Dans un club, 12 élèves représentent 40 % des adhérents. Combien y a-t-il d’adhérents ?\n3. Un prix augmente de 10 %, puis de nouveau de 10 %. Par quel coefficient est-il multiplié ? Est-ce une hausse de 20 % ? Justifie.\n4. Un article à 50 € augmente de 20 %. Quel est son nouveau prix ?","bareme":[{"critere":"Filles : 15 ÷ 25 = 0,6 = 60 %","points":4},{"critere":"Adhérents : 12 ÷ 0,40 = 30","points":4},{"critere":"Coefficient 1,1 × 1,1 = 1,21, soit +21 % et non +20 %","points":6},{"critere":"Nouveau prix : 50 × 1,2 = 60 €","points":6}],"dureeMin":14,"corrige":"1. (partie ÷ tout) × 100 : 15 ÷ 25 = 0,6, soit **60 %** de la classe.\n\n2. On cherche le tout : 12 ÷ 0,40 = **30 adhérents**.\n\n3. Chaque hausse multiplie par 1,1. Les coefficients se multiplient : 1,1 × 1,1 = **1,21**, soit une hausse de **21 %**. Les pourcentages successifs ne s’additionnent pas : la deuxième hausse s’applique sur un prix déjà augmenté (avec 100 € : 110 € puis 121 €).\n\n4. Augmenter de 20 %, c’est multiplier par 1,20 : 50 × 1,20 = **60 €**."}$exo$::jsonb),
  ('6a3f78a6-751a-5a50-8aa1-d1864977da6e'::uuid, 1, 'probleme', $exo${"titre":"Lire une carte","consigne":"Convertis toutes les distances dans la même unité avant de calculer.","enonce":"**Situation.** Une carte est à l’échelle 1/25 000.\n\n1. Deux villages sont distants de 5 cm sur la carte. Quelle est la distance réelle en km ?\n2. Deux ponts sont distants de 6 cm sur la carte. Quelle est la distance réelle en km ?\n3. Une randonnée de 2,5 km doit être dessinée sur la carte. Quelle longueur aura-t-elle sur la carte ?","bareme":[{"critere":"5 cm : 125 000 cm réels, soit 1,25 km","points":6},{"critere":"6 cm : 150 000 cm réels, soit 1,5 km","points":7},{"critere":"2,5 km = 250 000 cm ; 250 000 ÷ 25 000 = 10 cm","points":7}],"dureeMin":6,"corrige":"1. Distance réelle : 5 × 25 000 = 125 000 cm = 1 250 m = **1,25 km**.\n\n2. 6 × 25 000 = 150 000 cm = 1 500 m = **1,5 km**.\n\n3. 2,5 km = 2 500 m = 250 000 cm. Sur la carte : 250 000 ÷ 25 000 = **10 cm**. (Piège : 1 km = 100 000 cm et non 1 000 cm.)"}$exo$::jsonb),
  ('6a3f78a6-751a-5a50-8aa1-d1864977da6e'::uuid, 2, 'probleme', $exo${"titre":"Partager selon un ratio","consigne":"Suis les étapes du partage en parts.","enonce":"**Situation.** Deux amis, Élio et Nora, se partagent 84 € selon le ratio 3 : 4 (3 parts pour Élio, 4 parts pour Nora).\n\n1. Combien y a-t-il de parts en tout ? Quelle est la valeur d’une part ?\n2. Quelle somme reçoit chacun ?\n3. Quelle fraction du total reçoit Élio ? Vérifie ton résultat.","bareme":[{"critere":"7 parts en tout, une part vaut 12 €","points":7},{"critere":"Élio 36 € et Nora 48 €","points":7},{"critere":"Élio reçoit 3/7 du total ; vérification 36 + 48 = 84","points":6}],"dureeMin":9,"corrige":"1. 3 + 4 = **7 parts**. Une part vaut 84 ÷ 7 = **12 €**.\n\n2. Élio : 3 × 12 = **36 €**. Nora : 4 × 12 = **48 €**.\n\n3. Élio reçoit **3/7** du total (le dénominateur est le total des parts, pas 4). Vérification : 36 + 48 = 84 €, et 3/7 de 84 = 84 ÷ 7 × 3 = 36 €."}$exo$::jsonb),
  ('6a3f78a6-751a-5a50-8aa1-d1864977da6e'::uuid, 3, 'probleme', $exo${"titre":"Échelles et ratios","consigne":"Rédige chaque calcul avec ses conversions.","enonce":"**Situation.** Sur un plan, un trajet mesure 8 cm alors qu’il mesure 2 km dans la réalité.\n\n1. Calcule l’échelle du plan et écris-la sous la forme 1/…\n2. Sur ce plan, un autre trajet mesure 12 cm. Quelle est sa longueur réelle en km ?\n3. Trois personnes se partagent 180 € selon le ratio 1 : 2 : 3. Quelle somme reçoit chacune ?\n4. Un insecte est dessiné à l’échelle 5 (agrandissement) et mesure 6 cm sur le dessin. Quelle est sa taille réelle ?","bareme":[{"critere":"Échelle : 8 ÷ 200 000 = 1/25 000","points":5},{"critere":"12 cm sur le plan : 300 000 cm, soit 3 km","points":5},{"critere":"6 parts de 30 € : 30 €, 60 € et 90 €","points":5},{"critere":"Taille réelle : 6 ÷ 5 = 1,2 cm","points":5}],"dureeMin":14,"corrige":"1. On convertit 2 km = 200 000 cm. Échelle = distance sur le plan ÷ distance réelle = 8 ÷ 200 000 = 1/25 000. L’échelle est **1/25 000**.\n\n2. 12 × 25 000 = 300 000 cm = 3 000 m = **3 km**.\n\n3. Nombre de parts : 1 + 2 + 3 = 6. Une part : 180 ÷ 6 = 30 €. Les trois personnes reçoivent **30 €, 60 € et 90 €** (vérification : 30 + 60 + 90 = 180).\n\n4. L’échelle 5 est supérieure à 1 : c’est un **agrandissement**. La taille réelle est 6 ÷ 5 = **1,2 cm**."}$exo$::jsonb),
  ('de7dec4c-a53a-5f6e-8d1b-702d6e9ae51d'::uuid, 1, 'application', $exo${"titre":"Quelle forme d’énergie ?","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Pour chaque situation, indique la forme d’énergie principale mise en jeu.\n\n1. Une balle de tennis lancée à toute vitesse.\n2. Un livre posé en haut d’une étagère.\n3. Une barre de céréales.\n4. Quelle est l’unité légale de l’énergie ?","bareme":[{"critere":"Les trois formes citées correctement (cinétique, de position, chimique)","points":12},{"critere":"Unité légale : le joule (J)","points":4},{"critere":"Formulations claires, liées au mouvement, à la hauteur, aux aliments","points":4}],"dureeMin":6,"corrige":"1. **Énergie cinétique** : la balle est en mouvement.\n2. **Énergie de position** : le livre est situé en hauteur (Epp = m × g × h).\n3. **Énergie chimique** : les aliments stockent de l’énergie liée aux liaisons entre atomes.\n4. L’unité légale de l’énergie est le **joule (J)**."}$exo$::jsonb),
  ('de7dec4c-a53a-5f6e-8d1b-702d6e9ae51d'::uuid, 2, 'application', $exo${"titre":"Énergie de position d’une pierre","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Dans un jardin, Malo soulève une pierre de masse **m = 4 kg** et la pose sur un muret de **h = 0,50 m**. On prend g = 10 N/kg.\n\n1. Quelle forme d’énergie la pierre possède-t-elle sur le muret ? De quelles grandeurs dépend-elle ?\n2. Calcule l’énergie de position de la pierre (formule Epp = m × g × h).\n3. Malo pose ensuite la pierre sur un mur deux fois plus haut. Que devient son énergie de position ?","bareme":[{"critere":"Forme : énergie de position, dépend de la masse et de la hauteur","points":5},{"critere":"Calcul Epp = 4 × 10 × 0,5 = 20 J avec unité","points":9},{"critere":"Énergie doublée si la hauteur double, justifiée par la proportionnalité","points":6}],"dureeMin":10,"corrige":"1. La pierre possède de l’**énergie de position**, qui dépend de sa **masse** et de sa **hauteur**.\n2. Epp = m × g × h = 4 × 10 × 0,5 = **20 J**.\n3. L’énergie de position est proportionnelle à la hauteur : avec une hauteur **doublée** (1 m), Epp = 4 × 10 × 1 = **40 J**, donc elle est **doublée**."}$exo$::jsonb),
  ('de7dec4c-a53a-5f6e-8d1b-702d6e9ae51d'::uuid, 3, 'application', $exo${"titre":"Le radiateur et la barre chocolatée","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Léa lit ces informations : un radiateur de 1 000 W fonctionne 2 h ; une barre chocolatée apporte environ 10⁶ J. On rappelle que 1 kWh = 3,6 × 10⁶ J.\n\n1. Calcule l’énergie consommée par le radiateur en kWh puis en joules.\n2. Compare-la à l’énergie de la barre chocolatée : combien de barres correspondent à cette énergie ?\n3. Le radiateur est alimenté par du gaz naturel. Distingue la **source** d’énergie et la **forme** d’énergie mise en jeu, puis dis si cette source est renouvelable.","bareme":[{"critere":"Énergie du radiateur : 1 kW × 2 h = 2 kWh, convertie en 7,2 × 10⁶ J","points":7},{"critere":"Comparaison : 7,2 × 10⁶ ÷ 10⁶ ≈ 7 barres","points":5},{"critere":"Source (gaz) et forme (chimique) bien distinguées","points":5},{"critere":"Source non renouvelable justifiée (réserves limitées)","points":3}],"dureeMin":15,"corrige":"1. E = P × t = 1 kW × 2 h = **2 kWh**. En joules : 2 × 3,6 × 10⁶ = **7,2 × 10⁶ J**.\n2. 7,2 × 10⁶ ÷ 10⁶ ≈ **7 barres chocolatées** (environ 7).\n3. La **source** est le gaz naturel ; la **forme** d’énergie qu’il contient est l’énergie **chimique**. Le gaz est une source **non renouvelable** : ses réserves sont limitées et ne se reconstituent pas à l’échelle humaine."}$exo$::jsonb),
  ('5c602e2c-32c5-5631-ab24-4db2daaad74e'::uuid, 1, 'application', $exo${"titre":"Trois convertisseurs","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Pour chaque appareil, donne la conversion d’énergie réalisée (forme d’entrée → forme utile).\n\n1. Un panneau photovoltaïque.\n2. Une pile.\n3. Un moteur électrique.\n4. Quel mode de transfert thermique permet à la chaleur du Soleil de traverser le vide ?","bareme":[{"critere":"Panneau : lumineuse → électrique","points":5},{"critere":"Pile : chimique → électrique","points":5},{"critere":"Moteur : électrique → cinétique (avec de la chaleur)","points":5},{"critere":"Rayonnement pour le transfert à travers le vide","points":5}],"dureeMin":6,"corrige":"1. Panneau photovoltaïque : énergie **lumineuse → électrique**.\n2. Pile : énergie **chimique → électrique**.\n3. Moteur électrique : énergie **électrique → cinétique** (avec une part perdue en énergie thermique).\n4. C’est le **rayonnement**, seul mode de transfert qui n’a pas besoin de support matériel."}$exo$::jsonb),
  ('5c602e2c-32c5-5631-ab24-4db2daaad74e'::uuid, 2, 'application', $exo${"titre":"La centrale thermique","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Dans une centrale thermique au charbon, l’énergie passe par quatre étapes : charbon, chaudière, turbine, alternateur.\n\n1. Donne la forme d’énergie à chaque étape.\n2. Schématise la chaîne énergétique sous la forme source → convertisseur → utilisation, en indiquant la flèche des pertes.\n3. Sous quelle forme se font presque toujours les pertes ?\n4. Le charbon d’une centrale apporte 100 unités d’énergie ; 35 sont converties en énergie électrique. Calcule le rendement de la centrale.","bareme":[{"critere":"Formes d’énergie : chimique, thermique, cinétique, électrique","points":6},{"critere":"Chaîne énergétique cohérente avec flèche latérale des pertes","points":5},{"critere":"Pertes thermiques","points":3},{"critere":"Rendement 35 ÷ 100 = 35 % justifié","points":6}],"dureeMin":10,"corrige":"1. Charbon : **chimique** ; chaudière : **thermique** ; turbine : **cinétique** ; alternateur : **électrique**.\n2. Charbon (énergie chimique) → chaudière, turbine, alternateur (convertisseurs) → énergie électrique utilisée ; une flèche latérale part vers l’environnement pour les **pertes**.\n3. Les pertes sont presque toujours de l’énergie **thermique**.\n4. Rendement = énergie utile ÷ énergie reçue = 35 ÷ 100 = **0,35, soit 35 %**."}$exo$::jsonb),
  ('5c602e2c-32c5-5631-ab24-4db2daaad74e'::uuid, 3, 'application', $exo${"titre":"Ampoule à incandescence ou LED","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un ménage compare deux lampes. Chacune reçoit **100 J** d’énergie électrique. La lampe à incandescence en convertit 5 J en lumière ; la LED en convertit 30 J.\n\n1. Calcule le rendement lumineux de chaque lampe en pourcentage.\n2. Calcule l’énergie perdue par chaque lampe et dis sous quelle forme elle apparaît.\n3. Une pièce est chauffée par un radiateur : l’air chaud monte vers le plafond. Nomme le mode de transfert thermique et explique le mécanisme.\n4. Un rendement de 100 % est-il possible ? Justifie.","bareme":[{"critere":"Rendements 5 % et 30 %, calculs posés","points":5},{"critere":"Pertes 95 J et 70 J, sous forme thermique","points":5},{"critere":"Convection : déplacement de matière dans un fluide","points":5},{"critere":"Rendement toujours inférieur à 100 % : une part part en chaleur non désirée","points":5}],"dureeMin":15,"corrige":"1. Incandescence : 5 ÷ 100 = **5 %**. LED : 30 ÷ 100 = **30 %**.\n2. Pertes : 100 − 5 = **95 J** pour l’incandescence, 100 − 30 = **70 J** pour la LED, sous forme d’énergie **thermique** (chaleur).\n3. C’est la **convection** : l’air chaud se déplace (il monte), donc de la matière transporte l’énergie dans le fluide.\n4. Non : le rendement est **toujours inférieur à 100 %**, car une part de l’énergie est convertie en chaleur non désirée."}$exo$::jsonb),
  ('b75e090d-266d-5866-b981-9c6ec13d21b5'::uuid, 1, 'application', $exo${"titre":"Convertir et calculer","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Une voiture de masse **1 000 kg** roule à **72 km/h**.\n\n1. Convertis la vitesse en m/s.\n2. Écris la formule de l’énergie cinétique et précise l’unité de chaque grandeur.\n3. Calcule l’énergie cinétique de la voiture.","bareme":[{"critere":"Conversion : 72 ÷ 3,6 = 20 m/s","points":6},{"critere":"Formule Ec = ½ × m × v² avec unités (J, kg, m/s)","points":6},{"critere":"Calcul Ec = 0,5 × 1 000 × 20² = 200 000 J","points":8}],"dureeMin":7,"corrige":"1. 72 ÷ 3,6 = **20 m/s**.\n2. **Ec = ½ × m × v²** : Ec en joules (J), m en kilogrammes (kg), v en mètres par seconde (m/s).\n3. Ec = 0,5 × 1 000 × 20² = 0,5 × 1 000 × 400 = **200 000 J**.\n\n**Critères de correction :** Conversion : 72 ÷ 3,6 = 20 m/s (6 pts) ; Formule Ec = ½ × m × v² avec unités (J, kg, m/s) (6 pts) ; Calcul Ec = 0,5 × 1 000 × 20² = 200 000 J (8 pts)."}$exo$::jsonb),
  ('b75e090d-266d-5866-b981-9c6ec13d21b5'::uuid, 2, 'application', $exo${"titre":"Le scooter et le camion","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un scooter et son conducteur (**200 kg**) roulent à **10 m/s**. Un camion de **20 000 kg** roule à **10 m/s**.\n\n1. Calcule l’énergie cinétique du scooter.\n2. Calcule l’énergie cinétique du camion.\n3. Compare les deux valeurs : par combien est-elle multipliée ? Quelle grandeur explique la différence ?\n4. Le scooter double sa vitesse (20 m/s). Calcule sa nouvelle énergie cinétique.","bareme":[{"critere":"Ec du scooter : 0,5 × 200 × 10² = 10 000 J","points":5},{"critere":"Ec du camion : 0,5 × 20 000 × 10² = 1 000 000 J","points":5},{"critere":"Rapport 100, expliqué par la masse cent fois plus grande","points":5},{"critere":"Ec à 20 m/s : 40 000 J, soit 4 fois plus","points":5}],"dureeMin":11,"corrige":"1. Ec = 0,5 × 200 × 10² = **10 000 J**.\n2. Ec = 0,5 × 20 000 × 10² = **1 000 000 J** (10⁶ J).\n3. 10⁶ ÷ 10⁴ = **100** : le camion a une énergie cinétique 100 fois plus grande, parce que sa **masse** est 100 fois plus grande (à vitesse égale, Ec est proportionnelle à la masse).\n4. Ec = 0,5 × 200 × 20² = 0,5 × 200 × 400 = **40 000 J**, soit **4 fois** plus : doubler la vitesse multiplie l’énergie par 2² = 4."}$exo$::jsonb),
  ('b75e090d-266d-5866-b981-9c6ec13d21b5'::uuid, 3, 'application', $exo${"titre":"Freiner à 50 ou à 100 km/h","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Une voiture de **1 200 kg** freine avant un obstacle. On compare deux vitesses : **50 km/h** et **100 km/h**.\n\n1. Convertis les deux vitesses en m/s (arrondis à 0,1).\n2. Calcule l’énergie cinétique à 50 km/h puis à 100 km/h (arrondie au kJ).\n3. Par combien l’énergie à dissiper est-elle multipliée ? Explique pourquoi.\n4. Que devient cette énergie au freinage ?\n5. Cite un facteur qui allonge la distance de réaction et un qui allonge la distance de freinage.","bareme":[{"critere":"Conversions 13,9 m/s et 27,8 m/s","points":4},{"critere":"Ec ≈ 116 kJ à 50 km/h et ≈ 463 kJ à 100 km/h","points":6},{"critere":"Facteur 4 expliqué par le carré de la vitesse","points":4},{"critere":"Conversion en énergie thermique par les frottements","points":3},{"critere":"Un facteur de réaction et un de freinage bien classés","points":3}],"dureeMin":18,"corrige":"1. 50 ÷ 3,6 ≈ **13,9 m/s** ; 100 ÷ 3,6 ≈ **27,8 m/s**.\n2. À 50 km/h : Ec = 0,5 × 1 200 × 13,9² ≈ 0,5 × 1 200 × 193 ≈ **116 000 J ≈ 116 kJ**. À 100 km/h : Ec = 0,5 × 1 200 × 27,8² ≈ 0,5 × 1 200 × 773 ≈ **463 000 J ≈ 463 kJ**.\n3. Elle est multipliée par **4** (463 ÷ 116 ≈ 4) : la vitesse est doublée et Ec dépend de **v²**, donc 2² = 4.\n4. L’énergie cinétique est **convertie en énergie thermique** par les frottements des freins : elle n’a pas disparu.\n5. Réaction : alcool, fatigue ou téléphone. Freinage : pluie ou pneus usés."}$exo$::jsonb),
  ('e62c3f56-4c33-537b-89b6-1175140c90dd'::uuid, 1, 'application', $exo${"titre":"Bilan d’une lampe","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Une lampe reçoit **50 J** d’énergie électrique en une seconde et fournit **10 J** d’énergie lumineuse utile.\n\n1. Écris le bilan énergétique de la lampe.\n2. Calcule l’énergie dissipée et dis sous quelle forme elle apparaît.\n3. Calcule le rendement de la lampe.","bareme":[{"critere":"Bilan : énergie reçue = énergie utile + énergie dissipée","points":6},{"critere":"Énergie dissipée 40 J, sous forme thermique","points":7},{"critere":"Rendement 10 ÷ 50 = 20 %","points":7}],"dureeMin":6,"corrige":"1. **énergie reçue = énergie utile + énergie dissipée**.\n2. Énergie dissipée = 50 − 10 = **40 J**, sous forme d’énergie **thermique** (chaleur).\n3. Rendement = 10 ÷ 50 = 0,2, soit **20 %**.\n\n**Critères de correction :** Bilan : énergie reçue = énergie utile + énergie dissipée (6 pts) ; Énergie dissipée 40 J, sous forme thermique (7 pts) ; Rendement 10 ÷ 50 = 20 % (7 pts)."}$exo$::jsonb),
  ('e62c3f56-4c33-537b-89b6-1175140c90dd'::uuid, 2, 'application', $exo${"titre":"La bille qui tombe","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"On lâche une bille de masse 50 g du haut d’une rampe. On néglige les frottements.\n\n1. Quelle forme d’énergie la bille possède-t-elle en haut ? Et juste avant d’arriver en bas ?\n2. Que peut-on dire de la somme de ces énergies pendant la chute ? Nomme le principe utilisé.\n3. Dans la réalité, la bille finit par s’arrêter en bas d’un chemin plat. Que devient son énergie ? Explique pourquoi on parle de « perte » alors que rien n’a disparu.","bareme":[{"critere":"Position en haut, cinétique en bas","points":5},{"critere":"Somme constante, principe de conservation de l’énergie","points":6},{"critere":"Énergie dissipée en chaleur par les frottements","points":5},{"critere":"« Perte » = énergie dégradée, inutilisable, non détruite","points":4}],"dureeMin":10,"corrige":"1. En haut : énergie de **position** (maximale). Juste avant d’arriver en bas : énergie **cinétique** (l’énergie de position s’est convertie).\n2. La **somme** reste **constante** si l’on néglige les frottements : c’est le **principe de conservation de l’énergie** (l’énergie ne se crée ni ne se détruit, elle se transforme).\n3. L’énergie est dissipée en **énergie thermique** par les frottements. On parle de « perte » car cette énergie est **dégradée** : trop diluée dans l’environnement pour être récupérée. Elle n’a pas disparu, elle est inutilisable."}$exo$::jsonb),
  ('e62c3f56-4c33-537b-89b6-1175140c90dd'::uuid, 3, 'application', $exo${"titre":"Moteur thermique contre moteur électrique","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Une voiture thermique consomme, pour un trajet, une énergie chimique de **300 MJ** ; son moteur a un rendement d’environ 30 %. Un moteur électrique de rendement 90 % reçoit **100 MJ**.\n\n1. Calcule l’énergie utile fournie par le moteur thermique et l’énergie dissipée.\n2. Calcule l’énergie utile et l’énergie dissipée du moteur électrique.\n3. Sous quelle forme l’énergie dissipée apparaît-elle ? Cette énergie a-t-elle disparu ?\n4. Cite deux gestes qui permettent d’économiser l’énergie dans un logement.","bareme":[{"critere":"Moteur thermique : utile 90 MJ, dissipée 210 MJ","points":6},{"critere":"Moteur électrique : utile 90 MJ, dissipée 10 MJ","points":6},{"critere":"Chaleur, énergie conservée mais dégradée","points":4},{"critere":"Deux gestes d’économie pertinents","points":4}],"dureeMin":15,"corrige":"1. Utile = 0,30 × 300 = **90 MJ** ; dissipée = 300 − 90 = **210 MJ**.\n2. Utile = 0,90 × 100 = **90 MJ** ; dissipée = 100 − 90 = **10 MJ**.\n3. L’énergie dissipée apparaît sous forme **thermique**. Elle n’a **pas disparu** (conservation de l’énergie) : elle est dégradée, dispersée dans l’environnement. À énergie utile égale, le moteur électrique dissipe bien moins.\n4. Par exemple : **isoler** le logement, éteindre les **veilles**, choisir un appareil de bon **rendement** (étiquette énergie), limiter la durée des appareils puissants."}$exo$::jsonb),
  ('325b9123-94f9-5ab6-a91e-c0f05f425523'::uuid, 1, 'application', $exo${"titre":"Adresse cosmique","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Range dans l’ordre du plus petit au plus grand : Univers, Terre, Voie lactée, Système solaire.\n2. Quel astre est au centre du Système solaire ? Cet astre produit-il sa propre lumière ?\n3. Cite les quatre planètes telluriques.","bareme":[{"critere":"Ordre : Terre, Système solaire, Voie lactée, Univers","points":7},{"critere":"Le Soleil, une étoile, qui produit sa lumière","points":6},{"critere":"Mercure, Vénus, Terre, Mars","points":7}],"dureeMin":6,"corrige":"1. **Terre → Système solaire → Voie lactée → Univers**.\n2. Le **Soleil**, une **étoile** : elle produit sa propre lumière.\n3. Les planètes telluriques : **Mercure, Vénus, la Terre, Mars**.\n\n**Critères de correction :** Ordre : Terre, Système solaire, Voie lactée, Univers (7 pts) ; Le Soleil, une étoile, qui produit sa lumière (6 pts) ; Mercure, Vénus, Terre, Mars (7 pts)."}$exo$::jsonb),
  ('325b9123-94f9-5ab6-a91e-c0f05f425523'::uuid, 2, 'application', $exo${"titre":"La lumière de la Lune","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"La lumière se propage à environ **300 000 km/s** dans le vide. La Lune est à environ **384 000 km** de la Terre.\n\n1. Calcule le temps que met la lumière de la Lune pour nous parvenir (formule t = d ÷ v).\n2. La Lune produit-elle sa propre lumière ? Explique ce que l’on voit dans le ciel.\n3. Cite deux différences entre une étoile et une planète.","bareme":[{"critere":"Calcul t = 384 000 ÷ 300 000 ≈ 1,3 s avec unité","points":8},{"critere":"La Lune diffuse la lumière du Soleil","points":6},{"critere":"Deux différences étoile / planète correctes","points":6}],"dureeMin":9,"corrige":"1. t = d ÷ v = 384 000 ÷ 300 000 ≈ **1,3 s**.\n2. Non : la Lune **ne produit pas** de lumière, elle **diffuse** la lumière reçue du Soleil. On la voit parce qu’elle renvoie cette lumière vers la Terre.\n3. Une **étoile** produit sa propre lumière, une **planète** la diffuse seulement ; l’étoile est au centre, les planètes tournent autour ; une étoile est une boule de gaz très chaude, une planète est plus petite et plus froide."}$exo$::jsonb),
  ('325b9123-94f9-5ab6-a91e-c0f05f425523'::uuid, 3, 'application', $exo${"titre":"De la Terre au Soleil et à Proxima","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Données : vitesse de la lumière 300 000 km/s ; une année-lumière ≈ 9,5 × 10¹² km ; le Soleil est à 8 minutes-lumière ; Proxima du Centaure est à 4,2 années-lumière.\n\n1. Calcule la distance Terre-Soleil (on prend 8 min = 480 s).\n2. Que signifie « 4,2 années-lumière » ? Calcule en km la distance de Proxima (arrondie à 4 × 10¹³ km).\n3. Combien de fois Proxima est-elle plus loin que le Soleil ? Donne un ordre de grandeur.\n4. Explique la phrase : « regarder loin, c’est regarder tôt ».","bareme":[{"critere":"d = 300 000 × 480 = 1,44 × 10⁸ km (≈ 1,5 × 10⁸ km)","points":5},{"critere":"Définition de l’année-lumière et distance ≈ 4 × 10¹³ km","points":6},{"critere":"Rapport de l’ordre de 300 000 (10⁵)","points":4},{"critere":"Explication : la lumière met du temps, on voit le passé","points":5}],"dureeMin":16,"corrige":"1. d = v × t = 300 000 × 480 = **1,44 × 10⁸ km**, soit environ 1,5 × 10⁸ km.\n2. Une année-lumière est la **distance parcourue par la lumière en un an**. 4,2 × 9,5 × 10¹² ≈ 4,0 × 10¹³ km : environ **4 × 10¹³ km**.\n3. 4 × 10¹³ ÷ 1,5 × 10⁸ ≈ 2,7 × 10⁵ : Proxima est environ **300 000 fois** plus loin que le Soleil.\n4. La lumière a besoin de temps pour voyager : plus un astre est loin, plus la lumière qui nous arrive est **ancienne**. On voit le Soleil tel qu’il était il y a 8 minutes, Proxima telle qu’elle était il y a 4,2 ans."}$exo$::jsonb),
  ('5e15eaa3-663a-5071-9b8e-0353e35d0887'::uuid, 1, 'application', $exo${"titre":"Les briques de la matière","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Quels sont les deux éléments les plus abondants dans l’Univers ?\n2. Donne un exemple de molécule et dis ce qu’est une molécule.\n3. Comment connaît-on la composition d’une étoile lointaine sans y aller ?","bareme":[{"critere":"Hydrogène et hélium","points":6},{"critere":"Une molécule est un assemblage d’atomes, exemple H₂O ou CO₂","points":7},{"critere":"Par l’analyse du spectre de sa lumière","points":7}],"dureeMin":6,"corrige":"1. L’**hydrogène** et l’**hélium**.\n2. Une **molécule** est un **assemblage d’atomes** ; exemples : H₂O, CO₂, O₂.\n3. En analysant la **lumière** de l’étoile : son **spectre** montre des couleurs précises, propres à chaque élément."}$exo$::jsonb),
  ('5e15eaa3-663a-5071-9b8e-0353e35d0887'::uuid, 2, 'application', $exo${"titre":"Du plus petit au plus grand","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Voici des ordres de grandeur en désordre : 1 m ; 10⁻¹⁰ m ; 10⁷ m ; 10⁻⁵ m.\n\n1. Associe chaque valeur à un objet parmi : atome, cellule, organisme, planète.\n2. Range ces niveaux du plus petit au plus grand et complète la chaîne : atomes → … → …\n3. Combien de fois l’organisme (1 m) est-il plus grand que la cellule ?","bareme":[{"critere":"Associations : atome 10⁻¹⁰ m, cellule 10⁻⁵ m, organisme 1 m, planète 10⁷ m","points":8},{"critere":"Chaîne d’organisation cohérente","points":6},{"critere":"Rapport 10⁵ (100 000) justifié","points":6}],"dureeMin":10,"corrige":"1. Atome : **10⁻¹⁰ m** ; cellule : **10⁻⁵ m** ; organisme : **1 m** ; planète : **10⁷ m**.\n2. atomes → molécules → cellules → organismes → planètes → étoiles → galaxies.\n3. 1 ÷ 10⁻⁵ = **10⁵**, soit 100 000 fois plus grand.\n\n**Critères de correction :** Associations : atome 10⁻¹⁰ m, cellule 10⁻⁵ m, organisme 1 m, planète 10⁷ m (8 pts) ; Chaîne d’organisation cohérente (6 pts) ; Rapport 10⁵ (100 000) justifié (6 pts)."}$exo$::jsonb),
  ('5e15eaa3-663a-5071-9b8e-0353e35d0887'::uuid, 3, 'application', $exo${"titre":"Des atomes venus des étoiles","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un élève lit : « Les atomes de notre corps ont été fabriqués dans des étoiles mortes avant la naissance du Soleil. »\n\n1. Cite un élément formé peu après la naissance de l’Univers et un élément formé au cœur des étoiles.\n2. Explique comment ces éléments se retrouvent ensuite dans notre corps.\n3. Comment les astronomes peuvent-ils affirmer que la composition d’une étoile lointaine ressemble à celle du Soleil ?\n4. Que signifie l’expression « unité de la matière » ?","bareme":[{"critere":"Hydrogène ou hélium d’un côté, carbone, oxygène ou fer de l’autre","points":5},{"critere":"Explosion des étoiles et dispersion des éléments","points":5},{"critere":"Analyse du spectre (couleurs précises de chaque élément)","points":5},{"critere":"Mêmes atomes et mêmes lois partout dans l’Univers","points":5}],"dureeMin":14,"corrige":"1. **Hydrogène** ou **hélium** (peu après la naissance de l’Univers) ; **carbone**, **oxygène** ou **fer** (au cœur des étoiles).\n2. Les éléments fabriqués dans les étoiles sont **dispersés lors de leur explosion** ; ils se retrouvent ensuite dans le gaz qui forme de nouvelles étoiles, des planètes et des êtres vivants.\n3. Chaque élément émet ou absorbe des **couleurs précises** : l’analyse du **spectre** de la lumière révèle les éléments présents, même à des millions d’années-lumière.\n4. La matière est faite **partout des mêmes atomes**, et les **mêmes lois** physiques et chimiques s’appliquent ici et ailleurs."}$exo$::jsonb),
  ('07f64309-fc58-5a91-86c7-46957272cbf8'::uuid, 1, 'application', $exo${"titre":"Les particules de l’atome","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Nomme les trois particules qui constituent l’atome et donne la charge de chacune.\n2. Où se trouve la presque totalité de la masse d’un atome ?\n3. Pourquoi un atome est-il électriquement neutre ?","bareme":[{"critere":"Proton +, neutron nul, électron −","points":8},{"critere":"La masse est dans le noyau","points":5},{"critere":"Autant de protons que d’électrons","points":7}],"dureeMin":6,"corrige":"1. **Proton** : charge positive ; **neutron** : charge nulle ; **électron** : charge négative.\n2. Dans le **noyau**.\n3. Un atome possède **autant de protons que d’électrons** : les charges se compensent.\n\n**Critères de correction :** Proton +, neutron nul, électron − (8 pts) ; La masse est dans le noyau (5 pts) ; Autant de protons que d’électrons (7 pts)."}$exo$::jsonb),
  ('07f64309-fc58-5a91-86c7-46957272cbf8'::uuid, 2, 'application', $exo${"titre":"Atome de carbone et molécule d’eau","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Le carbone possède **6 protons** ; l’oxygène **8 protons** ; l’hydrogène **1 proton**.\n\n1. Combien d’électrons possède un atome de carbone ? Justifie.\n2. Un atome perd 2 électrons. Est-il encore le même élément ? Quelle est sa charge globale ?\n3. Combien d’atomes de chaque sorte contient la molécule H₂O ? Combien de protons au total dans cette molécule ?","bareme":[{"critere":"6 électrons, justifiés par la neutralité","points":6},{"critere":"Même élément (les protons sont inchangés), ion positif","points":7},{"critere":"H₂O : 2 H et 1 O, total 10 protons","points":7}],"dureeMin":10,"corrige":"1. **6 électrons** : l’atome est neutre, donc autant d’électrons que de protons.\n2. C’est le **même élément** : c’est le nombre de protons qui identifie l’élément, et il ne change pas. L’atome devient un **ion positif** (deux charges positives en excès, car les électrons sont négatifs).\n3. H₂O : **2 atomes d’hydrogène** et **1 atome d’oxygène**. Protons : 2 × 1 + 8 = **10 protons**."}$exo$::jsonb),
  ('07f64309-fc58-5a91-86c7-46957272cbf8'::uuid, 3, 'application', $exo${"titre":"Dimensions et symboles","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un atome mesure environ 10⁻¹⁰ m ; son noyau est environ 100 000 fois plus petit.\n\n1. Calcule l’ordre de grandeur de la taille du noyau.\n2. Avec l’image du stade de football (atome) et d’une bille (noyau), explique ce que signifie « structure essentiellement vide ».\n3. Distingue Co et CO : que désigne chaque symbole ?\n4. La molécule de dioxyde de carbone est CO₂. Combien d’atomes contient-elle ? Un atome peut-il changer de nombre de protons en restant le même élément ?","bareme":[{"critere":"Noyau : 10⁻¹⁰ ÷ 10⁵ = 10⁻¹⁵ m","points":5},{"critere":"Structure vide : noyau minuscule au centre, le reste est du vide","points":5},{"critere":"Co cobalt, CO monoxyde de carbone (casse)","points":5},{"critere":"CO₂ : 3 atomes ; changer de protons = changer d’élément","points":5}],"dureeMin":15,"corrige":"1. 10⁻¹⁰ ÷ 100 000 = 10⁻¹⁰ ÷ 10⁵ = **10⁻¹⁵ m**.\n2. Si l’atome est un stade, le noyau est une bille au centre du terrain : presque tout l’atome est du **vide**, où circulent les électrons, alors que la masse est concentrée dans le noyau.\n3. **Co** (majuscule + minuscule) est le **cobalt**, un élément. **CO** (deux majuscules) est le **monoxyde de carbone**, une molécule formée d’un atome de carbone et d’un atome d’oxygène.\n4. CO₂ contient **3 atomes** (1 C et 2 O). Non : **changer le nombre de protons, c’est changer d’élément**."}$exo$::jsonb),
  ('557f795d-4fa9-526a-8dbd-96b02c71657a'::uuid, 1, 'application', $exo${"titre":"Un circuit simple","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Un circuit est formé d’une pile, d’une lampe, d’un interrupteur et de fils.\n\n1. Quel est le rôle de la pile ? Quel est celui de la lampe ?\n2. À quelle condition la lampe s’allume-t-elle ?\n3. Que se passe-t-il quand on ouvre l’interrupteur ?","bareme":[{"critere":"Pile : générateur, fournit l’énergie ; lampe : récepteur","points":7},{"critere":"Circuit fermé, boucle sans coupure","points":7},{"critere":"Interrupteur ouvert : plus de courant, lampe éteinte","points":6}],"dureeMin":6,"corrige":"1. La pile est le **générateur** : elle fournit l’énergie. La lampe est un **récepteur** : elle la consomme.\n2. Le circuit doit être **fermé** : une boucle ininterrompue avec générateur, récepteur et fils.\n3. L’interrupteur ouvert **coupe la boucle** : le courant ne circule plus, la lampe s’éteint."}$exo$::jsonb),
  ('557f795d-4fa9-526a-8dbd-96b02c71657a'::uuid, 2, 'application', $exo${"titre":"Sens du courant et sécurité","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Dans un circuit, on branche une pile (bornes + et −) à une lampe.\n\n1. Dessine ou décris le sens conventionnel du courant à l’extérieur de la pile.\n2. Dans quel sens circulent les électrons dans les fils métalliques ? Pourquoi ce sens diffère-t-il du sens conventionnel ?\n3. Range en conducteurs et isolants : cuivre, plastique, corps humain, bois sec, graphite.\n4. Pourquoi un court-circuit est-il dangereux ?","bareme":[{"critere":"Sens conventionnel de + vers −","points":4},{"critere":"Électrons en sens inverse, convention historique","points":6},{"critere":"Classement correct des cinq matériaux","points":5},{"critere":"Court-circuit : intensité énorme, fils chauds, risque d’incendie","points":5}],"dureeMin":11,"corrige":"1. À l’extérieur du générateur, le courant va de la borne **+** vers la borne **−**.\n2. Les électrons circulent en sens **inverse** (de − vers +). Le sens conventionnel est une **convention historique**, choisie avant la découverte de l’électron.\n3. **Conducteurs** : cuivre, corps humain, graphite. **Isolants** : plastique, bois sec.\n4. Dans un court-circuit, un fil relie directement les deux bornes du générateur : l’**intensité devient énorme**, les fils chauffent, d’où un **risque d’incendie**."}$exo$::jsonb),
  ('557f795d-4fa9-526a-8dbd-96b02c71657a'::uuid, 3, 'application', $exo${"titre":"Le circuit de la lampe de poche","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Lina démonte une lampe de poche : elle contient deux piles, une ampoule, un interrupteur et des lames métalliques. Quand elle appuie sur l’interrupteur, l’ampoule s’allume.\n\n1. Trace le schéma du circuit avec les symboles normalisés (décris chaque symbole).\n2. Explique en quelques phrases ce qui se passe dans les lames métalliques quand le circuit est fermé.\n3. Lina essaie de remplacer l’interrupteur par un morceau de bois sec, puis par un morceau de cuivre. Prévois le résultat pour chaque cas et justifie.\n4. Dans une solution d’eau salée, quels sont les porteurs de charge ?","bareme":[{"critere":"Schéma cohérent : pile, interrupteur, lampe, fils avec angles droits","points":5},{"critere":"Déplacement ordonné d’électrons libres dans le métal","points":5},{"critere":"Bois isolant : la lampe reste éteinte ; cuivre conducteur : elle s’allume","points":6},{"critere":"Ions dans la solution","points":4}],"dureeMin":15,"corrige":"1. Schéma en traits droits et angles droits : **deux piles** (deux traits inégaux), un **interrupteur**, une **lampe** (cercle barré d’une croix), reliés en boucle par des fils.\n2. Le courant est un **déplacement ordonné d’électrons libres** dans les lames métalliques, uniquement si la boucle est fermée.\n3. Avec le **bois sec** (isolant) : la boucle n’est pas fermée électriquement, la lampe reste **éteinte**. Avec le **cuivre** (conducteur) : le courant passe, la lampe **s’allume**.\n4. Dans une solution ionique, ce sont les **ions** qui transportent le courant."}$exo$::jsonb),
  ('b8ce18ed-61ea-5877-be7f-0baeed60a3ca'::uuid, 1, 'application', $exo${"titre":"Série ou dérivation","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"On considère deux lampes L₁ et L₂.\n\n1. Quand on branche les deux lampes en série, combien y a-t-il de boucles ? Et en dérivation ?\n2. Dans chaque montage, que se passe-t-il si L₁ grille ?\n3. Quel montage est utilisé dans une maison ? Donne un avantage.","bareme":[{"critere":"Série : une boucle ; dérivation : plusieurs branches","points":6},{"critere":"Série : tout s’éteint ; dérivation : L₂ continue de briller","points":7},{"critere":"Dérivation à la maison, avec un avantage (tension identique, appareils indépendants)","points":7}],"dureeMin":6,"corrige":"1. En **série**, une seule boucle. En **dérivation**, plusieurs branches reliées entre deux nœuds.\n2. En série, si L₁ grille, **tout s’éteint**. En dérivation, **L₂ continue** de fonctionner.\n3. Les installations domestiques sont en **dérivation** : chaque appareil reçoit la même tension (230 V) et fonctionne indépendamment."}$exo$::jsonb),
  ('b8ce18ed-61ea-5877-be7f-0baeed60a3ca'::uuid, 2, 'application', $exo${"titre":"Deux lampes, deux montages","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un générateur de **12 V** alimente deux lampes.\n\n**Montage A (série)** : les tensions mesurées sont U₁ = 5 V aux bornes de L₁. Le courant vaut 0,4 A.\n**Montage B (dérivation)** : les intensités dans les branches sont 0,3 A et 0,2 A.\n\n1. Montage A : calcule la tension aux bornes de L₂ et donne l’intensité dans L₂.\n2. Montage B : quelle est la tension aux bornes de chaque lampe ?\n3. Montage B : calcule l’intensité dans la branche principale.\n4. Comment branche-t-on un ampèremètre pour mesurer l’intensité de L₁ dans le montage A ?","bareme":[{"critere":"U₂ = 12 − 5 = 7 V et I₂ = 0,4 A (même intensité en série)","points":6},{"critere":"12 V pour chaque lampe en dérivation","points":4},{"critere":"Loi des nœuds : 0,3 + 0,2 = 0,5 A","points":6},{"critere":"Ampèremètre en série avec L₁","points":4}],"dureeMin":11,"corrige":"1. En série les tensions s’additionnent : U₂ = 12 − 5 = **7 V**. L’intensité est la **même partout** : **0,4 A**.\n2. En dérivation, la tension est la même dans chaque branche que celle du générateur : **12 V**.\n3. Loi des nœuds : I = 0,3 + 0,2 = **0,5 A**.\n4. L’ampèremètre se branche **en série**, dans la branche de L₁, pour être traversé par le courant."}$exo$::jsonb),
  ('b8ce18ed-61ea-5877-be7f-0baeed60a3ca'::uuid, 3, 'application', $exo${"titre":"Guirlande ou installation domestique","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Une guirlande de 10 ampoules identiques est branchée sur un générateur de 12 V. Quand une ampoule grille, toute la guirlande s’éteint. Dans le salon, la lampe et le réfrigérateur sont branchés sur la même prise (230 V) : éteindre la lampe ne coupe pas le réfrigérateur.\n\n1. Quel montage la guirlande utilise-t-elle ? Justifie avec l’observation.\n2. Quelle tension reçoit chaque ampoule de la guirlande ?\n3. Quel montage utilise l’installation du salon ? Justifie et donne deux avantages.\n4. Pourquoi ne faut-il jamais brancher un ampèremètre en dérivation aux bornes d’un générateur ?","bareme":[{"critere":"Guirlande en série, panne d’une ampoule coupe tout","points":5},{"critere":"12 V ÷ 10 = 1,2 V par ampoule, justifié par l’addition des tensions","points":5},{"critere":"Salon en dérivation, deux avantages","points":5},{"critere":"Ampèremètre en dérivation : court-circuit dangereux","points":5}],"dureeMin":16,"corrige":"1. La guirlande est montée en **série** : une seule boucle, donc si une ampoule grille, la boucle est coupée et tout s’éteint.\n2. En série les tensions s’additionnent : 12 V ÷ 10 = **1,2 V** par ampoule (ampoules identiques).\n3. Le salon est en **dérivation** : chaque appareil reçoit la même tension (230 V), fonctionne indépendamment et a son propre interrupteur.\n4. Un ampèremètre a une résistance très faible : en dérivation aux bornes du générateur, il crée un **court-circuit** qui peut le détruire et faire chauffer les fils."}$exo$::jsonb),
  ('97000b68-7348-585f-918c-35677b956e55'::uuid, 1, 'application', $exo${"titre":"Mesurer une tension","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Dans quelle unité mesure-t-on la tension électrique ? Avec quel appareil ?\n2. Comment branche-t-on cet appareil par rapport au dipôle ?\n3. Quelle est la tension du secteur domestique en France ? Est-elle dangereuse ?","bareme":[{"critere":"Volt, voltmètre","points":6},{"critere":"Branchement en dérivation aux bornes du dipôle","points":7},{"critere":"230 V, dangereuse (mortelle)","points":7}],"dureeMin":6,"corrige":"1. L’unité est le **volt (V)**, mesuré avec un **voltmètre**.\n2. Le voltmètre se branche **en dérivation**, aux bornes du dipôle.\n3. La tension du secteur est de **230 V** : elle est **mortelle**, très supérieure au seuil de sécurité d’environ 25 V."}$exo$::jsonb),
  ('97000b68-7348-585f-918c-35677b956e55'::uuid, 2, 'application', $exo${"titre":"Tensions dans un circuit en série","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un générateur de **9 V** alimente en série une lampe L₁ et une lampe L₂. Un voltmètre placé aux bornes de L₁ indique **5,5 V**.\n\n1. Calcule la tension aux bornes de L₂.\n2. Quelle est la tension aux bornes d’un interrupteur fermé placé dans le circuit ? Et s’il est ouvert ?\n3. Le voltmètre est branché à l’envers (bornes inversées). Que va-t-il afficher ? Y a-t-il un danger pour le circuit ?","bareme":[{"critere":"U₂ = 9 − 5,5 = 3,5 V","points":8},{"critere":"Interrupteur fermé ≈ 0 V, ouvert : 9 V","points":6},{"critere":"Valeur négative, aucun danger","points":6}],"dureeMin":9,"corrige":"1. En série U générateur = U₁ + U₂, donc U₂ = 9 − 5,5 = **3,5 V**.\n2. Interrupteur **fermé** : environ **0 V**. Interrupteur **ouvert** : **toute la tension du générateur**, soit 9 V.\n3. Le voltmètre affiche une valeur **négative** ; le circuit ne risque rien, seul le signe change."}$exo$::jsonb),
  ('97000b68-7348-585f-918c-35677b956e55'::uuid, 3, 'application', $exo${"titre":"Continu ou alternatif ?","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Deux tensions sont visualisées à l’oscilloscope. Tension A : une ligne horizontale à 4,5 V. Tension B : une sinusoïde qui fait 50 périodes par seconde.\n\n1. Identifie A et B (continue ou alternative) et donne un exemple de source pour chacune.\n2. Quelle est la fréquence de la tension B ? Combien de fois par seconde change-t-elle de signe ?\n3. Une pile plate de 4,5 V est-elle dangereuse ? Compare avec le secteur.\n4. Une pile posée sur une table a-t-elle une tension à ses bornes ? Un courant circule-t-il ? Justifie.","bareme":[{"critere":"A continue (pile), B alternative (secteur)","points":5},{"critere":"50 Hz et 100 changements de signe par seconde","points":5},{"critere":"4,5 V < 25 V donc sans danger ; le secteur (230 V) est mortel","points":5},{"critere":"Tension sans courant : circuit non fermé","points":5}],"dureeMin":15,"corrige":"1. **A** est une tension **continue** (constante), exemple : une **pile**. **B** est **alternative** (elle change de signe), exemple : le **secteur**.\n2. B a une fréquence de **50 Hz** ; elle change de signe **100 fois par seconde**.\n3. 4,5 V est inférieure au seuil de sécurité (environ 25 V) : elle est **sans danger**, alors que le secteur (**230 V**) est mortel.\n4. Oui : une tension existe même sans courant, la pile a bien **1,5 ou 4,5 V** à ses bornes. Aucun courant ne circule car le circuit n’est **pas fermé**."}$exo$::jsonb),
  ('d09ff7a8-4754-5594-a1f7-a3b2733342b7'::uuid, 1, 'application', $exo${"titre":"Mesurer une intensité","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Dans quelle unité mesure-t-on l’intensité du courant ? Avec quel appareil ?\n2. Comment branche-t-on cet appareil ?\n3. Convertis 300 mA en ampères.","bareme":[{"critere":"Ampère, ampèremètre","points":6},{"critere":"Branchement en série","points":7},{"critere":"300 mA = 0,3 A","points":7}],"dureeMin":5,"corrige":"1. L’unité est l’**ampère (A)**, mesuré avec un **ampèremètre**.\n2. L’ampèremètre se branche **en série**, pour que le courant le **traverse**.\n3. 300 mA = 300 × 0,001 = **0,3 A**.\n\n**Critères de correction :** Ampère, ampèremètre (6 pts) ; Branchement en série (7 pts) ; 300 mA = 0,3 A (7 pts)."}$exo$::jsonb),
  ('d09ff7a8-4754-5594-a1f7-a3b2733342b7'::uuid, 2, 'application', $exo${"titre":"Loi des nœuds et calibre","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un courant de **0,9 A** arrive à un nœud et se sépare en trois branches. Deux branches portent **0,4 A** et **0,3 A**.\n\n1. Calcule l’intensité dans la troisième branche.\n2. Sur quel calibre commence-t-on une mesure d’intensité quand on ne connaît pas sa valeur ? Pourquoi ?\n3. Un ampèremètre est branché en dérivation aux bornes d’une pile. Que risque-t-il de se passer ?","bareme":[{"critere":"Loi des nœuds : 0,9 − 0,4 − 0,3 = 0,2 A","points":8},{"critere":"Plus grand calibre, puis on descend, pour protéger l’appareil","points":6},{"critere":"Court-circuit possible, pile ou appareil détruits","points":6}],"dureeMin":9,"corrige":"1. Loi des nœuds : 0,9 = 0,4 + 0,3 + I₃, donc I₃ = 0,9 − 0,7 = **0,2 A**.\n2. On commence sur le **plus grand calibre**, puis on descend : cela protège l’appareil d’une intensité trop forte.\n3. En dérivation aux bornes d’un générateur, l’ampèremètre crée un **court-circuit** : il peut détruire le générateur ou l’appareil."}$exo$::jsonb),
  ('d09ff7a8-4754-5594-a1f7-a3b2733342b7'::uuid, 3, 'application', $exo${"titre":"La multiprise surchargée","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Sur une multiprise branchée sur une prise de 230 V, Inès branche un radiateur qui appelle 8 A, un four qui appelle 9 A et une bouilloire qui appelle 7 A. Le fusible de la prise supporte au plus **16 A**.\n\n1. Comment sont montés ces appareils ? Justifie.\n2. Calcule l’intensité totale dans le fil de la prise.\n3. Que se passe-t-il pour le fusible ? Quelle différence y a-t-il avec un disjoncteur ?\n4. Brancher des appareils supplémentaires change-t-il la tension reçue par chacun ? Explique.","bareme":[{"critere":"Montage en dérivation, même tension 230 V","points":4},{"critere":"Intensité totale 8 + 9 + 7 = 24 A","points":5},{"critere":"Fusible qui fond car 24 A > 16 A, disjoncteur qui se réarme","points":6},{"critere":"La tension ne change pas, les intensités s’additionnent","points":5}],"dureeMin":14,"corrige":"1. Les appareils sont montés en **dérivation** (chacun sous 230 V, indépendants).\n2. Loi des nœuds : I = 8 + 9 + 7 = **24 A**.\n3. 24 A dépasse la limite de 16 A : le **fusible fond** et coupe le circuit, évitant l’échauffement des fils. Un fusible doit être **remplacé**, un **disjoncteur** coupe aussi mais se **réarme**.\n4. La **tension reste 230 V**, mais les **intensités s’additionnent** : c’est ainsi qu’on dépasse la limite de l’installation."}$exo$::jsonb),
  ('8536aaf8-cdf3-5206-a5e7-59301f04e085'::uuid, 1, 'application', $exo${"titre":"Appliquer la loi d’Ohm","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Une résistance de **200 Ω** est traversée par un courant de **0,03 A**.\n\n1. Écris la loi d’Ohm et précise les unités.\n2. Calcule la tension aux bornes de la résistance.","bareme":[{"critere":"Loi U = R × I avec U en V, R en Ω, I en A","points":8},{"critere":"Calcul U = 200 × 0,03 = 6 V","points":12}],"dureeMin":5,"corrige":"1. **U = R × I**, avec U en volts (V), R en ohms (Ω) et I en ampères (A).\n2. U = 200 × 0,03 = **6 V**.\n\n**Critères de correction :** Loi U = R × I avec U en V, R en Ω, I en A (8 pts) ; Calcul U = 200 × 0,03 = 6 V (12 pts)."}$exo$::jsonb),
  ('8536aaf8-cdf3-5206-a5e7-59301f04e085'::uuid, 2, 'application', $exo${"titre":"Trouver R ou I","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un élève mesure pour un conducteur ohmique : U = **4,5 V** et I = **15 mA**.\n\n1. Convertis l’intensité en ampères.\n2. Calcule la résistance du conducteur.\n3. On le branche maintenant sur une pile de 9 V. Calcule la nouvelle intensité.\n4. Que devient l’intensité si on remplace ce conducteur par une résistance plus grande, à tension constante ?","bareme":[{"critere":"15 mA = 0,015 A","points":3},{"critere":"R = 4,5 ÷ 0,015 = 300 Ω","points":6},{"critere":"I = 9 ÷ 300 = 0,03 A (30 mA)","points":6},{"critere":"L’intensité diminue quand R augmente","points":5}],"dureeMin":10,"corrige":"1. 15 mA = **0,015 A**.\n2. R = U ÷ I = 4,5 ÷ 0,015 = **300 Ω**.\n3. I = U ÷ R = 9 ÷ 300 = **0,03 A** (30 mA).\n4. À tension constante, si R augmente, l’intensité **diminue**.\n\n**Critères de correction :** 15 mA = 0,015 A (3 pts) ; R = 4,5 ÷ 0,015 = 300 Ω (6 pts) ; I = 9 ÷ 300 = 0,03 A (30 mA) (6 pts) ; L’intensité diminue quand R augmente (5 pts)."}$exo$::jsonb),
  ('8536aaf8-cdf3-5206-a5e7-59301f04e085'::uuid, 3, 'application', $exo${"titre":"Une LED protégée","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Une LED supporte au plus **20 mA**. On la branche en série avec un conducteur ohmique sur une pile de 4,5 V ; on néglige la tension aux bornes de la LED (on suppose que la résistance reçoit 4,5 V).\n\n1. Quel est le rôle de la résistance placée en série avec la LED ?\n2. Calcule la valeur minimale de la résistance pour que l’intensité ne dépasse pas 20 mA.\n3. Décris une expérience pour mesurer une résistance inconnue avec un voltmètre et un ampèremètre (méthode voltampèremétrique), en précisant les branchements.\n4. Une résistance chauffe quand elle est traversée par un courant : donne le nom du phénomène et un appareil où il est recherché.","bareme":[{"critere":"La résistance limite l’intensité pour ne pas griller la LED","points":4},{"critere":"R = 4,5 ÷ 0,02 = 225 Ω","points":6},{"critere":"Méthode voltampèremétrique : voltmètre en dérivation, ampèremètre en série, R = U ÷ I","points":6},{"critere":"Effet Joule, exemple : grille-pain ou radiateur","points":4}],"dureeMin":16,"corrige":"1. La résistance en série **limite l’intensité** qui traverse la LED et l’empêche de griller.\n2. R = U ÷ I = 4,5 ÷ 0,020 = **225 Ω** au minimum (une valeur plus grande donne une intensité plus faible).\n3. On branche l’**ampèremètre en série** avec la résistance et le **voltmètre en dérivation** à ses bornes, on lit I et U, puis on calcule **R = U ÷ I**.\n4. C’est l’**effet Joule** ; il est recherché dans un grille-pain, un radiateur, un sèche-cheveux ou une ampoule à filament."}$exo$::jsonb),
  ('c8399bb4-15ec-54ce-8b03-d87f62733ffd'::uuid, 1, 'application', $exo${"titre":"Puissance d’un appareil","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Un appareil est branché sur le secteur (**230 V**) et est traversé par une intensité de **2 A**.\n\n1. Écris la formule de la puissance électrique avec les unités.\n2. Calcule la puissance de l’appareil.\n3. Dans quelle unité s’exprime l’énergie consommée dans une facture d’électricité ?","bareme":[{"critere":"Formule P = U × I, en W, V, A","points":6},{"critere":"Calcul P = 230 × 2 = 460 W","points":8},{"critere":"Énergie en kilowattheures (kWh)","points":6}],"dureeMin":6,"corrige":"1. **P = U × I** : P en watts (W), U en volts (V), I en ampères (A).\n2. P = 230 × 2 = **460 W**.\n3. Sur une facture, l’énergie est exprimée en **kilowattheures (kWh)** (1 kWh = 3,6 × 10⁶ J).\n\n**Critères de correction :** Formule P = U × I, en W, V, A (6 pts) ; Calcul P = 230 × 2 = 460 W (8 pts) ; Énergie en kilowattheures (kWh) (6 pts)."}$exo$::jsonb),
  ('c8399bb4-15ec-54ce-8b03-d87f62733ffd'::uuid, 2, 'application', $exo${"titre":"Le four et son coût","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un four porte la plaque « 230 V – 2 300 W ». Il fonctionne pendant **45 min**. Le prix du kWh est de **0,20 €**.\n\n1. Calcule l’intensité appelée par le four.\n2. Calcule l’énergie consommée en kWh (45 min = 0,75 h).\n3. Calcule le coût de fonctionnement.\n4. Quelle est la différence entre puissance et énergie ?","bareme":[{"critere":"I = 2 300 ÷ 230 = 10 A","points":5},{"critere":"E = 2,3 kW × 0,75 h ≈ 1,7 kWh","points":6},{"critere":"Coût ≈ 1,7 × 0,20 = 0,34 €","points":5},{"critere":"Puissance : vitesse de consommation ; énergie : quantité totale","points":4}],"dureeMin":11,"corrige":"1. I = P ÷ U = 2 300 ÷ 230 = **10 A**.\n2. E = P × t = 2,3 kW × 0,75 h = **1,725 kWh**, soit environ 1,7 kWh.\n3. Coût = 1,725 × 0,20 = **0,345 €**, soit environ **0,35 €** (0,34 € si l’on arrondit E à 1,7 kWh).\n4. La **puissance** dit à quelle vitesse on consomme (en W) ; l’**énergie** est la quantité totale consommée (E = P × t, en Wh, kWh ou J)."}$exo$::jsonb),
  ('c8399bb4-15ec-54ce-8b03-d87f62733ffd'::uuid, 3, 'application', $exo${"titre":"LED contre ampoule à filament","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Pour éclairer un salon pendant **5 h par jour**, on hésite entre une ampoule à filament de **60 W** et une ampoule LED de **8 W** qui éclairent autant. Le kWh coûte **0,20 €**.\n\n1. Calcule l’énergie consommée en une journée par chaque ampoule, en Wh puis en kWh.\n2. Calcule le coût annuel (365 jours) de chaque ampoule.\n3. Calcule l’économie réalisée en un an en choisissant la LED.\n4. Une ampoule de 60 W allumée 1 h consomme autant qu’une ampoule de 6 W allumée combien d’heures ? Que montre ce résultat ?\n5. Donne deux gestes pour réduire la consommation d’électricité.","bareme":[{"critere":"Énergies journalières 300 Wh (0,3 kWh) et 40 Wh (0,04 kWh)","points":5},{"critere":"Coûts annuels 21,90 € et 2,92 €","points":5},{"critere":"Économie ≈ 19 € par an","points":3},{"critere":"10 h : distinction puissance et énergie","points":4},{"critere":"Deux gestes pertinents","points":3}],"dureeMin":18,"corrige":"1. Filament : E = 60 × 5 = **300 Wh = 0,3 kWh** par jour. LED : E = 8 × 5 = **40 Wh = 0,04 kWh** par jour.\n2. Filament : 0,3 × 365 × 0,20 = **21,90 €**. LED : 0,04 × 365 × 0,20 = **2,92 €**.\n3. Économie : 21,90 − 2,92 = **18,98 €**, soit environ **19 €** par an.\n4. 60 Wh = 6 W × **10 h**. La puissance dit la vitesse de consommation, l’énergie dépend aussi de la durée.\n5. Par exemple : préférer les **LED**, éteindre les **veilles**, comparer les **étiquettes énergie**, limiter la durée d’usage des appareils puissants."}$exo$::jsonb),
  ('8bfc7fdd-cb95-55ad-9c0a-a1734702ab1d'::uuid, 1, 'application', $exo${"titre":"Mélange homogène ou hétérogène","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Pour chaque mélange, indique s’il est homogène ou hétérogène : eau salée ; eau boueuse ; huile dans l’eau ; vinaigre.\n\nPuis réponds : qu’est-ce qu’un corps pur ?","bareme":[{"critere":"Classement correct des quatre mélanges","points":12},{"critere":"Corps pur : une seule espèce chimique","points":8}],"dureeMin":5,"corrige":"**Homogènes** : eau salée, vinaigre (on ne distingue pas les constituants). **Hétérogènes** : eau boueuse, huile dans l’eau (on distingue au moins deux constituants).\n\nUn **corps pur** est constitué d’une **seule espèce chimique**."}$exo$::jsonb),
  ('8bfc7fdd-cb95-55ad-9c0a-a1734702ab1d'::uuid, 2, 'application', $exo${"titre":"Séparer eau, sable et sel","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un élève dispose d’un mélange d’eau, de sable et de sel dissous.\n\n1. Ce mélange est-il homogène ou hétérogène ? Justifie.\n2. Quelle technique sépare le sable du reste ? Comment s’appelle le liquide obtenu ?\n3. Peut-on obtenir de l’eau pure avec le liquide obtenu par simple filtration ? Justifie.\n4. Quelle technique permet de récupérer l’eau pure ? Décris son principe.","bareme":[{"critere":"Hétérogène à cause du sable, eau salée homogène","points":4},{"critere":"Filtration et filtrat","points":5},{"critere":"Non, le sel dissous traverse le filtre","points":5},{"critere":"Distillation : chauffer, refroidir la vapeur, recueillir le distillat","points":6}],"dureeMin":11,"corrige":"1. Le mélange est **hétérogène** (on voit le sable), mais l’eau salée seule est **homogène**.\n2. La **filtration** ; le liquide qui passe est le **filtrat**.\n3. **Non** : le sel est **dissous**, il traverse le filtre ; le filtrat est de l’eau salée.\n4. La **distillation** : on chauffe le liquide, la vapeur d’eau est refroidie puis recueillie, c’est le **distillat** ; le sel reste dans le récipient."}$exo$::jsonb),
  ('8bfc7fdd-cb95-55ad-9c0a-a1734702ab1d'::uuid, 3, 'application', $exo${"titre":"Eau pure ou eau minérale","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un professeur donne deux échantillons d’eau claire : A et B. Il fait bouillir A : la température reste à 100 °C pendant toute l’ébullition. Pour B, la température monte lentement de 100 °C à 103 °C pendant l’ébullition. Il laisse aussi s’évaporer 100 mL de chaque : A ne laisse rien, B laisse un dépôt blanc.\n\n1. Lequel est un corps pur ? Justifie avec les deux observations.\n2. Quel test permet de vérifier qu’un liquide contient de l’eau ? Donne le résultat attendu.\n3. Le dépôt blanc de B est-il présent dans le filtrat après filtration de B ? Explique pourquoi la filtration ne suffit pas à l’éliminer.\n4. Pourquoi un mélange homogène n’est-il pas séparable par décantation ?","bareme":[{"critere":"A est un corps pur : palier à 100 °C et aucun résidu","points":6},{"critere":"Sulfate de cuivre anhydre blanc devient bleu","points":4},{"critere":"Sels dissous qui traversent le filtre","points":5},{"critere":"Décantation inefficace car constituants dissous, aucune séparation par densité","points":5}],"dureeMin":15,"corrige":"1. **A** est un **corps pur** : sa température reste **constante** à 100 °C pendant l’ébullition (palier), et l’évaporation ne laisse **aucun résidu**. B change d’état sur un intervalle de températures et laisse un dépôt : c’est un mélange.\n2. Le **sulfate de cuivre anhydre**, blanc, devient **bleu** en présence d’eau.\n3. Oui, il est dans le filtrat : les sels sont **dissous**, ils traversent le filtre. Seule la distillation les retient.\n4. Dans un mélange homogène, les constituants sont **dissous** et ne se déposent pas : on ne distingue rien, donc la décantation ne sépare rien."}$exo$::jsonb),
  ('d6033598-dfab-515d-a064-270fdacaca74'::uuid, 1, 'application', $exo${"titre":"Les trois états","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Nomme les trois états physiques de la matière.\n2. Pour chacun, dis s’il a une forme propre et un volume propre.\n3. Dans quel état les molécules sont-elles les plus éloignées ?","bareme":[{"critere":"Solide, liquide, gaz","points":4},{"critere":"Solide : forme et volume propres ; liquide : volume propre seulement ; gaz : ni l’un ni l’autre","points":10},{"critere":"Gaz : molécules très éloignées","points":6}],"dureeMin":6,"corrige":"1. **Solide, liquide, gaz**.\n2. **Solide** : forme propre et volume propre. **Liquide** : volume propre, mais forme du récipient. **Gaz** : ni forme propre ni volume propre, il occupe tout l’espace.\n3. Dans le **gaz** : les molécules sont très éloignées, désordonnées et très agitées."}$exo$::jsonb),
  ('d6033598-dfab-515d-a064-270fdacaca74'::uuid, 2, 'application', $exo${"titre":"La seringue et la bouteille","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Léo remplit à ras bord une bouteille d’eau bouchée et la place au congélateur. Il bouche une seringue contenant de l’air et de l’eau et appuie sur le piston.\n\n1. Que fait le volume de l’eau quand elle gèle ? Que se passe-t-il pour la bouteille pleine ? Que devient la masse ?\n2. Avec l’air enfermé dans la seringue bouchée, le piston peut-il s’enfoncer ? Avec l’eau ? Explique avec les molécules.\n3. Décris la disposition des molécules dans un solide et dans un liquide.","bareme":[{"critere":"Volume augmenté, bouteille qui peut éclater, masse conservée","points":7},{"critere":"Gaz compressible (vide entre molécules), liquide quasi incompressible","points":7},{"critere":"Solide ordonné et serré, liquide serré et désordonné qui glisse","points":6}],"dureeMin":10,"corrige":"1. Le **volume augmente** quand l’eau gèle (exception de l’eau) : la bouteille pleine peut **éclater**. La **masse se conserve**.\n2. L’**air** se comprime (beaucoup de **vide** entre ses molécules), l’**eau** presque pas (molécules déjà au contact).\n3. **Solide** : molécules serrées, **ordonnées**, vibrant sur place. **Liquide** : molécules serrées mais **désordonnées**, qui **glissent** les unes sur les autres."}$exo$::jsonb),
  ('d6033598-dfab-515d-a064-270fdacaca74'::uuid, 3, 'application', $exo${"titre":"Chauffer un glaçon","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"On chauffe un glaçon jusqu’à ce qu’il devienne de la vapeur, dans un récipient fermé sur une balance. La masse indiquée reste 18 g pendant toute l’expérience.\n\n1. Nomme les trois états rencontrés dans l’ordre.\n2. Explique, avec les molécules, la différence entre le glaçon et la vapeur (distance, agitation).\n3. La masse reste 18 g : que conclure ? Le volume est-il aussi constant ? Explique.\n4. Que se passerait-il à −273 °C ?\n5. Pourquoi la vapeur remplit-elle tout le récipient alors que l’eau liquide non ?","bareme":[{"critere":"Solide, liquide, gaz dans l’ordre","points":3},{"critere":"Molécules serrées et peu agitées / éloignées et très agitées","points":5},{"critere":"Masse conservée, volume qui varie","points":4},{"critere":"Zéro absolu : l’agitation cesserait","points":3},{"critere":"Gaz expansible, liquide de volume propre","points":5}],"dureeMin":15,"corrige":"1. **Solide** (glace) → **liquide** (eau) → **gaz** (vapeur).\n2. Dans le glaçon, les molécules sont **serrées, ordonnées** et vibrent sur place ; dans la vapeur, elles sont **très éloignées**, désordonnées et **très agitées**. Chauffer augmente l’agitation.\n3. La **masse se conserve** : ce sont les mêmes molécules. Le **volume varie** (il augmente fortement avec la vapeur, un peu diminue à la fusion du glaçon).\n4. À −273 °C, le **zéro absolu**, l’agitation des molécules cesserait.\n5. Un gaz est **expansible** : ses molécules très éloignées et agitées occupent tout l’espace offert. Un liquide a un **volume propre** : ses molécules sont serrées."}$exo$::jsonb),
  ('b78fa741-2b26-572f-b79f-a227a062e588'::uuid, 1, 'application', $exo${"titre":"Nommer les changements d’état","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Donne le nom de chaque changement d’état :\n\n1. solide → liquide ;\n2. liquide → gaz ;\n3. gaz → liquide ;\n4. solide → gaz.\n\n5. À quelle température l’eau pure fond-elle sous pression normale ?","bareme":[{"critere":"Fusion, vaporisation, liquéfaction, sublimation","points":12},{"critere":"Fusion à 0 °C","points":8}],"dureeMin":5,"corrige":"1. **Fusion**. 2. **Vaporisation**. 3. **Liquéfaction**. 4. **Sublimation**.\n\n5. L’eau pure fond à **0 °C** sous pression normale (1 013 hPa).\n\n**Critères de correction :** Fusion, vaporisation, liquéfaction, sublimation (12 pts) ; Fusion à 0 °C (8 pts)."}$exo$::jsonb),
  ('b78fa741-2b26-572f-b79f-a227a062e588'::uuid, 2, 'application', $exo${"titre":"Courbe de refroidissement","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"On refroidit de l’eau pure liquide jusqu’à obtenir de la glace. On note la température : 20 °C, 10 °C, 0 °C (pendant 12 minutes), puis −5 °C.\n\n1. Comment s’appelle le changement d’état étudié ?\n2. Que fait la température pendant la durée de ce changement ? Comment s’appelle cette portion de courbe ?\n3. Que prouve ce comportement sur l’eau étudiée ?\n4. On ajoute du sel à l’eau : la température de solidification est-elle plus haute ou plus basse ? Cite une application.","bareme":[{"critere":"Solidification","points":4},{"critere":"Température constante à 0 °C, palier","points":6},{"critere":"Palier : signature d’un corps pur","points":5},{"critere":"Température plus basse, salage des routes","points":5}],"dureeMin":10,"corrige":"1. La **solidification** (liquide → solide).\n2. La température reste **constante à 0 °C** : c’est le **palier** de température.\n3. Ce palier est la **signature d’un corps pur** : l’eau étudiée est pure.\n4. Le sel **abaisse** la température de changement d’état, sous 0 °C : c’est le **salage des routes** contre le verglas."}$exo$::jsonb),
  ('b78fa741-2b26-572f-b79f-a227a062e588'::uuid, 3, 'application', $exo${"titre":"Eau en cuisine, en montagne et dans la nature","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Voici trois situations : (a) Julie fait bouillir de l’eau dans une casserole, au-dessus de laquelle un nuage blanc apparaît ; (b) en montagne, à 3 000 m d’altitude, l’eau bout à environ 90 °C ; (c) le matin, de la rosée se forme sur l’herbe et du givre sur une vitre.\n\n1. Distingue évaporation et ébullition (où et à quelle température).\n2. Le nuage blanc est-il de la vapeur d’eau ? Justifie.\n3. Explique pourquoi l’eau bout en dessous de 100 °C en altitude.\n4. Nomme le changement d’état qui forme la rosée et celui qui forme le givre.\n5. Julie continue de chauffer fortement l’eau qui bout à 100 °C : sa température monte-t-elle ? Explique où va l’énergie.","bareme":[{"critere":"Évaporation en surface à toute température ; ébullition dans toute la masse à température fixe","points":4},{"critere":"La vapeur est invisible, le nuage est fait de gouttelettes","points":4},{"critere":"Pression plus faible en altitude","points":4},{"critere":"Rosée = liquéfaction, givre = condensation solide","points":4},{"critere":"Température constante, l’énergie sert à réorganiser les molécules","points":4}],"dureeMin":17,"corrige":"1. **Évaporation** : en **surface**, à **toute température**. **Ébullition** : dans **toute la masse**, à **température fixe**.\n2. **Non** : la vapeur d’eau est **invisible** ; le nuage blanc est formé de **gouttelettes** d’eau liquide déjà condensées.\n3. En altitude la **pression atmosphérique** est plus faible : l’eau bout donc **en dessous de 100 °C**.\n4. Rosée : **liquéfaction**. Givre : **condensation solide**.\n5. **Non** : pendant l’ébullition d’un corps pur, la température reste **constante à 100 °C** ; l’énergie reçue sert à réorganiser les molécules (l’eau se vaporise plus vite)."}$exo$::jsonb),
  ('6001c167-005a-5b27-90ce-39854c5abb21'::uuid, 1, 'application', $exo${"titre":"Sucre dans l’eau","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Julie dissout 15 g de sucre dans 300 g d’eau.\n\n1. Quel est le solvant ? Quel est le soluté ?\n2. Quelle est la masse de la solution obtenue ?\n3. Le sucre a-t-il disparu ? Explique.","bareme":[{"critere":"Solvant : l’eau ; soluté : le sucre","points":6},{"critere":"Masse de la solution : 300 + 15 = 315 g","points":8},{"critere":"Le sucre est dispersé en particules invisibles, la masse se conserve","points":6}],"dureeMin":6,"corrige":"1. Le **solvant** est l’**eau** (le liquide qui dissout), le **soluté** est le **sucre** (l’espèce dissoute).\n2. Masse de la solution = masse du solvant + masse du soluté = 300 + 15 = **315 g**.\n3. Non, le sucre n’a pas disparu : il s’est **dispersé en particules invisibles à l’œil nu** ; la **masse se conserve**."}$exo$::jsonb),
  ('6001c167-005a-5b27-90ce-39854c5abb21'::uuid, 2, 'application', $exo${"titre":"Eau, huile et alcool","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Lina verse de l’huile dans de l’eau : deux couches se forment. Elle verse ensuite de l’alcool dans de l’eau : le mélange reste limpide.\n\n1. Quelles paires de liquides sont miscibles ? non miscibles ? Justifie par l’observation.\n2. Dans le mélange eau-huile, quel liquide est au-dessus ? Pourquoi ?\n3. Quel matériel utilise-t-on pour séparer eau et huile ?\n4. Quel type de mélange obtient-on avec l’eau et l’alcool ?","bareme":[{"critere":"Eau-alcool miscibles (une seule phase), eau-huile non miscibles (deux phases)","points":6},{"critere":"L’huile au-dessus car moins dense","points":5},{"critere":"Ampoule à décanter","points":4},{"critere":"Mélange homogène","points":5}],"dureeMin":10,"corrige":"1. **Eau et alcool** sont **miscibles** (une seule phase, mélange limpide). **Eau et huile** sont **non miscibles** (deux phases superposées).\n2. L’**huile** est au-dessus : elle est **moins dense** que l’eau (0,92 g/cm³ contre 1 g/cm³).\n3. On sépare les deux liquides avec une **ampoule à décanter**.\n4. L’eau et l’alcool forment un **mélange homogène**."}$exo$::jsonb),
  ('6001c167-005a-5b27-90ce-39854c5abb21'::uuid, 3, 'application', $exo${"titre":"Solubilité du sel et des gaz","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"La solubilité du sel de cuisine dans l’eau est d’environ 360 g/L à 20 °C. Nathan verse 50 g de sel dans 100 mL d’eau (0,1 L), puis rajoute du sel jusqu’à ce qu’il reste un dépôt au fond.\n\n1. Que signifie « solubilité de 360 g/L » ?\n2. Calcule la masse maximale de sel qui peut se dissoudre dans 0,1 L d’eau à 20 °C.\n3. La solution de Nathan avec 50 g de sel est-elle saturée ? Justifie.\n4. Comment appelle-t-on la solution quand un dépôt reste au fond ?\n5. Un soda est laissé au soleil. Explique pourquoi il pétille moins, en utilisant la solubilité des gaz.","bareme":[{"critere":"Définition : masse maximale dissoute dans 1 L de solvant à une température donnée","points":4},{"critere":"Masse maximale : 360 × 0,1 = 36 g","points":5},{"critere":"50 g > 36 g donc solution saturée, avec un dépôt de 14 g","points":5},{"critere":"Solution saturée","points":2},{"critere":"La solubilité d’un gaz diminue quand la température augmente","points":4}],"dureeMin":14,"corrige":"1. C’est la **masse maximale** de sel qu’on peut dissoudre dans **1 litre** d’eau à 20 °C : 360 g.\n2. Dans 0,1 L : 360 × 0,1 = **36 g** au maximum.\n3. 50 g dépassent 36 g : la solution est **saturée** et il reste **50 − 36 = 14 g** de sel au fond.\n4. Une **solution saturée**.\n5. La solubilité d’un **gaz diminue** quand la **température augmente** : le dioxyde de carbone dissous s’échappe, le soda tiède pétille moins."}$exo$::jsonb),
  ('c86739a7-4ff5-56da-b730-61db0bd645a2'::uuid, 1, 'application', $exo${"titre":"Ce que contient l’air","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. L’air est-il un corps pur ? Justifie.\n2. Donne les deux principaux gaz de l’air et leurs proportions approximatives.\n3. Comment reconnaît-on le dioxyde de carbone ?","bareme":[{"critere":"Mélange homogène de gaz, pas un corps pur","points":6},{"critere":"Diazote 78 % et dioxygène 21 %","points":8},{"critere":"Eau de chaux qui se trouble","points":6}],"dureeMin":6,"corrige":"1. L’air est un **mélange homogène** de gaz : ce n’est **pas un corps pur**.\n2. **Diazote** (N₂) : environ **78 %** ; **dioxygène** (O₂) : environ **21 %** (le reste, environ 1 %, est de l’argon, du CO₂, de la vapeur d’eau).\n3. On utilise l’**eau de chaux**, qui se **trouble** (blanc laiteux) en présence de dioxyde de carbone."}$exo$::jsonb),
  ('c86739a7-4ff5-56da-b730-61db0bd645a2'::uuid, 2, 'application', $exo${"titre":"Peser l’air","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un ballon de basket dégonflé pèse 600 g. Gonflé, il pèse 606 g et son volume d’air est de 5 L.\n\n1. Quelle est la masse de l’air contenu dans le ballon ?\n2. Calcule la masse d’un litre d’air.\n3. Quel test permet de reconnaître le dioxygène ? Décris le résultat.\n4. Quelle est la pression atmosphérique au niveau de la mer ? Avec quel instrument la mesure-t-on ?","bareme":[{"critere":"Masse de l’air : 606 − 600 = 6 g","points":5},{"critere":"1 L d’air : 6 ÷ 5 = 1,2 g","points":6},{"critere":"Bûchette incandescente qui se rallume","points":4},{"critere":"1 013 hPa, baromètre","points":5}],"dureeMin":10,"corrige":"1. Masse de l’air = 606 − 600 = **6 g**.\n2. Masse d’un litre = 6 ÷ 5 = **1,2 g**.\n3. La **bûchette incandescente** se **rallume** dans le dioxygène.\n4. Environ **1 013 hPa**, mesurée avec un **baromètre**.\n\n**Critères de correction :** Masse de l’air : 606 − 600 = 6 g (5 pts) ; 1 L d’air : 6 ÷ 5 = 1,2 g (6 pts) ; Bûchette incandescente qui se rallume (4 pts) ; 1 013 hPa, baromètre (5 pts)."}$exo$::jsonb),
  ('c86739a7-4ff5-56da-b730-61db0bd645a2'::uuid, 3, 'application', $exo${"titre":"Altitude, plongée et pollution","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Trois situations. (a) Un randonneur monte à 3 000 m d’altitude : la pression baisse. (b) Un plongeur remplit une bouteille avec de l’air fortement comprimé. (c) Une ville brûle beaucoup de pétrole et de charbon.\n\n1. Comment évolue la pression atmosphérique avec l’altitude ? Explique pourquoi.\n2. Pourquoi peut-on faire tenir beaucoup d’air dans la bouteille du plongeur ?\n3. Quelle est la conséquence de la situation (c) sur la composition de l’air ? Cite un gaz à effet de serre et deux polluants.\n4. L’air est-il toujours le même à l’échelle du siècle ? Justifie.","bareme":[{"critere":"La pression diminue car la colonne d’air au-dessus est plus courte","points":5},{"critere":"Un gaz est compressible : le volume diminue sous forte pression","points":5},{"critere":"Le CO₂ augmente ; polluants : particules fines, oxydes d’azote","points":5},{"critere":"La composition évolue avec les activités humaines","points":5}],"dureeMin":14,"corrige":"1. La pression **diminue** avec l’altitude : la **colonne d’air** au-dessus de nous est plus courte.\n2. Un gaz est **compressible** : sous forte pression, le même air occupe un **volume bien plus petit** (beaucoup de vide entre ses molécules).\n3. La proportion de **CO₂** (gaz à effet de serre issu des énergies fossiles) **augmente** ; les polluants sont les **particules fines** et les **oxydes d’azote**.\n4. Non : la composition de l’air **n’est pas fixe** à l’échelle du siècle, elle évolue avec les **activités humaines**."}$exo$::jsonb),
  ('73ab5885-f84d-54b8-86de-7ce0375cb4b1'::uuid, 1, 'application', $exo${"titre":"Calculer une masse volumique","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Un morceau de métal a une masse de **158 g** et un volume de **20 cm³**.\n\n1. Écris la formule de la masse volumique et ses unités.\n2. Calcule la masse volumique du métal.\n3. Le métal est-il du fer (7,9 g/cm³) ? Justifie.","bareme":[{"critere":"Formule ρ = m ÷ V, en g/cm³","points":6},{"critere":"Calcul ρ = 158 ÷ 20 = 7,9 g/cm³","points":8},{"critere":"Identification comme du fer","points":6}],"dureeMin":6,"corrige":"1. **ρ = m ÷ V**, avec m en g, V en cm³ et ρ en **g/cm³**.\n2. ρ = 158 ÷ 20 = **7,9 g/cm³**.\n3. Oui : cette valeur est celle du **fer** (7,9 g/cm³), donc le métal est probablement du fer.\n\n**Critères de correction :** Formule ρ = m ÷ V, en g/cm³ (6 pts) ; Calcul ρ = 158 ÷ 20 = 7,9 g/cm³ (8 pts) ; Identification comme du fer (6 pts)."}$exo$::jsonb),
  ('73ab5885-f84d-54b8-86de-7ce0375cb4b1'::uuid, 2, 'application', $exo${"titre":"Flotte ou coule ?","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un élève dispose d’un cube de bois de masse 46 g et de volume 50 cm³, et d’un caillou de forme irrégulière de masse 90 g. En plongeant le caillou dans une éprouvette contenant 60 mL d’eau, le niveau monte à 90 mL.\n\n1. Calcule la masse volumique du bois. Flotte-t-il sur l’eau ? Justifie.\n2. Comment obtient-on le volume du caillou ? Donne sa valeur.\n3. Calcule la masse volumique du caillou. Flotte-t-il ?","bareme":[{"critere":"ρ du bois = 46 ÷ 50 = 0,92 g/cm³ < 1, il flotte","points":7},{"critere":"Volume du caillou : 90 − 60 = 30 cm³ (volume d’eau déplacé)","points":6},{"critere":"ρ du caillou = 90 ÷ 30 = 3 g/cm³ > 1, il coule","points":7}],"dureeMin":10,"corrige":"1. ρ = 46 ÷ 50 = **0,92 g/cm³**. C’est **inférieur** à 1 g/cm³ (eau) : le bois **flotte**.\n2. Le volume est celui de l’**eau déplacée** : 90 − 60 = **30 mL = 30 cm³**.\n3. ρ = 90 ÷ 30 = **3 g/cm³**, supérieur à 1 g/cm³ : le caillou **coule**."}$exo$::jsonb),
  ('73ab5885-f84d-54b8-86de-7ce0375cb4b1'::uuid, 3, 'application', $exo${"titre":"Un kilogramme de plumes, un kilogramme de plomb","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Voici des données : eau 1 g/cm³ ; huile 0,92 g/cm³ ; fer 7,9 g/cm³ ; air 0,0012 g/cm³. Une bouteille contient 250 mL d’huile.\n\n1. Calcule la masse d’huile contenue dans la bouteille.\n2. Convertis la masse volumique du fer en kg/m³.\n3. Explique la phrase : « un kilogramme de plumes et un kilogramme de plomb ont la même masse mais pas le même volume ».\n4. On verse l’huile dans un verre d’eau. Où se place-t-elle ? Justifie avec les valeurs.\n5. Pourquoi ne peut-on pas dire « le fer est plus lourd que l’eau » sans précaution ?","bareme":[{"critere":"m = 0,92 × 250 = 230 g","points":4},{"critere":"7,9 g/cm³ = 7 900 kg/m³","points":3},{"critere":"Même masse, volumes différents car masses volumiques différentes","points":5},{"critere":"L’huile surnage car 0,92 < 1","points":4},{"critere":"La comparaison n’a de sens qu’à volume égal","points":4}],"dureeMin":16,"corrige":"1. 250 mL = 250 cm³ ; m = ρ × V = 0,92 × 250 = **230 g**.\n2. 1 g/cm³ = 1 000 kg/m³, donc 7,9 g/cm³ = **7 900 kg/m³**.\n3. La masse et la masse volumique sont différentes : 1 kg de plumes occupe un **grand volume** (faible ρ), 1 kg de plomb un **petit volume** (grand ρ). C’est ce que mesure la masse volumique.\n4. L’huile **surnage** (au-dessus) car 0,92 g/cm³ est **inférieure** à 1 g/cm³.\n5. « Plus lourd » n’a de sens qu’**à volume égal** : une grosse quantité d’eau peut avoir plus de masse qu’un petit clou de fer."}$exo$::jsonb),
  ('d91271ab-cddc-541e-a62b-0a2321d40e62'::uuid, 1, 'application', $exo${"titre":"Signaux et information","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Qu’est-ce qu’un signal ?\n2. Cite trois éléments de la chaîne de transmission dans l’ordre.\n3. Un signal sonore peut-il se propager dans le vide ? Et un signal lumineux ?","bareme":[{"critere":"Signal : phénomène physique qui transporte une information sans matière","points":6},{"critere":"Émetteur → milieu de propagation → récepteur","points":7},{"critere":"Son : non ; lumière : oui","points":7}],"dureeMin":6,"corrige":"1. Un signal est un **phénomène physique qui transporte une information** d’un émetteur à un récepteur, **sans transport de matière**.\n2. **Émetteur → milieu de propagation → récepteur**.\n3. Le **son ne se propage pas** dans le vide (il faut un milieu matériel) ; la **lumière** se propage dans le vide."}$exo$::jsonb),
  ('d91271ab-cddc-541e-a62b-0a2321d40e62'::uuid, 2, 'application', $exo${"titre":"Analogique ou numérique ?","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Voici quatre supports : un disque vinyle, un fichier MP3, une photo JPEG, une aiguille de cadran.\n\n1. Classe chaque support en analogique ou numérique.\n2. Combien de bits y a-t-il dans un octet ? Combien d’octets dans 3 ko ?\n3. Donne un avantage du numérique par rapport à l’analogique.","bareme":[{"critere":"Classement correct des quatre supports","points":8},{"critere":"1 octet = 8 bits, 3 ko = 3 000 octets","points":6},{"critere":"Copie sans perte ou compression possible","points":6}],"dureeMin":9,"corrige":"1. **Analogiques** : disque vinyle, aiguille de cadran (variation continue). **Numériques** : fichier MP3, photo JPEG (suite de 0 et de 1).\n2. 1 octet = **8 bits** ; 3 ko = 3 × 1 000 = **3 000 octets**.\n3. Le signal numérique se **copie sans perte** (l’analogique se dégrade à chaque copie) et se **compresse**."}$exo$::jsonb),
  ('d91271ab-cddc-541e-a62b-0a2321d40e62'::uuid, 3, 'application', $exo${"titre":"Le thermomètre connecté","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un thermomètre connecté mesure la température d’une serre, transmet la valeur à un boîtier qui commande l’ouverture d’une fenêtre quand il fait trop chaud. La valeur est transmise par un signal Wi-Fi.\n\n1. Associe les rôles capteur, microcontrôleur et actionneur aux éléments : la sonde de température, le boîtier, le moteur de la fenêtre.\n2. Quel type de signal est le Wi-Fi ? Se propage-t-il dans le vide ?\n3. À quelle vitesse ce signal se propage-t-il dans le vide ? Calcule le temps qu’il met pour parcourir 300 km.\n4. Un fichier de 12 Mo est envoyé : combien d’octets et combien de bits cela représente-t-il ?","bareme":[{"critere":"Sonde : capteur ; boîtier : microcontrôleur ; moteur : actionneur","points":5},{"critere":"Signal électromagnétique, oui il se propage dans le vide","points":4},{"critere":"300 000 km/s, temps de 300 ÷ 300 000 = 0,001 s","points":5},{"critere":"12 Mo = 1,2 × 10⁷ octets = 9,6 × 10⁷ bits","points":6}],"dureeMin":15,"corrige":"1. La **sonde** est le **capteur** (elle transforme la température en signal électrique), le **boîtier** est le **microcontrôleur** (il traite), le **moteur** est l’**actionneur** (il agit).\n2. Le Wi-Fi est un signal **électromagnétique** ; il **se propage dans le vide**.\n3. Environ **300 000 km/s** ; t = d ÷ v = 300 ÷ 300 000 = **0,001 s** (1 ms).\n4. 12 Mo = 12 × 10⁶ = **1,2 × 10⁷ octets** ; en bits : 1,2 × 10⁷ × 8 = **9,6 × 10⁷ bits**."}$exo$::jsonb),
  ('142c0616-d15d-5720-a485-a07be22dca5e'::uuid, 1, 'application', $exo${"titre":"Sources et objets diffusants","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Pour chacun, dis si c’est une source primaire ou un objet diffusant : le Soleil, la Lune, une lampe allumée, une page de livre.\n\nPuis : comment se propage la lumière dans un milieu homogène et transparent ?","bareme":[{"critere":"Soleil et lampe : sources primaires ; Lune et page : diffusants","points":12},{"critere":"Propagation en ligne droite","points":8}],"dureeMin":5,"corrige":"**Sources primaires** : le Soleil, la lampe allumée. **Objets diffusants** : la Lune, la page de livre (ils renvoient la lumière reçue).\n\nDans un milieu **homogène et transparent**, la lumière se propage **en ligne droite**.\n\n**Critères de correction :** Soleil et lampe : sources primaires ; Lune et page : diffusants (12 pts) ; Propagation en ligne droite (8 pts)."}$exo$::jsonb),
  ('142c0616-d15d-5720-a485-a07be22dca5e'::uuid, 2, 'application', $exo${"titre":"Couleur d’un tissu et ombre","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Zoé éclaire un tissu rouge, d’abord en lumière blanche, puis en lumière verte. Elle place ensuite une balle devant une lampe : une ombre se forme sur le mur.\n\n1. De quelle couleur voit-elle le tissu dans chaque cas ? Justifie.\n2. Distingue l’ombre propre et l’ombre portée de la balle.\n3. Dessine ou décris le trajet de la lumière entre la lampe et l’ombre (rayons).\n4. Pourquoi voit-on la balle ?","bareme":[{"critere":"Rouge en lumière blanche, noir en lumière verte, avec justification","points":7},{"critere":"Ombre propre = face non éclairée, ombre portée = sur le mur","points":5},{"critere":"Rayons droits fléchés, zone d’ombre derrière la balle","points":4},{"critere":"On voit la balle car elle diffuse de la lumière vers l’œil","points":4}],"dureeMin":10,"corrige":"1. En lumière **blanche** : **rouge** (il diffuse le rouge et absorbe le reste). En lumière **verte** : **noir** (il n’a aucun rouge à renvoyer).\n2. **Ombre propre** : la face de la balle non éclairée. **Ombre portée** : l’ombre projetée sur le mur.\n3. Les rayons partent de la lampe **en lignes droites** ; ceux qui sont arrêtés par la balle laissent une zone sans lumière derrière elle (cône d’ombre).\n4. La balle **diffuse vers notre œil** la lumière qu’elle reçoit : on ne voit un objet que si de la lumière parvient de lui jusqu’à l’œil."}$exo$::jsonb),
  ('142c0616-d15d-5720-a485-a07be22dca5e'::uuid, 3, 'application', $exo${"titre":"Lumière, couleurs et éclipse","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Une éclipse de Lune se produit quand la Lune passe dans l’ombre de la Terre. Sur un écran d’ordinateur, un pixel blanc est obtenu avec trois couleurs. Un peintre mélange trois pigments pour obtenir du noir.\n\n1. Explique l’éclipse de Lune avec la propagation rectiligne de la lumière.\n2. Quelles sont les trois couleurs primaires de l’écran ? Que donne leur mélange ? Comment s’appelle cette synthèse ?\n3. Quelles sont les primaires du peintre ? Explique pourquoi cette synthèse est dite soustractive.\n4. Un prisme éclaire de la lumière blanche : que voit-on ? Que prouve cette expérience ? Où l’observe-t-on dans la nature ?\n5. La lumière du Soleil met environ 8 minutes pour nous parvenir ; celle de la Lune environ 1,3 s. Explique en une phrase pourquoi.","bareme":[{"critere":"Éclipse : la lumière du Soleil, en ligne droite, est arrêtée par la Terre qui projette un cône d’ombre","points":5},{"critere":"Rouge, vert, bleu, blanc, synthèse additive","points":4},{"critere":"Cyan, magenta, jaune ; chaque pigment retire des couleurs","points":4},{"critere":"Spectre continu, lumière blanche composée, arc-en-ciel","points":4},{"critere":"Distance Terre-Soleil bien plus grande que Terre-Lune, même vitesse","points":3}],"dureeMin":18,"corrige":"1. La lumière du Soleil se propage **en ligne droite** : la **Terre**, entre le Soleil et la Lune, arrête une partie de cette lumière et projette un **cône d’ombre** ; la Lune plongée dans ce cône n’est plus éclairée.\n2. **Rouge, vert, bleu** (RVB). Leur mélange donne le **blanc** : c’est la synthèse **additive**.\n3. **Cyan, magenta, jaune**. La synthèse est **soustractive** car chaque pigment **retire** des couleurs à la lumière blanche : le mélange des trois donne du sombre.\n4. Le prisme **disperse** la lumière blanche en un **spectre continu** (rouge à violet) : elle est **composée**. Dans la nature : l’**arc-en-ciel** (gouttes d’eau).\n5. Le Soleil est **beaucoup plus loin** que la Lune, alors que la lumière va toujours à la même vitesse (environ 300 000 km/s dans le vide)."}$exo$::jsonb),
  ('2634a046-e696-5db5-a47d-c65c8757425a'::uuid, 1, 'application', $exo${"titre":"Comment naît un son","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Qu’est-ce qui produit un son ? Donne deux exemples.\n2. Un son se propage-t-il dans le vide ? Justifie.\n3. Quelle est la vitesse du son dans l’air ?","bareme":[{"critere":"Un objet qui vibre, deux exemples (corde, membrane, cordes vocales…)","points":7},{"critere":"Non, il faut un milieu matériel (cloche à vide)","points":7},{"critere":"Environ 340 m/s","points":6}],"dureeMin":6,"corrige":"1. Un son est produit par un **objet qui vibre** : une corde de guitare, une membrane de haut-parleur, les cordes vocales.\n2. **Non** : le son a besoin d’un **milieu matériel** ; dans le vide, aucun son ne se propage (expérience de la cloche à vide).\n3. Environ **340 m/s** dans l’air."}$exo$::jsonb),
  ('2634a046-e696-5db5-a47d-c65c8757425a'::uuid, 2, 'application', $exo${"titre":"L’orage et l’écho","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Pendant un orage, Inès voit un éclair puis entend le tonnerre **9 s** plus tard. Plus tard, en criant face à une falaise, elle entend son écho **4 s** après. La vitesse du son dans l’air est 340 m/s.\n\n1. Pourquoi voit-elle l’éclair avant d’entendre le tonnerre ?\n2. Calcule la distance de l’éclair.\n3. Calcule la distance de la falaise.","bareme":[{"critere":"La lumière va bien plus vite que le son","points":4},{"critere":"d = 340 × 9 = 3 060 m ≈ 3 km","points":7},{"critere":"Falaise : 340 × 4 = 1 360 m aller-retour, soit 680 m","points":9}],"dureeMin":10,"corrige":"1. La **lumière** (300 000 km/s) va **beaucoup plus vite** que le **son** (340 m/s) : on voit l’éclair avant d’entendre le tonnerre.\n2. d = v × t = 340 × 9 = **3 060 m**, soit environ **3 km** (on retrouve la règle : 9 ÷ 3 = 3 km).\n3. Avec un écho, le son fait l’**aller-retour** : distance totale = 340 × 4 = 1 360 m, donc la falaise est à la **moitié**, soit **680 m**."}$exo$::jsonb),
  ('2634a046-e696-5db5-a47d-c65c8757425a'::uuid, 3, 'application', $exo${"titre":"Le concert et le casque","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Lors d’un concert, Yanis mesure un niveau sonore de 100 dB. Il écoute aussi de la musique au casque. Le son d’une flûte a une fréquence de 1 000 Hz ; un son de 30 000 Hz est émis par une chauve-souris.\n\n1. Distingue fréquence et niveau sonore : unités et ce que chacun donne.\n2. Le son de 30 000 Hz est-il audible par l’oreille humaine ? Comment l’appelle-t-on ?\n3. À partir de quel niveau une exposition prolongée est-elle dangereuse ? Que dire du concert à 100 dB ?\n4. Pourquoi les dommages à l’oreille interne sont-ils définitifs ? Cite deux précautions.\n5. Dans l’eau, la vitesse du son est de 1 500 m/s. Un sonar émet un signal qui revient au bout de 0,4 s. Calcule la profondeur.","bareme":[{"critere":"Fréquence : Hz, hauteur ; niveau sonore : dB, volume","points":4},{"critere":"30 000 Hz : inaudible, ultrason","points":3},{"critere":"85 dB ; 100 dB dépasse le seuil de danger","points":4},{"critere":"Les cellules ne se régénèrent pas ; deux précautions","points":4},{"critere":"Profondeur : 1 500 × 0,4 ÷ 2 = 300 m","points":5}],"dureeMin":18,"corrige":"1. La **fréquence** (en **Hz**) donne la **hauteur** (grave ou aigu) ; le **niveau sonore** (en **dB**) donne l’**intensité** perçue, le volume.\n2. L’oreille humaine perçoit environ **20 Hz à 20 000 Hz** : 30 000 Hz est **inaudible**, c’est un **ultrason**.\n3. Au-delà de **85 dB**, une exposition prolongée abîme l’oreille interne : **100 dB** est dangereux à la longue.\n4. Les cellules de l’oreille interne **ne se régénèrent pas**. Précautions : casque à volume modéré, pauses régulières, bouchons en concert.\n5. Aller-retour : distance totale = 1 500 × 0,4 = 600 m, donc profondeur = 600 ÷ 2 = **300 m**."}$exo$::jsonb),
  ('4d0ef04f-8098-5b96-9d88-47491b919ec7'::uuid, 1, 'application', $exo${"titre":"Période et fréquence","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Un microphone relié à un oscilloscope enregistre un son dont un motif dure **T = 5 ms**.\n\n1. Convertis T en secondes.\n2. Écris la relation entre fréquence et période, puis calcule f.\n3. Ce son est-il audible ? Justifie.","bareme":[{"critere":"T = 0,005 s","points":4},{"critere":"f = 1 ÷ T = 1 ÷ 0,005 = 200 Hz avec unité","points":10},{"critere":"Audible, car entre 20 Hz et 20 000 Hz","points":6}],"dureeMin":7,"corrige":"1. T = 5 ms = **0,005 s**.\n2. **f = 1 ÷ T** = 1 ÷ 0,005 = **200 Hz**.\n3. Ce son est **audible** : 200 Hz est compris entre 20 Hz et 20 000 Hz.\n\n**Critères de correction :** T = 0,005 s (4 pts) ; f = 1 ÷ T = 1 ÷ 0,005 = 200 Hz avec unité (10 pts) ; Audible, car entre 20 Hz et 20 000 Hz (6 pts)."}$exo$::jsonb),
  ('4d0ef04f-8098-5b96-9d88-47491b919ec7'::uuid, 2, 'application', $exo${"titre":"Deux sons à l’oscilloscope","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Deux sons A et B sont visualisés à l’oscilloscope. Le son A est une sinusoïde de période **2 ms** et d’amplitude 3 carreaux. Le son B est une sinusoïde de période **4 ms** et d’amplitude 3 carreaux.\n\n1. Calcule la fréquence de chaque son.\n2. Lequel est le plus aigu ? Justifie.\n3. Lequel est le plus fort ? Justifie.\n4. Ces sons sont-ils purs, composés, ou des bruits ? Justifie.","bareme":[{"critere":"Fréquences 500 Hz et 250 Hz","points":6},{"critere":"A plus aigu : fréquence plus grande (période plus courte)","points":5},{"critere":"Même amplitude, donc même intensité : aucun n’est plus fort","points":5},{"critere":"Sons purs (sinusoïdes)","points":4}],"dureeMin":10,"corrige":"1. f(A) = 1 ÷ 0,002 = **500 Hz** ; f(B) = 1 ÷ 0,004 = **250 Hz**.\n2. **A** est plus aigu : sa période est plus **courte**, donc sa fréquence est plus **grande**.\n3. **Aucun** : les deux courbes ont la **même amplitude** (3 carreaux), donc la même intensité.\n4. Ce sont des **sons purs** : leurs courbes sont des **sinusoïdes** régulières."}$exo$::jsonb),
  ('4d0ef04f-8098-5b96-9d88-47491b919ec7'::uuid, 3, 'application', $exo${"titre":"Le sonar du bateau","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un bateau utilise un sonar : il émet un ultrason de fréquence 40 000 Hz et enregistre l’écho. Sur l’écran, l’écho revient au bout de 0,08 s. La vitesse du son dans l’eau est 1 500 m/s. Le microphone du bateau enregistre aussi le bruit d’un moteur : une courbe sans motif qui se répète.\n\n1. Calcule la période de l’ultrason émis.\n2. Pourquoi ne l’entend-on pas ?\n3. Calcule la profondeur de l’eau sous le bateau.\n4. Le capitaine augmente la puissance du sonar : que change-t-on sur la courbe (fréquence ou amplitude) ? Pourquoi la hauteur ne change-t-elle pas ?\n5. Quelle famille de courbe correspond au bruit du moteur ?","bareme":[{"critere":"T = 1 ÷ 40 000 = 0,000025 s = 25 µs (2,5 × 10⁻⁵ s)","points":4},{"critere":"Ultrason > 20 000 Hz donc inaudible","points":3},{"critere":"Profondeur : 1 500 × 0,08 ÷ 2 = 60 m","points":5},{"critere":"Amplitude qui augmente, fréquence inchangée donc hauteur inchangée","points":4},{"critere":"Bruit : courbe sans période identifiable","points":4}],"dureeMin":17,"corrige":"1. T = 1 ÷ f = 1 ÷ 40 000 = **2,5 × 10⁻⁵ s** (25 µs).\n2. La fréquence dépasse **20 000 Hz** : c’est un **ultrason**, hors du domaine audible.\n3. Distance aller-retour = 1 500 × 0,08 = 120 m ; la profondeur est la **moitié** : **60 m**.\n4. Il augmente l’**amplitude** ; la **fréquence** ne change pas, donc la **hauteur** du son non plus (les deux caractéristiques sont indépendantes).\n5. Un **bruit** donne une courbe **sans période** identifiable."}$exo$::jsonb),
  ('7d0426c6-216e-519d-aa0e-31d31fe1d22c'::uuid, 1, 'application', $exo${"titre":"Réactifs et produits","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Dans la combustion du méthane, on écrit : méthane + dioxygène donne dioxyde de carbone + eau.\n\n1. Quels sont les réactifs ? Quels sont les produits ?\n2. Cette transformation est-elle physique ou chimique ? Justifie.\n3. Que devient la masse totale au cours de la transformation ?","bareme":[{"critere":"Réactifs : méthane et dioxygène ; produits : CO₂ et eau","points":7},{"critere":"Chimique : de nouvelles espèces apparaissent","points":7},{"critere":"La masse totale se conserve (Lavoisier)","points":6}],"dureeMin":6,"corrige":"1. **Réactifs** : méthane et dioxygène. **Produits** : dioxyde de carbone et eau.\n2. C’est une transformation **chimique** : des espèces disparaissent et de **nouvelles apparaissent** (les atomes se réorganisent).\n3. La **masse totale se conserve** : c’est la loi de Lavoisier."}$exo$::jsonb),
  ('7d0426c6-216e-519d-aa0e-31d31fe1d22c'::uuid, 2, 'application', $exo${"titre":"Ajuster une équation","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"On étudie la combustion du méthane : CH₄ + O₂ → CO₂ + H₂O (équation non ajustée).\n\n1. Compte les atomes de chaque sorte à gauche et à droite : l’équation est-elle ajustée ?\n2. Écris l’équation ajustée.\n3. Vérifie-la en comptant les atomes de chaque côté.\n4. 16 g de méthane réagissent avec 64 g de dioxygène pour former 44 g de dioxyde de carbone. Quelle masse d’eau se forme ?","bareme":[{"critere":"Comptage : gauche C1 H4 O2, droite C1 H2 O3, équation non ajustée","points":5},{"critere":"Équation CH₄ + 2 O₂ → CO₂ + 2 H₂O","points":5},{"critere":"Vérification C 1, H 4, O 4 de chaque côté","points":5},{"critere":"Masse d’eau = 80 − 44 = 36 g par conservation","points":5}],"dureeMin":11,"corrige":"1. À gauche : 1 C, 4 H, 2 O. À droite : 1 C, 2 H, 3 O. Ce n’est **pas ajusté**.\n2. **CH₄ + 2 O₂ → CO₂ + 2 H₂O**.\n3. Gauche : 1 C, 4 H, 4 O. Droite : 1 C, 4 H (2 × 2), 2 + 2 = 4 O. **Ajustée**.\n4. Masse des réactifs = 16 + 64 = 80 g ; par **conservation de la masse**, les produits pèsent 80 g, donc masse d’eau = 80 − 44 = **36 g**."}$exo$::jsonb),
  ('7d0426c6-216e-519d-aa0e-31d31fe1d22c'::uuid, 3, 'application', $exo${"titre":"Fer et soufre, flamme du bois","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un élève chauffe de la laine de fer dans du dioxygène : elle brûle et se transforme en un nouveau solide cassant, de couleur différente. Il mesure : 5,6 g de fer réagissent avec 2,4 g de dioxygène. Dans une deuxième expérience, il enferme 5,6 g de fer avec seulement 1,2 g de dioxygène : quand tout le dioxygène est consommé, il reste du fer. Il compare aussi la glace qui fond à du bois qui brûle.\n\n1. Quel est le signe qui prouve une transformation chimique dans la première expérience ?\n2. Calcule la masse du solide formé quand tout est consommé.\n3. Qu’appelle-t-on le réactif limitant ? Dans la deuxième expérience, quel est-il ?\n4. Compare la fusion de la glace et la combustion du bois : que devient chaque molécule ?\n5. Une équation mal ajustée peut-elle être juste ? Justifie avec la conservation des atomes.","bareme":[{"critere":"Signe d’une transformation chimique (changement de couleur, nouveau solide)","points":3},{"critere":"Masse formée 5,6 + 2,4 = 8,0 g","points":4},{"critere":"Réactif limitant : entièrement consommé, ici le dioxygène","points":5},{"critere":"Fusion : molécules inchangées ; combustion : atomes réorganisés en nouvelles molécules","points":5},{"critere":"Équation fausse : les atomes ne sont pas conservés","points":3}],"dureeMin":18,"corrige":"1. Le **changement de couleur** et l’**apparition d’un nouveau solide**, avec disparition des réactifs, prouvent une transformation chimique.\n2. Par conservation de la masse : 5,6 + 2,4 = **8,0 g** de nouveau solide.\n3. Le **réactif limitant** est celui qui est **entièrement consommé** et arrête la réaction : dans la 2ᵉ expérience, c’est le **dioxygène** (il manque alors que le fer reste).\n4. **Fusion de la glace** : les molécules d’eau restent les mêmes, seul leur arrangement change. **Combustion du bois** : les atomes se **réorganisent** en nouvelles molécules (CO₂ et eau).\n5. Non : une équation mal ajustée est **fausse**, car les atomes ne sont ni créés ni détruits : il doit y avoir **le même nombre de chaque sorte d’atome** à gauche et à droite."}$exo$::jsonb),
  ('a5af4e19-a6cd-52ae-8b9e-cb8e48588386'::uuid, 1, 'application', $exo${"titre":"Reconnaître un gaz","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Associe chaque test à l’espèce identifiée.\n\n1. Une bûchette incandescente se rallume.\n2. L’eau de chaux se trouble.\n3. Une flamme approchée provoque une détonation.\n4. Le sulfate de cuivre anhydre blanc devient bleu.","bareme":[{"critere":"Dioxygène (1) et dioxyde de carbone (2)","points":8},{"critere":"Dihydrogène (3) et eau (4)","points":8},{"critere":"Réponses formulées par le nom de l’espèce","points":4}],"dureeMin":6,"corrige":"1. **Dioxygène**. 2. **Dioxyde de carbone**. 3. **Dihydrogène**. 4. **Eau** (le sulfate de cuivre anhydre passe du blanc au bleu).\n\nChaque test se conclut en **nommant l’espèce** identifiée.\n\n**Critères de correction :** Dioxygène (1) et dioxyde de carbone (2) (8 pts) ; Dihydrogène (3) et eau (4) (8 pts) ; Réponses formulées par le nom de l’espèce (4 pts)."}$exo$::jsonb),
  ('a5af4e19-a6cd-52ae-8b9e-cb8e48588386'::uuid, 2, 'application', $exo${"titre":"Identifier des ions","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un élève dispose de trois tubes A, B, C contenant chacun une solution différente. Il ajoute quelques gouttes de soude. Tube A : précipité bleu. Tube B : précipité rouille. Tube C : précipité blanc.\n\n1. Quel ion contient chaque solution (parmi cuivre II, fer III, zinc) ?\n2. Il ajoute du nitrate d’argent à une quatrième solution : un précipité blanc qui noircit à la lumière apparaît. Quel ion est identifié ?\n3. Quelle protection doit-il porter pour manipuler la soude ?\n4. Comment doit-il rédiger la conclusion pour le tube A ?","bareme":[{"critere":"A cuivre II, B fer III, C zinc","points":8},{"critere":"Ions chlorure","points":4},{"critere":"Lunettes, gants, blouse","points":3},{"critere":"Conclusion : la solution A contient des ions cuivre II","points":5}],"dureeMin":10,"corrige":"1. **A** : ions **cuivre II** (précipité bleu). **B** : ions **fer III** (précipité rouille). **C** : ions **zinc** (précipité blanc).\n2. Les ions **chlorure** Cl⁻.\n3. **Lunettes, gants et blouse** : la soude est corrosive.\n4. « La solution A contient des **ions cuivre II** » : on conclut en **nommant l’espèce**, jamais en donnant seulement la couleur."}$exo$::jsonb),
  ('a5af4e19-a6cd-52ae-8b9e-cb8e48588386'::uuid, 3, 'application', $exo${"titre":"Enquête sur une eau inconnue","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un élève doit analyser un gaz et une solution inconnus. Le gaz incolore, quand on approche une flamme, fait une petite détonation. Une deuxième expérience : le gaz produit par un morceau de craie dans du vinaigre trouble l’eau de chaux. La solution inconnue donne un précipité vert avec la soude, et un précipité blanc qui noircit avec le nitrate d’argent.\n\n1. Identifie le premier gaz et justifie.\n2. Identifie le gaz produit par la craie et justifie.\n3. Quels ions contient la solution ? Justifie chaque résultat.\n4. Rédige le protocole d’identification en quatre étapes.\n5. Pourquoi une couleur seule n’est-elle jamais une conclusion ?","bareme":[{"critere":"Dihydrogène (détonation)","points":3},{"critere":"Dioxyde de carbone (eau de chaux qui se trouble)","points":3},{"critere":"Fer II (vert) et chlorure (blanc noircissant)","points":5},{"critere":"Protocole en quatre étapes : prélever, ajouter le réactif, observer, conclure","points":5},{"critere":"Conclusion en nommant l’espèce, la couleur seule ne suffit pas","points":4}],"dureeMin":15,"corrige":"1. La **détonation** au contact d’une flamme identifie le **dihydrogène**.\n2. L’**eau de chaux qui se trouble** identifie le **dioxyde de carbone**.\n3. Le précipité **vert** avec la soude indique des ions **fer II** ; le précipité **blanc qui noircit à la lumière** avec le nitrate d’argent indique des ions **chlorure**.\n4. (1) **Prélever** un peu de solution dans un tube à essai ; (2) ajouter le **réactif** ; (3) **observer** et comparer au tableau ; (4) **conclure** en nommant l’espèce.\n5. Une couleur décrit l’observation, pas l’espèce : « précipité bleu » n’est pas une réponse, « la solution contient des ions cuivre II » en est une."}$exo$::jsonb),
  ('4a605e42-1ece-5c02-9e34-84bdc4b7881b'::uuid, 1, 'application', $exo${"titre":"Atomes et ions","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"1. Qu’est-ce qu’un ion ?\n2. Comment s’appelle un ion positif ? un ion négatif ?\n3. Donne l’exemple d’un cation et d’un anion.","bareme":[{"critere":"Un ion est un atome ou groupe d’atomes qui a gagné ou perdu des électrons","points":7},{"critere":"Cation (positif) et anion (négatif)","points":6},{"critere":"Exemples : Na⁺ ou Cu²⁺ ; Cl⁻ ou OH⁻","points":7}],"dureeMin":6,"corrige":"1. Un ion est un atome (ou un groupe d’atomes) qui a **gagné ou perdu** un ou plusieurs **électrons** : il porte une charge.\n2. Positif : **cation**. Négatif : **anion**.\n3. Cations : Na⁺, Cu²⁺, Fe³⁺, H⁺. Anions : Cl⁻, OH⁻, SO₄²⁻."}$exo$::jsonb),
  ('4a605e42-1ece-5c02-9e34-84bdc4b7881b'::uuid, 2, 'application', $exo${"titre":"Formation d’ions","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"L’atome de cuivre est neutre. Il perd deux électrons pour devenir l’ion Cu²⁺. L’atome de chlore gagne un électron pour devenir l’ion Cl⁻.\n\n1. Le nombre de protons du cuivre change-t-il ? Justifie.\n2. Explique pourquoi Cu²⁺ est positif et Cl⁻ négatif.\n3. Que signifie le « 2 » dans Cu²⁺ ?\n4. Quels ions obtient-on en dissolvant du sel dans l’eau ?","bareme":[{"critere":"Le nombre de protons ne change pas : le noyau reste le même","points":5},{"critere":"Cu²⁺ : deux électrons de moins ; Cl⁻ : un électron de plus","points":6},{"critere":"Le 2 indique deux charges positives, deux électrons perdus","points":4},{"critere":"Na⁺ et Cl⁻","points":5}],"dureeMin":10,"corrige":"1. **Non** : le noyau ne change jamais, sinon ce ne serait plus le même élément.\n2. Cu²⁺ a **perdu deux électrons** : il a deux protons de trop, donc charge **positive**. Cl⁻ a **gagné un électron** : un électron de trop, donc charge **négative**.\n3. Le **2** indique **deux charges** positives : l’atome a perdu **deux électrons**.\n4. Des ions **sodium Na⁺** et **chlorure Cl⁻**."}$exo$::jsonb),
  ('4a605e42-1ece-5c02-9e34-84bdc4b7881b'::uuid, 3, 'application', $exo${"titre":"Eau salée et eau distillée","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un élève réalise un circuit avec une pile, une lampe et deux électrodes plongées dans un bécher. Avec de l’eau distillée, la lampe reste éteinte. Avec de l’eau salée, la lampe s’allume. Il remarque aussi qu’un fil de cuivre allume la lampe.\n\n1. Explique pourquoi l’eau salée conduit et l’eau distillée non.\n2. Distingue les porteurs de charge dans le fil de cuivre et dans l’eau salée.\n3. L’eau salée est-elle chargée électriquement ? Justifie.\n4. Pourquoi l’eau du robinet et l’électricité font-elles mauvais ménage ?\n5. Un atome de sodium (11 protons) devient l’ion Na⁺ : combien d’électrons a-t-il ? Justifie.","bareme":[{"critere":"Eau salée : beaucoup d’ions mobiles ; eau distillée : presque aucun ion","points":5},{"critere":"Cuivre : électrons libres ; eau salée : ions","points":4},{"critere":"Solution neutre : autant de charges positives que négatives","points":4},{"critere":"L’eau du robinet contient des ions, elle conduit","points":3},{"critere":"Na⁺ : 11 protons, 10 électrons","points":4}],"dureeMin":15,"corrige":"1. L’**eau salée** contient **beaucoup d’ions** mobiles qui transportent la charge ; l’**eau distillée** n’en contient presque aucun.\n2. Dans le **fil de cuivre**, ce sont les **électrons libres** ; dans l’**eau salée**, ce sont les **ions**.\n3. Non : elle est **électriquement neutre** dans son ensemble, avec autant de charges positives que négatives.\n4. L’eau du robinet et la sueur contiennent des **ions** : elles **conduisent** le courant, donc danger.\n5. L’atome neutre a 11 électrons ; il en perd un : **10 électrons** pour 11 protons, d’où la charge globale 1+."}$exo$::jsonb),
  ('3c32118c-3fd8-5d9c-beb4-b5746ac94895'::uuid, 1, 'application', $exo${"titre":"Acide, neutre ou basique","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Classe chaque solution en acide, neutre ou basique : jus de citron (pH 2) ; eau pure (pH 7) ; déboucheur (pH 13) ; vinaigre (pH 3).\n\nPuis : entre quelles valeurs le pH est-il compris en pratique ?","bareme":[{"critere":"Acide : citron et vinaigre ; neutre : eau pure ; basique : déboucheur","points":14},{"critere":"pH compris entre 0 et 14","points":6}],"dureeMin":5,"corrige":"**Acides** : jus de citron (pH 2), vinaigre (pH 3). **Neutre** : eau pure (pH 7). **Basique** : déboucheur (pH 13).\n\nEn pratique le pH est compris entre **0 et 14**.\n\n**Critères de correction :** Acide : citron et vinaigre ; neutre : eau pure ; basique : déboucheur (14 pts) ; pH compris entre 0 et 14 (6 pts)."}$exo$::jsonb),
  ('3c32118c-3fd8-5d9c-beb4-b5746ac94895'::uuid, 2, 'application', $exo${"titre":"Mesurer et diluer","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un élève dispose de papier pH, d’un pH-mètre et d’une solution de vinaigre de pH 3. Il en verse 10 mL dans un verre et ajoute 90 mL d’eau.\n\n1. Quels ions sont majoritaires dans le vinaigre ?\n2. Quel instrument est le plus précis ? À quelle précision donne-t-il le pH ?\n3. Le pH de la solution diluée sera-t-il inférieur, égal ou supérieur à 3 ? Peut-il dépasser 7 ?\n4. Quelle règle de sécurité respecte-t-on pour diluer un acide ?","bareme":[{"critere":"Ions hydrogène H⁺","points":4},{"critere":"pH-mètre, précis au dixième","points":5},{"critere":"pH supérieur à 3, proche de 7 sans le dépasser","points":6},{"critere":"Verser l’acide dans l’eau","points":5}],"dureeMin":10,"corrige":"1. Les ions **hydrogène H⁺**.\n2. Le **pH-mètre**, précis au **dixième** (le papier pH : environ 1 unité).\n3. Le pH **augmente** : il devient **supérieur à 3**, se rapproche de 7 mais ne peut **jamais dépasser 7**.\n4. On verse **toujours l’acide dans l’eau**, jamais l’inverse, avec lunettes, gants et blouse : l’opération dégage de la chaleur et peut projeter le liquide."}$exo$::jsonb),
  ('3c32118c-3fd8-5d9c-beb4-b5746ac94895'::uuid, 3, 'application', $exo${"titre":"Trois produits ménagers","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un élève mesure le pH de trois produits : vinaigre (pH 3), eau du robinet (pH 7), déboucheur (pH 13). Il dilue chaque produit dix fois avec de l’eau distillée.\n\n1. Classe les trois produits et cite l’ion majoritaire de chacun (ou dis s’ils sont à égalité).\n2. Prévois, sans calcul, le sens de variation du pH du vinaigre et du déboucheur après dilution.\n3. Le déboucheur dilué peut-il devenir acide ? Justifie.\n4. Que se passe-t-il pour le nombre d’ions H⁺ du vinaigre quand on le dilue ? Que se passe-t-il pour leur concentration ?\n5. Quels équipements de sécurité pour manipuler le déboucheur ? Pourquoi est-il dangereux ?","bareme":[{"critere":"Vinaigre acide (H⁺), eau neutre (autant des deux), déboucheur basique (OH⁻)","points":5},{"critere":"Vinaigre : pH monte ; déboucheur : pH descend","points":4},{"critere":"Non : on tend vers 7 sans le dépasser","points":4},{"critere":"Nombre de H⁺ inchangé, concentration diminue","points":4},{"critere":"Lunettes, gants, blouse ; produit corrosif","points":3}],"dureeMin":16,"corrige":"1. **Vinaigre** : acide, ions **H⁺**. **Eau du robinet** : neutre, autant de H⁺ que de OH⁻. **Déboucheur** : basique, ions **OH⁻**.\n2. Le pH du vinaigre **monte** vers 7 ; celui du déboucheur **descend** vers 7.\n3. **Non** : la dilution rapproche de la neutralité **sans jamais la dépasser**.\n4. Le **nombre** d’ions H⁺ ne change pas ; leur **concentration diminue** (ils sont dans plus d’eau).\n5. **Lunettes, gants et blouse** : les solutions très basiques sont **corrosives**."}$exo$::jsonb),
  ('5084dced-79ff-5c7c-9c0d-03bf141f6ff0'::uuid, 1, 'application', $exo${"titre":"Fer et acide chlorhydrique","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"On plonge un clou en fer dans de l’acide chlorhydrique : des bulles apparaissent et la solution devient verte.\n\n1. Quel gaz se dégage ? Comment le reconnaît-on ?\n2. Quels ions expliquent la couleur verte ?\n3. Cette transformation est-elle chimique ? Justifie.","bareme":[{"critere":"Dihydrogène, reconnu par une détonation avec une flamme","points":7},{"critere":"Ions fer II","points":6},{"critere":"Transformation chimique : le fer disparaît, gaz et ions nouveaux","points":7}],"dureeMin":6,"corrige":"1. Le **dihydrogène**, reconnu par une **détonation** à l’approche d’une flamme.\n2. Les ions **fer II** (couleur verte, précipité vert avec la soude).\n3. Oui, c’est une transformation **chimique** : le fer **disparaît**, un gaz et de nouvelles espèces apparaissent."}$exo$::jsonb),
  ('5084dced-79ff-5c7c-9c0d-03bf141f6ff0'::uuid, 2, 'application', $exo${"titre":"Quels métaux réagissent ?","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un élève verse de l’acide chlorhydrique sur quatre métaux : zinc, cuivre, aluminium, argent.\n\n1. Prévois le résultat pour chacun.\n2. Dans la réaction Fe + 2 H⁺ → Fe²⁺ + H₂, quel ion est un ion spectateur dans l’acide chlorhydrique ? Justifie.\n3. Quel danger présente le gaz dégagé ? Quelle précaution prendre ?","bareme":[{"critere":"Zinc et aluminium réagissent, cuivre et argent non","points":8},{"critere":"Cl⁻ est spectateur, il ne participe pas","points":6},{"critere":"H₂ explosif avec l’air et une flamme, petites quantités et ventilation","points":6}],"dureeMin":10,"corrige":"1. **Zinc** et **aluminium** : réaction avec dégagement de dihydrogène. **Cuivre** et **argent** : pas de réaction.\n2. L’ion **chlorure Cl⁻** est spectateur : il ne participe pas à la transformation (seuls les ions H⁺ réagissent).\n3. Le **dihydrogène** est **explosif** avec l’air et une flamme : petites quantités, salle **ventilée** ou hotte, pas de flamme."}$exo$::jsonb),
  ('5084dced-79ff-5c7c-9c0d-03bf141f6ff0'::uuid, 3, 'application', $exo${"titre":"La rouille","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Une grille en fer, laissée dehors, se couvre de rouille. Une barre de fer de 100 g est entièrement transformée en rouille : le solide obtenu pèse 143 g.\n\n1. Écris la transformation avec les mots réactifs et produit. Quelles sont les deux conditions nécessaires ?\n2. Explique pourquoi la rouille pèse plus que le fer disparu.\n3. Le fer « s’use »-t-il ? Justifie.\n4. Propose deux méthodes pour protéger la grille.\n5. Compare la rouille à la réaction du fer avec l’acide chlorhydrique : pourquoi parle-t-on de « la même chimie au ralenti » ?","bareme":[{"critere":"Fer + eau + dioxygène donnent de la rouille","points":4},{"critere":"La rouille contient des atomes d’oxygène en plus (143 − 100 = 43 g d’oxygène)","points":5},{"critere":"Le fer se transforme, il ne s’use pas","points":3},{"critere":"Peinture, huile, galvanisation ou alliage inoxydable","points":4},{"critere":"Dans les deux cas, le fer disparaît et donne des ions ou composés du fer","points":4}],"dureeMin":15,"corrige":"1. **Fer + dioxygène (en présence d’eau) → rouille**. Il faut de l’**eau** et du **dioxygène**.\n2. La rouille contient, en plus du fer, des **atomes d’oxygène** : ici 143 − 100 = **43 g** d’oxygène se sont fixés (la masse totale se conserve).\n3. Non : le fer ne « s’use » pas, il se **transforme**.\n4. **Peinture**, **huile**, **galvanisation** (isoler le métal) ou utiliser un **alliage inoxydable**.\n5. Dans les deux cas, le fer est **consommé** et donne de nouvelles espèces contenant du fer : avec l’acide la réaction est **rapide**, avec l’air humide elle est **lente**."}$exo$::jsonb),
  ('d5136ad7-3fd6-5d57-8178-39c8697ad58a'::uuid, 1, 'application', $exo${"titre":"Calculer une vitesse","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Un coureur parcourt **400 m** en **50 s**.\n\n1. Écris la formule de la vitesse.\n2. Calcule sa vitesse en m/s.\n3. Convertis cette vitesse en km/h.","bareme":[{"critere":"Formule v = d ÷ t","points":4},{"critere":"v = 400 ÷ 50 = 8 m/s","points":8},{"critere":"8 × 3,6 = 28,8 km/h","points":8}],"dureeMin":6,"corrige":"1. **v = d ÷ t**.\n2. v = 400 ÷ 50 = **8 m/s**.\n3. 8 × 3,6 = **28,8 km/h** (pour passer des m/s aux km/h on multiplie par 3,6 ; pour l’inverse on divise par 3,6). Le résultat est cohérent : un coureur rapide dépasse 25 km/h sur 400 m."}$exo$::jsonb),
  ('d5136ad7-3fd6-5d57-8178-39c8697ad58a'::uuid, 2, 'application', $exo${"titre":"Train et quai","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Ben est assis dans un train qui roule à **72 km/h** sur une voie droite. Un observateur est sur le quai.\n\n1. Ben est-il immobile ou en mouvement ? Réponds pour chaque référentiel.\n2. Convertis 72 km/h en m/s.\n3. Quelle distance le train parcourt-il en 30 s ?\n4. Le train ralentit avant la gare. Comment évoluent les positions sur une chronophotographie ?","bareme":[{"critere":"Immobile dans le train, en mouvement par rapport au quai","points":5},{"critere":"72 ÷ 3,6 = 20 m/s","points":5},{"critere":"d = 20 × 30 = 600 m","points":5},{"critere":"Positions de plus en plus rapprochées","points":5}],"dureeMin":10,"corrige":"1. Dans le référentiel du **train**, Ben est **immobile** ; dans celui du **quai**, il est **en mouvement**. Les deux descriptions sont vraies.\n2. 72 ÷ 3,6 = **20 m/s**.\n3. d = v × t = 20 × 30 = **600 m**.\n4. Le train **ralentit** : les positions successives sont de **plus en plus rapprochées**."}$exo$::jsonb),
  ('d5136ad7-3fd6-5d57-8178-39c8697ad58a'::uuid, 3, 'application', $exo${"titre":"Un trajet de vélo","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Léa fait un trajet en vélo en trois étapes : 6 km en 20 min (montée), 9 km en 20 min (plat), puis 3 km en 5 min (descente).\n\n1. Calcule la vitesse moyenne de chaque étape en km/h.\n2. Calcule la distance totale, la durée totale et la vitesse moyenne sur tout le trajet (en km/h).\n3. Ce mouvement est-il uniforme ? Justifie.\n4. Distingue vitesse moyenne et vitesse instantanée : laquelle lit-on sur le compteur ?\n5. Convertis la vitesse de la descente en m/s (arrondie au dixième).","bareme":[{"critere":"Vitesses 18 km/h, 27 km/h et 36 km/h avec calculs","points":6},{"critere":"Distance 18 km, durée 45 min, vitesse moyenne 24 km/h","points":6},{"critere":"Mouvement non uniforme : vitesse qui change","points":3},{"critere":"Moyenne sur tout le trajet, instantanée au compteur","points":3},{"critere":"36 ÷ 3,6 = 10 m/s","points":2}],"dureeMin":16,"corrige":"1. Montée : 6 km ÷ (1/3 h) = **18 km/h**. Plat : 9 ÷ (1/3) = **27 km/h**. Descente : 3 ÷ (5/60) = 3 ÷ 0,0833 = **36 km/h**.\n2. Distance totale = 6 + 9 + 3 = **18 km** ; durée = 20 + 20 + 5 = **45 min = 0,75 h** ; vitesse moyenne = 18 ÷ 0,75 = **24 km/h**.\n3. **Non**, le mouvement n’est pas uniforme : la vitesse **change** d’une étape à l’autre.\n4. La vitesse **moyenne** porte sur tout le trajet ; la vitesse **instantanée**, celle du **compteur**, est celle d’un instant précis.\n5. 36 ÷ 3,6 = **10 m/s**."}$exo$::jsonb),
  ('329f4753-6e4f-5440-a91c-b17954859ac8'::uuid, 1, 'application', $exo${"titre":"Représenter une force","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Une main pousse une caisse vers la droite avec une force de 20 N.\n\n1. Cette interaction est-elle de contact ou à distance ?\n2. Quelles sont les quatre caractéristiques à représenter pour la flèche de la force ?\n3. Avec quel appareil mesure-t-on une force ? En quelle unité ?","bareme":[{"critere":"Interaction de contact","points":4},{"critere":"Point d’application, direction, sens, valeur","points":10},{"critere":"Dynamomètre, newton","points":6}],"dureeMin":6,"corrige":"1. C’est une interaction **de contact** (la main touche la caisse).\n2. **Point d’application**, **direction**, **sens** et **valeur** (longueur de la flèche, ici 20 N).\n3. On la mesure avec un **dynamomètre**, en **newtons (N)**.\n\n**Critères de correction :** Interaction de contact (4 pts) ; Point d’application, direction, sens, valeur (10 pts) ; Dynamomètre, newton (6 pts)."}$exo$::jsonb),
  ('329f4753-6e4f-5440-a91c-b17954859ac8'::uuid, 2, 'application', $exo${"titre":"Actions réciproques","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un nageur pousse l’eau vers l’arrière pour avancer. Un aimant attire un clou sans le toucher.\n\n1. Énonce le principe des actions réciproques et applique-le au nageur.\n2. L’interaction aimant-clou est-elle de contact ou à distance ? Cite une autre interaction du même type.\n3. Cite trois effets possibles d’une force sur un objet.\n4. Un skieur glisse en ligne droite à vitesse constante. Que peut-on dire des forces qui s’exercent sur lui ?","bareme":[{"critere":"Principe : si A agit sur B, B agit sur A avec une force opposée de même valeur ; l’eau pousse le nageur vers l’avant","points":6},{"critere":"Interaction à distance (magnétisme), autre : gravitation ou électrostatique","points":4},{"critere":"Trois effets : mettre en mouvement, modifier la vitesse, la trajectoire ou déformer","points":5},{"critere":"Les forces se compensent","points":5}],"dureeMin":11,"corrige":"1. Si A exerce une force sur B, B exerce sur A une force de **même direction, même valeur, sens opposé**. Le nageur pousse l’eau vers l’arrière, l’eau le pousse **vers l’avant**.\n2. Interaction **à distance** (magnétisme). Autres : **gravitation**, **électrostatique**.\n3. Mettre en mouvement, **modifier la vitesse**, **modifier la trajectoire**, **déformer**.\n4. Le mouvement est rectiligne et uniforme : les forces **se compensent**."}$exo$::jsonb),
  ('329f4753-6e4f-5440-a91c-b17954859ac8'::uuid, 3, 'application', $exo${"titre":"La caisse et le camion","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Deux élèves tirent une caisse sur le sol avec des forces horizontales : Ana tire vers la droite avec 30 N, Malik tire aussi vers la droite avec 20 N. Les frottements du sol sont de 50 N vers la gauche. La caisse est d’abord immobile.\n\n1. Représente (décris) les forces horizontales : sens, valeur, point d’application, en choisissant une échelle (1 cm pour 10 N).\n2. Fais le bilan des forces horizontales : se compensent-elles ? Quel est l’état de la caisse ?\n3. Malik tire maintenant avec 40 N. Les forces se compensent-elles encore ? Que peut-on prévoir ?\n4. Le camion arrêté sur la route reçoit la poussée d’un piéton : Que dit le principe des actions réciproques ?\n5. Réponds par vrai ou faux et justifie : « il faut une force pour qu’un objet continue d’avancer ».","bareme":[{"critere":"Flèches à 3 cm, 2 cm (droite) et 5 cm (gauche) avec point d’application","points":4},{"critere":"30 + 20 = 50 N vers la droite = frottements : forces compensées, la caisse reste immobile","points":5},{"critere":"Forces non compensées (70 N contre 50 N) : la caisse se met en mouvement","points":4},{"critere":"Actions réciproques : le camion pousse le piéton avec une force opposée de même valeur","points":4},{"critere":"Faux : une force sert à changer le mouvement, pas à le maintenir","points":3}],"dureeMin":17,"corrige":"1. Sur la caisse : **Ana** 30 N vers la droite (flèche de **3 cm**), **Malik** 20 N vers la droite (**2 cm**), **frottements** 50 N vers la gauche (**5 cm**), tous appliqués sur la caisse.\n2. Vers la droite : 30 + 20 = **50 N**, vers la gauche : **50 N**. Les forces **se compensent** : la caisse **reste immobile**.\n3. Vers la droite : 30 + 40 = **70 N** contre 50 N : les forces **ne se compensent plus**, la caisse **se met en mouvement** vers la droite.\n4. Le piéton pousse le camion et le camion exerce sur le piéton une force de **même valeur, même direction, sens opposé**.\n5. **Faux** : un objet n’a pas besoin d’une force pour **continuer** d’avancer, il en a besoin pour **changer** de mouvement."}$exo$::jsonb),
  ('1f739b6b-8153-5184-8714-ef636bf0fb32'::uuid, 1, 'application', $exo${"titre":"Calculer un poids","consigne":"Réponds à chaque question en justifiant et en précisant les unités.","enonce":"Un sac de 6 kg est posé sur Terre. On prend g = 9,8 N/kg.\n\n1. Écris la formule du poids avec les unités.\n2. Calcule le poids du sac.\n3. Quelle est la direction du poids ?","bareme":[{"critere":"Formule P = m × g, N, kg, N/kg","points":6},{"critere":"P = 6 × 9,8 = 58,8 N","points":8},{"critere":"Verticale, vers le bas","points":6}],"dureeMin":6,"corrige":"1. **P = m × g** : P en newtons (N), m en kilogrammes (kg), g en N/kg.\n2. P = 6 × 9,8 = **58,8 N**.\n3. Le poids est **vertical**, dirigé **vers le bas** (vers le centre de la Terre).\n\n**Critères de correction :** Formule P = m × g, N, kg, N/kg (6 pts) ; P = 6 × 9,8 = 58,8 N (8 pts) ; Verticale, vers le bas (6 pts)."}$exo$::jsonb),
  ('1f739b6b-8153-5184-8714-ef636bf0fb32'::uuid, 2, 'application', $exo${"titre":"Sur la Lune","consigne":"Rédige des réponses complètes : écris les formules, les calculs et les unités.","enonce":"Un astronaute équipé a une masse de 90 kg. On donne g = 9,8 N/kg sur Terre et g = 1,6 N/kg sur la Lune.\n\n1. Calcule son poids sur Terre.\n2. Calcule son poids sur la Lune.\n3. Que devient sa masse sur la Lune ? Quel instrument mesure la masse ? Quel instrument mesure le poids ?","bareme":[{"critere":"P sur Terre = 90 × 9,8 = 882 N","points":6},{"critere":"P sur la Lune = 90 × 1,6 = 144 N","points":6},{"critere":"Masse inchangée (90 kg), balance pour la masse, dynamomètre pour le poids","points":8}],"dureeMin":9,"corrige":"1. P = 90 × 9,8 = **882 N**.\n2. P = 90 × 1,6 = **144 N** (environ 6 fois moins).\n3. La **masse ne change pas** : **90 kg**. La masse se mesure avec une **balance**, le poids avec un **dynamomètre**.\n\n**Critères de correction :** P sur Terre = 90 × 9,8 = 882 N (6 pts) ; P sur la Lune = 90 × 1,6 = 144 N (6 pts) ; Masse inchangée (90 kg), balance pour la masse, dynamomètre pour le poids (8 pts)."}$exo$::jsonb),
  ('1f739b6b-8153-5184-8714-ef636bf0fb32'::uuid, 3, 'application', $exo${"titre":"Gravitation et masse de l’objet","consigne":"Justifie chaque réponse avec le vocabulaire du cours ; détaille tes calculs.","enonce":"Un dynamomètre indique 245 N quand on y accroche une malle sur Terre (g = 9,8 N/kg). On emporte la malle sur une planète où g = 3,7 N/kg.\n\n1. Calcule la masse de la malle.\n2. Calcule son poids sur cette planète.\n3. Distingue masse et poids : unité, instrument, et ce qui varie d’un astre à l’autre.\n4. De quoi dépend la force de gravitation entre deux corps ? Un objet de 1 kg attire-t-il la Terre ?\n5. Quel rôle joue la gravitation pour la Lune ? Que se passerait-il sans elle ?","bareme":[{"critere":"m = 245 ÷ 9,8 = 25 kg","points":4},{"critere":"P = 25 × 3,7 = 92,5 N","points":4},{"critere":"Masse en kg, balance, inchangée ; poids en N, dynamomètre, varie avec l’astre","points":4},{"critere":"Dépend des masses et de la distance ; oui, l’attraction est réciproque","points":4},{"critere":"Retient la Lune en orbite ; sans elle, elle partirait en ligne droite","points":4}],"dureeMin":17,"corrige":"1. m = P ÷ g = 245 ÷ 9,8 = **25 kg**.\n2. P = m × g = 25 × 3,7 = **92,5 N**.\n3. La **masse** (kg, balance) est la quantité de matière et **ne change pas** ; le **poids** (N, dynamomètre) est une force d’attraction qui **dépend de l’astre**.\n4. La force de gravitation est d’autant plus grande que les **masses** sont grandes et la **distance** petite. Oui, l’attraction s’exerce dans les **deux sens** (imperceptible pour 1 kg).\n5. La gravitation maintient la Lune en **orbite** autour de la Terre ; sans elle, la Lune partirait **en ligne droite**."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
